	} },
	{ title = "Snow Leopard", note = "Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of Kharanos, more north-west and west of it; the smaller Juvenile Snow Leopards do not count.", only = { races = {"Dwarf"} }, when = {{ k = "onquest", neg = true, q = {94792, 94863, 94864, 94793} }, { k = "turnedin", neg = true, q = 94792 }}, goals = {
