	{ title = "Jocaste in Darnassus", note = "Take the road west from Dolanaar to Darnassus. Jocaste stands inside the Cenarion Enclave with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her.", only = { races = {"NightElf"} }, when = {{ k = "onquest", neg = true, q = {94792, 94863, 94864, 94793} }, { k = "turnedin", neg = true, q = 94792 }}, goals = {
		{ t = "turnin", quest = 6103, title = "Training the Beast", npc = "Jocaste", map = 1457, x = 40.38, y = 8.55, era = true, note = "Jocaste: Beast Training" },
	} },
	{ title = "Josephine Carson in Goldshire", note = "At 10 go to Josephine Carson, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in Goldshire; Isaac Chan, the pet trainer, is beside her. Skyborne: this is for one who left Zephras Isle without taming; it teaches the same.", only = { races = {"Human", "Skyborne"} }, label = "goldshire", goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 94792, title = "Taming the Beast", npc = "Josephine Carson", map = 1429, x = 41.15, y = 66.23, era = true, qlvl = 10, note = "Josephine Carson: the first Taming Rod" },
	} },
	{ title = "Rockhide Boar", note = "Rockhide Boars (level 7-8) graze in three herds south and south-east of Goldshire, toward the Maclure Vineyards. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use Rushing Charge, so start with the rod, not Auto Shot. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through Goldshire from here.", when = {{ k = "turnedin", neg = true, q = 6064 }, { k = "turnedin", neg = true, q = 6063 }}, goals = {
		{ t = "kill", quest = 94792, title = "Taming the Beast", map = 1429, x = 43.32, y = 77.87, era = true, count = 1, target = "Rockhide Boar", oi = 1, mobLevel = 8, note = "Use the Taming Rod on a living boar", text = "Tame Rockhide Boar", spots = "43.3,77.9;45.6,83.9;45,88.3;53.3,83.4;53.1,75.2" },
