	} },
	{ title = "Gray Forest Wolf", note = "Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of Goldshire, east of Crystal Lake.", when = {{ k = "turnedin", neg = true, q = 6064 }, { k = "turnedin", neg = true, q = 6063 }}, goals = {
		{ t = "kill", quest = 94863, title = "Taming the Beast", map = 1429, x = 58.44, y = 62.13, era = true, count = 1, target = "Gray Forest Wolf", oi = 1, mobLevel = 8, note = "Use the Taming Rod on a living wolf", text = "Tame Gray Forest Wolf", spots = "59.8,64.4;61,60.8;64.6,60.3;64.6,63.9;66.2,66.7" },
		{ t = "turnin", quest = 94863, title = "Taming the Beast", npc = "Josephine Carson", map = 1429, x = 41.15, y = 66.23, era = true },
