	{ title = "High Sorcerer Andromath (Skyborne)", note = "You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of Stormwind's Mage Quarter. High Sorcerer Andromath waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. (Jennea Cannon may also offer you High Sorcerer Andromath, the pointer quest; it is only a pointer and you can skip it.)", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 26 },
