	} },
} end)

Waypost.RegisterSteps("class/paladin/holy-mightstone", function() return {
	{ title = "Lord Grayson Shadowbreaker", note = "At 50 Lord Grayson Shadowbreaker, the paladin trainer in the Cathedral of Light, sends you to Chillwind Camp in the Western Plaguelands. Brandur Ironhammer in Ironforge gives the same quest.", only = { races = {"Human"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8415, title = "Chillwind Point", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 52 },
	} },
	{ title = "Brandur Ironhammer", note = "At 50 Brandur Ironhammer, the paladin trainer in the Mystic Ward, sends you to Chillwind Camp in the Western Plaguelands. Lord Grayson Shadowbreaker in Stormwind gives the same quest.", only = { races = {"Dwarf"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8415, title = "Chillwind Point", npc = "Brandur Ironhammer", map = 1455, x = 23.13, y = 6.14, era = true, qlvl = 52 },
	} },
	{ title = "Chillwind Camp", note = "Chillwind Camp is the Alliance camp at the south end of the Western Plaguelands, north of the Alterac foothills. Commander Ashlam Valorfist commands it; Argent Officer Pureheart stands in the same camp.", goals = {
		{ t = "turnin", quest = 8415, title = "Chillwind Point", npc = "Commander Ashlam Valorfist", map = 1422, x = 42.7, y = 84.03, era = true },
		{ t = "accept", quest = 8414, title = "Dispelling Evil", npc = "Commander Ashlam Valorfist", map = 1422, x = 42.7, y = 84.03, era = true, qlvl = 52 },
	} },
	{ title = "The Argent Dawn Commission", note = "The Scourge drop no Scourgestones unless you wear an Argent Dawn Commission. Argent Officer Pureheart gives you one through her quest, Argent Dawn Commission, which you hand in straight away (if you already have one from Light's Hope Chapel, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones.", when = {{ k = "has", neg = true, n = 1, item = 12846 }}, goals = {
		{ t = "accept", quest = 5401, title = "Argent Dawn Commission", npc = "Argent Officer Pureheart", map = 1422, x = 42.97, y = 83.55, era = true, qlvl = 55, note = "Argent Officer Pureheart: Argent Dawn Commission" },
		{ t = "turnin", quest = 5401, title = "Argent Dawn Commission", npc = "Argent Officer Pureheart", map = 1422, x = 42.97, y = 83.55, era = true, note = "the Argent Dawn Commission trinket: equip it" },
	} },
	{ title = "Minion's Scourgestones", note = "Kill the Scourge of the Western Plaguelands with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a Minion's Scourgestone about two kills in five. Sorrow Hill, just east of Chillwind Camp around Uther's Tomb, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast Cone of Cold and Arcane Explosion up close, Dark Summoners run for help at low health.", goals = {
		{ t = "collect", quest = 8414, title = "Dispelling Evil", map = 1422, x = 47.37, y = 84.3, era = true, count = 20, item = 12840, itemName = "Minion's Scourgestone", oi = 1, mobLevel = 56, note = "Minion's Scourgestone x20", spots = "47.6,83;49.9,77;47.1,71.6;48.7,63.3;43.5,63.3" },
	} },
	{ title = "High Priest Thel'danis", note = "High Priest Thel'danis keeps watch at Uther's Tomb on Sorrow Hill, east of the camp. He turns your 20 stones into one Inert Scourgestone: keep it.", goals = {
		{ t = "turnin", quest = 8414, title = "Dispelling Evil", npc = "High Priest Thel'danis", map = 1422, x = 52.05, y = 83.27, era = true },
		{ t = "accept", quest = 8416, title = "Inert Scourgestones", npc = "High Priest Thel'danis", map = 1422, x = 52.05, y = 83.27, era = true, qlvl = 52 },
	} },
	{ title = "Commander Ashlam Valorfist", note = "Back to Chillwind Camp. Ashlam needs the voodoo of the Sunken Temple's trolls for the stone.", goals = {
		{ t = "turnin", quest = 8416, title = "Inert Scourgestones", npc = "Commander Ashlam Valorfist", map = 1422, x = 42.7, y = 84.03, era = true },
		{ t = "accept", quest = 8418, title = "Forging the Mightstone", npc = "Commander Ashlam Valorfist", map = 1422, x = 42.7, y = 84.03, era = true, qlvl = 52 },
	} },
	{ title = "The Sunken Temple", note = "The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears in eastern Swamp of Sorrows: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first.", goals = {
		{ t = "goto", map = 1435, x = 69.9, y = 53.6, era = true, text = "The Temple of Atal'Hakkar" },
		{ t = "collect", quest = 8418, title = "Forging the Mightstone", map = 1435, x = 69.9, y = 53.6, era = true, count = 2, item = 20606, itemName = "Amber Voodoo Feather", oi = 1, note = "Amber Voodoo Feather x2: Gasher, Zul'Lor" },
		{ t = "collect", quest = 8418, title = "Forging the Mightstone", map = 1435, x = 69.9, y = 53.6, era = true, count = 2, item = 20607, itemName = "Blue Voodoo Feather", oi = 2, note = "Blue Voodoo Feather x2: Hukku, Mijan" },
		{ t = "collect", quest = 8418, title = "Forging the Mightstone", map = 1435, x = 69.9, y = 53.6, era = true, count = 2, item = 20608, itemName = "Green Voodoo Feather", oi = 3, note = "Green Voodoo Feather x2: Zolo, Loro" },
	} },
	{ title = "Forging the Mightstone", note = "Back to Ashlam in Chillwind Camp: he forges the Holy Mightstone. Look at the reward window before you hand in: Classic also offered the Chivalrous Signet, the Lightforged Blade or the Sanctified Orb, and Forever's notes say that choice may be gone. Use the stone before a fight against undead (Stratholme, Scholomance): it lasts ten minutes and is gone after one use.", goals = {
		{ t = "turnin", quest = 8418, title = "Forging the Mightstone", npc = "Commander Ashlam Valorfist", map = 1422, x = 42.7, y = 84.03, era = true, note = "Commander Ashlam Valorfist: Holy Mightstone" },
	} },
} end)

