Waypost.RegisterSteps("class/paladin/verigans-fist", function() return {
	{ title = "The Tome of Valor (Ironforge)", note = "At 20 Tiza Battleforge, upstairs in the Hall of Mysteries in the Mystic Ward, gives you the Tome of Valor. Right-click it: it sends you to Duthorian Rall in Stormwind's Cathedral of Light. Take the Deeprun Tram from Ironforge to Stormwind.", only = { races = {"Dwarf"} }, goals = {
		{ t = "level", level = 20 },
