	} },
	{ title = "The Tome of Valor", note = "Duthorian Rall stands in the Cathedral of Light. Humans get the Tome of Valor from him. Right-click the book to start its quest and hand it straight back to him.", goals = {
		{ t = "level", level = 20 },
		{ t = "turnin", quest = 1793, title = "The Tome of Valor", npc = "Duthorian Rall", map = 1453, x = 50.48, y = 47.49, qlvl = 20, only = { races = {"Human"} } },
		{ t = "accept", quest = 1649, title = "The Tome of Valor", item = 6776, itemName = "Tome of Valor", qlvl = 20, note = "Right-click the Tome of Valor" },
		{ t = "turnin", quest = 1649, title = "The Tome of Valor", npc = "Duthorian Rall", map = 1453, x = 50.48, y = 47.49 },
		{ t = "accept", quest = 1650, title = "The Tome of Valor", npc = "Duthorian Rall", map = 1453, x = 50.48, y = 47.49, qlvl = 23 },
	} },
	{ title = "Daphne Stilwell", note = "Daphne Stilwell's farmhouse stands on the south-west coast of Westfall, south of Moonbrook: take the path that runs south beside the Deadmines' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or Daphne die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24.", goals = {
		{ t = "turnin", quest = 1650, title = "The Tome of Valor", npc = "Daphne Stilwell", map = 1436, x = 41.69, y = 89.24, era = true },
		{ t = "accept", quest = 1651, title = "The Tome of Valor", npc = "Daphne Stilwell", map = 1436, x = 41.69, y = 89.24, era = true, qlvl = 25 },
		{ t = "complete", quest = 1651, title = "The Tome of Valor", note = "Protect Daphne Stilwell: three waves", objs = {"Protect Daphne Stilwell"} },
		{ t = "turnin", quest = 1651, title = "The Tome of Valor", npc = "Daphne Stilwell", map = 1436, x = 41.69, y = 89.24, era = true },
		{ t = "accept", quest = 1652, title = "The Tome of Valor", npc = "Daphne Stilwell", map = 1436, x = 41.69, y = 89.24, era = true, qlvl = 25 },
	} },
	{ title = "Duthorian Rall", note = "Back to the Cathedral of Light: Duthorian gives you the Bastion of Stormwind shield and teaches you Sense Undead.", goals = {
		{ t = "turnin", quest = 1652, title = "The Tome of Valor", npc = "Duthorian Rall", map = 1453, x = 50.48, y = 47.49, note = "Duthorian Rall: Bastion of Stormwind, Sense Undead" },
		{ t = "accept", quest = 1653, title = "The Test of Righteousness", npc = "Duthorian Rall", map = 1453, x = 50.48, y = 47.49, qlvl = 21 },
	} },
	{ title = "Jordan Stilwell", note = "Jordan Stilwell works outside the gates of Ironforge, not inside. He gives you Jordan's Weapon Notes: four parts, in any order. Keep the notes.", goals = {
		{ t = "turnin", quest = 1653, title = "The Test of Righteousness", npc = "Jordan Stilwell", map = 1426, x = 52.49, y = 36.92, era = true },
		{ t = "accept", quest = 1654, title = "The Test of Righteousness", npc = "Jordan Stilwell", map = 1426, x = 52.49, y = 36.92, era = true, qlvl = 22 },
	} },
	{ title = "Bailor Stonehand", note = "Bailor Stonehand is downstairs in the house of Thelsamar that has a tailoring merchant outside. His quest only opens once you hold Jordan's.", goals = {
		{ t = "accept", quest = 1655, title = "Bailor's Ore Shipment", npc = "Bailor Stonehand", map = 1432, x = 35.95, y = 44.91, era = true, qlvl = 22 },
	} },
	{ title = "Bailor's Ore", note = "The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east Loch Modan, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one.", goals = {
		{ t = "collect", quest = 1655, title = "Bailor's Ore Shipment", map = 1432, x = 71.6, y = 21.61, era = true, count = 1, item = 6992, itemName = "Jordan's Ore Shipment", oi = 1, note = "Bailor's Ore crate" },
	} },
	{ title = "Back to Bailor", note = "Bailor turns the ore into Jordan's Refined Ore Shipment, the part Jordan wants.", goals = {
		{ t = "turnin", quest = 1655, title = "Bailor's Ore Shipment", npc = "Bailor Stonehand", map = 1432, x = 35.95, y = 44.91, era = true },
		{ t = "collect", quest = 1654, title = "The Test of Righteousness", map = 1432, x = 35.95, y = 44.91, era = true, count = 1, item = 6993, itemName = "Jordan's Refined Ore Shipment", oi = 2 },
	} },
	{ title = "Whitestone Oak Lumber", note = "The Deadmines is a group of five under Moonbrook; the instance portal is at the bottom of the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time.", goals = {
		{ t = "goto", map = 1436, x = 42.5, y = 71.7, text = "The Deadmines, in the Moonbrook mine" },
		{ t = "collect", quest = 1654, title = "The Test of Righteousness", map = 1436, x = 42.5, y = 71.7, count = 1, item = 6994, itemName = "Whitestone Oak Lumber", oi = 1, group = true, note = "Goblin Woodcarvers, inside" },
	} },
	{ title = "Jordan's Smithing Hammer", note = "Shadowfang Keep is a dungeon for a group of five in the low to mid 20s, in southern Silverpine Forest, Horde land: a long trip for the Alliance, through the Wetlands, Arathi and Hillsbrad. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it.", goals = {
		{ t = "goto", map = 1421, x = 44.8, y = 67.8, text = "Shadowfang Keep" },
		{ t = "collect", quest = 1654, title = "The Test of Righteousness", map = 1421, x = 44.8, y = 67.8, count = 1, item = 6895, itemName = "Jordan's Smithing Hammer", oi = 3, note = "Jordan's Hammer, inside" },
	} },
	{ title = "Thundris Windweaver", note = "Thundris Windweaver is in Auberdine. Take his quest before you hunt naga: the Kor Gem never drops without it.", goals = {
		{ t = "accept", quest = 1442, title = "Seeking the Kor Gem", npc = "Thundris Windweaver", map = 1439, x = 37.4, y = 40.13, era = true, qlvl = 22 },
	} },
	{ title = "The Corrupted Kor Gem", note = "The Blackfathom naga in the flooded passages around the Blackfathom Deeps entrance, on Ashenvale's north-west coast, drop the Corrupted Kor Gem: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group.", goals = {
		{ t = "collect", quest = 1442, title = "Seeking the Kor Gem", map = 1440, x = 13.55, y = 12.06, era = true, count = 1, item = 6995, itemName = "Corrupted Kor Gem", oi = 1, mobLevel = 22, group = true, spots = "13.8,9.3;16.2,11.3;13.6,12.1;17.7,11.1" },
	} },
	{ title = "The Purified Kor Gem", note = "Back to Thundris in Auberdine: he purifies the gem.", goals = {
		{ t = "turnin", quest = 1442, title = "Seeking the Kor Gem", npc = "Thundris Windweaver", map = 1439, x = 37.4, y = 40.13, era = true },
		{ t = "collect", quest = 1654, title = "The Test of Righteousness", map = 1439, x = 37.4, y = 40.13, era = true, count = 1, item = 7083, itemName = "Purified Kor Gem", oi = 4 },
	} },
	{ title = "Verigan's Fist", note = "Bring the four parts to Jordan Stilwell outside Ironforge. Accept his last quest and wait by him while he forges the mace at his anvil.", goals = {
		{ t = "turnin", quest = 1654, title = "The Test of Righteousness", npc = "Jordan Stilwell", map = 1426, x = 52.49, y = 36.92, era = true },
		{ t = "accept", quest = 1806, title = "The Test of Righteousness", npc = "Jordan Stilwell", map = 1426, x = 52.49, y = 36.92, era = true, qlvl = 22 },
