	{ title = "Elune's Grace: Rohan's letter", note = "Hand Rohan's letter to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", when = {{ k = "onquest", q = {5675} }}, goals = {
		{ t = "turnin", quest = 5675, title = "Elune's Grace", npc = "Priestess Alathea", map = 1457, x = 39.52, y = 81.2, era = true, note = "Priestess Alathea: Elune's Grace" },
	} },
} end)

Waypost.RegisterSteps("class/rogue/blade-of-cunning-alliance", function() return {
