Waypost.RegisterSteps("class/rogue/certificate-of-thievery", function() return {
	{ title = "SI:7 (Goldshire)", note = "At 16 Keryn Sylvius, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, sends you to Renzik \"The Shiv\" in Stormwind. Taking it shuts out the other towns' breadcrumbs.", only = { races = {"Human", "Skyborne"} }, goals = {
		{ t = "level", level = 16 },
