	{ title = "Erion Shadewhisper", note = "Erion stands in the Cenarion Enclave. Then the boat from Rut'theran Village to Auberdine, and the boat from Auberdine to Stormwind Harbor.", only = { races = {"NightElf"} }, goals = {
		{ t = "turnin", quest = 2259, title = "Erion Shadewhisper", npc = "Erion Shadewhisper", map = 1457, x = 34.52, y = 25.93, era = true, note = "Erion Shadewhisper, Darnassus" },
		{ t = "accept", quest = 2260, title = "Erion's Behest", npc = "Erion Shadewhisper", map = 1457, x = 34.52, y = 25.93, era = true, qlvl = 16 },
	} },
	{ title = "Renzik \"The Shiv\"", note = "Renzik stands upstairs in the SI:7 building in Old Town, behind the rogue trainers. Before you leave: if you lack Pick Lock, Lord Tony Romano in the SI:7 building teaches it; Lockpicking is the test of the next quest.", goals = {
		{ t = "turnin", quest = 2300, title = "SI:7", npc = "Renzik \"The Shiv\"", map = 1453, x = 78.29, y = 71.14, only = { races = {"Human", "Skyborne"} } },
		{ t = "turnin", quest = 2298, title = "Kingly Shakedown", npc = "Renzik \"The Shiv\"", map = 1453, x = 78.29, y = 71.14, only = { races = {"Dwarf", "Gnome"} } },
		{ t = "turnin", quest = 2260, title = "Erion's Behest", npc = "Renzik \"The Shiv\"", map = 1453, x = 78.29, y = 71.14, only = { races = {"NightElf"} } },
		{ t = "accept", quest = 2281, title = "Redridge Rendezvous", npc = "Renzik \"The Shiv\"", map = 1453, x = 78.29, y = 71.14, qlvl = 16 },
	} },
	{ title = "Lucius", note = "Head east through Elwynn Forest into Redridge, or fly to Lakeshire. Lucius stands on a crate on one of the Lakeshire docks, south of town; he gives you Thieves' Tools with the job (Gerald Crawley in Lakeshire sells more). Pick Lock does not work without the tools in your bags.", goals = {
		{ t = "turnin", quest = 2281, title = "Redridge Rendezvous", npc = "Lucius", map = 1433, x = 22.97, y = 52.04 },
		{ t = "accept", quest = 2282, title = "Alther's Mill", npc = "Lucius", map = 1433, x = 22.97, y = 52.04, qlvl = 20 },
	} },
	{ title = "Alther's Mill", note = "Alther's Mill stands east of Lakeshire, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until Lucius's Lockbox opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75.", goals = {
		{ t = "collect", quest = 2282, title = "Alther's Mill", map = 1433, x = 46.95, y = 44.69, count = 1, item = 7871, itemName = "Token of Thievery", oi = 1, note = "Token of Thievery: Lucius's Lockbox" },
