	} },
} end)

Waypost.RegisterSteps("class/rogue/poisons-alliance", function() return {
	{ title = "Mathias and the Defias", note = "At 20 Master Mathias Shaw, upstairs in the SI:7 building in Old Town, sends you to Agent Kearnen in Westfall. This chain is how you learn Poisons on Forever, so do not skip it.", goals = {
		{ t = "level", level = 20 },
		{ t = "accept", quest = 2360, title = "Mathias and the Defias", npc = "Master Mathias Shaw", map = 1453, x = 78.31, y = 70.74, qlvl = 20 },
	} },
	{ title = "Agent Kearnen", note = "Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of Klaven Mortwake's Defias tower in the far east of Westfall, by the Duskwood border. Read Kearnen's Journal for the tower's layout if you like.", goals = {
		{ t = "turnin", quest = 2360, title = "Mathias and the Defias", npc = "Agent Kearnen", map = 1436, x = 68.49, y = 70.08, era = true },
		{ t = "accept", quest = 2359, title = "Klaven's Tower", npc = "Agent Kearnen", map = 1436, x = 68.49, y = 70.08, era = true, qlvl = 24 },
	} },
	{ title = "The Defias Tower Key", note = "Get the key first. The Malformed Defias Drone (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and Pick Pocket it from behind: it always has the key. It hits hard: if stealth breaks, Sprint away. Watch for the pair of Defias Drones that also patrol.", goals = {
		{ t = "collect", quest = 2359, title = "Klaven's Tower", map = 1436, x = 69.47, y = 73.99, era = true, count = 1, item = 7923, itemName = "Defias Tower Key", oi = 2, text = "Pick Pocket the Malformed Defias Drone for the Defias Tower Key" },
	} },
	{ title = "Klaven's journal", note = "Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. Klaven Mortwake, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The Duskwood Chest beside his desk needs Lockpicking of about 70-75 (practise on the boxes at Alther's Mill in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the Touch of Zanzil, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out.", goals = {
		{ t = "collect", quest = 2359, title = "Klaven's Tower", map = 1436, x = 70.4, y = 74, era = true, count = 1, item = 7908, itemName = "Klaven Mortwake's Journal", oi = 1, note = "Klaven Mortwake's Journal: the Duskwood Chest, top floor" },
	} },
	{ title = "Master Mathias Shaw", note = "Head north through Elwynn to Stormwind; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the Thistle Tea recipe. Poisons are made, not bought: each batch of Instant Poison takes a Dust of Decay and an Empty Vial, which Jasper Fel and Sloan McCoy sell in Old Town next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon.", goals = {
		{ t = "turnin", quest = 2359, title = "Klaven's Tower", npc = "Master Mathias Shaw", map = 1453, x = 78.31, y = 70.74, note = "Master Mathias Shaw: Poisons" },
		{ t = "accept", quest = 2607, title = "The Touch of Zanzil", npc = "Master Mathias Shaw", map = 1453, x = 78.31, y = 70.74, qlvl = 20 },
	} },
	{ title = "Doc Mixilpixil", note = "The Touch of Zanzil still sits on you. Doc Mixilpixil works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind Jasper Fel. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down.", goals = {
		{ t = "turnin", quest = 2607, title = "The Touch of Zanzil", npc = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9 },
		{ t = "accept", quest = 2608, title = "The Touch of Zanzil", npc = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9, qlvl = 20 },
		{ t = "complete", quest = 2608, title = "The Touch of Zanzil", map = 1453, x = 80.06, y = 69.9, note = "/lay with the Doc targeted", objs = {"Diagnosis Complete"} },
		{ t = "turnin", quest = 2608, title = "The Touch of Zanzil", npc = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9 },
		{ t = "accept", quest = 2609, title = "The Touch of Zanzil", npc = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9, qlvl = 20 },
	} },
	{ title = "The cure's ingredients", note = "All four are in Stormwind. Simple Wildflowers: Bernard or Felicia Gump's flower shop by the Trade District canal. A Leaded Vial: many general goods and alchemy vendors (Keldric Boucher, Jasper Fel and others). A Bronze Tube: the Auction House in the Trade District; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The Spool of Light Chartreuse Silk Thread lies on the floor beside the left end of the counter in The Finest Thread, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an Anti-Venom (First Aid) or a druid's Cure Poison also clears the Touch of Zanzil.", goals = {
		{ t = "buy", count = 1, item = 3421, itemName = "Simple Wildflowers" },
		{ t = "buy", count = 1, item = 3372, itemName = "Leaded Vial" },
		{ t = "collect", map = 1453, x = 61.2, y = 71.3, count = 1, item = 4371, itemName = "Bronze Tube", note = "Bronze Tube: the Auction House" },
		{ t = "collect", quest = 2609, title = "The Touch of Zanzil", map = 1453, x = 50.58, y = 60.14, count = 1, item = 8431, itemName = "Spool of Light Chartreuse Silk Thread", oi = 4 },
	} },
	{ title = "Back to Doc Mixilpixil", goals = {
		{ t = "turnin", quest = 2609, title = "The Touch of Zanzil", npc = "Doc Mixilpixil", map = 1453, x = 80.06, y = 69.9, note = "Doc Mixilpixil: Eau de Mixilpixil" },
	} },
} end)

Waypost.RegisterSteps("class/shaman/call-of-air-alliance", function() return {
	{ title = "Eldrun Stormbreaker", note = "At 30 Eldrun Stormbreaker, the shaman trainer in Ironforge, sends you to Veyric Thunderhame in Arathi Highlands. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem he gives.", goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 94789, title = "Call of Air", npc = "Eldrun Stormbreaker", map = 1455, x = 47.1, y = 13.79, era = true, qlvl = 30 },
	} },
	{ title = "Veyric Thunderhame", note = "Veyric Thunderhame camps in the hills just west of Hammerfall, the Horde town in the north-east of Arathi: mind its guards. Fly to Refuge Pointe and head north-east.", goals = {
		{ t = "turnin", quest = 94789, title = "Call of Air", npc = "Veyric Thunderhame", map = 1417, x = 59.84, y = 27.57, era = true, note = "Veyric Thunderhame: your Air Totem" },
		{ t = "accept", quest = 96264, title = "Elemental Aid", npc = "Veyric Thunderhame", map = 1417, x = 59.84, y = 27.57, era = true, qlvl = 33 },
	} },
	{ title = "Charlga Razorflank", note = "Razorfen Kraul is a five-player dungeon at the southern edge of the Barrens (the arrow points at its entrance); Charlga Razorflank (level 33 elite) is its last boss. She casts Chain Bolt, Renew on her allies and Purity; the Tattered Note drops only from her.", goals = {
		{ t = "collect", quest = 96264, title = "Elemental Aid", map = 1413, x = 42.9, y = 90.2, count = 1, item = 274463, itemName = "Tattered Note", oi = 1, group = true, note = "Tattered Note, from Charlga Razorflank" },
