		{ t = "accept", quest = 1680, title = "Tormus Deepforge", npc = "Muren Stormpike", map = 1455, x = 70.77, y = 90.27, era = true, qlvl = 11 },
		{ t = "turnin", quest = 1680, title = "Tormus Deepforge", npc = "Tormus Deepforge", map = 1455, x = 48.64, y = 42.48, era = true },
