		{ t = "turnin", quest = 1693, title = "Weapons of Elunite", npc = "Mathiel", map = 1457, x = 59.51, y = 45.38, era = true },
	} },
	{ title = "A Warrior's Training", note = "At 10, Lyria Du Lac, the warrior trainer by the inn in Goldshire, sends you to Harry Burlguard in Stormwind; Ilsa Corbin, the warrior trainer in Stormwind's Old Town, offers it too.", only = { races = {"Human", "Skyborne"} }, goals = {
