Waypost.RegisterSteps("collectibles/mounts/alliance/black-war-mounts", function() return {
	{ title = "PvP rank 11", note = "Rank Points come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. Riding one at full speed needs Journeyman Riding (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman Riding.", goals = {
		{ t = "level", level = 60 },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
	{ title = "Lieutenant Karter", note = "Lieutenant Karter sells the mounts in Stormwind's Old Town by the Champions' Hall, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city).", goals = {
		{ t = "vendor", npc = "Lieutenant Karter", map = 1453, x = 70.6, y = 55.9, era = true },
		{ t = "buy", npc = "Lieutenant Karter", map = 1453, x = 70.6, y = 55.9, era = true, item = 18241, itemName = "Black War Steed Bridle", optional = true, note = "Black War Steed, Horse Riding, 100g" },
		{ t = "buy", npc = "Lieutenant Karter", map = 1453, x = 70.6, y = 55.9, era = true, item = 18242, itemName = "Reins of the Black War Tiger", optional = true, note = "Black War Tiger, Tiger Riding, 100g" },
		{ t = "buy", npc = "Lieutenant Karter", map = 1453, x = 70.6, y = 55.9, era = true, item = 18243, itemName = "Black Battlestrider", optional = true, note = "Black Battlestrider, Mechanostrider Piloting, 100g" },
		{ t = "buy", npc = "Lieutenant Karter", map = 1453, x = 70.6, y = 55.9, era = true, item = 18244, itemName = "Black War Ram", optional = true, note = "Black War Ram, Ram Riding, 100g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/alliance/horse", function() return {
	{ title = "Learn to ride", note = "Randal Hunter and Katie Hunter's horse pen are at Eastvale Logging Camp in eastern Elwynn Forest. At 40 Randal Hunter teaches Riding to Humans for 100g (10% less at Honored with Stormwind), and it comes with a horse. Other races learn Riding, with their own first mount, at their own race's riding trainer.", goals = {
		{ t = "level", level = 40 },
		{ t = "train", npc = "Randal Hunter", map = 1429, x = 84.32, y = 64.87, era = true, only = { races = {"Human"} }, note = "Randal Hunter, riding trainer" },
		{ t = "skill", level = 75, skillName = "Riding" },
	} },
	{ title = "Horse Riding for other races", note = "Any Alliance race can buy these horses, but riding one also takes Horse Riding, which only Humans get with Riding. Randal Hunter teaches it to other races once they are Exalted with Stormwind (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character.", only = { races = {"Dwarf", "NightElf", "Gnome", "Skyborne"} }, when = {{ k = "knows", neg = true, spell = 824 }}, goals = {
		{ t = "rep", factionName = "Stormwind", faction = 72, standing = 8 },
		{ t = "train", npc = "Randal Hunter", map = 1429, x = 84.32, y = 64.87, era = true, note = "Randal Hunter, Horse Riding" },
	} },
	{ title = "Pick a colour", note = "Katie Hunter sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like.", goals = {
		{ t = "vendor", npc = "Katie Hunter", map = 1429, x = 84.15, y = 65.49, era = true },
		{ t = "buy", npc = "Katie Hunter", map = 1429, x = 84.15, y = 65.49, era = true, item = 2414, itemName = "Pinto Bridle", optional = true, note = "Pinto Bridle, 20g" },
		{ t = "buy", npc = "Katie Hunter", map = 1429, x = 84.15, y = 65.49, era = true, item = 5655, itemName = "Chestnut Mare Bridle", optional = true, note = "Chestnut Mare Bridle, 20g" },
		{ t = "buy", npc = "Katie Hunter", map = 1429, x = 84.15, y = 65.49, era = true, item = 5656, itemName = "Brown Horse Bridle", optional = true, note = "Brown Horse Bridle, 20g" },
	} },
	{ title = "Black Stallion in Menethil Harbor", note = "The Black Stallion is not at Katie Hunter: Unger Statforth sells it, at the stables of Menethil Harbor in the Wetlands (20g in the Forever client). Skip this unless you want that colour.", goals = {
		{ t = "buy", npc = "Unger Statforth", map = 1437, x = 8.57, y = 54.34, era = true, item = 2411, itemName = "Black Stallion Bridle", optional = true, note = "Black Stallion Bridle, 20g, Unger Statforth" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/alliance/mechanostrider", function() return {
	{ title = "Learn to ride", note = "Steelgrill's Depot is just east of Kharanos; Binjy Featherwhistle stands beside Milli Featherwhistle's mechanostriders. At 40 Binjy Featherwhistle teaches Riding to Gnomes for 100g (10% less at Honored with Gnomeregan Exiles), and it comes with a mechanostrider. Other races learn Riding, with their own first mount, at their own race's riding trainer.", goals = {
		{ t = "level", level = 40 },
		{ t = "train", npc = "Binjy Featherwhistle", map = 1426, x = 49.15, y = 48.13, era = true, only = { races = {"Gnome"} }, note = "Binjy Featherwhistle, riding trainer" },
		{ t = "skill", level = 75, skillName = "Riding" },
	} },
	{ title = "Mechanostrider Piloting for other races", note = "Any Alliance race can buy these mechanostriders, but riding one also takes Mechanostrider Piloting, which only Gnomes get with Riding. Binjy Featherwhistle teaches it to other races once they are Exalted with Gnomeregan Exiles (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character.", only = { races = {"Human", "Dwarf", "NightElf", "Skyborne"} }, when = {{ k = "knows", neg = true, spell = 10907 }}, goals = {
		{ t = "rep", factionName = "Gnomeregan Exiles", faction = 54, standing = 8 },
		{ t = "train", npc = "Binjy Featherwhistle", map = 1426, x = 49.15, y = 48.13, era = true, note = "Binjy Featherwhistle, Mechanostrider Piloting" },
	} },
	{ title = "Pick a colour", note = "Milli Featherwhistle sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like.", goals = {
		{ t = "vendor", npc = "Milli Featherwhistle", map = 1426, x = 49.13, y = 47.95, era = true },
		{ t = "buy", npc = "Milli Featherwhistle", map = 1426, x = 49.13, y = 47.95, era = true, item = 8563, itemName = "Red Mechanostrider", optional = true, note = "Red Mechanostrider, 20g" },
		{ t = "buy", npc = "Milli Featherwhistle", map = 1426, x = 49.13, y = 47.95, era = true, item = 8595, itemName = "Blue Mechanostrider", optional = true, note = "Blue Mechanostrider, 20g" },
		{ t = "buy", npc = "Milli Featherwhistle", map = 1426, x = 49.13, y = 47.95, era = true, item = 13321, itemName = "Green Mechanostrider", optional = true, note = "Green Mechanostrider, 20g" },
		{ t = "buy", npc = "Milli Featherwhistle", map = 1426, x = 49.13, y = 47.95, era = true, item = 13322, itemName = "Unpainted Mechanostrider", optional = true, note = "Unpainted Mechanostrider, 20g" },
		{ t = "note", text = "In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn Mechanostrider Piloting." },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/alliance/pack-kodo", function() return {
	{ title = "Azeroth Commerce Authority", note = "The camp is at Three Corners in western Redridge Mountains, where the roads from Elwynn Forest, Duskwood and Lakeshire meet. Huey Sunnydale sells the Pack Kodo only once you are Exalted with the Azeroth Commerce Authority, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time Shipping Label, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside.", goals = {
		{ t = "goto", map = 1433, x = 10.5, y = 72.7, text = "Azeroth Commerce Authority camp" },
		{ t = "rep", factionName = "Azeroth Commerce Authority", faction = 2586, standing = 8 },
	} },
	{ title = "Pack Kodo", note = "The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier.", goals = {
		{ t = "vendor", npc = "Huey Sunnydale", map = 1433, x = 8.5, y = 72.1 },
		{ t = "buy", npc = "Huey Sunnydale", map = 1433, x = 8.45, y = 72.09, item = 262766, itemName = "Reins of the Pack Kodo", note = "6,000 Merchant's Favor" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/alliance/paladin-charger", function() return {
	{ title = "Lord Grayson Shadowbreaker (Ironforge)", note = "At 60 Brandur Ironhammer in the Mystic Ward sends you to Lord Grayson Shadowbreaker in Stormwind's Cathedral of Light.", only = { races = {"Dwarf"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7670, title = "Lord Grayson Shadowbreaker", npc = "Brandur Ironhammer", map = 1455, x = 23.13, y = 6.14, era = true, qlvl = 60 },
	} },
	{ title = "Lord Grayson Shadowbreaker", note = "The Summon Charger chain is long: Stratholme, Dire Maul West and Scholomance with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 Runecloth, 10 Arthas' Tears, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, Duthorian Rall nearby.", goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7638, title = "Lord Grayson Shadowbreaker", npc = "Duthorian Rall", map = 1453, x = 50.48, y = 47.49, qlvl = 60, only = { races = {"Human"} }, note = "Duthorian Rall, Cathedral of Light" },
		{ t = "turnin", quest = 7638, title = "Lord Grayson Shadowbreaker", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, only = { races = {"Human"} } },
		{ t = "turnin", quest = 7670, title = "Lord Grayson Shadowbreaker", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, only = { races = {"Dwarf"} } },
		{ t = "accept", quest = 7637, title = "Emphasis on Sacrifice", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 60 },
	} },
	{ title = "High Priest Rohan", note = "High Priest Rohan, the priest trainer, walks about the Hall of Mysteries in Ironforge's Mystic Ward. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer.", goals = {
		{ t = "money", money = 1500000 },
		{ t = "turnin", quest = 7637, title = "Emphasis on Sacrifice", npc = "High Priest Rohan", map = 1455, x = 24.73, y = 8.16, era = true, note = "High Priest Rohan: 150 gold" },
		{ t = "accept", quest = 7639, title = "To Show Due Judgment", npc = "High Priest Rohan", map = 1455, x = 24.73, y = 8.16, era = true, qlvl = 60 },
	} },
	{ title = "Back to Lord Grayson", note = "Lord Grayson blesses the censer into the Exorcism Censer for Terrordale.", goals = {
		{ t = "turnin", quest = 7639, title = "To Show Due Judgment", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22 },
		{ t = "accept", quest = 7640, title = "Exorcising Terrordale", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 60 },
	} },
	{ title = "Exorcising Terrordale", note = "Terrordale lies in the far north-west of the Eastern Plaguelands, west of the Stratholme gates. Stand inside a green glowing patch on the ground (a Terrordale Haunting Spirit; some are inside the ruined houses) and use the Exorcism Censer: up to three Terrordale Spirits (level 59-60) rise and attack. Their Wailing Dead lowers all your stats by 30%: fight them one at a time and use Turn Undead. The patches come back quickly; several paladins can work side by side.", goals = {
		{ t = "use", map = 1423, x = 14.5, y = 25.5, era = true, item = 18752, itemName = "Exorcism Censer", note = "Exorcism Censer, inside a green patch" },
		{ t = "kill", quest = 7640, title = "Exorcising Terrordale", map = 1423, x = 14.59, y = 25.65, count = 25, target = "Terrordale Spirit", oi = 1, mobLevel = 60, note = "Terrordale Spirits x25", spots = "14.3,24.9;14.8,21.5;11.8,23.1;11.4,20.5;8.9,21.2" },
	} },
	{ title = "Lord Grayson Shadowbreaker", note = "Lord Grayson takes the censer back.", goals = {
		{ t = "turnin", quest = 7640, title = "Exorcising Terrordale", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22 },
		{ t = "accept", quest = 7641, title = "The Work of Grimand Elmore", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 60 },
	} },
	{ title = "Grimand Elmore", note = "Grimand Elmore works in Stormwind's Dwarven District. He forges the Arcanite Barding from your materials and 150 gold.", goals = {
		{ t = "turnin", quest = 7641, title = "The Work of Grimand Elmore", npc = "Grimand Elmore", map = 1453, x = 59.73, y = 33.78 },
		{ t = "accept", quest = 7642, title = "Collection of Goods", npc = "Grimand Elmore", map = 1453, x = 59.73, y = 33.78, qlvl = 60 },
	} },
	{ title = "Grimand's materials", note = "Runecloth drops from humanoids of level 50 and up (Everlook's Bruisers, the Scarlet Crusade in the Plaguelands, the Dire Maul ogres). Arthas' Tears is a Plaguelands herb (Herbalism 220), common around Chillwind Camp. An Arcanite Bar is an alchemist's transmute from a Thorium Bar and an Arcane Crystal, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three.", goals = {
		{ t = "collect", quest = 7642, title = "Collection of Goods", map = 1453, x = 61.2, y = 71.3, count = 40, item = 14047, itemName = "Runecloth", oi = 3, note = "Runecloth x40" },
		{ t = "collect", quest = 7642, title = "Collection of Goods", map = 1423, x = 45.06, y = 45.59, count = 10, item = 8836, itemName = "Arthas' Tears", oi = 2, note = "Arthas' Tears x10", spots = "44.2,51.8;41.4,32.8;47.2,19.9;54.8,26.9;65.2,27.5" },
		{ t = "collect", quest = 7642, title = "Collection of Goods", map = 1453, x = 61.2, y = 71.3, count = 6, item = 12360, itemName = "Arcanite Bar", oi = 4, note = "Arcanite Bars x6: an alchemist, or the Trade District Auction House" },
	} },
	{ title = "Stratholme Holy Water", note = "Stratholme is a dungeon for a group of five at 58-60, at the north end of the Eastern Plaguelands. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key.", goals = {
		{ t = "goto", map = 1423, x = 26.5, y = 10.4, text = "Stratholme" },
		{ t = "collect", quest = 7642, title = "Collection of Goods", map = 1423, x = 26.5, y = 10.4, count = 5, item = 13180, itemName = "Stratholme Holy Water", oi = 1, note = "Stratholme Supply Crates, inside" },
	} },
	{ title = "Grimand Elmore", note = "Bring the materials and 150 gold, taken at the hand-in. Grimand walks to his forge and hands you the Arcanite Barding.", goals = {
		{ t = "money", money = 1500000 },
		{ t = "turnin", quest = 7642, title = "Collection of Goods", npc = "Grimand Elmore", map = 1453, x = 59.73, y = 33.78, note = "Grimand Elmore: 150 gold" },
		{ t = "accept", quest = 7648, title = "Grimand's Finest Work", npc = "Grimand Elmore", map = 1453, x = 59.73, y = 33.78, qlvl = 60 },
	} },
	{ title = "Lord Grayson Shadowbreaker", note = "Lord Grayson keeps the barding for now: you get it back with the next quest.", goals = {
		{ t = "turnin", quest = 7648, title = "Grimand's Finest Work", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, note = "Lord Grayson Shadowbreaker: the Arcanite Barding" },
		{ t = "accept", quest = 7643, title = "Ancient Equine Spirit", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 60 },
	} },
	{ title = "Enriched Manna Biscuits", note = "The Argent Dawn quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the Argent Dawn is Friendly with you: Argent Quartermaster Lightspark at Chillwind Camp or Quartermaster Miranda Breechlock at Light's Hope Chapel. Scourgestones and the Plaguelands quests raise the standing.", goals = {
		{ t = "buy", npc = "Argent Quartermaster Lightspark", map = 1422, x = 42.84, y = 83.72, era = true, count = 20, item = 13724, itemName = "Enriched Manna Biscuit", note = "Enriched Manna Biscuits: Argent Quartermaster Lightspark, Chillwind Camp" },
	} },
	{ title = "Merideth Carlson", note = "Merideth Carlson breeds horses in Southshore's stable. She makes the Manna-Enriched Horse Feed from the 20 biscuits and 50 gold, taken at the hand-in.", goals = {
		{ t = "money", money = 500000 },
		{ t = "accept", quest = 7645, title = "Manna-Enriched Horse Feed", npc = "Merideth Carlson", map = 1424, x = 52.19, y = 55.48, era = true, qlvl = 60 },
		{ t = "buy", npc = "Argent Quartermaster Lightspark", map = 1422, x = 42.84, y = 83.72, era = true, count = 20, item = 13724, itemName = "Enriched Manna Biscuit", note = "Enriched Manna Biscuits: Argent Quartermaster Lightspark, Chillwind Camp" },
		{ t = "turnin", quest = 7645, title = "Manna-Enriched Horse Feed", npc = "Merideth Carlson", map = 1424, x = 52.19, y = 55.48, era = true, note = "Manna-Enriched Horse Feed" },
	} },
	{ title = "Dire Maul: Tendris Warpwood", note = "Dire Maul lies in central Feralas. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a Crescent Key (from Pusillin in Dire Maul East) or a rogue's lockpicking. Tendris Warpwood (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every Ironbark Protector still alive in the courtyard: kill them first. His death frees the Ancient Equine Spirit: talk to it to give it the horse feed and the Arcanite Barding, and it blesses the barding. A group of five at 60.", goals = {
		{ t = "goto", map = 1444, x = 60.3, y = 30.2, era = true, text = "Dire Maul West's door" },
		{ t = "kill", map = 1444, x = 60.3, y = 30.2, era = true, target = "Tendris Warpwood", group = true, note = "Tendris Warpwood, inside the West wing" },
		{ t = "turnin", quest = 7643, title = "Ancient Equine Spirit", npc = "Ancient Equine Spirit", map = 1444, x = 60.3, y = 30.2, era = true },
		{ t = "accept", quest = 7644, title = "Blessed Arcanite Barding", npc = "Ancient Equine Spirit", map = 1444, x = 60.3, y = 30.2, era = true, qlvl = 60 },
	} },
	{ title = "Lord Grayson Shadowbreaker", goals = {
		{ t = "turnin", quest = 7644, title = "Blessed Arcanite Barding", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22 },
		{ t = "accept", quest = 7646, title = "The Divination Scryer", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 60 },
	} },
	{ title = "Two diamonds", note = "An Azerothian Diamond comes from Thorium veins and obsidian, about one vein in a hundred; a Pristine Black Diamond drops rarely from elites of level 59 and up (Revanchion and Lord Blackwood about one kill in nine and one in a hundred). The Auction House is the usual source of both.", goals = {
		{ t = "collect", quest = 7646, title = "The Divination Scryer", map = 1444, x = 54.39, y = 66.38, era = true, count = 1, item = 12800, itemName = "Azerothian Diamond", oi = 1, spots = "62.2,69.3;61.6,84.1;73.5,63.6;47.8,57.5;45.4,69.4" },
		{ t = "collect", quest = 7646, title = "The Divination Scryer", map = 1424, x = 15.49, y = 82.46, era = true, count = 1, item = 18335, itemName = "Pristine Black Diamond", oi = 2, mobLevel = 60, spots = "15,82;16.9,83.8" },
	} },
	{ title = "Lord Grayson Shadowbreaker", note = "Lord Grayson hands you Lord Grayson's Satchel: open it for the Divination Scryer and the Blessed Arcanite Barding. Keep both.", goals = {
		{ t = "turnin", quest = 7646, title = "The Divination Scryer", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22 },
		{ t = "accept", quest = 7647, title = "Judgment and Redemption", npc = "Lord Grayson Shadowbreaker", map = 1453, x = 48.43, y = 50.22, qlvl = 60 },
		{ t = "use", quest = 7647, title = "Judgment and Redemption", map = 1453, x = 48.43, y = 50.22, item = 18804, itemName = "Lord Grayson's Satchel", oi = 2 },
		{ t = "collect", quest = 7647, title = "Judgment and Redemption", map = 1453, x = 48.43, y = 50.22, count = 1, item = 18792, itemName = "Blessed Arcanite Barding", oi = 2, group = true, note = "Blessed Arcanite Barding, from the satchel" },
	} },
	{ title = "The Great Ossuary", note = "Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands; the door needs the Skeleton Key (The Key to Scholomance). Clear the Great Ossuary, Rattlegore's room in the basement, then use the Divination Scryer at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with Seal of Wisdom, Justice, Righteousness and then Light, which stuns them. Death Knight Darkreaver (level 62 elite) comes after the last; he mind-controls players. Loot the Charger's Lost Soul, use it inside the Ossuary to redeem it, and give it and the Blessed Arcanite Barding to Darkreaver's Fallen Charger. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the Great Ossuary, after the mount, lets you fight him again.", goals = {
		{ t = "goto", map = 1422, x = 69.7, y = 73.2, era = true, text = "Scholomance" },
		{ t = "collect", map = 1422, x = 69.7, y = 73.2, era = true, item = 18749, itemName = "Charger's Lost Soul", group = true, note = "Charger's Lost Soul: Death Knight Darkreaver" },
		{ t = "use", quest = 7647, title = "Judgment and Redemption", map = 1422, x = 69.7, y = 73.2, era = true, item = 18749, itemName = "Charger's Lost Soul", oi = 1, note = "Charger's Lost Soul, inside the Great Ossuary" },
		{ t = "collect", quest = 7647, title = "Judgment and Redemption", map = 1422, x = 69.7, y = 73.2, era = true, count = 1, item = 18799, itemName = "Charger's Redeemed Soul", oi = 1 },
		{ t = "turnin", quest = 7647, title = "Judgment and Redemption", npc = "Darkreaver's Fallen Charger", map = 1422, x = 69.7, y = 73.2, era = true, note = "Darkreaver's Fallen Charger: Summon Charger" },
	} },
} end)

