		{ t = "kill", quest = 4182, title = "Dragonkin Menace", map = 1428, x = 89.5, y = 56.96, era = true, count = 1, target = "Black Drake", oi = 3, mobLevel = 52, group = true, spots = "89.5,57;89.9,43.9;84.9,28.5" },
