	} },
	{ title = "Lakeshire: Magistrate Solomon", note = "Magistrate Solomon waits in the town hall of Lakeshire; his next quest takes you to Stormwind Keep (the Stormwind guide follows it). Other Darnassus quests at this level, for when you pass by: Erelas Ambersky in Rut'theran Village has a wildkin chain into Winterspring (325 in all, with Ranshalla's escort), Arei's escort in Felwood pays 150 after the Emerald Sanctuary's chain, Mulgris Deepriver at the Writhing Haunt in the Western Plaguelands 100 for the Glyphed Oaken Branch, and Put Her Down in Upper Blackrock Spire 100 with a group.", goals = {
		{ t = "turnin", quest = 4183, title = "The True Masters", npc = "Magistrate Solomon", map = 1433, x = 24.9, y = 44.45 },
	} },
	{ title = "Morrowgrain (optional)", note = "Morrowgrain to Darnassus takes 10 Morrowgrain for 50, as often as you like, and pays in full at 60. The chain before it is level 50: 220. Innkeeper Saelienne sends you to Arch Druid Fandral Staghelm in the Cenarion Enclave; he wants 20 Un'Goro Soil. (The innkeepers of Stormwind and Ironforge give the same start.)", label = "dn-morrowgrain-start", goals = {
		{ t = "accept", quest = 3763, title = "Assisting Arch Druid Staghelm", npc = "Innkeeper Saelienne", map = 1457, x = 67.42, y = 15.65, era = true, qlvl = 50, note = "Assisting Arch Druid Staghelm, +10" },
	} },
	{ title = "Cenarion Enclave", when = {{ k = "done", label = "dn-morrowgrain-start" }}, goals = {
		{ t = "goto", map = 1457, x = 35.8, y = 11.6, era = true, text = "Cenarion Enclave" },
	} },
	{ title = "Morrowgrain (optional)", when = {{ k = "done", label = "dn-morrowgrain-start" }}, label = "dn-morrowgrain", goals = {
		{ t = "turnin", quest = 3763, title = "Assisting Arch Druid Staghelm", npc = "Arch Druid Fandral Staghelm", map = 1457, x = 34.81, y = 9.26, era = true },
		{ t = "accept", quest = 3764, title = "Un'Goro Soil", npc = "Arch Druid Fandral Staghelm", map = 1457, x = 34.81, y = 9.26, era = true, qlvl = 50, note = "Un'Goro Soil, +100" },
	} },
	{ title = "Un'Goro Crater: Un'Goro Soil", note = "Dig Un'Goro Soil from the dirt mounds all over the crater; most of the crater's beasts and the Gorishi silithids drop it too, about one kill in three. Take far more than 20: every pouch use takes 2, about 18 for each 10 Morrowgrain.", when = {{ k = "done", label = "dn-morrowgrain" }}, goals = {
		{ t = "collect", quest = 3764, title = "Un'Goro Soil", map = 1449, x = 46.7, y = 52.71, era = true, count = 20, item = 11018, itemName = "Un'Goro Soil", oi = 1, spots = "45.9,53.7;35.2,40.8;30,56.8;31.7,77.5;50.5,90.1" },
	} },
	{ title = "Darnassus: Morrowgrain Research", note = "Jenal, beside Fandral in the Cenarion Enclave, takes the soil. Mathrengyl Bearwalker sells the Evergreen Pouch and Packets of Tharlendris Seeds. With a seed packet and 2 Un'Goro Soil in your bags, use the pouch to grow an Evergreen Herb Casing and open it: about one casing in three holds Morrowgrain (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things.", when = {{ k = "done", label = "dn-morrowgrain" }}, goals = {
		{ t = "turnin", quest = 3764, title = "Un'Goro Soil", npc = "Jenal", map = 1457, x = 31.49, y = 8.23, era = true },
	} },
	{ title = "Cenarion Enclave", when = {{ k = "done", label = "dn-morrowgrain" }}, goals = {
		{ t = "goto", map = 1457, x = 35.8, y = 11.6, era = true, text = "Cenarion Enclave" },
	} },
	{ title = "Darnassus: Morrowgrain Research", note = "Jenal, beside Fandral in the Cenarion Enclave, takes the soil. Mathrengyl Bearwalker sells the Evergreen Pouch and Packets of Tharlendris Seeds. With a seed packet and 2 Un'Goro Soil in your bags, use the pouch to grow an Evergreen Herb Casing and open it: about one casing in three holds Morrowgrain (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things.", when = {{ k = "done", label = "dn-morrowgrain" }}, goals = {
		{ t = "accept", quest = 3781, title = "Morrowgrain Research", npc = "Arch Druid Fandral Staghelm", map = 1457, x = 34.81, y = 9.26, era = true, qlvl = 50, note = "Morrowgrain Research, +10" },
