		{ t = "collect", quest = 3785, title = "Morrowgrain Research", map = 1457, x = 35.4, y = 8.4, era = true, count = 10, item = 11040, itemName = "Morrowgrain", oi = 1, note = "Morrowgrain: grow it here and open the casings" },
		{ t = "turnin", quest = 3785, title = "Morrowgrain Research", npc = "Mathrengyl Bearwalker", map = 1457, x = 35.37, y = 8.4, era = true },
	} },
	{ title = "Morrowgrain to Darnassus", note = "Every 10 Morrowgrain: 50 reputation at Mathrengyl Bearwalker. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 Un'Goro Soil and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the Runecloth. Quintis Jonespyre at Feathermoon Stronghold in Feralas takes Morrowgrain at the same rate, 25 for 5, after his own quest.", when = {{ k = "done", label = "dn-morrowgrain" }}, goals = {
		{ t = "goto", map = 1457, x = 35.8, y = 11.6, era = true, optional = true, text = "Cenarion Enclave" },
		{ t = "collect", map = 1457, x = 35.4, y = 8.4, era = true, count = 10, item = 11040, itemName = "Morrowgrain", optional = true },
		{ t = "turnin", quest = 3803, title = "Morrowgrain to Darnassus", npc = "Mathrengyl Bearwalker", map = 1457, x = 35.37, y = 8.4, era = true, qlvl = 55, optional = true, note = "Mathrengyl Bearwalker: Morrowgrain to Darnassus, +50" },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). The True Masters and the Morrowgrain chain above take 8 turn-ins off, and every 10 Morrowgrain you hand in counts as one more; each hub you did takes 20 to 28 more off. More quests pay Darnassus, in full while they are no more than 5 levels below you: the rest of Darkshore (about 3,400 more), Astranaar in Ashenvale (about 3,900) and Feathermoon in Feralas (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7801, title = "Additional Runecloth", npc = "Raedon Duskstriker", map = 1457, x = 64.02, y = 23, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Darnassus", faction = 69, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored: in Classic Darnassus's vendors take 10% off for you, Lelanai's nightsabers (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7801, title = "Additional Runecloth", npc = "Raedon Duskstriker", map = 1457, x = 64.02, y = 23, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Darnassus", faction = 69, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 Runecloth. At Exalted, Lelanai at the Cenarion Enclave in Darnassus sells her nightsabers to other races in Classic; the Saber and Swift Saber guides cover them.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7801, title = "Additional Runecloth", npc = "Raedon Duskstriker", map = 1457, x = 64.02, y = 23, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Darnassus", faction = 69, standing = 8 },
	} },
} end)

Waypost.RegisterSteps("reputation/gnomeregan-exiles", function() return {
	{ title = "Bubulo Acerbus, the cloth quartermaster", note = "Bubulo Acerbus takes cloth for the Gnomeregan Exiles; he stands in Tinker Town in Ironforge, by the tram. Each first donation of 60 Wool, Silk, Mageweave and Runecloth pays 150 reputation once; after the Runecloth one, Additional Runecloth pays 50 for every 20 Runecloth, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do Dun Morogh (levels 1-12) and Gaxim Rustfizzle's quests in Stonetalon (20-25) while you level. After the donations come Laris Geardawdle's ooze quests and Overmaster Pyron (400), then the optional Dun Morogh hubs, best rate first: Coldridge Valley (about 38 a minute at full value), Kharanos (26), the quarry (17). Every Gnomeregan gain also gives a quarter as much to Stormwind, Ironforge and Darnassus, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain.", goals = {
		{ t = "level", level = 12 },
		{ t = "collect", count = 60, item = 2592, itemName = "Wool Cloth", note = "Wool Cloth: troggs, gnolls and kobolds in Loch Modan and the Wetlands" },
		{ t = "accept", quest = 7807, title = "A Donation of Wool", npc = "Bubulo Acerbus", map = 1455, x = 74.09, y = 48.22, era = true, qlvl = 60 },
		{ t = "turnin", quest = 7807, title = "A Donation of Wool", npc = "Bubulo Acerbus", map = 1455, x = 74.09, y = 48.22, era = true },
