	{ title = "Morgan's Vigil: Jalinda Sprig", note = "Jalinda Sprig at Morgan's Vigil, in the south-east of the Burning Steppes, wants Overmaster Pyron dead: 100 Gnomeregan reputation (level 52: in Classic 40 at 60). Her next quest, Incendius!, needs a Blackrock Depths group: 100 more, in full.", goals = {
		{ t = "accept", quest = 4262, title = "Overmaster Pyron", npc = "Jalinda Sprig", map = 1428, x = 85.41, y = 70.06, era = true, qlvl = 52, note = "Overmaster Pyron, +100" },
	} },
	{ title = "Blackrock Mountain: Overmaster Pyron", note = "Blackrock Mountain stands in the west of the Burning Steppes. Overmaster Pyron, a fire elemental, walks the lava paths inside it, near the door of Blackrock Depths but outside the dungeon: at 60 you take him alone.", goals = {
		{ t = "kill", quest = 4262, title = "Overmaster Pyron", map = 1415, x = 46.82, y = 67.71, era = true, count = 1, target = "Overmaster Pyron", oi = 1, group = true },
