	{ title = "Morgan's Vigil: hand in", goals = {
		{ t = "turnin", quest = 4262, title = "Overmaster Pyron", npc = "Jalinda Sprig", map = 1428, x = 85.41, y = 70.06, era = true },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a Human, Dwarf or Night Elf stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Gnomes start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). Laris's and Jalinda's quests above take 8 turn-ins off; each Dun Morogh hub you did takes 10 to 26 more off. Outside Dun Morogh Gnomeregan pays little: Gaxim Rustfizzle's quests in Stonetalon (about 500) and Tinker Town's Gnomeregan dungeon quests. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7812, title = "Additional Runecloth", npc = "Bubulo Acerbus", map = 1455, x = 74.09, y = 48.22, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Gnomeregan Exiles", faction = 54, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored: in Classic the Gnomeregan Exiles' vendors take 10% off for you, Milli Featherwhistle's mechanostriders (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7812, title = "Additional Runecloth", npc = "Bubulo Acerbus", map = 1455, x = 74.09, y = 48.22, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Gnomeregan Exiles", faction = 54, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 Runecloth. At Exalted, Milli Featherwhistle at Steelgrill's Depot in Dun Morogh sells her mechanostriders to other races in Classic; the Mechanostrider and Swift Mechanostrider guides cover them.", goals = {
