		{ t = "interact", quest = 3825, title = "Ogre Head On A Stick = Party", npc = "Soft Dirt Mound", map = 1428, x = 81, y = 46.79, era = true, oi = 1 },
		{ t = "turnin", quest = 3825, title = "Ogre Head On A Stick = Party", npc = "Oralius", map = 1428, x = 84.56, y = 68.68, era = true },
	} },
	{ title = "Ironforge: Archesonus again", note = "With a group, Blackrock Depths pays more: Archesonus's chain goes on with Kharan Mighthammer (100) and The Fate of the Kingdom (Emperor Thaurissan, 150), and Oralius takes 20 Dark Iron Fanny Packs from the dwarves inside (The Good Stuff, 100). Alterac Valley, from level 51, pays Ironforge too: its one-time quests about 1,900 as your Stormpike standing grows (the Alterac Valley guide walks them), and inside the battle 25 for every 10 Irondeep or Coldtooth Supplies and 50 for 5 Storm Crystals, as often as you like.", goals = {
		{ t = "turnin", quest = 3701, title = "The Smoldering Ruins of Thaurissan", npc = "Royal Historian Archesonus", map = 1455, x = 38.37, y = 55.31, era = true },
	} },
	{ title = "Winterspring: Enraged Wildkin", note = "Harlo Wigglesworth in Everlook sends you west to Jaron Stoneshaper at Starfall Village. Jaron's damaged crate and wrecked wagon lie at Mazthoril, down the valley to the south-east; his supplies lie around the wagon and the owlbeasts nearby carry his amulet. The last quest is level 59: 100 Ironforge in full.", goals = {
		{ t = "accept", quest = 6604, title = "Enraged Wildkin", npc = "Harlo Wigglesworth", map = 1452, x = 61.12, y = 38.43, era = true, qlvl = 59 },
		{ t = "turnin", quest = 6604, title = "Enraged Wildkin", npc = "Jaron Stoneshaper", map = 1452, x = 52.14, y = 30.43, era = true },
		{ t = "accept", quest = 4861, title = "Enraged Wildkin", npc = "Jaron Stoneshaper", map = 1452, x = 52.14, y = 30.43, era = true, qlvl = 59 },
		{ t = "turnin", quest = 4861, title = "Enraged Wildkin", npc = "Damaged Crate", map = 1452, x = 58.99, y = 59.79, era = true },
		{ t = "accept", quest = 4863, title = "Enraged Wildkin", npc = "Damaged Crate", map = 1452, x = 58.99, y = 59.79, era = true, qlvl = 59 },
		{ t = "turnin", quest = 4863, title = "Enraged Wildkin", npc = "Jaron's Wagon", map = 1452, x = 61.44, y = 60.68, era = true },
		{ t = "accept", quest = 4864, title = "Enraged Wildkin", npc = "Jaron's Wagon", map = 1452, x = 61.44, y = 60.68, era = true, qlvl = 59, note = "Enraged Wildkin, +100" },
		{ t = "collect", quest = 4864, title = "Enraged Wildkin", map = 1452, x = 61.41, y = 60.73, era = true, count = 1, item = 12525, itemName = "Jaron's Supplies", oi = 1 },
		{ t = "collect", quest = 4864, title = "Enraged Wildkin", map = 1452, x = 59.41, y = 59.79, era = true, count = 1, item = 12524, itemName = "Blue-feathered Amulet", oi = 2, mobLevel = 59, spots = "58.9,59.6;64.2,59.1;64.9,61.3;66.3,60.2;64.8,64.6" },
		{ t = "turnin", quest = 4864, title = "Enraged Wildkin", npc = "Jaron Stoneshaper", map = 1452, x = 52.14, y = 30.43, era = true },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a Human, Night Elf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Dwarves start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). The level 52-59 quests above take 12 turn-ins off; each Dun Morogh hub you did takes 10 to 26 more off. More hubs pay Ironforge, in full while they are no more than 5 levels below you: Thelsamar in Loch Modan (about 3,500 in all) and Menethil Harbor in the Wetlands (about 2,500). From level 51 Alterac Valley's one-time quests add about 1,900. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7806, title = "Additional Runecloth", npc = "Mistina Steelshield", map = 1455, x = 43.22, y = 31.57, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Ironforge", faction = 47, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored: in Classic Ironforge's vendors take 10% off for you, Veron Amberstill's rams (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7806, title = "Additional Runecloth", npc = "Mistina Steelshield", map = 1455, x = 43.22, y = 31.57, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Ironforge", faction = 47, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 Runecloth. At Exalted, Veron Amberstill at Amberstill Ranch in eastern Dun Morogh sells his rams to other races in Classic; the Ram and Swift Ram guides cover them.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7806, title = "Additional Runecloth", npc = "Mistina Steelshield", map = 1455, x = 43.22, y = 31.57, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Ironforge", faction = 47, standing = 8 },
	} },
} end)

Waypost.RegisterSteps("reputation/kirin-tor", function() return {
	{ title = "Skyborne: the recipes now", note = "Alliance Skyborne start Friendly with the Kirin Tor, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so Archmage Alvareaux sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the Kirin Tor banners in Dalaran, past the Sky Enclave. Buy the ones for your profession.", only = { races = {"Skyborne"} }, goals = {
		{ t = "vendor", npc = "Archmage Alvareaux", map = 1416, x = 13.92, y = 63.29, era = true },
