	{ title = "An Alarming Request", note = "Emissary Jacques of the Kirin Tor waits in Southshore. He sends you to Archmage Modera's image by the shore of Lordamere Lake, outside Dalaran's walls. The Kirin Tor quests start at level 24 to 30 and pay full reputation at any level in Forever.", goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 92432, title = "An Alarming Request", npc = "Emissary Jacques", map = 1424, x = 48.34, y = 60.04, era = true, qlvl = 33 },
	} },
	{ title = "Archmage Modera's image", goals = {
		{ t = "turnin", quest = 92432, title = "An Alarming Request", npc = "Image of Archmage Modera", map = 1421, x = 68.62, y = 45.18, era = true },
		{ t = "accept", quest = 92458, title = "Heart of Disruption", npc = "Image of Archmage Modera", map = 1421, x = 68.62, y = 45.18, era = true, qlvl = 33, group = true, note = "you get the Dalaran Sewer Key with it" },
		{ t = "accept", quest = 92457, title = "Starving Arcane", npc = "Image of Archmage Modera", map = 1421, x = 68.62, y = 45.18, era = true, qlvl = 33, group = true },
	} },
	{ title = "The City of Dalaran", note = "The City of Dalaran is a dungeon for levels 28 to 33: go in through the sewers with the key Modera gave you. The arcane elementals throughout the city count for Starving Arcane. The Shade of the Archmage, the last boss, waits in the Purple Parlor above the Violet Citadel (a portal by Archmage Modera in the Citadel takes you up) and drops the Arcane Mote. Beta players saw every kill in the dungeon pay Kirin Tor reputation, the bosses the most. Group of five advised below level 35.", goals = {
