		{ t = "kill", quest = 92457, title = "Starving Arcane", map = 1416, x = 8.5, y = 59.3, count = 8, target = "Saturated Remnant", oi = 2, group = true },
		{ t = "kill", quest = 92457, title = "Starving Arcane", map = 1416, x = 8.5, y = 59.3, count = 8, target = "Mana Echo", oi = 3, group = true },
