	} },
	{ title = "Archmage Celindra", note = "Archmage Celindra waits in the Violet Citadel in Dalaran.", goals = {
		{ t = "turnin", quest = 92459, title = "Friend of the Kirin Tor", npc = "Archmage Celindra", map = 1416, x = 14.15, y = 60.05, era = true },
	} },
	{ title = "Past Due", note = "Magus Olvek in Dalaran wants a book back from Arcanist Doan, the last boss of the Scarlet Monastery's Library (levels 33 to 41), in Tirisfal Glades.", goals = {
