		{ t = "buy", npc = "Archmage Alvareaux", map = 1416, x = 13.92, y = 63.29, era = true, item = 276986, itemName = "Pattern: Azure Gustwoven Hood", optional = true, note = "Pattern: Azure Gustwoven Hood (Leatherworking)" },
