		{ t = "buy", npc = "Archmage Alvareaux", map = 1416, x = 13.92, y = 63.29, era = true, item = 276988, itemName = "Pattern: Azure Windraveled Cover", optional = true, note = "Pattern: Azure Windraveled Cover (Leatherworking)" },
		{ t = "buy", npc = "Archmage Alvareaux", map = 1416, x = 13.92, y = 63.29, era = true, item = 276989, itemName = "Pattern: Azure Windraveled Drapes", optional = true, note = "Pattern: Azure Windraveled Drapes (Leatherworking)" },
		{ t = "buy", npc = "Archmage Alvareaux", map = 1416, x = 13.92, y = 63.29, era = true, item = 276990, itemName = "Pattern: Azure Stormsewn Cowl", optional = true, note = "Pattern: Azure Stormsewn Cowl (Tailoring)" },
