	{ title = "Lakeshire: Solomon again", note = "With a group the chain goes on into Blackrock Depths: Marshal Windsor, Jail Break! and The Great Masquerade back in Stormwind pay about 750 Stormwind more, Maxwell's Mission (Lower Blackrock Spire) 250, Delivery to Ridgewell 135. Order Must Be Restored (Nathanos Blightcaller in the Eastern Plaguelands) pays 200, The Key to Scholomance 200; Onyxia's head 400 and Nefarian's 200 when the raids open.", goals = {
		{ t = "turnin", quest = 4186, title = "The True Masters", npc = "Magistrate Solomon", map = 1433, x = 24.9, y = 44.45 },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 50 reputation for 20 Runecloth, as often as you like. After the four first donations a non-Human stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 Runecloth (Humans start 900 higher: 88 turn-ins; a Skyborne's Exploring the Alliance paid 100, two fewer). The level 52-58 quests above take 23 turn-ins off; every Elwynn hub you did takes 20 to 30 more off. More quest hubs pay Stormwind, in full while they are no more than 5 levels below you: Westfall (about 2,500 in all), Redridge's Lakeshire (about 3,000) and Duskwood's Darkshire (about 2,900). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your Runecloth at once.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7796, title = "Additional Runecloth", npc = "Clavicus Knavingham", map = 1453, x = 53.93, y = 81.69, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Stormwind", faction = 72, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored: in Classic Stormwind's vendors take 10% off for you, Katie Hunter's horses (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 Runecloth.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7796, title = "Additional Runecloth", npc = "Clavicus Knavingham", map = 1453, x = 53.93, y = 81.69, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Stormwind", faction = 72, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 Runecloth. At Exalted, Katie Hunter at Eastvale Logging Camp sells her horses to other races in Classic; the Horse and Swift Horse guides cover them.", goals = {
		{ t = "collect", count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7796, title = "Additional Runecloth", npc = "Clavicus Knavingham", map = 1453, x = 53.93, y = 81.69, qlvl = 60, optional = true },
