		{ t = "kill", quest = 5201, title = "Winterfall Intrusion", map = 1452, x = 67.37, y = 35.22, era = true, count = 5, target = "Winterfall Shaman", oi = 1, mobLevel = 57, optional = true, spots = "67.5,35.4;68,37.5;69.5,38.3;67.5,39.8" },
