Waypost.RegisterSteps("class/hunter/taming-the-beast-horde", function() return {
	{ title = "Thotar in Razor Hill", note = "At 10 go to Thotar, the hunter trainer inside the barracks in Razor Hill. If Sian'dur in Orgrimmar, Kali Remik in Sen'jin Village or Kary Thunderhorn in Thunder Bluff hands you The Hunter's Path, take it and hand it to Thotar for a little experience; it is only a pointer, and you can take the first rod without it.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 6062, title = "Taming the Beast", npc = "Thotar", map = 1411, x = 51.85, y = 43.49, era = true, qlvl = 10, note = "Thotar: the first Taming Rod" },
	} },
	{ title = "Dire Mottled Boar", note = "Dire Mottled Boars (level 6-7) roam just north and west of Razor Hill. How the rod works: target a living beast, use the Taming Rod from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from Thotar. The boars charge from 20 yards, so start with the rod, not Auto Shot. The tamed boar becomes your pet for practice. Keep each rod: it goes back to Thotar.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "kill", quest = 6062, title = "Taming the Beast", map = 1411, x = 53.43, y = 46.16, era = true, count = 1, target = "Dire Mottled Boar", oi = 1, mobLevel = 7, note = "Use the Taming Rod on a living boar", text = "Tame Dire Mottled Boar", spots = "52.6,46.1;51.6,55.6;53.9,62.6;54.1,68.8;51.8,78.1" },
		{ t = "turnin", quest = 6062, title = "Taming the Beast", npc = "Thotar", map = 1411, x = 51.85, y = 43.49, era = true },
		{ t = "accept", quest = 6083, title = "Taming the Beast", npc = "Thotar", map = 1411, x = 51.85, y = 43.49, era = true, qlvl = 10 },
	} },
	{ title = "Surf Crawler", note = "First dismiss the boar (right-click your pet's portrait, Dismiss Pet): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around Sen'jin Village and the Echo Isles; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "kill", quest = 6083, title = "Taming the Beast", map = 1411, x = 58.85, y = 28.34, era = true, count = 1, target = "Surf Crawler", oi = 1, mobLevel = 8, note = "Use the Taming Rod on a living Surf Crawler", text = "Tame Surf Crawler", spots = "59.9,26.5;60.9,17.7;70.8,70.2;65.4,73.6;65.1,79.1" },
		{ t = "turnin", quest = 6083, title = "Taming the Beast", npc = "Thotar", map = 1411, x = 51.85, y = 43.49, era = true },
