	{ title = "Armored Scorpid", note = "Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of Razor Hill, some just south of the road west out of town; Track Beasts shows them. Their hits can break the channel: start at full health and keep still.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "kill", quest = 6082, title = "Taming the Beast", map = 1411, x = 50.99, y = 37.7, era = true, count = 1, target = "Armored Scorpid", oi = 1, mobLevel = 8, note = "Use the Taming Rod on a living scorpid", text = "Tame Armored Scorpid", spots = "51,37.7;54.6,35.2;57.2,29.6;55.6,22.3;51.3,19.6" },
		{ t = "turnin", quest = 6082, title = "Taming the Beast", npc = "Thotar", map = 1411, x = 51.85, y = 43.49, era = true, note = "Thotar: Tame Beast" },
		{ t = "accept", quest = 6081, title = "Training the Beast", npc = "Thotar", map = 1411, x = 51.85, y = 43.49, era = true, qlvl = 10 },
	} },
	{ title = "Ormak Grimshot in Orgrimmar", note = "Follow the road north to Orgrimmar's gate. Ormak Grimshot stands with the hunter trainers in the Valley of Honor, up the ramp at the city's east side; Xao'tsu, the pet trainer, is a few steps north of him.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "turnin", quest = 6081, title = "Training the Beast", npc = "Ormak Grimshot", map = 1454, x = 66.05, y = 18.53, era = true, note = "Ormak Grimshot: Beast Training" },
	} },
	{ title = "Yaw Sharpmane at Bloodhoof", note = "At 10 go to Yaw Sharpmane, who stands at the north edge of Bloodhoof Village. The Hunter's Path from Kary Thunderhorn in Thunder Bluff, Sian'dur in Orgrimmar or Thotar in Razor Hill also leads here, for a little experience; it is only a pointer.", only = { races = {"Tauren"} }, goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 6061, title = "Taming the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65, qlvl = 10, note = "Yaw Sharpmane: the first Taming Rod" },
	} },
	{ title = "Adult Plainstrider", note = "Adult Plainstriders (level 6-7) walk the plains south-west and north-west of Bloodhoof Village. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw.", only = { races = {"Tauren"} }, goals = {
		{ t = "kill", quest = 6061, title = "Taming the Beast", map = 1412, x = 42.87, y = 59.08, count = 1, target = "Adult Plainstrider", oi = 1, mobLevel = 8, note = "Use the Taming Rod on a living plainstrider", text = "Tame Adult Plainstrider", spots = "42.9,59.1;37.7,57.1;36.8,66.6;42.8,69.8;49.9,66.4" },
		{ t = "turnin", quest = 6061, title = "Taming the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65 },
		{ t = "accept", quest = 6087, title = "Taming the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65, qlvl = 10 },
	} },
	{ title = "Prairie Stalker", note = "Dismiss the plainstrider first (right-click the pet portrait, Dismiss Pet): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of Bloodhoof Village.", only = { races = {"Tauren"} }, goals = {
		{ t = "kill", quest = 6087, title = "Taming the Beast", map = 1412, x = 44.57, y = 54.12, count = 1, target = "Prairie Stalker", oi = 1, mobLevel = 8, note = "Use the Taming Rod on a living stalker", text = "Tame Prairie Stalker", spots = "46.1,53.4;41.7,55;36.6,55.6;39.6,47;44.4,46.9" },
		{ t = "turnin", quest = 6087, title = "Taming the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65 },
		{ t = "accept", quest = 6088, title = "Taming the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65, qlvl = 10 },
	} },
	{ title = "Swoop", note = "Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A Swoop's knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it.", only = { races = {"Tauren"} }, goals = {
		{ t = "kill", quest = 6088, title = "Taming the Beast", map = 1412, x = 45.53, y = 54.61, count = 1, target = "Swoop", oi = 1, mobLevel = 9, note = "Use the Taming Rod on a living Swoop", text = "Tame Swoop", spots = "43.8,55.1;42.2,51.4;42.7,46.4;46.3,43.3;51.1,43.6" },
		{ t = "turnin", quest = 6088, title = "Taming the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65, note = "Yaw Sharpmane: Tame Beast" },
		{ t = "accept", quest = 6089, title = "Training the Beast", npc = "Yaw Sharpmane", map = 1412, x = 46.93, y = 59.65, qlvl = 10 },
	} },
	{ title = "Holt Thunderhorn in Thunder Bluff", note = "Head north to Thunder Bluff and take a lift up. Holt Thunderhorn stands with the hunter trainers on Hunter Rise; Hesuwa Thunderhorn, the pet trainer, is nearby.", only = { races = {"Tauren"} }, goals = {
		{ t = "turnin", quest = 6089, title = "Training the Beast", npc = "Holt Thunderhorn", map = 1456, x = 57.3, y = 89.79, era = true, note = "Holt Thunderhorn: Beast Training" },
	} },
	{ title = "Elayaa Easewind", note = "At 10, Elayaa Easewind, a hunter trainer on Zephras Isle, may send you on to Valanaar with Taming the Beast. It is only a pointer: skip it if you are already in Valanaar.", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 94007, title = "Taming the Beast", npc = "Elayaa Easewind", map = 2521, x = 45.26, y = 44.24, qlvl = 10, optional = true },
	} },
	{ title = "Quel'ana Quickgale in Valanaar", note = "Quel'ana Quickgale stands with the trainers by Valanaar's west gate, Quel'dora Quickgale beside her.", only = { races = {"Skyborne"} }, goals = {
		{ t = "turnin", quest = 94007, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63, optional = true },
		{ t = "accept", quest = 94978, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63, qlvl = 10, note = "Quel'ana Quickgale: the first Taming Rod" },
	} },
	{ title = "Windsong Crawler", note = "Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of Valanaar, among the crabs. How the rod works: target a living crawler, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs a charge. Killing one does not count.", only = { races = {"Skyborne"} }, goals = {
		{ t = "kill", quest = 94978, title = "Taming the Beast", map = 2521, x = 53.8, y = 77, count = 1, target = "Windsong Crawler", oi = 1, mobLevel = 9, note = "Use the Taming Rod on a living crawler", text = "Tame Windsong Crawler", spots = "53.6,77.4;49.6,67;49.8,60;53.2,59.9;56.1,56.3" },
		{ t = "turnin", quest = 94978, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63 },
		{ t = "accept", quest = 94979, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63, qlvl = 10 },
	} },
	{ title = "Ornery Galestrider", note = "Dismiss the crawler first (right-click the pet portrait, Dismiss Pet). Ornery Galestriders graze in the Gustberry Lowlands, the fields a short walk west and south-west of Valanaar.", only = { races = {"Skyborne"} }, goals = {
		{ t = "kill", quest = 94979, title = "Taming the Beast", map = 2521, x = 59.17, y = 74, count = 1, target = "Ornery Galestrider", oi = 1, mobLevel = 9, note = "Use the Taming Rod on a living galestrider", text = "Tame Ornery Galestrider", spots = "59,73.3;58.1,67.8;59.4,63.6;56.6,61;61.7,67.2" },
		{ t = "turnin", quest = 94979, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63 },
		{ t = "accept", quest = 94013, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63, qlvl = 10 },
	} },
	{ title = "Vuldren Alpha", note = "Dismiss the galestrider. Vuldren Alphas hunt in the same Gustberry Lowlands, a little further south.", only = { races = {"Skyborne"} }, goals = {
		{ t = "kill", quest = 94013, title = "Taming the Beast", map = 2521, x = 59.69, y = 72.66, count = 1, target = "Vuldren Alpha", oi = 1, mobLevel = 10, note = "Use the Taming Rod on a living alpha", text = "Tame Vuldren Alpha", spots = "60.6,72.6;58.2,76;53.6,74.7;53.2,80.5;51.5,86.2" },
		{ t = "turnin", quest = 94013, title = "Taming the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63, note = "Quel'ana Quickgale: Tame Beast" },
		{ t = "accept", quest = 94050, title = "Training the Beast", npc = "Quel'ana Quickgale", map = 2521, x = 59.56, y = 72.63, qlvl = 10 },
		{ t = "turnin", quest = 94050, title = "Training the Beast", npc = "Quel'dora Quickgale", map = 2521, x = 59.92, y = 72.87, note = "Quel'dora Quickgale, beside her: Beast Training" },
	} },
	{ title = "Your first pet", note = "Tame Beast works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and Bite) and a boar takes more punishment.", goals = {
		{ t = "task", optional = true, text = "Tame a beast of your level to keep" },
		{ t = "note", only = { races = {"Orc", "Troll"} }, text = "Near Razor Hill: Durotar Tigers (cats, level 7-8) roam the south of Durotar, from Sen'jin Village down the coast; Venomtail Scorpids (9-10) the north-west toward Orgrimmar; at 11-12, Savannah Huntresses (cats) prowl the plains around the Crossroads in the Barrens." },
		{ t = "note", only = { races = {"Tauren"} }, text = "Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern Mulgore; at 11-12, Savannah Huntresses (cats) prowl around the Crossroads in the Barrens." },
		{ t = "note", only = { races = {"Skyborne"} }, text = "Near Valanaar: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the Gustberry Lowlands; Shriekling Matriarchs (raptors, level 9) nest just west of Valanaar; Shadowgale Urseras (bears, 10-11) roam the north of Zephras Isle." },
		{ t = "note", text = "Feed Pet: open your spellbook, cast Feed Pet and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Grimtak the butcher and Innkeeper Grosk in Razor Hill sell meat, Kaga Mistrunner in Thunder Bluff and the innkeepers on Zephras Isle too; Bloodhoof's innkeeper and bakers sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat." },
		{ t = "note", text = "Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away." },
		{ t = "note", text = "Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in Beast Training (pet level times loyalty rank minus one)." },
		{ t = "note", text = "Beast Training (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Shoja'my in Razor Hill, Seikwa at Bloodhoof, Genn Fairweather on Zephras Isle, Xon'cha in Orgrimmar), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with Beast Training. A pet holds four active abilities at most." },
		{ t = "note", text = "Pet trainers sell Growl ranks and resistances. Horde: Harruk in Razor Hill, Reban Freerunner at Bloodhoof, Xao'tsu in Orgrimmar's Valley of Honor, Hesuwa Thunderhorn on Thunder Bluff's Hunter Rise, Quel'dora Quickgale in Valanaar, later Grokor in Stonard and Zudd at Grom'gol." },
		{ t = "note", text = "Call Pet, Dismiss Pet and Revive Pet are in your spellbook now; Mend Pet comes from your trainer at 12. A dead pet needs Revive Pet; one that is away more than about 100 yards is dismissed and comes back with Call Pet." },
	} },
} end)

Waypost.RegisterSteps("class/mage/ju-ju-heaps", function() return {
	{ title = "Un'thuwa", note = "Un'thuwa, the troll mage trainer, stands in Sen'jin Village on the Durotar coast south of Razor Hill. Orcs coming from Orgrimmar can take Speak with Un'thuwa from Uthel'nay in the Valley of Spirits first; it is only a pointer and Un'thuwa gives Ju-Ju Heaps without it. Taking it shuts out the Undercity's Balnir Farmstead.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 1884, title = "Ju-Ju Heaps", npc = "Un'Thuwa", map = 1411, x = 56.31, y = 75.11, era = true, qlvl = 10, note = "Un'thuwa" },
	} },
	{ title = "Cain Firesong (Brill)", note = "At 10 Cain Firesong, the Brill mage trainer upstairs in the Gallows' End Tavern, sends you to Anastasia Hartwell in the Undercity. Taking it shuts out Ju-Ju Heaps; if Speak with Un'thuwa (from Orgrimmar or Thunder Bluff) is in your log, abandon it first or Cain cannot give you this one. (A Troll who took this one in Brill follows the Balnir steps; an Undead who took Ju-Ju Heaps in Sen'jin, the Echo Isles steps.)", only = { races = {"Scourge"} }, goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 1881, title = "Speak with Anastasia", npc = "Cain Firesong", map = 1420, x = 61.97, y = 52.47, era = true, qlvl = 10 },
	} },
	{ title = "The Ju-Ju Heaps", note = "Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed.", only = { races = {"Orc", "Troll", "Scourge"} }, when = {{ k = "onquest", q = {1884} }}, goals = {
		{ t = "interact", quest = 1884, title = "Ju-Ju Heaps", npc = "Ju-Ju Heap", map = 1411, x = 67.81, y = 84.27, era = true, oi = 1, note = "Ju-Ju Heap, four of them", spots = "68.1,83.1;67.1,87.1" },
	} },
	{ title = "Back to Un'thuwa", note = "The orb is an off-hand for a one-hand weapon; the staff is a two-hander.", only = { races = {"Orc", "Troll", "Scourge"} }, when = {{ k = "onquest", q = {1884} }}, goals = {
		{ t = "turnin", quest = 1884, title = "Ju-Ju Heaps", npc = "Un'Thuwa", map = 1411, x = 56.31, y = 75.11, era = true, note = "Un'thuwa: Ley Orb or Ley Staff" },
	} },
	{ title = "Anastasia Hartwell", note = "Walk south from Brill to the Ruins of Lordaeron and take the lift down into the Undercity. Anastasia stands in the Magic Quarter, the north-east ring of the city.", only = { races = {"Scourge", "Troll"} }, when = {{ k = "onquest", q = {1881} }}, goals = {
		{ t = "turnin", quest = 1881, title = "Speak with Anastasia", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true },
		{ t = "accept", quest = 1882, title = "The Balnir Farmstead", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true, qlvl = 10 },
	} },
	{ title = "The Balnir Farmstead", note = "The Balnir Farmstead lies south-east of Brill, south of the road east to the Bulwark. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no Herbalism. They come back within seconds.", only = { races = {"Scourge", "Troll"} }, when = {{ k = "onquest", q = {1882} }}, goals = {
		{ t = "collect", quest = 1882, title = "The Balnir Farmstead", map = 1420, x = 77.47, y = 61.89, era = true, count = 1, item = 7227, itemName = "Balnir Snapdragons", oi = 1 },
	} },
	{ title = "Back to Anastasia", only = { races = {"Scourge", "Troll"} }, when = {{ k = "onquest", q = {1882} }}, goals = {
		{ t = "turnin", quest = 1882, title = "The Balnir Farmstead", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true, note = "Anastasia Hartwell: Arcane Orb or Arcane Staff" },
	} },
} end)

Waypost.RegisterSteps("class/mage/nether-lace-garment", function() return {
	{ title = "Anastasia Hartwell", note = "Anastasia Hartwell stands in the Undercity's Magic Quarter. Orcs and Trolls use Teleport: Undercity or take the zeppelin from Orgrimmar to Tirisfal Glades for her.", goals = {
		{ t = "level", level = 26 },
		{ t = "accept", quest = 1943, title = "Speak with Deino", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true, qlvl = 26 },
	} },
	{ title = "Deino", note = "Take the zeppelin to Orgrimmar (or use Teleport: Orgrimmar, which lands you on the upper floor of Darkbriar Lodge). Deino stands with the mage trainers on the lower floor of Darkbriar Lodge in the Valley of Spirits. She hands you Deino's Flask.", goals = {
		{ t = "turnin", quest = 1943, title = "Speak with Deino", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true },
		{ t = "accept", quest = 1944, title = "Waters of Xavian", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true, qlvl = 26 },
	} },
	{ title = "The Xavian Waterfall", note = "Fly to Splintertree Post and swim north up the river past the big lake to its far northern end, where the zone text reads Xavian; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work.", goals = {
		{ t = "use", quest = 1944, title = "Waters of Xavian", map = 1440, x = 76.29, y = 41.49, era = true, item = 7269, itemName = "Deino's Flask", oi = 1, note = "Deino's Flask, under the falls" },
		{ t = "collect", quest = 1944, title = "Waters of Xavian", map = 1440, x = 76.29, y = 41.49, era = true, count = 1, item = 7268, itemName = "Xavian Water Sample", oi = 1 },
	} },
	{ title = "Back to Deino", goals = {
		{ t = "turnin", quest = 1944, title = "Waters of Xavian", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true },
		{ t = "accept", quest = 1945, title = "Laughing Sisters", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true, qlvl = 26 },
	} },
	{ title = "The Laughing Sisters", note = "The Laughing Sisters, dryads of level 24-25, roam around the Raynewood Retreat in central Ashenvale; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard.", goals = {
		{ t = "collect", quest = 1945, title = "Laughing Sisters", map = 1440, x = 59.87, y = 54.38, era = true, count = 12, item = 7270, itemName = "Laughing Sister's Hair", oi = 1, mobLevel = 25, spots = "59.4,55.4;60.3,53.2;60.3,55.8;58.6,54.7;61.2,51.6" },
	} },
	{ title = "Kil'hala", note = "Kil'hala, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit.", goals = {
		{ t = "turnin", quest = 1945, title = "Laughing Sisters", npc = "Kil'hala", map = 1413, x = 52.2, y = 31.7, era = true },
		{ t = "accept", quest = 1946, title = "Nether-lace Garment", npc = "Kil'hala", map = 1413, x = 52.2, y = 31.7, era = true, qlvl = 26 },
		{ t = "turnin", quest = 1946, title = "Nether-lace Garment", npc = "Kil'hala", map = 1413, x = 52.2, y = 31.7, era = true, note = "Nether-lace Garment" },
	} },
} end)

Waypost.RegisterSteps("class/mage/spellfire-robes", function() return {
	{ title = "Uthel'nay (Orgrimmar)", note = "Uthel'nay is one of Orgrimmar's mage trainers, in Darkbriar Lodge in the Valley of Spirits. Then take the zeppelin to Tirisfal Glades from the tower outside Orgrimmar's main gate.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 15 },
		{ t = "accept", quest = 1959, title = "Report to Anastasia", npc = "Uthel'nay", map = 1454, x = 39.16, y = 86.27, era = true, qlvl = 15 },
	} },
	{ title = "Cain Firesong (Brill)", note = "Cain Firesong is the Brill mage trainer, upstairs in the Gallows' End Tavern: take the stairs inside, the arrow cannot tell the floors apart.", only = { races = {"Scourge"} }, goals = {
		{ t = "level", level = 15 },
		{ t = "accept", quest = 1959, title = "Report to Anastasia", npc = "Cain Firesong", map = 1420, x = 61.97, y = 52.47, era = true, qlvl = 15 },
	} },
	{ title = "Anastasia Hartwell", note = "Anastasia Hartwell stands in the Magic Quarter. The Chest of Containment Coffers and the Cantation of Manifestation lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.", goals = {
		{ t = "turnin", quest = 1959, title = "Report to Anastasia", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true },
		{ t = "accept", quest = 1960, title = "Investigate the Alchemist Shop", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true, qlvl = 16 },
		{ t = "collect", quest = 1960, title = "Investigate the Alchemist Shop", map = 1458, x = 85.48, y = 9.9, era = true, count = 1, item = 7247, itemName = "Chest of Containment Coffers", oi = 2 },
		{ t = "collect", quest = 1960, title = "Investigate the Alchemist Shop", map = 1458, x = 85.65, y = 10.18, era = true, count = 1, item = 7308, itemName = "Cantation of Manifestation", oi = 3 },
	} },
	{ title = "The alchemist shop", note = "Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the Cantation of Manifestation: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the Chest of Containment Coffers on it, then click the Filled Containment Coffer once it appears on the floor (clicking too early wastes a charge). Three are needed.", goals = {
		{ t = "use", map = 1458, x = 53.2, y = 74.5, era = true, item = 7308, itemName = "Cantation of Manifestation", optional = true },
		{ t = "kill", map = 1458, x = 53.29, y = 74.56, era = true, target = "Rift Spawn", mobLevel = 17, optional = true, note = "Rift Spawn, down to the stun" },
		{ t = "use", map = 1458, x = 53.2, y = 74.5, era = true, item = 7247, itemName = "Chest of Containment Coffers", optional = true, note = "Chest of Containment Coffers, on the stunned Rift Spawn" },
		{ t = "collect", quest = 1960, title = "Investigate the Alchemist Shop", map = 1458, x = 53.2, y = 74.5, era = true, count = 3, item = 7292, itemName = "Filled Containment Coffer", oi = 1 },
	} },
	{ title = "Back to Anastasia Hartwell", goals = {
		{ t = "turnin", quest = 1960, title = "Investigate the Alchemist Shop", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true },
		{ t = "accept", quest = 1961, title = "Gathering Materials", npc = "Anastasia Hartwell", map = 1458, x = 85.14, y = 10.03, era = true, qlvl = 15 },
	} },
	{ title = "Ambermill", note = "Leave the Undercity and follow the road south through Silverpine Forest. Every Dalaran human drops a Dalaran Mana Gem four times in five, and Linen Cloth too: the easiest are the Dalaran Apprentices (level 13-14, Frostbolt) on the hills south-east of the Sepulcher, either side of the road south; deeper in, the walled town of Ambermill in south-east Silverpine has Watchers (18-19, Fire Shield and Flamestrike) and Wizards (19-20, Frost Nova) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten Linen Cloth also come from any humanoid or the Undercity Auction House.", goals = {
		{ t = "collect", quest = 1961, title = "Gathering Materials", map = 1421, x = 52.25, y = 64.46, era = true, count = 6, item = 7293, itemName = "Dalaran Mana Gem", oi = 2, mobLevel = 20, spots = "52,63.6;52.2,57.3;55.7,55;57.6,63.6;62.8,62.8" },
		{ t = "collect", quest = 1961, title = "Gathering Materials", map = 1421, x = 51.58, y = 64.26, era = true, count = 10, item = 2589, itemName = "Linen Cloth", oi = 1, spots = "52,63.6;52.2,57.3;55.7,55;59.7,62.3;62.2,71.8" },
	} },
	{ title = "Josef Gregorian", note = "Back to the Undercity. Josef Gregorian, Victor Ward and Rhiannon Davis keep the tailor's shop in the Magic Quarter. Hand the gems and cloth to Josef and let the three of them talk for a moment; then Josef offers Spellfire Robes: take it and hand it straight back to him for the robe.", goals = {
		{ t = "turnin", quest = 1961, title = "Gathering Materials", npc = "Josef Gregorian", map = 1458, x = 70.76, y = 30.69, era = true },
		{ t = "accept", quest = 1962, title = "Spellfire Robes", npc = "Josef Gregorian", map = 1458, x = 70.76, y = 30.69, era = true, qlvl = 15 },
		{ t = "turnin", quest = 1962, title = "Spellfire Robes", npc = "Josef Gregorian", map = 1458, x = 70.76, y = 30.69, era = true, note = "Lesser Spellfire Robes" },
	} },
} end)

Waypost.RegisterSteps("class/mage/teleports-horde", function() return {
	{ title = "Teleport: Orgrimmar", note = "At 20 go to Darkbriar Lodge in Orgrimmar's Valley of Spirits, where the mage trainers live. Thuul, the portal trainer, stands on the upper floor and teaches Teleport: Orgrimmar for 20 silver. Every teleport burns one Rune of Teleportation (10 silver at any reagent vendor), so carry a few.", goals = {
		{ t = "level", level = 20 },
		{ t = "money", money = 3000 },
		{ t = "train", npc = "Thuul", map = 1454, x = 38.68, y = 85.41, era = true, note = "Thuul: Teleport: Orgrimmar" },
		{ t = "buy", count = 5, item = 17031, itemName = "Rune of Teleportation", note = "Rune of Teleportation, 10s each" },
	} },
	{ title = "Teleport: Undercity", note = "Take the zeppelin from the tower outside Orgrimmar's gate to Tirisfal Glades and walk into the Undercity. Lexington Mortaim, the portal trainer, stands in the Magic Quarter with the mage trainers: Teleport: Undercity, 20 silver. Hannah Akeley beside him sells the runes.", goals = {
		{ t = "money", money = 2000 },
		{ t = "train", npc = "Lexington Mortaim", map = 1458, x = 84.19, y = 15.58, era = true, note = "Lexington Mortaim: Teleport: Undercity" },
	} },
	{ title = "Teleport: Thunder Bluff", note = "At 30. Thunder Bluff is in Mulgore: fly there from Orgrimmar or the Crossroads. Birgitte Cranston, the portal trainer, stands with the mage trainers in the Pools of Vision, the cave under Spirit Rise: go down inside, the arrow cannot tell the floors apart. She teaches Teleport: Thunder Bluff for 80 silver.", goals = {
		{ t = "level", level = 30 },
		{ t = "money", money = 8000 },
		{ t = "train", npc = "Birgitte Cranston", map = 1456, x = 22.5, y = 16.91, era = true, note = "Birgitte Cranston: Teleport: Thunder Bluff" },
	} },
	{ title = "Portals to Orgrimmar and the Undercity", note = "At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one Rune of Portals (20 silver at any reagent vendor). Thuul in Darkbriar Lodge has Portal: Orgrimmar; teleport to the Undercity for Lexington Mortaim's Portal: Undercity.", goals = {
		{ t = "level", level = 40 },
		{ t = "money", money = 30000 },
		{ t = "train", npc = "Thuul", map = 1454, x = 38.68, y = 85.41, era = true, note = "Thuul: Portal: Orgrimmar" },
		{ t = "buy", count = 5, item = 17032, itemName = "Rune of Portals", note = "Rune of Portals, 20s each" },
		{ t = "train", npc = "Lexington Mortaim", map = 1458, x = 84.19, y = 15.58, era = true, note = "Lexington Mortaim, Undercity: Portal: Undercity" },
	} },
	{ title = "Portal: Thunder Bluff", note = "At 50 Birgitte Cranston, down in the Pools of Vision under Spirit Rise in Thunder Bluff, teaches the last one, Portal: Thunder Bluff, for 3 gold 20 silver. Use your Teleport: Thunder Bluff to get there.", goals = {
		{ t = "level", level = 50 },
		{ t = "money", money = 32000 },
		{ t = "train", npc = "Birgitte Cranston", map = 1456, x = 22.5, y = 16.91, era = true, note = "Birgitte Cranston: Portal: Thunder Bluff" },
	} },
} end)

Waypost.RegisterSteps("class/paladin/lumina-windsinger", function() return {
	{ title = "Danitha Morr", note = "At 18 Danitha Morr, inside Bandarion Keep on the bluffs north-west of the Solliden Farmstead, sends you south to the Sepulcher in Silverpine Forest.", goals = {
		{ t = "level", level = 18 },
		{ t = "accept", quest = 91858, title = "Diplomatic Incident", npc = "Danitha Morr", map = 1420, x = 22.09, y = 44.66, era = true, qlvl = 22 },
	} },
	{ title = "The Sepulcher", note = "Trevan Rol stands in the lower part of the Sepulcher, below the surface; Deathguard Baldren keeps watch near the town's entrance.", goals = {
		{ t = "turnin", quest = 91858, title = "Diplomatic Incident", npc = "Trevan Rol", map = 1421, x = 43.4, y = 41.1, era = true },
		{ t = "accept", quest = 91859, title = "A Curious Pair", npc = "Trevan Rol", map = 1421, x = 43.4, y = 41.1, era = true, qlvl = 22 },
		{ t = "turnin", quest = 91859, title = "A Curious Pair", npc = "Deathguard Baldren", map = 1421, x = 45.81, y = 41.88, era = true },
		{ t = "accept", quest = 91860, title = "A Grim Fate", npc = "Deathguard Baldren", map = 1421, x = 45.81, y = 41.88, era = true, qlvl = 22 },
	} },
	{ title = "The pyre on Fenris Isle", note = "Fenris Isle lies in the lake north-east of the Sepulcher. The gnolls' pyre, with the Charred Remains, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's.", goals = {
		{ t = "turnin", quest = 91860, title = "A Grim Fate", npc = "Charred Remains", map = 1421, x = 65.02, y = 34.1, era = true },
		{ t = "accept", quest = 91861, title = "Into Fenris Keep", npc = "Charred Remains", map = 1421, x = 65.02, y = 34.1, era = true, qlvl = 22, note = "from the Charred Remains" },
	} },
	{ title = "Fenris Keep", note = "Lumina Windsinger is caged in the basement of Fenris Keep, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the Fenris Isle Key (often the first kill); the rare Rot Hide Bruiser (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back.", goals = {
		{ t = "turnin", quest = 91861, title = "Into Fenris Keep", npc = "Lumina Windsinger", map = 1421, x = 65.55, y = 23.27, era = true },
		{ t = "accept", quest = 91862, title = "Lumina Windsinger", npc = "Lumina Windsinger", map = 1421, x = 65.55, y = 23.27, era = true, qlvl = 22 },
		{ t = "collect", quest = 91862, title = "Lumina Windsinger", map = 1421, x = 65.57, y = 23.32, era = true, count = 1, item = 267412, itemName = "Fenris Isle Key", oi = 1, mobLevel = 23, note = "Fenris Isle Key, from the Rot Hide gnolls" },
	} },
	{ title = "Free Lumina", note = "Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: Lumina walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the Sepulcher. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage.", goals = {
		{ t = "turnin", quest = 91862, title = "Lumina Windsinger", npc = "Lumina Windsinger", map = 1421, x = 65.55, y = 23.27, era = true },
		{ t = "accept", quest = 96204, title = "The Windshaper's Wrath", npc = "Lumina Windsinger", map = 1421, x = 65.55, y = 23.27, era = true, qlvl = 22, escort = true },
	} },
	{ title = "Back to the Sepulcher", note = "Lumina waits beside Trevan Rol in the Sepulcher (a different Lumina from the one you escorted). For The Debt, click through every line of her story.", goals = {
		{ t = "turnin", quest = 96204, title = "The Windshaper's Wrath", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true, note = "Lumina Windsinger, the Sepulcher" },
		{ t = "accept", quest = 95034, title = "The Debt", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true, qlvl = 24 },
		{ t = "talk", quest = 95034, title = "The Debt", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true, oi = 1, note = "Lumina Windsinger: hear her story to the end" },
		{ t = "turnin", quest = 95034, title = "The Debt", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true },
	} },
	{ title = "A Moon-Kissed Blade", note = "At 20 Lumina asks for a blade that can kill Old Fire-Eye. Talk to Trevan Rol beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third.", goals = {
		{ t = "level", level = 20 },
		{ t = "accept", quest = 95036, title = "A Moon-Kissed Blade", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true, qlvl = 25 },
		{ t = "collect", npc = "Trevan Rol", map = 1421, x = 43.4, y = 41.1, era = true, item = 267454, itemName = "Trevan's Weapon Notes", note = "Trevan's Weapon Notes: talk to Trevan Rol" },
	} },
	{ title = "The Enchanted Silver Ingot", note = "Shadowfang Keep is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to Archmage Arugal at the very end. A friend's cleared instance works: walk in and run to the table.", goals = {
		{ t = "goto", map = 1421, x = 44.8, y = 67.8, text = "Shadowfang Keep" },
		{ t = "collect", quest = 95036, title = "A Moon-Kissed Blade", map = 1421, x = 44.8, y = 67.8, count = 1, item = 267361, itemName = "Enchanted Silver Ingot", oi = 3, note = "Enchanted Silver Ingot, on Arugal's table" },
	} },
	{ title = "Whitestone Oak Lumber", note = "The Deadmines lies under Moonbrook in Westfall, Alliance land: a group of five at about 17-24. From the Undercity take the zeppelin to Grom'gol in Stranglethorn Vale and go north through Duskwood into Westfall. The way in is the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time.", goals = {
		{ t = "goto", map = 1436, x = 42.5, y = 71.7, text = "The Deadmines, in the Moonbrook mine" },
		{ t = "collect", quest = 95036, title = "A Moon-Kissed Blade", map = 1436, x = 42.5, y = 71.7, count = 1, item = 6994, itemName = "Whitestone Oak Lumber", oi = 2, group = true, note = "Goblin Woodcarvers, inside" },
	} },
	{ title = "Ulric Frostveil", note = "Ulric Frostveil waits at Zoram'gar Outpost on Ashenvale's west coast: take the zeppelin from Grom'gol (or the Undercity) to Orgrimmar, then go north through the Barrens into Ashenvale and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take Ulric's quest before you hunt the naga: the Kor Gem only drops while you have it.", goals = {
		{ t = "accept", quest = 95042, title = "Seeking the Kor Gem", npc = "Ulric Frostveil", map = 1440, x = 11.87, y = 34.41, era = true, qlvl = 25, note = "Ulric Frostveil, Zoram'gar Outpost" },
	} },
	{ title = "The Corrupted Kor Gem", note = "The naga stand in the flooded ruins and passages around the Blackfathom Deeps entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the Corrupted Kor Gem, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group.", goals = {
		{ t = "collect", quest = 95042, title = "Seeking the Kor Gem", map = 1440, x = 13.55, y = 12.06, era = true, count = 1, item = 6995, itemName = "Corrupted Kor Gem", oi = 1, mobLevel = 22, group = true, spots = "13.8,9.3;16.2,11.3;13.6,12.1;17.7,11.1" },
	} },
	{ title = "The Purified Kor Gem", note = "Back to Ulric at Zoram'gar: he cleanses the gem. Keep the Purified Kor Gem for Trevan.", goals = {
		{ t = "turnin", quest = 95042, title = "Seeking the Kor Gem", npc = "Ulric Frostveil", map = 1440, x = 11.87, y = 34.41, era = true, note = "Ulric Frostveil: Purified Kor Gem" },
	} },
	{ title = "Trevan Rol", note = "Bring the lumber, the ingot and the gem to Trevan in the Sepulcher. He gives you a Bundle of Blacksmithing Materials for a smith in Tarren Mill: keep it in your bags.", goals = {
		{ t = "turnin", quest = 95036, title = "A Moon-Kissed Blade", npc = "Trevan Rol", map = 1421, x = 43.4, y = 41.1, era = true },
		{ t = "accept", quest = 95111, title = "An Underrated Talent", npc = "Trevan Rol", map = 1421, x = 43.4, y = 41.1, era = true, qlvl = 25 },
	} },
	{ title = "Ott", note = "Ott, the weaponsmith, stands just south of Tarren Mill in Hillsbrad Foothills. Accepting Ott's Masterwork starts the forging: step back and wait near him until he is done.", goals = {
		{ t = "turnin", quest = 95111, title = "An Underrated Talent", npc = "Ott", map = 1424, x = 60.43, y = 26.18, era = true, note = "Ott, Tarren Mill" },
		{ t = "accept", quest = 95125, title = "Ott's Masterwork", npc = "Ott", map = 1424, x = 60.43, y = 26.18, era = true, qlvl = 25 },
		{ t = "complete", quest = 95125, title = "Ott's Masterwork", note = "Watch Ott forge the blade", objs = {"Watch Ott craft the blade"} },
		{ t = "turnin", quest = 95125, title = "Ott's Masterwork", npc = "Ott", map = 1424, x = 60.43, y = 26.18, era = true },
		{ t = "accept", quest = 95126, title = "The Moonsilver Blade", npc = "Ott", map = 1424, x = 60.43, y = 26.18, era = true, qlvl = 25, note = "Ott gives you Ott's Masterwork" },
	} },
	{ title = "The Moonsilver Blade", note = "Back to Trevan Rol in the Sepulcher's lower part: he hands you the Moonsilver Blade, a two-handed sword.", goals = {
		{ t = "turnin", quest = 95126, title = "The Moonsilver Blade", npc = "Trevan Rol", map = 1421, x = 43.4, y = 41.1, era = true, note = "Trevan Rol: Moonsilver Blade" },
	} },
	{ title = "Two-Handed Swords", note = "The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. Archibald, the weapon master in the Undercity's War Quarter, teaches Two-Handed Swords for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level).", goals = {
		{ t = "train", npc = "Archibald", map = 1458, x = 57.31, y = 32.77, era = true, optional = true, note = "Archibald, War Quarter: Two-Handed Swords" },
	} },
	{ title = "Old Fire-Eye", note = "Equip the Moonsilver Blade. Old Fire-Eye, the great worgen, roams the woods south of the Sepulcher toward the gates of Gilneas. He is elite (level 25): the guide waits for level 22 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke.", goals = {
		{ t = "accept", quest = 95140, title = "Old Fire-Eye", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true, qlvl = 26, note = "Lumina Windsinger, the Sepulcher" },
		{ t = "level", level = 22 },
		{ t = "kill", quest = 95140, title = "Old Fire-Eye", map = 1421, x = 47.91, y = 85.33, era = true, count = 1, target = "Old Fire-Eye", oi = 1, mobLevel = 25, group = true, note = "Old Fire-Eye, with the Moonsilver Blade equipped", spots = "47.91,85.33;50.4,87;49.7,81.7;52.6,73.4" },
	} },
	{ title = "Wolfsbane", note = "Back to Lumina in the Sepulcher with the Moonsilver Blade (the quest asks for it): she takes it and blesses it with the magic of her people into Wolfsbane.", goals = {
		{ t = "turnin", quest = 95140, title = "Old Fire-Eye", npc = "Lumina Windsinger", map = 1421, x = 43.4, y = 40.99, era = true, note = "Lumina Windsinger: Wolfsbane" },
	} },
} end)

Waypost.RegisterSteps("class/paladin/tyrs-watch", function() return {
	{ title = "Aramis Hammerhand", note = "Shadow Priest Sarvis gives you a Consecrated Scroll after The Mindless Ones: read it, then bring it to Aramis Hammerhand by the church. He asks you to heal five Injured Deathguard lying around Deathknell. Holy Light hurts a Forsaken paladin a little each time: watch your health.", when = {{ k = "level", op = "<", n = 9 }}, goals = {
		{ t = "accept", quest = 98601, title = "A Difficult Path", npc = "Shadow Priest Sarvis", map = 1420, x = 30.84, y = 66.2, era = true, qlvl = 1 },
		{ t = "turnin", quest = 98601, title = "A Difficult Path", npc = "Aramis Hammerhand", map = 1420, x = 31.1, y = 66.41, era = true },
		{ t = "level", level = 2 },
		{ t = "accept", quest = 90902, title = "Rediscovering the Light", npc = "Aramis Hammerhand", map = 1420, x = 31.1, y = 66.41, era = true, qlvl = 2 },
		{ t = "complete", quest = 90902, title = "Rediscovering the Light", map = 1420, x = 31.6, y = 65.8, era = true, note = "Heal 5 Injured Deathguard with Holy Light", objs = {"Heal 5 Injured Deathguard"} },
		{ t = "turnin", quest = 90902, title = "Rediscovering the Light", npc = "Aramis Hammerhand", map = 1420, x = 31.1, y = 66.41, era = true },
	} },
	{ title = "Coming to Terms", note = "At 4 Aramis sends you after a Frightened Paladin who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy).", when = {{ k = "level", op = "<", n = 9 }}, goals = {
		{ t = "level", level = 4 },
		{ t = "accept", quest = 91208, title = "Coming to Terms", npc = "Aramis Hammerhand", map = 1420, x = 31.1, y = 66.41, era = true, qlvl = 4 },
		{ t = "accept", quest = 91209, title = "Continue Your Training", npc = "Aramis Hammerhand", map = 1420, x = 31.1, y = 66.41, era = true, qlvl = 4 },
		{ t = "kill", quest = 91208, title = "Coming to Terms", map = 1420, x = 27.69, y = 63.82, era = true, count = 1, target = "Frightened Paladin", oi = 1, note = "Talk to the Frightened Paladin, then defeat her" },
		{ t = "turnin", quest = 91208, title = "Coming to Terms", npc = "Aramis Hammerhand", map = 1420, x = 31.1, y = 66.41, era = true },
	} },
	{ title = "Shari Stilwell", note = "Follow the road east out of Deathknell to Brill. Shari Stilwell, the paladin trainer, stands in town; she trains you from here on.", when = {{ k = "level", op = "<", n = 9 }}, goals = {
		{ t = "turnin", quest = 91209, title = "Continue Your Training", npc = "Shari Stilwell", map = 1420, x = 60.22, y = 52.66, era = true, note = "Shari Stilwell, Brill" },
		{ t = "train", class = true },
	} },
	{ title = "A Second Home", note = "At 8 Shari Stilwell in Brill sends you to the order's keep on the west coast. The Tarnished in Shadowvale and the crypt under it hit hard at 8-9: come at 10 or later.", goals = {
		{ t = "level", level = 8 },
		{ t = "accept", quest = 91282, title = "A Second Home", npc = "Shari Stilwell", map = 1420, x = 60.22, y = 52.66, era = true, qlvl = 11, note = "Shari Stilwell, Brill" },
	} },
	{ title = "Bandarion Keep", note = "Bandarion Keep stands on the bluffs north-west of the Solliden Farmstead (the road west starts near 29,46). Breton Samuels waits at the gate. Hilda the Breaker, the keep's trainer, and Ephram Barbaro, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after A Righteous Cause from Leonid at the keep, the end of Hadric Harlson's chain that starts south-east of Brill; take their quests when you see them.", goals = {
		{ t = "turnin", quest = 91282, title = "A Second Home", npc = "Breton Samuels", map = 1420, x = 21.85, y = 45.23, era = true },
		{ t = "accept", quest = 91285, title = "Murlocs at the Gates", npc = "Breton Samuels", map = 1420, x = 21.85, y = 45.23, era = true, qlvl = 11 },
		{ t = "accept", quest = 99152, title = "As Above, So Below", npc = "Hilda the Breaker", map = 1420, x = 21.96, y = 47.25, era = true, qlvl = 12, optional = true, note = "Hilda the Breaker: As Above, So Below" },
		{ t = "accept", quest = 99153, title = "The One That Got Away", npc = "Ephram Barbaro", map = 1420, x = 20.17, y = 46.49, era = true, qlvl = 12, optional = true, note = "Ephram Barbaro: The One That Got Away" },
	} },
	{ title = "Murlocs at the Gates", note = "The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to Shadowvale.", goals = {
