Waypost.RegisterSteps("class/priest/priest-robes-horde", function() return {
	{ title = "In Favor of Spirituality", note = "At 5, Ken'jai, the priest trainer in the Den in the middle of the Valley of Trials, sends you to Tai'jin in Razor Hill. Train Lesser Heal (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", only = { races = {"Troll"} }, goals = {
		{ t = "level", level = 5 },
		{ t = "accept", quest = 5649, title = "In Favor of Spirituality", npc = "Ken'jai", map = 1411, x = 42.36, y = 68.81, era = true, qlvl = 4 },
	} },
