		{ t = "turnin", quest = 5649, title = "In Favor of Spirituality", npc = "Tai'jin", map = 1411, x = 54.26, y = 42.93, era = true },
		{ t = "accept", quest = 5648, title = "Garments of Spirituality", npc = "Tai'jin", map = 1411, x = 54.26, y = 42.93, era = true, qlvl = 4 },
		{ t = "train", class = true, note = "Lesser Heal (Rank 2), if Ken'jai did not teach it yet" },
	} },
	{ title = "Grunt Kor'ja", note = "Grunt Kor'ja kneels behind a group of rocks just off the road, a short walk south of Razor Hill. Cast Lesser Heal (Rank 2) on her first, then Power Word: Fortitude. Rank 1 of Lesser Heal does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes.", only = { races = {"Troll"} }, goals = {
		{ t = "kill", quest = 5648, title = "Garments of Spirituality", map = 1411, x = 53.1, y = 46.46, era = true, count = 1, target = "Grunt Kor'ja", oi = 1, text = "Heal and fortify Grunt Kor'ja" },
