		{ t = "accept", quest = 79442, title = "The Tempest's Weapons", npc = "Rau Cliffrunner", map = 1441, x = 46.14, y = 51.71, era = true, qlvl = 40 },
	} },
	{ title = "Bath'rah the Windwatcher", note = "Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm; the Elementalist's Guard shield comes with it.", goals = {
		{ t = "turnin", quest = 79442, title = "The Tempest's Weapons", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true, note = "Bath'rah the Windwatcher: the Elementalist's Guard and your weapon" },
	} },
} end)

Waypost.RegisterSteps("class/shaman/call-of-earth-horde", function() return {
	{ title = "Canaga Earthcaller", note = "Canaga Earthcaller stands just outside the Den, the cave in the middle of the Valley of Trials. The quest opens at level 4.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 4 },
		{ t = "accept", quest = 1516, title = "Call of Earth", npc = "Canaga Earthcaller", map = 1411, x = 42.4, y = 69.17, era = true, qlvl = 4 },
	} },
	{ title = "Felstalker Hooves", note = "Felstalkers (level 3-4) prowl the slope below the Burning Blade Coven, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every Felstalker drops a hoof (four kills in five); they respawn in a little over three minutes.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "collect", quest = 1516, title = "Call of Earth", map = 1411, x = 43.01, y = 55.34, era = true, count = 2, item = 6640, itemName = "Felstalker Hoof", oi = 1, mobLevel = 4, spots = "44.1,54.8;42.9,53.2;44.6,52.8;45.4,55.5" },
	} },
	{ title = "Canaga Earthcaller", note = "Back to Canaga outside the Den. She hands you the Earth Sapta: do not drink it yet.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "turnin", quest = 1516, title = "Call of Earth", npc = "Canaga Earthcaller", map = 1411, x = 42.4, y = 69.17, era = true },
		{ t = "accept", quest = 1517, title = "Call of Earth", npc = "Canaga Earthcaller", map = 1411, x = 42.4, y = 69.17, era = true, qlvl = 4 },
	} },
	{ title = "Lost the Earth Sapta?", note = "Only if the Earth Sapta is gone from your bags (drunk away from the rock, or sold): Canaga gives you another.", only = { races = {"Orc", "Troll"} }, when = {{ k = "onquest", q = {1517} }, { k = "has", neg = true, n = 1, item = 6635 }}, goals = {
		{ t = "turnin", quest = 1463, title = "Earth Sapta", npc = "Canaga Earthcaller", map = 1411, x = 42.4, y = 69.17, era = true, qlvl = 4, note = "Canaga Earthcaller: a new Earth Sapta" },
	} },
	{ title = "Spirit Rock", note = "Spirit Rock sits on a ledge in the hills just south of the Den. The Hidden Path up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the Earth Sapta: the Minor Manifestation of Earth appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "use", map = 1411, x = 44.1, y = 76.4, era = true, item = 6635, itemName = "Earth Sapta", note = "Earth Sapta, beside Spirit Rock" },
		{ t = "turnin", quest = 1517, title = "Call of Earth", npc = "Minor Manifestation of Earth", map = 1411, x = 44.03, y = 76.2, era = true },
		{ t = "accept", quest = 1518, title = "Call of Earth", npc = "Minor Manifestation of Earth", map = 1411, x = 44.03, y = 76.2, era = true, qlvl = 4, note = "it hands you the Rough Quartz: keep it" },
	} },
	{ title = "Canaga Earthcaller", note = "Bring the Rough Quartz back to Canaga outside the Den. Keep the Earth Totem she gives you in your bags for good: every earth totem needs it.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "turnin", quest = 1518, title = "Call of Earth", npc = "Canaga Earthcaller", map = 1411, x = 42.4, y = 69.17, era = true, note = "Canaga Earthcaller: Stoneskin Totem and your Earth Totem" },
		{ t = "train", class = true, note = "the level 4 shaman spells" },
	} },
	{ title = "Seer Ravenfeather", note = "Seer Ravenfeather stands in Camp Narache. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4.", only = { races = {"Tauren"} }, goals = {
		{ t = "level", level = 4 },
		{ t = "accept", quest = 1519, title = "Call of Earth", npc = "Seer Ravenfeather", map = 1412, x = 44.35, y = 76.77, qlvl = 4 },
	} },
	{ title = "Ritual Salve", note = "The Bristleback Shamans (level 3-4) stand among the quilboar huts of Brambleblade Ravine, east of the camp, and throw the odd Lightning Bolt. Four kills in five drop a salve; they respawn in about four minutes.", only = { races = {"Tauren"} }, goals = {
		{ t = "collect", quest = 1519, title = "Call of Earth", map = 1412, x = 56.61, y = 78.3, count = 2, item = 6634, itemName = "Ritual Salve", oi = 1, mobLevel = 4, spots = "57,76.3;60.1,81.6;61.3,77.9;56.6,78.3;58.4,76.7" },
	} },
	{ title = "Seer Ravenfeather", note = "Back to the Seer in Camp Narache. She hands you the Earth Sapta: do not drink it yet.", only = { races = {"Tauren"} }, goals = {
		{ t = "turnin", quest = 1519, title = "Call of Earth", npc = "Seer Ravenfeather", map = 1412, x = 44.35, y = 76.77 },
		{ t = "accept", quest = 1520, title = "Call of Earth", npc = "Seer Ravenfeather", map = 1412, x = 44.35, y = 76.77, qlvl = 4 },
	} },
	{ title = "Lost the Earth Sapta?", note = "Only if the Earth Sapta is gone from your bags: the Seer gives you another.", only = { races = {"Tauren"} }, when = {{ k = "onquest", q = {1520} }, { k = "has", neg = true, n = 1, item = 6635 }}, goals = {
		{ t = "turnin", quest = 1462, title = "Earth Sapta", npc = "Seer Ravenfeather", map = 1412, x = 44.35, y = 76.77, qlvl = 4, note = "Seer Ravenfeather: a new Earth Sapta" },
	} },
	{ title = "Kodo Rock", note = "Kodo Rock is a small pillar on a low mound due east of Greatmother Hawkwind's well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the Earth Sapta, then speak to the Minor Manifestation of Earth before it fades (drink again if it does).", only = { races = {"Tauren"} }, goals = {
		{ t = "use", map = 1412, x = 52, y = 80.1, era = true, item = 6635, itemName = "Earth Sapta", note = "Earth Sapta, beside Kodo Rock" },
		{ t = "turnin", quest = 1520, title = "Call of Earth", npc = "Minor Manifestation of Earth", map = 1412, x = 51.99, y = 80.4 },
		{ t = "accept", quest = 1521, title = "Call of Earth", npc = "Minor Manifestation of Earth", map = 1412, x = 51.99, y = 80.4, qlvl = 4, note = "it hands you the Rough Quartz: keep it" },
	} },
	{ title = "Seer Ravenfeather", note = "Bring the Rough Quartz back to the Seer. Keep the Earth Totem in your bags for good: every earth totem needs it.", only = { races = {"Tauren"} }, goals = {
		{ t = "turnin", quest = 1521, title = "Call of Earth", npc = "Seer Ravenfeather", map = 1412, x = 44.35, y = 76.77, note = "Seer Ravenfeather: Stoneskin Totem and your Earth Totem" },
		{ t = "train", class = true, note = "the level 4 shaman spells" },
	} },
	{ title = "Windshaper Boro", note = "Windshaper Boro, the shaman trainer, stands in Thendal Village. The quest opens at level 3.", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 3 },
		{ t = "accept", quest = 92466, title = "Call of Earth", npc = "Windshaper Boro", map = 2521, x = 42.79, y = 23.58, qlvl = 4 },
	} },
	{ title = "Signet of Akir", note = "Any Al'Aketh cultist can carry the Signet of Akir: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond Hanaa Nightwind, south-west of the village. Keep killing until one drops it.", only = { races = {"Skyborne"} }, goals = {
		{ t = "collect", quest = 92466, title = "Call of Earth", map = 2521, x = 45.41, y = 19.38, count = 1, item = 251924, itemName = "Signet of Akir", oi = 1, spots = "46.5,19;48.1,19.6;47.9,20.9;37.6,31.6;38.4,33.4" },
	} },
	{ title = "Windshaper Boro", note = "Back to Boro in Thendal Village. He hands you the Earth Sapta: do not drink it yet.", only = { races = {"Skyborne"} }, goals = {
