	} },
	{ title = "Kranal Fiss", note = "Down the trail, back over the bridge to Kranal Fiss by his tower. Keep the Fire Totem in your bags for good: every fire totem needs it.", only = { races = {"Orc", "Troll", "Tauren"} }, goals = {
		{ t = "turnin", quest = 1527, title = "Call of Fire", npc = "Kranal Fiss", map = 1413, x = 56.03, y = 19.89, era = true, note = "Kranal Fiss: Searing Totem, your Fire Totem and the Totem of Charged Flames" },
	} },
	{ title = "Sessaria Skystride", note = "At 10 Sessaria Skystride, the shaman trainer beside Ayessa Dawnsinger in Valanaar, hands you the Torch of the Dormant Flame (Aarnor Galestrike offers the same quest). Already left the isle? A Call of Fire sends you back to them: take the skycutter from the cliffs south of Skywatcher Plateau, north of Thunder Bluff. Learn Flame Shock from her now: Kuramaa, later in the chain, only takes fire damage.", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 10 },
		{ t = "accept", quest = 97243, title = "Call of Fire", npc = "Sessaria Skystride", map = 2521, x = 58.31, y = 78.51, qlvl = 10 },
		{ t = "train", class = true },
	} },
	{ title = "Olariaan Swiftburn", note = "The Shrine of Flames hides on the island's outer rim south-west of Valanaar, just south-east of Windfield Orchard: Olariaan Swiftburn keeps it.", only = { races = {"Skyborne"} }, goals = {
		{ t = "turnin", quest = 97243, title = "Call of Fire", npc = "Olariaan Swiftburn", map = 2521, x = 51.24, y = 86.19 },
		{ t = "accept", quest = 97244, title = "Call of Fire", npc = "Olariaan Swiftburn", map = 2521, x = 51.24, y = 86.19, qlvl = 10 },
	} },
	{ title = "Skypriest Faladiel", note = "Skypriest Faladiel (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past Valanaar, just south of the Shrine of Akir, on the hill west of the falls north of the East Pylon Watchtower. Kill him and take his heart.", only = { races = {"Skyborne"} }, goals = {
		{ t = "collect", quest = 97244, title = "Call of Fire", map = 2521, x = 64.43, y = 63.71, count = 1, item = 277267, itemName = "Faladiel's Heart", oi = 1 },
	} },
	{ title = "Olariaan Swiftburn", note = "Back to Olariaan at the Shrine of Flames.", only = { races = {"Skyborne"} }, goals = {
		{ t = "turnin", quest = 97244, title = "Call of Fire", npc = "Olariaan Swiftburn", map = 2521, x = 51.24, y = 86.19 },
		{ t = "accept", quest = 97245, title = "Call of Fire", npc = "Olariaan Swiftburn", map = 2521, x = 51.24, y = 86.19, qlvl = 10 },
	} },
	{ title = "Kuramaa", note = "Kuramaa's Stump is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of Valanaar, in the hills south of the Windsong Crawlers' lakes. Knock on it to call Kuramaa (level 10). The spirit shrugs off most magic: only fire hurts it, so keep Flame Shock on it. Take its wooden mask.", only = { races = {"Skyborne"} }, goals = {
		{ t = "interact", npc = "Kuramaa's Stump", map = 2521, x = 42.35, y = 68.82, note = "Kuramaa's Stump: knock on the bark" },
		{ t = "collect", quest = 97245, title = "Call of Fire", map = 2521, x = 42.44, y = 68.75, count = 1, item = 277269, itemName = "Kuramaa's Mask", oi = 1 },
	} },
	{ title = "The Eternal Flame", note = "Back to Olariaan. Accept the last quest, then wait by the Brazier of Offering while he performs the ritual; when the fire spirits light the Eternal Flame, hold the torch to it. From then you have six minutes: carry the flame straight to the Brazier of Eternal Flame beside Sessaria in Valanaar, with no detours or fights. Timer out? Abandon the quest and take it again from Olariaan.", only = { races = {"Skyborne"} }, goals = {
		{ t = "turnin", quest = 97245, title = "Call of Fire", npc = "Olariaan Swiftburn", map = 2521, x = 51.24, y = 86.19 },
		{ t = "accept", quest = 97257, title = "Call of Fire", npc = "Olariaan Swiftburn", map = 2521, x = 51.24, y = 86.19, qlvl = 10 },
		{ t = "goto", map = 2521, x = 51.2, y = 85.9, text = "Brazier of Offering" },
		{ t = "complete", quest = 97257, title = "Call of Fire", map = 2521, x = 58.4, y = 78.8, note = "the ritual, then the Brazier of Eternal Flame in Valanaar", objs = {"Brazier of Offering", "Brazier of Eternal Flame"}, startItem = 277329, startItemName = "Torch of Eternal Flame" },
	} },
	{ title = "Sessaria Skystride", note = "Keep the Fire Totem in your bags for good: every fire totem needs it.", only = { races = {"Skyborne"} }, goals = {
		{ t = "turnin", quest = 97257, title = "Call of Fire", npc = "Sessaria Skystride", map = 2521, x = 58.31, y = 78.51, note = "Sessaria Skystride: Searing Totem, your Fire Totem and the Totem of Charged Flames" },
	} },
} end)

Waypost.RegisterSteps("class/shaman/call-of-water-horde", function() return {
	{ title = "Searn Firewarder", note = "At 20 Searn Firewarder in the Valley of Wisdom sends you to Islen Waterseer in the Barrens. (Swart in Razor Hill gives the same letter: carry either.)", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 20 },
