Waypost.RegisterSteps("class/warrior/heirloom-weapon", function() return {
	{ title = "Seena Skybreaker in Valanaar", note = "At 10, Seena Skybreaker stands with the trainers by Valanaar's west gate. A cultist, Zaal Stormshield, holds her family's shield at the Shrine of Akir.", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 10 },
