		{ t = "accept", quest = 1818, title = "Speak with Dillinger", npc = "Austil de Mon", map = 1420, x = 61.85, y = 52.54, era = true, qlvl = 10 },
	} },
	{ title = "Deathguard Dillinger", note = "Dillinger stands by the graveyard on Brill's west edge. An Orc, Troll, Tauren or Skyborne who took Speak with Dillinger from Austil de Mon instead of Uzzek's road is led through Brill from here.", when = {{ k = "turnedin", neg = true, q = 1505 }}, goals = {
		{ t = "turnin", quest = 1818, title = "Speak with Dillinger", npc = "Deathguard Dillinger", map = 1420, x = 58.2, y = 51.45, era = true },
		{ t = "accept", quest = 1819, title = "Ulag the Cleaver", npc = "Deathguard Dillinger", map = 1420, x = 58.2, y = 51.45, era = true, qlvl = 10 },
	} },
	{ title = "Ulag the Cleaver", note = "Ulag sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and Ulag (level 11, not elite) walks out. Start at full health.", when = {{ k = "turnedin", neg = true, q = 1505 }}, goals = {
		{ t = "kill", quest = 1819, title = "Ulag the Cleaver", map = 1420, x = 59.47, y = 48.28, era = true, count = 1, target = "Ulag the Cleaver", oi = 1 },
		{ t = "turnin", quest = 1819, title = "Ulag the Cleaver", npc = "Deathguard Dillinger", map = 1420, x = 58.2, y = 51.45, era = true, note = "Deathguard Dillinger: Defensive Stance" },
		{ t = "accept", quest = 1820, title = "Speak with Coleman", npc = "Deathguard Dillinger", map = 1420, x = 58.2, y = 51.45, era = true, qlvl = 10 },
	} },
	{ title = "Coleman Farthing", note = "Coleman Farthing is in the Gallows' End Tavern, the inn on Brill's east side.", when = {{ k = "turnedin", neg = true, q = 1505 }}, goals = {
		{ t = "turnin", quest = 1820, title = "Speak with Coleman", npc = "Coleman Farthing", map = 1420, x = 61.72, y = 52.29, era = true },
		{ t = "accept", quest = 1821, title = "Agamand Heirlooms", npc = "Coleman Farthing", map = 1420, x = 61.72, y = 52.29, era = true, qlvl = 11 },
	} },
	{ title = "The Agamand Family Crypt", note = "The four Agamand Weapon Racks are inside the Agamand Family Crypt at the north end of Agamand Mills, north of Brill, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them.", when = {{ k = "turnedin", neg = true, q = 1505 }}, goals = {
		{ t = "collect", quest = 1821, title = "Agamand Heirlooms", map = 1420, x = 51.68, y = 25.69, era = true, count = 1, item = 7567, itemName = "Agamand Family Axe", oi = 1 },
		{ t = "collect", quest = 1821, title = "Agamand Heirlooms", map = 1420, x = 51.88, y = 27.14, era = true, count = 1, item = 7568, itemName = "Agamand Family Dagger", oi = 2 },
		{ t = "collect", quest = 1821, title = "Agamand Heirlooms", map = 1420, x = 51.88, y = 27.14, era = true, count = 1, item = 7569, itemName = "Agamand Family Mace", oi = 3 },
		{ t = "collect", quest = 1821, title = "Agamand Heirlooms", map = 1420, x = 52.66, y = 25.85, era = true, count = 1, item = 7566, itemName = "Agamand Family Sword", oi = 4 },
	} },
	{ title = "Back to Coleman Farthing", when = {{ k = "turnedin", neg = true, q = 1505 }}, goals = {
