Waypost.RegisterSteps("collectibles/mounts/horde/black-war-mounts", function() return {
	{ title = "PvP rank 11", note = "Rank Points come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Lieutenant General (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. Riding one at full speed needs Journeyman Riding (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman Riding.", goals = {
		{ t = "level", level = 60 },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
	{ title = "Raider Bork", note = "Raider Bork sells the mounts by the Hall of Legends in Orgrimmar's Valley of Honor, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Orcs ride the wolf, Trolls the raptor, Tauren the kodo, Undead the skeletal warhorse. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city).", goals = {
		{ t = "vendor", npc = "Raider Bork", map = 1454, x = 37.9, y = 64.2, era = true },
		{ t = "buy", npc = "Raider Bork", map = 1454, x = 37.9, y = 64.2, era = true, item = 18245, itemName = "Horn of the Black War Wolf", optional = true, note = "Black War Wolf, Wolf Riding, 100g" },
		{ t = "buy", npc = "Raider Bork", map = 1454, x = 37.9, y = 64.2, era = true, item = 18246, itemName = "Whistle of the Black War Raptor", optional = true, note = "Black War Raptor, Raptor Riding, 100g" },
		{ t = "buy", npc = "Raider Bork", map = 1454, x = 37.9, y = 64.2, era = true, item = 18247, itemName = "Black War Kodo", optional = true, note = "Black War Kodo, Kodo Riding, 100g" },
		{ t = "buy", npc = "Raider Bork", map = 1454, x = 37.9, y = 64.2, era = true, item = 18248, itemName = "Red Skeletal Warhorse", optional = true, note = "Red Skeletal Warhorse, Undead Horsemanship, 100g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/horde/frostwolf-howler", function() return {
	{ title = "Frostwolf Clan", note = "Alterac Valley (level 51+) raises Frostwolf Clan: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. Jekyll Flandring waits at the Horde end of Alterac Mountains outside the battleground; Grunnda Wolfheart inside Alterac Valley sells the same mount.", goals = {
		{ t = "rep", factionName = "Frostwolf Clan", faction = 729, standing = 8 },
	} },
	{ title = "Horn of the Frostwolf Howler", note = "The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman Riding; any Horde race can ride it.", goals = {
		{ t = "level", level = 60 },
		{ t = "skill", level = 150, skillName = "Riding" },
		{ t = "buy", npc = "Jekyll Flandring", map = 1416, x = 62.84, y = 59.27, era = true, item = 19029, itemName = "Horn of the Frostwolf Howler", note = "Jekyll Flandring, 200g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/horde/great-kodo", function() return {
	{ title = "Journeyman Riding", note = "Kar Stormsinger and Harb Clawhoof's kodos are in Bloodhoof Village, Mulgore. At 60 Kar Stormsinger teaches Journeyman Riding to Tauren for 1,000g (10% less at Honored with Thunder Bluff); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each great kodo costs 200g here.", goals = {
		{ t = "level", level = 60 },
		{ t = "train", npc = "Kar Stormsinger", map = 1412, x = 46.79, y = 61.97, only = { races = {"Tauren"} }, note = "Kar Stormsinger, riding trainer" },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
	{ title = "Kodo Riding for other races", note = "Any Horde race can buy these kodos, but riding one also takes Kodo Riding, which only Tauren get with Riding. Kar Stormsinger teaches it to other races once they are Exalted with Thunder Bluff (the Thunder Bluff Reputation guide shows the way). Until then, don't buy a kodo for this character.", only = { races = {"Orc", "Troll", "Scourge", "Skyborne"} }, when = {{ k = "knows", neg = true, spell = 18995 }}, goals = {
		{ t = "rep", factionName = "Thunder Bluff", faction = 81, standing = 8 },
		{ t = "train", npc = "Kar Stormsinger", map = 1412, x = 46.79, y = 61.97, note = "Kar Stormsinger, Kodo Riding" },
	} },
	{ title = "Pick a colour", note = "Harb Clawhoof sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like.", goals = {
		{ t = "vendor", npc = "Harb Clawhoof", map = 1412, x = 46.65, y = 62.08 },
		{ t = "buy", npc = "Harb Clawhoof", map = 1412, x = 46.65, y = 62.08, item = 18793, itemName = "Great White Kodo", optional = true, note = "Great White Kodo, 200g" },
		{ t = "buy", npc = "Harb Clawhoof", map = 1412, x = 46.65, y = 62.08, item = 18794, itemName = "Great Brown Kodo", optional = true, note = "Great Brown Kodo, 200g" },
		{ t = "buy", npc = "Harb Clawhoof", map = 1412, x = 46.65, y = 62.08, item = 18795, itemName = "Great Gray Kodo", optional = true, note = "Great Gray Kodo, 200g" },
	} },
} end)

