	} },
	{ title = "The Venture Co. Mine", note = "Ride down the lift and south-east across Mulgore to the Venture Co. Mine. Put on the disguise, then open the carts of Blasting Supplies inside the mine and on the slope outside it; stay on the upper levels where you can, the lower tunnels are packed. Five charges.", goals = {
		{ t = "collect", quest = 76156, title = "Stalk With The Earthmother", map = 1412, x = 58.77, y = 47.41, count = 5, item = 206157, itemName = "Seaforium Mining Charge", oi = 1, note = "Seaforium Mining Charge, from the Blasting Supplies", spots = "58.7,47.4;59.9,49.5;56.8,43.3" },
	} },
	{ title = "Boarton Shadetotem", note = "Back to Boarton in Thunder Bluff. He gives you the Mortar and Pestle for his next test.", goals = {
		{ t = "turnin", quest = 76156, title = "Stalk With The Earthmother", npc = "Boarton Shadetotem", map = 1456, x = 39.44, y = 65.82, era = true },
		{ t = "accept", quest = 76160, title = "Stalk With The Earthmother", npc = "Boarton Shadetotem", map = 1456, x = 39.44, y = 65.82, era = true, qlvl = 11 },
	} },
	{ title = "Windfury Cones", note = "Windfury Cones lie on the ground under the harpies' nest trees on Windfury Ridge, north-west of Thunder Bluff; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the Mortar and Pestle to grind them.", goals = {
		{ t = "collect", map = 1412, x = 31.9, y = 32, count = 8, item = 206170, itemName = "Windfury Cone", optional = true, note = "the mortar takes all eight", spots = "31.9,32;31.8,35.2;38,22.4;39.1,19.8;51.6,21.1" },
		{ t = "use", quest = 76160, title = "Stalk With The Earthmother", map = 1412, x = 31.9, y = 32, item = 206176, itemName = "Mortar and Pestle", oi = 1, note = "grind the eight cones into the Pine Salve" },
	} },
	{ title = "Boarton Shadetotem", note = "Back to Boarton. He hands you the Knife Set for the last test.", goals = {
		{ t = "turnin", quest = 76160, title = "Stalk With The Earthmother", npc = "Boarton Shadetotem", map = 1456, x = 39.44, y = 65.82, era = true },
		{ t = "accept", quest = 76240, title = "Stalk With The Earthmother", npc = "Boarton Shadetotem", map = 1456, x = 39.44, y = 65.82, era = true, qlvl = 11 },
	} },
	{ title = "Raw Brilliant Smallfish", note = "Buy a Raw Brilliant Smallfish at the Auction House (Auctioneer Stampi, north of the pool), or fish one yourself: Kah Mistrunner trains Fishing and Sewa Mistrunner beside him sells the Fishing Pole and a Shiny Bauble; the pool on the main mesa gives smallfish at any skill. Then use the Knife Set on it, wherever you are.", goals = {
		{ t = "collect", map = 1456, x = 40.4, y = 51.8, era = true, count = 1, item = 6291, itemName = "Raw Brilliant Smallfish", optional = true, note = "Raw Brilliant Smallfish: the Auction House, or the pool; the knife takes it" },
		{ t = "use", quest = 76240, title = "Stalk With The Earthmother", map = 1456, x = 41.7, y = 59.9, era = true, item = 206344, itemName = "Knife Set", oi = 1, note = "fillet the smallfish into Fish Chunks (where players did it, on the way back to Boarton)" },
	} },
	{ title = "Boarton Shadetotem", note = "Take your weapon from Boarton: the Hoof-Holstered Blade or the Valley Cosh.", goals = {
		{ t = "turnin", quest = 76240, title = "Stalk With The Earthmother", npc = "Boarton Shadetotem", map = 1456, x = 39.44, y = 65.82, era = true },
	} },
} end)

Waypost.RegisterSteps("reputation/darkspear-trolls", function() return {
	{ title = "Vehena: how it works", note = "Darkspear reputation comes from quests and cloth. Vehena, the Darkspear cloth quartermaster, stands in Orgrimmar's Valley of Spirits. She takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with the Darkspear Trolls also gives a quarter as much to Orgrimmar, Thunder Bluff and the Undercity. While you level, do the Darkspear quests within 5 levels of them: Durotar at 5 to 12, Zoram Strand in Ashenvale at 19 to 27, Grom'gol in Stranglethorn at 34 to 46. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the Darkspear merchants sell to you for 10% less (the Classic rule), the raptor vendor included; at Exalted other races can buy the raptors: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60, once you have mount training. The Darkspear Trolls have no tabard or other reward.", goals = {
		{ t = "goto", map = 1454, x = 37.7, y = 87.9, era = true, note = "her donations are handed in from her window and never enter the log", text = "Vehena" },
	} },
	{ title = "Valley of Trials (optional hub)", note = "Forever pays these old quests in full at any level. The Valley of Trials is the best of them: about 1,400 Orgrimmar and 1,400 Darkspear reputation in 25 minutes. Gornek waits in the Den, the big hut; Kaltunk stands outside it.", label = "valley", goals = {
