	} },
	{ title = "Everlook: A Little Luck", note = "Luck Be With You is level 60, so it pays in full. Harlo Wigglesworth in Everlook sends you to Witch Doctor Mau'ari, who stands in the same town. The Frostmaul Shards lie on the ground in Frostwhisper Gorge, the canyon at the south end of Winterspring, and the Frostmaul Giants there drop them too (about one in five). The giants are elite level 59 and 60 and stand close together: pick the shards at the edges, pull one giant at a time, or bring a friend.", goals = {
		{ t = "level", level = 55 },
		{ t = "accept", quest = 6606, title = "A Little Luck", npc = "Harlo Wigglesworth", map = 1452, x = 61.12, y = 38.43, era = true, qlvl = 60, note = "Harlo Wigglesworth: A Little Luck" },
