		{ t = "turnin", quest = 969, title = "Luck Be With You", npc = "Witch Doctor Mau'ari", map = 1452, x = 61.92, y = 38.3, era = true },
	} },
	{ title = "Blackrock Mountain, with a group", note = "For The Horde! (Rend's head, Blackrock Spire) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city, the Darkspear Trolls included. Kargath in the Badlands starts the Rend chain: Warlord's Command, Eitrigg's Wisdom, then For The Horde!. Take them when your group goes. The Spider God chain of the Undercity guide (Zul'Farrak and the Hinterlands) pays 225 Darkspear on the way.", goals = {
		{ t = "accept", quest = 4903, title = "Warlord's Command", npc = "Warlord Goretooth", map = 1418, x = 5.81, y = 47.52, era = true, qlvl = 60, optional = true, group = true, note = "Warlord Goretooth: Warlord's Command, a group of five" },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (a troll starts at Friendly 1,000: 100 hand-ins; an Undead or Skyborne at Neutral 2,000 first needs 20 more to reach Friendly). Hand in every 20 you carry, one after another.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
