		{ t = "rep", factionName = "Darkspear Trolls", faction = 530, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth. The Auction House price of a stack decides whether to farm or buy.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7837, title = "Additional Runecloth", npc = "Vehena", map = 1454, x = 37.7, y = 87.9, era = true, qlvl = 60, optional = true, note = "Additional Runecloth, +50" },
		{ t = "rep", factionName = "Darkspear Trolls", faction = 530, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. At Exalted, Zjolnir in Sen'jin Village sells the raptors to every Horde race: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true },
