		{ t = "talk", npc = "Zjolnir", map = 1411, x = 55.23, y = 75.65, era = true, optional = true, note = "Zjolnir: the raptors" },
	} },
} end)

Waypost.RegisterSteps("reputation/orgrimmar", function() return {
	{ title = "Orgrimmar: how it works", note = "Orgrimmar reputation comes from quests and cloth. Rashona Straglash, the cloth quartermaster, stands in the Drag beside the cloth and leather armor shop. She takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with Orgrimmar also gives a quarter as much to Thunder Bluff, the Undercity and the Darkspear Trolls. While you level, do Orgrimmar's quests within 5 levels of them: Durotar at 5 to 12, the Crossroads at 12 to 20, Thrall's Hidden Enemies at 12 to 16. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored Orgrimmar's merchants sell to you for 10% less (the Classic rule), the wolf vendor included; at Exalted other races can buy the wolves: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60, once you have mount training. Orgrimmar has no tabard or other reward.", goals = {
		{ t = "goto", map = 1454, x = 63.6, y = 51.2, era = true, note = "her donations are handed in from her window and never enter the log", text = "Rashona Straglash" },
	} },
	{ title = "Valley of Trials (optional hub)", note = "Forever pays these old quests in full at any level. The Valley of Trials is the best of them: about 1,400 Orgrimmar and 1,400 Darkspear reputation in 25 minutes. Gornek waits in the Den, the big hut; Kaltunk stands outside it.", label = "valley", goals = {
		{ t = "accept", quest = 787, title = "The New Horde", npc = "Eitrigg", map = 1454, x = 34.28, y = 39.35, era = true, qlvl = 1, note = "Eitrigg, in Orgrimmar: The New Horde, +50" },
		{ t = "turnin", quest = 787, title = "The New Horde", npc = "Gornek", map = 1411, x = 42.06, y = 68.33, era = true },
		{ t = "accept", quest = 4641, title = "Your Place in the World", npc = "Kaltunk", map = 1411, x = 43.29, y = 68.53, era = true, qlvl = 1, note = "Kaltunk: Your Place in the World, +50" },
