	{ title = "Belgrom Rockmaul: Betrayed", note = "Belgrom stands in the Valley of Honor outside the Hall of the Brave. The first two Betrayed quests are level 53 and pay in full at 60 too, as every quest does in Forever.", goals = {
		{ t = "accept", quest = 3504, title = "Betrayed", npc = "Belgrom Rockmaul", map = 1454, x = 75.23, y = 34.24, era = true, qlvl = 53, note = "Betrayed, +50" },
	} },
	{ title = "Valormok", note = "Fly to Valormok in western Azshara. Ag'tor Bloodfist sends you north-east to the blood elf camp on the bluffs of the northern peninsula.", goals = {
