	{ title = "Magus Rimtori's camp", note = "Kill the Reclaimers and Surveyors, then walk up to the book inside the ring of stone pillars. Read the Kaldorei Tome of Summoning there to start the next quest: break the crystals around the circle, kill the guard that comes, then Magus Rimtori.", goals = {
		{ t = "kill", quest = 3505, title = "Betrayed", map = 1447, x = 55.6, y = 30.13, era = true, count = 10, target = "Blood Elf Reclaimer", oi = 1, mobLevel = 53, spots = "56.3,29.8;55.9,27.3;58.3,28;57,25.9;58.8,29.3" },
		{ t = "kill", quest = 3505, title = "Betrayed", map = 1447, x = 55.46, y = 29.5, era = true, count = 10, target = "Blood Elf Surveyor", oi = 2, mobLevel = 52, spots = "55.8,29.9;57.4,28.1;58.4,26.9;55.4,26.5;58.2,31.2" },
		{ t = "complete", quest = 3505, title = "Betrayed", map = 1447, x = 59.5, y = 31.5, era = true, note = "Find Magus Rimtori's camp", objs = {"Blood Elf Reclaimer", "Blood Elf Surveyor", "Find Magus Rimtori's camp"} },
		{ t = "turnin", quest = 3505, title = "Betrayed", npc = "Kaldorei Tome of Summoning", map = 1447, x = 59.51, y = 31.3, era = true, note = "the Kaldorei Tome of Summoning" },
		{ t = "accept", quest = 3506, title = "Betrayed", npc = "Kaldorei Tome of Summoning", map = 1447, x = 59.51, y = 31.3, era = true, qlvl = 56, note = "Betrayed, +75" },
