	{ title = "Valormok and Orgrimmar", goals = {
		{ t = "turnin", quest = 3506, title = "Betrayed", npc = "Ag'tor Bloodfist", map = 1447, x = 22.26, y = 51.48, era = true },
		{ t = "accept", quest = 3507, title = "Betrayed", npc = "Ag'tor Bloodfist", map = 1447, x = 22.26, y = 51.48, era = true, qlvl = 56, note = "Betrayed, +150" },
		{ t = "turnin", quest = 3507, title = "Betrayed", npc = "Belgrom Rockmaul", map = 1454, x = 75.23, y = 34.24, era = true, note = "Belgrom Rockmaul, in Orgrimmar" },
		{ t = "note", text = "Betrayed: 300 Orgrimmar reputation at 60." },
	} },
	{ title = "Blackrock Mountain, with a group", note = "Kargath in the Badlands hands out Orgrimmar quests for Blackrock Depths and Blackrock Spire, all level 58 to 60 and paid in full: Precarious Predicament and Operation: Death to Angerforge (150 each), The Pack Mistress and Bijou's Reconnaissance Report (100 each), Warlord's Command (150), Eitrigg's Wisdom (100) and For The Horde! (Rend's head, 200 to every Horde city). These are dungeon quests: take them when your group goes.", goals = {
		{ t = "accept", quest = 4903, title = "Warlord's Command", npc = "Warlord Goretooth", map = 1418, x = 5.81, y = 47.52, era = true, qlvl = 60, optional = true, group = true, note = "Warlord Goretooth: Warlord's Command, +150, a group of five" },
		{ t = "accept", quest = 4724, title = "The Pack Mistress", npc = "Galamav the Marksman", map = 1418, x = 5.96, y = 47.73, era = true, qlvl = 59, optional = true, group = true, note = "Galamav the Marksman: The Pack Mistress, +100, a group of five" },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (an orc starts at Friendly 1,000: 100 hand-ins; an Undead or Skyborne starts at Neutral 2,000 and first needs 20 hand-ins, 400 Runecloth, to reach Friendly). Hand in every 20 you carry, one after another.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
		{ t = "turnin", quest = 7832, title = "Additional Runecloth", npc = "Rashona Straglash", map = 1454, x = 63.6, y = 51.23, era = true, qlvl = 60, optional = true, note = "Rashona Straglash: Additional Runecloth, +50" },
		{ t = "rep", factionName = "Orgrimmar", faction = 76, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth. The Auction House price of a stack decides whether to farm or buy.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7832, title = "Additional Runecloth", npc = "Rashona Straglash", map = 1454, x = 63.6, y = 51.23, era = true, qlvl = 60, optional = true, note = "Additional Runecloth, +50" },
		{ t = "rep", factionName = "Orgrimmar", faction = 76, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. Raid heads pay too: The Lord of Blackrock (Nefarian) 200 to every Horde city and Victory for the Horde (Onyxia) 400 to Orgrimmar. At Exalted, Ogunaro Wolfrunner in the Valley of Honor sells the wolves to every Horde race: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7832, title = "Additional Runecloth", npc = "Rashona Straglash", map = 1454, x = 63.6, y = 51.23, era = true, qlvl = 60, optional = true, note = "Additional Runecloth, +50" },
