		{ t = "turnin", quest = 7821, title = "A Donation of Silk", npc = "Rumstag Proudstrider", map = 1456, x = 43.05, y = 42.72, era = true, qlvl = 60, note = "+150" },
	} },
	{ title = "A Donation of Mageweave", note = "Mageweave: the Jadefire satyrs in southern Felwood and the Dunemaul ogres in Tanaris drop it about one kill in three, or buy it.", goals = {
		{ t = "level", level = 40 },
		{ t = "collect", map = 1448, x = 41.6, y = 85.7, era = true, count = 60, item = 4338, itemName = "Mageweave Cloth", note = "Mageweave Cloth: the Jadefire satyrs" },
		{ t = "turnin", quest = 7822, title = "A Donation of Mageweave", npc = "Rumstag Proudstrider", map = 1456, x = 43.05, y = 42.72, era = true, qlvl = 60, note = "+150" },
	} },
	{ title = "A Donation of Runecloth", note = "Runecloth: the Scarlet at Tyr's Hand in the Eastern Plaguelands, the Gordok ogres outside Dire Maul in Feralas and the Twilight camps of Silithus drop it about one kill in three. The Auction House is faster if you have gold.", goals = {
		{ t = "level", level = 50 },
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 60, item = 14047, itemName = "Runecloth", note = "Runecloth: the Scarlet outside Tyr's Hand" },
