	} },
	{ title = "Everlook: Storm Shadowhoof", note = "Storm Shadowhoof's four quests are level 56 to 60, so they pay in full: 400 Thunder Bluff reputation. Ursius, an elite bear, walks a loop over the four hills north of Everlook: wait on a hilltop for him.", goals = {
		{ t = "level", level = 55 },
		{ t = "accept", quest = 5054, title = "Ursius of the Shardtooth", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true, qlvl = 56, note = "Ursius of the Shardtooth, +100" },
		{ t = "kill", quest = 5054, title = "Ursius of the Shardtooth", map = 1452, x = 60.92, y = 32.9, era = true, count = 1, target = "Ursius", oi = 1, group = true, note = "Ursius, elite" },
		{ t = "turnin", quest = 5054, title = "Ursius of the Shardtooth", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true },
		{ t = "accept", quest = 5055, title = "Brumeran of the Chillwind", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true, qlvl = 58, note = "Brumeran of the Chillwind, +100" },
	} },
	{ title = "Brumeran and Shy-Rotam", note = "Brumeran, an elite chimera, spawns south of Everlook. For Shy-Rotam, kill frostsabers north of Everlook until one drops Sacred Frostsaber Meat (about one in ten), then use the meat at the Stone of Shy-Rotam, far to the north, and kill the great cat that comes. If you have done Trull Failbane's Wild Guardians quests (the Orgrimmar guide), the Crazed, Moontouched and Berserk owlbeasts around Everlook sometimes drop a Blue-feathered Necklace: it starts Guarding Secrets, 50 Orgrimmar and then 100 Thunder Bluff reputation in full.", goals = {
		{ t = "kill", quest = 5055, title = "Brumeran of the Chillwind", map = 1452, x = 62.54, y = 57.9, era = true, count = 1, target = "Brumeran", oi = 1, group = true, note = "Brumeran, elite" },
		{ t = "turnin", quest = 5055, title = "Brumeran of the Chillwind", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true },
		{ t = "accept", quest = 5056, title = "Shy-Rotam", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true, qlvl = 60, note = "Shy-Rotam, +150" },
		{ t = "collect", map = 1452, x = 56.62, y = 17.19, era = true, item = 12733, itemName = "Sacred Frostsaber Meat", mobLevel = 60, optional = true, note = "Sacred Frostsaber Meat, from the frostsabers", spots = "56.2,16.7;56.3,12.5;54.5,10.9;52.4,11.5;51,14.1" },
		{ t = "kill", quest = 5056, title = "Shy-Rotam", map = 1452, x = 49.81, y = 9.8, era = true, count = 1, target = "Shy-Rotam", oi = 1, group = true },
		{ t = "turnin", quest = 5056, title = "Shy-Rotam", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true },
		{ t = "accept", quest = 5057, title = "Past Endeavors", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true, qlvl = 60, note = "Past Endeavors, +50" },
		{ t = "turnin", quest = 5057, title = "Past Endeavors", npc = "Storm Shadowhoof", map = 1452, x = 61.93, y = 38.38, era = true },
	} },
	{ title = "Bloodvenom Post: Trull Failbane", note = "Trull Failbane stands at Bloodvenom Post, through the Timbermaw tunnel south of Winterspring.", when = {{ k = "onquest", q = {4882} }}, goals = {
		{ t = "turnin", quest = 4882, title = "Guarding Secrets", npc = "Trull Failbane", map = 1448, x = 34.73, y = 52.79, era = true },
		{ t = "accept", quest = 4883, title = "Guarding Secrets", npc = "Trull Failbane", map = 1448, x = 34.73, y = 52.79, era = true, qlvl = 59, note = "Guarding Secrets, +100: to Nara Wildmane in Thunder Bluff" },
