	{ title = "Thunder Bluff: Nara Wildmane", note = "Nara Wildmane stands on Elder Rise, beside Arch Druid Hamuul Runetotem.", when = {{ k = "onquest", q = {4883} }}, goals = {
		{ t = "turnin", quest = 4883, title = "Guarding Secrets", npc = "Nara Wildmane", map = 1456, x = 75.65, y = 31.61, era = true },
	} },
	{ title = "Morrowgrain (optional)", note = "Morrowgrain to Thunder Bluff takes 10 Morrowgrain for 50, as often as you like, and pays in full at 60, but it is slow: the Evergreen Pouch grows one casing every 10 minutes and a casing holds about one Morrowgrain on average, so each hand-in takes about 90 minutes of waiting, 18 Un'Goro Soil and 9 seed packets (90 silver). It runs beside whatever else you do: a little over 30 reputation an hour. The chain before it is level 50. Innkeeper Pala sends you to Arch Druid Hamuul Runetotem on Elder Rise; he wants 20 Un'Goro Soil.", label = "morrowgrain", goals = {
		{ t = "accept", quest = 3762, title = "Assisting Arch Druid Runetotem", npc = "Innkeeper Pala", map = 1456, x = 45.81, y = 64.71, era = true, qlvl = 50, note = "Innkeeper Pala: Assisting Arch Druid Runetotem" },
		{ t = "turnin", quest = 3762, title = "Assisting Arch Druid Runetotem", npc = "Arch Druid Hamuul Runetotem", map = 1456, x = 78.62, y = 28.56, era = true },
		{ t = "accept", quest = 3761, title = "Un'Goro Soil", npc = "Arch Druid Hamuul Runetotem", map = 1456, x = 78.62, y = 28.56, era = true, qlvl = 50, note = "Un'Goro Soil, +100" },
	} },
	{ title = "Un'Goro Crater: Un'Goro Soil", note = "Nearly every beast, plant and silithid in the crater drops Un'Goro Soil, about one kill in three (the Bloodpetals and the Gorishi wasps about one in two), and the dirt mounds give it too. Take far more than 20: every casing uses 2, about 18 for each Morrowgrain hand-in.", when = {{ k = "done", label = "morrowgrain" }}, goals = {
		{ t = "collect", quest = 3761, title = "Un'Goro Soil", map = 1449, x = 46.7, y = 52.71, era = true, count = 20, item = 11018, itemName = "Un'Goro Soil", oi = 1, spots = "45.9,53.7;35.2,40.8;30,56.8;31.7,77.5;50.5,90.1" },
	} },
	{ title = "Thunder Bluff: Morrowgrain Research", note = "Ghede takes the soil. Bashana Runetotem sells the Evergreen Pouch (1 gold) and Packets of Tharlendris Seeds (10 silver each). With a seed packet and 2 Un'Goro Soil in your bags, use the pouch: it grows an Evergreen Herb Casing, once every 10 minutes. Open each casing: about one in three holds 1 to 5 Morrowgrain, the rest common herbs. Use the pouch whenever it is ready while you follow the rest of this guide.", when = {{ k = "done", label = "morrowgrain" }}, goals = {
		{ t = "turnin", quest = 3761, title = "Un'Goro Soil", npc = "Ghede", map = 1456, x = 77.46, y = 21.97, era = true },
		{ t = "accept", quest = 3782, title = "Morrowgrain Research", npc = "Arch Druid Hamuul Runetotem", map = 1456, x = 78.62, y = 28.56, era = true, qlvl = 50, note = "Arch Druid Hamuul Runetotem: Morrowgrain Research" },
		{ t = "turnin", quest = 3782, title = "Morrowgrain Research", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true },
		{ t = "accept", quest = 3786, title = "Morrowgrain Research", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, qlvl = 50, note = "Morrowgrain Research, +100" },
		{ t = "buy", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, item = 11020, itemName = "Evergreen Pouch", note = "Evergreen Pouch, 1 gold" },
		{ t = "buy", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, count = 10, item = 11022, itemName = "Packet of Tharlendris Seeds", note = "Packet of Tharlendris Seeds, 10 silver each" },
	} },
	{ title = "Morrowgrain as you go", when = {{ k = "done", label = "morrowgrain" }}, goals = {
		{ t = "collect", quest = 3786, title = "Morrowgrain Research", map = 1456, x = 71.1, y = 34.2, era = true, count = 10, item = 11040, itemName = "Morrowgrain", oi = 1, note = "Morrowgrain: use the pouch every 10 minutes and open the casings; Bashana takes it" },
	} },
	{ title = "Bashana Runetotem: Morrowgrain Research", note = "Bashana Runetotem stands on Elder Rise. If your 10 Morrowgrain are not ready yet, skip this step and go on with the cloth: the cloth steps below list the Morrowgrain hand-in too.", when = {{ k = "done", label = "morrowgrain" }}, label = "morrowgrain-in", goals = {
		{ t = "turnin", quest = 3786, title = "Morrowgrain Research", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true },
		{ t = "collect", map = 1456, x = 71.1, y = 34.2, era = true, count = 10, item = 11040, itemName = "Morrowgrain", optional = true },
		{ t = "turnin", quest = 3804, title = "Morrowgrain to Thunder Bluff", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, qlvl = 55, optional = true, note = "Morrowgrain to Thunder Bluff, +50" },
	} },
	{ title = "Additional Runecloth to Honored", note = "Additional Runecloth: 20 Runecloth for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 Runecloth, less what the quests gave you (a tauren starts at Friendly 1,000: 100 hand-ins; an Undead at Neutral 500 first needs 50 more to reach Friendly). Hand in every 20 you carry, one after another.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true, note = "Runecloth: the Scarlet outside Tyr's Hand" },
		{ t = "turnin", quest = 7825, title = "Additional Runecloth", npc = "Rumstag Proudstrider", map = 1456, x = 43.05, y = 42.72, era = true, qlvl = 60, optional = true, note = "Rumstag Proudstrider: Additional Runecloth, +50" },
		{ t = "collect", map = 1456, x = 71.1, y = 34.2, era = true, count = 10, item = 11040, itemName = "Morrowgrain", optional = true, note = "Morrowgrain, if you grow it: Bashana takes it" },
		{ t = "turnin", quest = 3804, title = "Morrowgrain to Thunder Bluff", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, qlvl = 55, optional = true, note = "Bashana Runetotem: Morrowgrain to Thunder Bluff, +50" },
		{ t = "rep", factionName = "Thunder Bluff", faction = 81, standing = 6 },
	} },
	{ title = "Additional Runecloth to Revered", note = "Honored to Revered is 12,000: 240 hand-ins, 4,800 Runecloth, fewer if you also hand in Morrowgrain. Blackrock Depths pays too: Disharmony of Flame and Disharmony of Fire from Thunderheart at Kargath (Lord Incendius, 150 in full).", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7825, title = "Additional Runecloth", npc = "Rumstag Proudstrider", map = 1456, x = 43.05, y = 42.72, era = true, qlvl = 60, optional = true, note = "Additional Runecloth, +50" },
		{ t = "collect", map = 1456, x = 71.1, y = 34.2, era = true, count = 10, item = 11040, itemName = "Morrowgrain", optional = true, note = "Morrowgrain, if you grow it" },
		{ t = "turnin", quest = 3804, title = "Morrowgrain to Thunder Bluff", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, qlvl = 55, optional = true, note = "Morrowgrain to Thunder Bluff, +50" },
		{ t = "rep", factionName = "Thunder Bluff", faction = 81, standing = 7 },
	} },
	{ title = "Additional Runecloth to Exalted", note = "Revered to Exalted is 21,000: 420 hand-ins, 8,400 Runecloth. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, Harb Clawhoof in Bloodhoof Village sells the kodos to every Horde race: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.", goals = {
		{ t = "collect", map = 1423, x = 68, y = 69.5, count = 20, item = 14047, itemName = "Runecloth", optional = true },
		{ t = "turnin", quest = 7825, title = "Additional Runecloth", npc = "Rumstag Proudstrider", map = 1456, x = 43.05, y = 42.72, era = true, qlvl = 60, optional = true, note = "Additional Runecloth, +50" },
		{ t = "collect", map = 1456, x = 71.1, y = 34.2, era = true, count = 10, item = 11040, itemName = "Morrowgrain", optional = true, note = "Morrowgrain, if you grow it" },
		{ t = "turnin", quest = 3804, title = "Morrowgrain to Thunder Bluff", npc = "Bashana Runetotem", map = 1456, x = 71.06, y = 34.19, era = true, qlvl = 55, optional = true, note = "Morrowgrain to Thunder Bluff, +50" },
		{ t = "rep", factionName = "Thunder Bluff", faction = 81, standing = 8 },
		{ t = "talk", npc = "Harb Clawhoof", map = 1412, x = 46.65, y = 62.08, optional = true, note = "Harb Clawhoof: the kodos" },
	} },
} end)

Waypost.RegisterSteps("reputation/undercity", function() return {
	{ title = "Undercity: how it works", note = "Undercity reputation comes from quests and cloth. Ralston Farnsley, the cloth quartermaster, stands in the Magic Quarter beside the tailors. He takes four one-time donations of 60 cloth (150 each) and then Additional Runecloth, 20 Runecloth for 50, as often as you like. Every point you earn with the Undercity also gives a quarter as much to Orgrimmar, Thunder Bluff and the Darkspear Trolls. While you level, do the Undercity's quests within 5 levels of them: Tirisfal at 1 to 12, Silverpine at 10 to 20, Hillsbrad and Tarren Mill at 20 to 33. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the Undercity's merchants sell to you for 10% less (the Classic rule), the horse vendor included; at Exalted other races can buy the skeletal horses: 20 gold for a level 40 horse, 200 gold for a level 60 warhorse, once you have mount training. The Undercity has no tabard or other reward.", goals = {
		{ t = "goto", map = 1458, x = 71.7, y = 29.2, era = true, note = "his donations are handed in from his window and never enter the log", text = "Ralston Farnsley" },
	} },
	{ title = "Deathknell (optional hub)", note = "Forever pays these old quests in full at any level. Deathknell, the Forsaken start at the west end of Tirisfal: about 900 Undercity reputation in 25 minutes. Starting-zone quests give the other cities no share. Novice Elreth, Executor Arren and Deathguard Saltain stand in the village.", label = "deathknell", goals = {
		{ t = "accept", quest = 376, title = "The Damned", npc = "Novice Elreth", map = 1420, x = 30.86, y = 66.05, era = true, qlvl = 2, note = "Novice Elreth: The Damned, +100" },
		{ t = "collect", quest = 376, title = "The Damned", map = 1420, x = 29.4, y = 65.67, era = true, count = 6, item = 3265, itemName = "Scavenger Paw", oi = 1, mobLevel = 1, spots = "29.5,64.8;29.2,67.7;30.3,61.9;33.6,67.7;31.7,59" },
		{ t = "collect", quest = 376, title = "The Damned", map = 1420, x = 29.14, y = 66.71, era = true, count = 6, item = 3264, itemName = "Duskbat Wing", oi = 2, mobLevel = 2, spots = "28.8,68;29.9,65.3;28.1,63.6;31,58.8;34.6,57.8" },
		{ t = "turnin", quest = 376, title = "The Damned", npc = "Novice Elreth", map = 1420, x = 30.86, y = 66.05, era = true },
	} },
	{ title = "Deathknell: the next quests", when = {{ k = "done", label = "deathknell" }}, goals = {
