		{ t = "kill", quest = 380, title = "Night Web's Hollow", map = 1420, x = 29.4, y = 59.42, era = true, count = 10, target = "Young Night Web Spider", oi = 1, mobLevel = 3, spots = "28.2,59.3;29.6,57.5;29.4,55.9;27.8,56.5" },
