	{ title = "Moonglade", note = "Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs, past the armor vendor. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Sindrayl, south of the lake) for later, then take Silva Fil'naveth's flight from the middle of Nighthaven: she flies druids straight to Rut'theran Village, no flight path needed. Take the portal up to Darnassus.", only = { races = {"NightElf"} }, goals = {
		{ t = "turnin", quest = 5921, title = "Moonglade", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true },
		{ t = "accept", quest = 5929, title = "Great Bear Spirit", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true, qlvl = 10 },
		{ t = "complete", quest = 5929, title = "Great Bear Spirit", map = 1450, x = 39.1, y = 27.5, era = true, note = "Speak with the Great Bear Spirit", objs = {"Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear."} },
		{ t = "turnin", quest = 5929, title = "Great Bear Spirit", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true },
		{ t = "accept", quest = 5931, title = "Back to Darnassus", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true, qlvl = 10 },
		{ t = "getfp", npc = "Sindrayl", map = 1450, x = 48.1, y = 67.34, era = true, location = "Moonglade" },
		{ t = "fly", location = "Rut'theran Village" },
	} },
	{ title = "Cenarion Enclave", only = { races = {"NightElf"} }, goals = {
		{ t = "goto", map = 1457, x = 35.8, y = 11.6, era = true, text = "Cenarion Enclave" },
