Waypost.RegisterSteps("class/druid/bloodpetal-poison", function() return {
	{ title = "Loganaar", note = "Cast Teleport: Moonglade. Loganaar stands in Nighthaven; your class trainer (Turak Runetotem, Mathrengyl Bearwalker or Theridran in Stormwind) offers the same quest.", goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 9063, title = "Torwa Pathfinder", npc = "Loganaar", map = 1450, x = 52.53, y = 40.57, era = true, qlvl = 52 },
	} },
	{ title = "Torwa Pathfinder", note = "Fly to Gadgetzan, ride west to the long ramp down into Un'Goro Crater: Torwa camps at its foot, in the south-east corner of the crater.", goals = {
		{ t = "turnin", quest = 9063, title = "Torwa Pathfinder", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true },
		{ t = "accept", quest = 9052, title = "Bloodpetal Poison", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true, qlvl = 52 },
	} },
	{ title = "Gorishi Stings and Bloodcap", note = "Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the Slithering Scar, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' Silithid Pox makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around Marshal's Refuge and the western half): open them, about every other one gives a Bloodcap, back in three to five minutes.", goals = {
		{ t = "collect", quest = 9052, title = "Bloodpetal Poison", map = 1449, x = 56.37, y = 84.9, era = true, count = 8, item = 22435, itemName = "Gorishi Sting", oi = 1, mobLevel = 53, spots = "55.2,84.4;52.4,84.5;51.5,80.4;53.8,75.7;49,84.4" },
		{ t = "collect", quest = 9052, title = "Bloodpetal Poison", map = 1449, x = 53.34, y = 70.37, era = true, count = 8, item = 22434, itemName = "Bloodcap", oi = 2, spots = "50.3,69.9;41.2,63.2;31.3,67;27.1,52.8;28.6,37.1" },
	} },
	{ title = "Torwa Pathfinder", goals = {
		{ t = "turnin", quest = 9052, title = "Bloodpetal Poison", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true },
		{ t = "accept", quest = 9051, title = "Toxic Test", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true, qlvl = 52 },
	} },
	{ title = "Toxic Test", note = "Any Devilsaur counts, the Ironhide and Tyrant Devilsaurs too. They are elite (level 54-55), hit with Mighty Blow and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or Entangling Roots it from range, stab it with the Devilsaur Barb (the barb does not break Hibernate), then leave. The credit counts the moment the barb lands, even if you die after. The arrow points at the plain Devilsaurs of the west and north; an Ironhide Devilsaur roams the middle of the crater's south, nearer Torwa.", goals = {
		{ t = "kill", quest = 9051, title = "Toxic Test", map = 1449, x = 57.26, y = 23.68, era = true, count = 1, target = "Devilsaur", oi = 1, mobLevel = 55, group = true, note = "Devilsaur: stab it with the Devilsaur Barb", text = "Stab a Devilsaur with the Devilsaur Barb", spots = "57.3,23.7;34.6,22.4;31.2,36.4" },
	} },
	{ title = "Torwa Pathfinder", goals = {
		{ t = "turnin", quest = 9051, title = "Toxic Test", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true },
		{ t = "accept", quest = 9053, title = "A Better Ingredient", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true, qlvl = 52 },
	} },
	{ title = "The Sunken Temple", note = "A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north. The Temple of Atal'Hakkar stands in the middle of the Pool of Tears in the Swamp of Sorrows: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Atal'alarion (level 50 elite, Sweeping Slam and Ground Tremor) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The Putrid Vine always drops.", goals = {
		{ t = "goto", map = 1435, x = 69.9, y = 53.6, era = true, text = "The Temple of Atal'Hakkar" },
		{ t = "collect", quest = 9053, title = "A Better Ingredient", map = 1435, x = 69.9, y = 53.6, era = true, count = 1, item = 22444, itemName = "Putrid Vine", oi = 1, group = true, note = "Putrid Vine: Atal'alarion" },
	} },
	{ title = "A Better Ingredient", note = "Back to Torwa in the south-east corner of Un'Goro Crater.", goals = {
		{ t = "turnin", quest = 9053, title = "A Better Ingredient", npc = "Torwa Pathfinder", map = 1449, x = 71.64, y = 75.96, era = true, note = "Torwa Pathfinder: the old item choice may be gone, count on the experience" },
	} },
} end)

Waypost.RegisterSteps("class/druid/cat-form", function() return {
	{ title = "Cenarion Enclave", note = "Mathrengyl Bearwalker stands in the Cenarion Enclave. Skyborne far from Darnassus: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to Dendrite, and its Trial of the Lake (the Aquatic Form guide) is in the same Moonglade.", only = { races = {"NightElf", "Skyborne"}, factions = {"Alliance"} }, goals = {
