		{ t = "accept", quest = 98341, title = "The Great Windborne Cat Spirit", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true, qlvl = 20, only = { races = {"Skyborne"} } },
		{ t = "getfp", npc = "Sindrayl", map = 1450, x = 48.1, y = 67.34, era = true, location = "Moonglade" },
	} },
	{ title = "The relics of the Barrow Dens", note = "The Great Cat Spirit (Night Elves) waits on the hill above the bridge in southern Moonglade; the Avatar of Saeyleenan (Skyborne) stands on high ground past the twin bridges, south-west of Nighthaven: climb up to it. The relics lie in the Stormrage Barrow Dens east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more.", only = { races = {"NightElf", "Skyborne"}, factions = {"Alliance"} }, goals = {
		{ t = "turnin", quest = 98394, title = "The Great Cat Spirit", npc = "Great Cat Spirit", map = 1450, x = 54.5, y = 75, era = true, only = { races = {"NightElf"} } },
		{ t = "accept", quest = 98396, title = "The Great Cat Spirit", npc = "Great Cat Spirit", map = 1450, x = 54.5, y = 75, era = true, qlvl = 20, only = { races = {"NightElf"} } },
		{ t = "turnin", quest = 98341, title = "The Great Windborne Cat Spirit", npc = "Avatar of Saeyleenan", map = 1450, x = 43.92, y = 73.44, era = true, only = { races = {"Skyborne"} } },
		{ t = "accept", quest = 98404, title = "The Great Windborne Cat Spirit", npc = "Avatar of Saeyleenan", map = 1450, x = 43.92, y = 73.44, era = true, qlvl = 20, only = { races = {"Skyborne"} } },
		{ t = "collect", quest = 98396, title = "The Great Cat Spirit", map = 1450, x = 72.4, y = 66, era = true, count = 1, item = 280502, itemName = "Relic of the Fang", oi = 1, only = { races = {"NightElf"} } },
		{ t = "collect", quest = 98396, title = "The Great Cat Spirit", map = 1450, x = 75.2, y = 67.2, era = true, count = 1, item = 280679, itemName = "Relic of the Claw", oi = 2, only = { races = {"NightElf"} } },
