	} },
	{ title = "Sickly Gazelles", note = "Use the Curative Animal Salve on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the Ashenvale border, north-west of the Crossroads and west of Ratchet. Druid trick: root a gazelle with Entangling Roots, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from Tonga for a fresh salve.", only = { races = {"Tauren", "Skyborne"}, factions = {"Horde"} }, goals = {
		{ t = "kill", quest = 6129, title = "Curing the Sick", map = 1413, x = 54.5, y = 32.09, era = true, count = 10, target = "Sickly Gazelle", oi = 1, mobLevel = 3, text = "Use the Curative Animal Salve on Sickly Gazelles", spots = "54.6,31;54.5,37.4;49.8,36.9;43.2,37.7;44.9,28.2" },
	} },
	{ title = "Curing the Sick", note = "Cast Teleport: Moonglade and see Dendrite Starblaze, then take Bunthen Plainswind's flight to Thunder Bluff. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", only = { races = {"Tauren", "Skyborne"}, factions = {"Horde"} }, goals = {
		{ t = "turnin", quest = 6129, title = "Curing the Sick", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true },
		{ t = "accept", quest = 6130, title = "Power over Poison", npc = "Dendrite Starblaze", map = 1450, x = 56.21, y = 30.64, era = true, qlvl = 14 },
		{ t = "fly", location = "Thunder Bluff" },
	} },
	{ title = "Power over Poison", note = "Turak Runetotem on Elder Rise teaches you Cure Poison.", only = { races = {"Tauren", "Skyborne"}, factions = {"Horde"} }, goals = {
		{ t = "turnin", quest = 6130, title = "Power over Poison", npc = "Turak Runetotem", map = 1456, x = 76.48, y = 27.22, era = true, note = "Turak Runetotem: Cure Poison" },
	} },
} end)

Waypost.RegisterSteps("class/hunter/rhokdelar", function() return {
	{ title = "The Ancient Petrified Leaf", note = "Molten Core is a 40-player raid inside Blackrock Mountain. When Majordomo Executus yields, the Cache of the Firelord appears; it holds the Ancient Petrified Leaf about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest.", goals = {
		{ t = "accept", quest = 7632, title = "The Ancient Leaf", item = 18703, itemName = "Ancient Petrified Leaf", qlvl = 60, group = true, note = "from the Ancient Petrified Leaf" },
	} },
	{ title = "Vartrus the Ancient", note = "Vartrus, Stoma and Hastat the Ancient are petrified trees on a small island in a ring-shaped lake in Irontree Woods, north Felwood. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to Talonbranch Glade; Horde: fly to Bloodvenom Post. Vartrus gives Stave of the Ancients, Stoma A Proper String, Hastat the quiver; each can be handed in on its own.", goals = {
		{ t = "turnin", quest = 7632, title = "The Ancient Leaf", npc = "Vartrus the Ancient", map = 1448, x = 47.78, y = 24.08, era = true },
		{ t = "accept", quest = 7633, title = "An Introduction", npc = "Vartrus the Ancient", map = 1448, x = 47.78, y = 24.08, era = true, qlvl = 60 },
		{ t = "turnin", quest = 7633, title = "An Introduction", npc = "Vartrus the Ancient", map = 1448, x = 47.78, y = 24.08, era = true },
		{ t = "accept", quest = 7636, title = "Stave of the Ancients", npc = "Vartrus the Ancient", map = 1448, x = 47.78, y = 24.08, era = true, qlvl = 60 },
		{ t = "accept", quest = 7635, title = "A Proper String", npc = "Stoma the Ancient", map = 1448, x = 48.39, y = 22.29, era = true, qlvl = 60 },
		{ t = "accept", quest = 7634, title = "Ancient Sinew Wrapped Lamina", npc = "Hastat the Ancient", map = 1448, x = 46.7, y = 24.06, era = true, qlvl = 60, note = "Hastat the Ancient: the quiver, last in this guide" },
	} },
	{ title = "Before the demons", note = "The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring a Potion of Demon Slaying (Alchemy or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. Track Demons, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head.", goals = {
		{ t = "task", optional = true, text = "Learn Track Demons and get demon-slaying potions" },
	} },
	{ title = "Simone the Inconspicuous", note = "Simone the Inconspicuous, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use Track Demons. Talk to her and she becomes Simone the Seductress, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her Chain Lightning hits hard, so drain her mana with Viper Sting (a 15-second cooldown on Forever) and keep her busy; her Temptress' Kiss cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free.", goals = {
		{ t = "talk", npc = "Simone the Inconspicuous", map = 1449, x = 34.32, y = 40.79, era = true },
		{ t = "collect", quest = 7636, title = "Stave of the Ancients", map = 1449, x = 34.32, y = 40.79, era = true, count = 1, item = 18952, itemName = "Simone's Head", oi = 1, group = true },
	} },
	{ title = "Franklin the Friendly", note = "Franklin the Friendly, a human, wanders the western Burning Steppes south of Blackrock Mountain. Talk to him and he becomes Klinfran the Crazed, the easiest of the four. Keep Scorpid Sting on him the whole fight: while it lasts he barely hurts you. When he goes into Demonic Frenzy, remove it with Tranquilizing Shot and never stand in melee while it is up; between frenzies you can fight him in melee with Wing Clip and Raptor Strike. He cannot leave the Burning Steppes, so kite him around the trees if needed.", goals = {
		{ t = "talk", npc = "Franklin the Friendly", map = 1428, x = 24.82, y = 65.93, era = true },
		{ t = "collect", quest = 7636, title = "Stave of the Ancients", map = 1428, x = 24.82, y = 65.93, era = true, count = 1, item = 18953, itemName = "Klinfran's Head", oi = 2, group = true },
	} },
	{ title = "Nelson the Nice", note = "Nelson the Nice, a gnome, walks around the gates of Ahn'Qiraj in the far south-west of Silithus. Talk to him and he becomes Solenor the Slayer. He enrages with Soul Flame as he turns: drop a Frost Trap, Feign Death, and he resets without the enrage. Wing Clip roots him for a long time; while rooted he fears you and sends beetles (Creeping Doom): kill them fast with traps and Multi-Shot before they wear you down.", goals = {
		{ t = "talk", npc = "Nelson the Nice", map = 1451, x = 24.72, y = 76.02, era = true },
		{ t = "collect", quest = 7636, title = "Stave of the Ancients", map = 1451, x = 24.72, y = 76.02, era = true, count = 1, item = 18954, itemName = "Solenor's Head", oi = 3, group = true },
	} },
	{ title = "Artorius the Amiable", note = "Artorius the Amiable, a tauren, walks a loop in the rocks of northern Winterspring, north of Everlook. Talk to him and he becomes Artorius the Doombringer. Within 30 yards of him Demonic Doom hits hard: keep your distance and kite him the whole fight, Aspect of the Cheetah on, south down the road. Serpent Sting on him adds Stinging Trauma, extra Nature damage, so keep it ticking while you run; his Demonic Frenzy can be removed with Tranquilizing Shot, but distance matters more. It is a long fight: bring mana potions and plan your kiting path.", goals = {
		{ t = "talk", npc = "Artorius the Amiable", map = 1452, x = 60.31, y = 13.18, era = true },
		{ t = "collect", quest = 7636, title = "Stave of the Ancients", map = 1452, x = 60.31, y = 13.18, era = true, count = 1, item = 18955, itemName = "Artorius's Head", oi = 4, group = true },
	} },
	{ title = "Onyxia", note = "Onyxia is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh; she returns once a week. She drops one Mature Black Dragon Sinew in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first.", goals = {
		{ t = "collect", quest = 7635, title = "A Proper String", map = 1445, x = 52.1, y = 75.8, era = true, count = 1, item = 18705, itemName = "Mature Black Dragon Sinew", oi = 1, group = true, note = "Mature Black Dragon Sinew, from Onyxia" },
	} },
	{ title = "Back to the Ancients", goals = {
		{ t = "turnin", quest = 7636, title = "Stave of the Ancients", npc = "Vartrus the Ancient", map = 1448, x = 47.78, y = 24.08, era = true },
		{ t = "turnin", quest = 7635, title = "A Proper String", npc = "Stoma the Ancient", map = 1448, x = 48.39, y = 22.29, era = true },
	} },
	{ title = "Rhok'delar and Lok'delar", note = "Not confirmed in Forever. In Classic, using the Ancient Rune Etched Stave with the Enchanted Black Dragon Sinew in your bags made Rhok'delar, and talking to Vartrus once more then gave Lok'delar, Stave of the Ancient Keepers, at no extra cost.", goals = {
		{ t = "use", map = 1448, x = 47.8, y = 24.1, era = true, item = 18707, itemName = "Ancient Rune Etched Stave", note = "Ancient Rune Etched Stave, by Vartrus" },
		{ t = "talk", npc = "Vartrus the Ancient", map = 1448, x = 47.78, y = 24.08, era = true, optional = true, note = "Vartrus the Ancient: Lok'delar in Classic" },
	} },
	{ title = "Azuregos", note = "Hastat's quiver needs the Mature Blue Dragon Sinew. Azuregos, a world boss for a raid, stands in southern Azshara, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around Mazthoril, the cave south of Everlook in Winterspring, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver.", goals = {
		{ t = "collect", quest = 7634, title = "Ancient Sinew Wrapped Lamina", map = 1447, x = 53.3, y = 80.4, era = true, count = 1, item = 18704, itemName = "Mature Blue Dragon Sinew", oi = 1, group = true, note = "Mature Blue Dragon Sinew, from Azuregos" },
	} },
	{ title = "Hastat the Ancient", goals = {
		{ t = "turnin", quest = 7634, title = "Ancient Sinew Wrapped Lamina", npc = "Hastat the Ancient", map = 1448, x = 46.7, y = 24.06, era = true },
	} },
} end)

Waypost.RegisterSteps("class/hunter/the-hunters-charm", function() return {
	{ title = "The Hunter's Charm (Alliance)", note = "At 50 any Alliance hunter trainer offers it: Ulfir Ironbeard in Stormwind's Dwarven District, Olmin Burningbeard in Ironforge's Hall of Arms or Dorion in Darnassus' Cenarion Enclave.", only = { factions = {"Alliance"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8151, title = "The Hunter's Charm", npc = "Ulfir Ironbeard", map = 1453, x = 67.59, y = 35.78, qlvl = 52 },
	} },
	{ title = "The Hunter's Charm (Horde)", note = "At 50 any Horde hunter trainer offers it: Ormak Grimshot in Orgrimmar's Valley of Honor or Holt Thunderhorn on Hunter Rise in Thunder Bluff.", only = { factions = {"Horde"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8151, title = "The Hunter's Charm", npc = "Ormak Grimshot", map = 1454, x = 66.05, y = 18.53, era = true, qlvl = 52 },
	} },
	{ title = "Ogtinc", note = "Ogtinc lives on a raised spot on the cliffs at the north-east rim of the Ruins of Eldarath, west-central Azshara. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to Talrendis Point; Horde: fly to Valormok, a short ride west of him.", goals = {
		{ t = "getfp", npc = "Jarrodenus", map = 1447, x = 11.9, y = 77.59, era = true, location = "Talrendis Point", only = { factions = {"Alliance"} } },
		{ t = "getfp", npc = "Kroum", map = 1447, x = 21.96, y = 49.62, era = true, location = "Valormok", only = { factions = {"Horde"} } },
		{ t = "turnin", quest = 8151, title = "The Hunter's Charm", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
		{ t = "accept", quest = 8153, title = "Courser Antlers", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true, qlvl = 52 },
	} },
	{ title = "Courser Antlers", note = "You need two Perfect Courser Antlers. Mosshoof Coursers (level 52-53, deer) graze all over Azshara and drop one about one kill in twelve, so expect two dozen kills. Good herds: north of the Thalassian Base Camp in the north, and the hills north-east and south-east of Valormok; the Lake Mennar area also has elite giants and dragonkin. They Enrage at 30% health. Coursers share spawn points with the Thunderhead hippogryphs: if none are around, kill the hippogryphs and coursers may spawn instead. Respawn is about five and a half minutes.", goals = {
		{ t = "collect", quest = 8153, title = "Courser Antlers", map = 1447, x = 52.1, y = 35.39, era = true, count = 2, item = 20017, itemName = "Perfect Courser Antler", oi = 1, mobLevel = 53, note = "Perfect Courser Antler, from Mosshoof Coursers", spots = "52.1,35.4;52.4,25.2;53,14.7;46.2,18.6;62.5,16.1" },
	} },
	{ title = "Ogtinc", goals = {
		{ t = "turnin", quest = 8153, title = "Courser Antlers", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
		{ t = "accept", quest = 8231, title = "Wavethrashing", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true, qlvl = 52 },
	} },
	{ title = "Wavethrashing", note = "You need six Wavethrasher Scales. Wavethrashers (three-headed sea beasts) live along Azshara's coasts, mostly underwater: the Young Wavethrashers (level 51-52) of the north-east shore drop a scale about one kill in three, the Wavethrashers (52-53) of the east coast by the Tower of Eldara about as often (a few walk the beach there), the Great Wavethrashers (53-54) of the south-east shore about one in seven. Track Beasts does not show them; fight them where you can breathe, and bring water breathing if you can. Elite sharks swim the deeper water.", goals = {
		{ t = "collect", quest = 8231, title = "Wavethrashing", map = 1447, x = 84.6, y = 30.9, era = true, count = 6, item = 20087, itemName = "Wavethrasher Scales", oi = 1, mobLevel = 53, spots = "84.6,30.9;87.6,27.4;89.8,31.9;90.9,37.3;89.6,22.4" },
	} },
	{ title = "Ogtinc", goals = {
		{ t = "turnin", quest = 8231, title = "Wavethrashing", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
		{ t = "accept", quest = 8232, title = "The Green Drake", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true, qlvl = 52 },
	} },
	{ title = "Morphaz in the Sunken Temple", note = "Morphaz is an elite green drake (level 52) inside the Sunken Temple, a five-player dungeon: needs a group of five. The temple stands in the Pool of Tears in eastern Swamp of Sorrows: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep or Darkshire and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to Jammal'an the Prophet in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses Acid Breath and Wing Flap. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls.", goals = {
		{ t = "collect", quest = 8232, title = "The Green Drake", map = 1435, x = 69, y = 54, era = true, count = 1, item = 20019, itemName = "Tooth of Morphaz", oi = 1, group = true, note = "Tooth of Morphaz, inside the Sunken Temple" },
	} },
	{ title = "The Green Drake", note = "In Classic Ogtinc let you choose the Devilsaur Eye, the Devilsaur Tooth or the Hunting Spear here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in.", goals = {
		{ t = "turnin", quest = 8232, title = "The Green Drake", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
	} },
} end)

Waypost.RegisterSteps("class/mage/arcane-refreshment", function() return {
	{ title = "Lorekeeper Lydros", note = "Fly to Feathermoon (Alliance) or Camp Mojache (Horde) and ride to Dire Maul in central Feralas. Lorekeeper Lydros waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a Crescent Key (it drops from the imp Pusillin in the East wing; a Powerful Seaforium Charge also opens them; Blink no longer gets past). Other mages in your group can take it too: share it.", goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7463, title = "Arcane Refreshment", npc = "Lorekeeper Lydros", map = 1444, x = 58, y = 44.5, era = true, qlvl = 60 },
	} },
	{ title = "Hydrospawn", note = "Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. Riptide hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets.", goals = {
		{ t = "collect", quest = 7463, title = "Arcane Refreshment", map = 1444, x = 58, y = 44.5, era = true, count = 1, item = 18299, itemName = "Hydrospawn Essence", oi = 1, group = true, note = "Hydrospawn Essence: Hydrospawn" },
	} },
	{ title = "Back to Lydros", goals = {
		{ t = "turnin", quest = 7463, title = "Arcane Refreshment", npc = "Lorekeeper Lydros", map = 1444, x = 58, y = 44.5, era = true, note = "Lorekeeper Lydros: Conjure Water, and 200 Shen'dralar reputation" },
	} },
} end)

Waypost.RegisterSteps("class/mage/atiesh", function() return {
	{ title = "Splinters of Atiesh", note = "Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the Plaguewood in Eastern Plaguelands: each of its twelve bosses before Sapphiron and Kel'Thuzad, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack.", goals = {
		{ t = "level", level = 60 },
		{ t = "collect", count = 40, item = 22726, itemName = "Splinter of Atiesh", group = true },
		{ t = "use", item = 22726, itemName = "Splinter of Atiesh", note = "Forming Frame of Atiesh: forty splinters become the Frame of Atiesh" },
	} },
	{ title = "Anachronos", note = "Right-click the Frame of Atiesh to start the quest, then take it to Anachronos, the bronze dragon in elf form who stands outside the Caverns of Time in eastern Tanaris. Fly to Gadgetzan and ride east.", goals = {
		{ t = "accept", quest = 9250, title = "Frame of Atiesh", item = 22727, itemName = "Frame of Atiesh", qlvl = 60 },
		{ t = "turnin", quest = 9250, title = "Frame of Atiesh", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true },
		{ t = "accept", quest = 9251, title = "Atiesh, the Befouled Greatstaff", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60 },
	} },
	{ title = "The Staff Head and the Base", note = "Two more raid bosses, a full 40-player raid each, both pieces always drop: the Staff Head of Atiesh from Kel'Thuzad on his throne at the top of Naxxramas, the Base of Atiesh from C'Thun at the bottom of the Temple of Ahn'Qiraj, behind the Gates of Ahn'Qiraj in southern Silithus. Each boss comes back once a week.", goals = {
		{ t = "collect", quest = 9251, title = "Atiesh, the Befouled Greatstaff", count = 1, item = 22733, itemName = "Staff Head of Atiesh", oi = 1, group = true, note = "Staff Head of Atiesh: Kel'Thuzad, Naxxramas" },
		{ t = "collect", quest = 9251, title = "Atiesh, the Befouled Greatstaff", map = 1451, x = 29.1, y = 93.6, era = true, count = 1, item = 22734, itemName = "Base of Atiesh", oi = 2, group = true, note = "Base of Atiesh: C'Thun, Temple of Ahn'Qiraj, past the Gate of Ahn'Qiraj" },
	} },
	{ title = "Back to Anachronos", goals = {
		{ t = "turnin", quest = 9251, title = "Atiesh, the Befouled Greatstaff", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true },
		{ t = "accept", quest = 9270, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60, only = { classes = {"MAGE"} }, note = "your class's Atiesh quest; he hands you the befouled staff" },
		{ t = "accept", quest = 9257, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60, only = { classes = {"PRIEST"} } },
		{ t = "accept", quest = 9271, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60, only = { classes = {"WARLOCK"} } },
		{ t = "accept", quest = 9269, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60, only = { classes = {"DRUID"} } },
	} },
	{ title = "Atiesh, Hand of Sargeras", note = "Take the befouled staff to Stratholme, the dungeon at the north end of Eastern Plaguelands, through the main gate. On Festival Lane find the patch of Consecrated Earth with a small white flame on it, stand on it and use the staff: Atiesh, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his Unholy Aura hurts everyone and cannot be dispelled (shadow resistance helps), his Breath of Sargeras curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup.", goals = {
		{ t = "use", map = 1423, x = 26.11, y = 11.13, era = true, item = 22737, itemName = "Atiesh, Greatstaff of the Guardian", note = "the befouled staff, on the Consecrated Earth inside Stratholme" },
		{ t = "kill", quest = 9270, title = "Atiesh, Greatstaff of the Guardian", map = 1423, x = 26.11, y = 11.13, era = true, count = 1, target = "Atiesh", oi = 1, group = true, only = { classes = {"MAGE"} }, note = "Atiesh, Hand of Sargeras" },
		{ t = "kill", quest = 9257, title = "Atiesh, Greatstaff of the Guardian", map = 1423, x = 26.11, y = 11.13, era = true, count = 1, target = "Atiesh", oi = 1, group = true, only = { classes = {"PRIEST"} } },
		{ t = "kill", quest = 9271, title = "Atiesh, Greatstaff of the Guardian", map = 1423, x = 26.11, y = 11.13, era = true, count = 1, target = "Atiesh", oi = 1, group = true, only = { classes = {"WARLOCK"} } },
		{ t = "kill", quest = 9269, title = "Atiesh, Greatstaff of the Guardian", map = 1423, x = 26.11, y = 11.13, era = true, count = 1, target = "Atiesh", oi = 1, group = true, only = { classes = {"DRUID"} } },
	} },
	{ title = "The Greatstaff", note = "Back to Anachronos at the Caverns of Time.", goals = {
		{ t = "turnin", quest = 9270, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, only = { classes = {"MAGE"} }, note = "Anachronos: Atiesh, Greatstaff of the Guardian" },
		{ t = "turnin", quest = 9257, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, only = { classes = {"PRIEST"} } },
		{ t = "turnin", quest = 9271, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, only = { classes = {"WARLOCK"} } },
		{ t = "turnin", quest = 9269, title = "Atiesh, Greatstaff of the Guardian", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, only = { classes = {"DRUID"} } },
	} },
} end)

Waypost.RegisterSteps("class/mage/celestial-orb", function() return {
	{ title = "Return to the Marsh (Stormwind)", note = "Jennea Cannon at the top of the Wizard's Sanctum, Stormwind's Mage Quarter, sends you back to Tabetha; Bink in Ironforge gives the same quest.", only = { factions = {"Alliance"} }, goals = {
