	} },
	{ title = "Return to the Marsh (Orgrimmar)", note = "Deino, one of Orgrimmar's mage trainers in Darkbriar Lodge, sends you back to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", only = { factions = {"Horde"} }, goals = {
		{ t = "level", level = 35 },
		{ t = "accept", quest = 1953, title = "Return to the Marsh", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true, qlvl = 40 },
	} },
	{ title = "Tabetha", note = "Tabetha's cottage is deep in the marsh west of Theramore, just north of the Stonemaul Ruins; come in from the west road, the elites roam its east side.", goals = {
		{ t = "turnin", quest = 1953, title = "Return to the Marsh", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 1954, title = "The Infernal Orb", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
	} },
	{ title = "The Infernal Orb", note = "The Burning Blade Summoners (level 38-39, not elite) work the Mannoroc Coven in southern Desolace, east of Shadowprey Village, and every one carries an Infernal Orb. They cast Shadow Bolt from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western Mulgore, south-west of Thunder Bluff.", goals = {
		{ t = "collect", quest = 1954, title = "The Infernal Orb", map = 1443, x = 66.49, y = 77.94, era = true, count = 1, item = 7291, itemName = "Infernal Orb", oi = 1, mobLevel = 39, note = "Infernal Orb: Burning Blade Summoner", spots = "54.9,71.7;50.3,72.3;49.6,77.2;52.7,80.2;80.5,77.1" },
	} },
	{ title = "The Exorcism", note = "Back at Tabetha's. Hand in the orb now; The Exorcism waits for level 38. Kill the critters around the cottage first: they join the fight. Accepting The Exorcism starts a 3 minute timer, and Tabetha calls the Demon of the Orb out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again.", goals = {
		{ t = "turnin", quest = 1954, title = "The Infernal Orb", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "level", level = 38 },
		{ t = "accept", quest = 1955, title = "The Exorcism", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
		{ t = "kill", quest = 1955, title = "The Exorcism", map = 1445, x = 45.79, y = 56.97, era = true, count = 1, target = "Demon of the Orb", oi = 1, group = true, note = "Demon of the Orb (elite, 40)" },
		{ t = "turnin", quest = 1955, title = "The Exorcism", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 1956, title = "Power in Uldaman", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
	} },
	{ title = "Power in Uldaman", note = "Uldaman is a dungeon in the northern Badlands: a group of five, from level 40 here. Go in by the rear entrance, a cave in Dustwind Gulch south-east of the main entrance (elite dragons fly nearby): the Obsidian Sentinel (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an Obsidian Shard, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back.", goals = {
		{ t = "level", level = 40 },
		{ t = "collect", quest = 1956, title = "Power in Uldaman", map = 1418, x = 49.1, y = 13.7, era = true, count = 1, item = 8053, itemName = "Obsidian Power Source", oi = 1, group = true, note = "Obsidian Power Source: Obsidian Sentinel" },
	} },
	{ title = "Mana Surges", note = "Back to Tabetha. Accepting Mana Surges opens a rift beside her cottage and starts a 10 minute timer: twelve Mana Surges (level 40, Shock and Lightning Bolt) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out.", goals = {
		{ t = "turnin", quest = 1956, title = "Power in Uldaman", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 1957, title = "Mana Surges", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
		{ t = "kill", quest = 1957, title = "Mana Surges", map = 1445, x = 45.83, y = 56.94, era = true, count = 12, target = "Mana Surge", oi = 1 },
		{ t = "turnin", quest = 1957, title = "Mana Surges", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 1958, title = "Celestial Power", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
		{ t = "turnin", quest = 1958, title = "Celestial Power", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, note = "Celestial Power: the Celestial Orb (off-hand) or the Celestial Stave" },
	} },
	{ title = "Tabetha's Task (optional)", note = "At 40 the mage trainers who send you to Tabetha (Jennea Cannon, Bink, Anastasia Hartwell, Deino) also have Tabetha's Task, a quest any class can do. Tabetha then wants the Tiara of the Deep from Hydromancer Velratha, a level 46 elite naga in Zul'Farrak, the troll dungeon in north-western Tanaris: a group of five, level 44-54. The reward window shows the Spellshifter Rod and the Gemshale Pauldrons.", goals = {
		{ t = "level", level = 40 },
		{ t = "accept", quest = 2861, title = "Tabetha's Task", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true, qlvl = 46, optional = true },
		{ t = "turnin", quest = 2861, title = "Tabetha's Task", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, optional = true },
		{ t = "accept", quest = 2846, title = "Tiara of the Deep", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 46, optional = true, group = true },
	} },
	{ title = "Tiara of the Deep in Zul'Farrak", note = "Zul'Farrak, the troll dungeon in north-western Tanaris, needs a group of five; the guide waits for level 44. Hydromancer Velratha is one of the bosses by the sacred pool, and the tiara always drops.", when = {{ k = "onquest", q = {2846} }}, goals = {
		{ t = "level", level = 44 },
		{ t = "collect", quest = 2846, title = "Tiara of the Deep", map = 1446, x = 38.7, y = 20, era = true, count = 1, item = 9234, itemName = "Tiara of the Deep", oi = 1, group = true, note = "Tiara of the Deep: Hydromancer Velratha, Zul'Farrak" },
		{ t = "turnin", quest = 2846, title = "Tiara of the Deep", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, group = true },
	} },
} end)

Waypost.RegisterSteps("class/mage/destroy-morphaz", function() return {
	{ title = "Magecraft (Stormwind)", note = "Maginor Dumas, the Master Mage, stands in the Wizard's Sanctum in Stormwind's Mage Quarter; Dink in Ironforge gives the same quest.", only = { factions = {"Alliance"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8250, title = "Magecraft", npc = "Maginor Dumas", map = 1453, x = 49.25, y = 87.77, qlvl = 52 },
	} },
	{ title = "Magecraft (Orgrimmar)", note = "Uthel'nay, one of Orgrimmar's mage trainers in Darkbriar Lodge, gives it; so do Pierce Shackleton in the Undercity and Archmage Shymm in Thunder Bluff.", only = { factions = {"Horde"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8250, title = "Magecraft", npc = "Uthel'nay", map = 1454, x = 39.16, y = 86.27, era = true, qlvl = 52 },
	} },
	{ title = "Sanath Lim-yo", note = "Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below his master's tower, a short way east of Valormok: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to Archmage Xylem at the top of the tower; an attendant at the top sends you back down, as often as you like.", goals = {
		{ t = "turnin", quest = 8250, title = "Magecraft", npc = "Sanath Lim-yo", map = 1447, x = 28.11, y = 50.09, era = true },
		{ t = "accept", quest = 8251, title = "Magic Dust", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52, note = "Archmage Xylem, in the tower" },
	} },
	{ title = "Glittering Dust", note = "The blood elves hold the Thalassian Base Camp on the hills of north-eastern Azshara. Blood Elf Surveyors (51-52, Fire Nova up close) and Reclaimers (52-53, Fireball, and they heal and Renew each other) each drop the dust about one time in four; they spot you from far off, so pull at the edges. They come back after 5 1/2 minutes.", goals = {
		{ t = "collect", quest = 8251, title = "Magic Dust", map = 1447, x = 55.46, y = 29.5, era = true, count = 10, item = 20028, itemName = "Glittering Dust", oi = 1, mobLevel = 53, spots = "56.1,29.9;55.9,27.3;57.3,26.1;58.5,30;58.6,28.1" },
	} },
	{ title = "Archmage Xylem", note = "Back to Sanath Lim-yo, who teleports you up to the tower.", goals = {
		{ t = "turnin", quest = 8251, title = "Magic Dust", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 8252, title = "The Siren's Coral", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52 },
	} },
	{ title = "Enchanted Coral", note = "The Spitelash Sirens (level 50-52) walk the ruins and beaches around the Ruins of Eldarath and the bay east of Valormok, often three together, and a few stand inside the Temple of Zin-Malor; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. Lingering Highborne ghosts wander the ruins: watch your back.", goals = {
		{ t = "collect", quest = 8252, title = "The Siren's Coral", map = 1447, x = 36.33, y = 48.02, era = true, count = 6, item = 20029, itemName = "Enchanted Coral", oi = 1, mobLevel = 52, note = "Enchanted Coral: Spitelash Siren", spots = "36.9,49;41,53.1;44.8,50.9;47.7,47.2;50.2,43.1" },
	} },
	{ title = "Archmage Xylem again", note = "Back to Sanath Lim-yo and up to the tower.", goals = {
		{ t = "turnin", quest = 8252, title = "The Siren's Coral", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 8253, title = "Destroy Morphaz", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52 },
	} },
	{ title = "Morphaz", note = "The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to Jammal'an the Prophet and Ogom the Wretched in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, Acid Breath and Wing Flap) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear.", goals = {
		{ t = "collect", quest = 8253, title = "Destroy Morphaz", map = 1435, x = 69.9, y = 53.6, era = true, count = 1, item = 20085, itemName = "Arcane Shard", oi = 1, group = true, note = "Arcane Shard: Morphaz" },
	} },
	{ title = "The Arcane Shard", note = "Back to Azshara, Sanath Lim-yo and the tower. Look at the reward window before you hand in: Classic offered the Arcane Crystal Pendant, the Fire Ruby or the Glacial Spike, and Forever's notes say the choice may be gone.", goals = {
		{ t = "turnin", quest = 8253, title = "Destroy Morphaz", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
	} },
} end)

Waypost.RegisterSteps("class/mage/mages-wand", function() return {
	{ title = "Journey to the Marsh (Stormwind)", note = "Jennea Cannon at the top of the Wizard's Sanctum, Stormwind's Mage Quarter, sends you to Tabetha; Bink in Ironforge gives the same quest.", only = { factions = {"Alliance"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1947, title = "Journey to the Marsh", npc = "Jennea Cannon", map = 1453, x = 49.56, y = 85.8, qlvl = 38 },
	} },
	{ title = "Journey to the Marsh (Orgrimmar)", note = "Deino, one of Orgrimmar's mage trainers in Darkbriar Lodge, sends you to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", only = { factions = {"Horde"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1947, title = "Journey to the Marsh", npc = "Deino", map = 1454, x = 38.45, y = 86.13, era = true, qlvl = 38 },
	} },
	{ title = "Tabetha", note = "Tabetha, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the Stonemaul Ruins. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the Barrens. Her cottage is no refuge: mobs follow you inside. Take both her quests.", goals = {
		{ t = "turnin", quest = 1947, title = "Journey to the Marsh", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 1949, title = "Hidden Secrets", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 38 },
		{ t = "accept", quest = 1948, title = "Items of Power", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
	} },
	{ title = "Magus Tirth", note = "Magus Tirth spends his days at the race track in the Shimmering Flats, south-east Thousand Needles.", goals = {
		{ t = "turnin", quest = 1949, title = "Hidden Secrets", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true },
		{ t = "accept", quest = 1950, title = "Get the Scoop", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true, qlvl = 30 },
	} },
	{ title = "\"Plucky\" Johnson", note = "Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes.", goals = {
		{ t = "complete", quest = 1950, title = "Get the Scoop", map = 1441, x = 79.6, y = 75.6, era = true, note = "\"Plucky\" Johnson", objs = {"\"Plucky\" Johnson"} },
		{ t = "turnin", quest = 1950, title = "Get the Scoop", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true },
		{ t = "accept", quest = 1951, title = "Rituals of Power", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true, qlvl = 40 },
	} },
	{ title = "Witherbark trolls and the Bolt Charged Bramble", note = "The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of Hammerfall; every kind of them drops a Witherbark Totem Stick about two times in five: you need ten. Then go to the Circle of Outer Binding (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the Bolt Charged Bramble forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more.", goals = {
		{ t = "collect", map = 1417, x = 42.87, y = 45.71, era = true, count = 10, item = 7273, itemName = "Witherbark Totem Stick", mobLevel = 35, spots = "37.5,41;35.6,49.4;30.8,43;61.1,72.4;64.4,72.8" },
		{ t = "use", quest = 1948, title = "Items of Power", map = 1417, x = 52.04, y = 50.74, era = true, item = 7273, itemName = "Witherbark Totem Stick", oi = 2, note = "at the middle stone of the Circle of Outer Binding" },
		{ t = "collect", quest = 1948, title = "Items of Power", map = 1417, x = 52.04, y = 50.74, era = true, count = 1, item = 7272, itemName = "Bolt Charged Bramble", oi = 2 },
	} },
	{ title = "Jade", note = "Tabetha also wants one Jade, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of Southshore drop one about every fifth kill. Do not sell it to a vendor by mistake.", goals = {
		{ t = "collect", quest = 1948, title = "Items of Power", map = 1417, x = 54.29, y = 50.44, era = true, count = 1, item = 1529, itemName = "Jade", oi = 1, spots = "54.9,49.6;72,52.5;66,26.9;86.2,32.1;69,81.8" },
	} },
	{ title = "Rituals of Power", note = "Tirth sold the book to the Scarlet Crusade. The Scarlet Monastery stands in north-eastern Tirisfal Glades; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in Arcanist Doan's round room: on the left-hand shelf as you face his room, next to the Compendium of the Fallen. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read.", goals = {
		{ t = "collect", quest = 1951, title = "Rituals of Power", map = 1420, x = 82.6, y = 33.8, era = true, count = 1, item = 7274, itemName = "Rituals of Power", oi = 1, note = "Rituals of Power: Scarlet Monastery Library" },
	} },
	{ title = "Tabetha's ritual", note = "Back to Tabetha. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire).", goals = {
		{ t = "turnin", quest = 1951, title = "Rituals of Power", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "turnin", quest = 1948, title = "Items of Power", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 1952, title = "Mage's Wand", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
		{ t = "turnin", quest = 1952, title = "Mage's Wand", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, note = "Mage's Wand" },
	} },
} end)

Waypost.RegisterSteps("class/mage/polymorph-pig", function() return {
	{ title = "Xylem's tower", note = "Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below Archmage Xylem's tower, a short way east of Valormok: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower.", goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 9362, title = "Warlord Krellian", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 60 },
	} },
	{ title = "Warlord Krellian", note = "Warlord Krellian (level 55, not elite, Strike and Demoralizing Roar) hides behind his Spitelash guards in the Temple of Zin-Malor, the biggest building in the middle of the Ruins of Eldarath. He always drops the Prismatic Shell and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine.", goals = {
		{ t = "collect", quest = 9362, title = "Warlord Krellian", map = 1447, x = 41.02, y = 53.05, era = true, count = 1, item = 23250, itemName = "Prismatic Shell", oi = 1, note = "Prismatic Shell: Warlord Krellian" },
	} },
	{ title = "Archmage Xylem", note = "Back to Sanath Lim-yo and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags.", goals = {
		{ t = "turnin", quest = 9362, title = "Warlord Krellian", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 9364, title = "Fragmented Magic", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 60 },
	} },
	{ title = "Polymorph Clones", note = "Back to the Ruins of Eldarath, full of Spitelash naga. Cast your sheep Polymorph (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with Frost Nova and Arcane Explosion. Fifty clones are needed, so it takes a while; not in a raid group.", goals = {
		{ t = "kill", quest = 9364, title = "Fragmented Magic", map = 1447, x = 29.94, y = 53.51, era = true, count = 50, target = "Polymorph Clone", oi = 1, mobLevel = 10, spots = "29.9,53.5;36.2,54.6" },
	} },
	{ title = "Fragmented Magic", note = "Back to Sanath Lim-yo and up to the tower.", goals = {
		{ t = "turnin", quest = 9364, title = "Fragmented Magic", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, note = "Archmage Xylem: Polymorph (pig)" },
	} },
} end)

Waypost.RegisterSteps("class/priest/benediction", function() return {
	{ title = "The Eye of Divinity", note = "The Eye of Divinity comes from the Cache of the Firelord, the chest that appears when Majordomo Executus yields in Molten Core, a 40-player raid (it is in the cache about half the time). Molten Core's portal is at the bottom of Blackrock Depths; once you have done Attunement to the Core (a Core Fragment from beside that portal), Lothos Riftwaker inside Blackrock Mountain ports you straight in. Nothing in this chain starts without the Eye: Eris is invisible until you equip it.", goals = {
		{ t = "talk", npc = "Lothos Riftwaker", map = 1428, x = 26.4, y = 24.5, era = true, optional = true, note = "Lothos Riftwaker: the way into Molten Core once attuned" },
		{ t = "collect", map = 1428, x = 26.4, y = 24.5, era = true, count = 1, item = 18646, itemName = "The Eye of Divinity", group = true, note = "The Eye of Divinity: Molten Core, through Blackrock Mountain" },
	} },
	{ title = "Eris Havenfire", note = "Equip The Eye of Divinity, then find Eris Havenfire, a ghost on the hillside in the north-west of the Eastern Plaguelands, west of Stratholme's gate (if she does not show, take the Eye off and put it back on). A Warning is only talk; The Balance of Light and Shadow starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or Nightfin Soup, and a stack of Oil of Immolation or Stratholme Holy Water for the skeletons.", goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7621, title = "A Warning", npc = "Eris Havenfire", map = 1423, x = 17.21, y = 12.79, qlvl = 60 },
		{ t = "turnin", quest = 7621, title = "A Warning", npc = "Eris Havenfire", map = 1423, x = 17.21, y = 12.79 },
		{ t = "accept", quest = 7622, title = "The Balance of Light and Shadow", npc = "Eris Havenfire", map = 1423, x = 17.21, y = 12.79, qlvl = 60 },
	} },
	{ title = "The Balance of Light and Shadow", note = "Save 50 peasants before 15 die (the Death Post by the path counts the dead). They walk from the cave towards Eris in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first (Abolish Disease), keep Renew on the hurt ones, Flash Heal the nearly dead, and kill skeletons as they spawn: one Holy Nova of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and Eris is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back.", goals = {
		{ t = "complete", quest = 7622, title = "The Balance of Light and Shadow", objs = {"The Balance of Light and Shadow"} },
	} },
	{ title = "Benediction", goals = {
		{ t = "turnin", quest = 7622, title = "The Balance of Light and Shadow", npc = "Eris Havenfire", map = 1423, x = 17.21, y = 12.79, note = "Eris Havenfire: Splinter of Nordrassil" },
	} },
	{ title = "The Eye of Shadow", note = "The splinter needs The Eye of Shadow as well. Lord Kazzak, a world boss in the Blasted Lands (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first.", goals = {
		{ t = "collect", map = 1419, x = 35.54, y = 74.98, era = true, count = 1, item = 18665, itemName = "The Eye of Shadow", group = true },
	} },
	{ title = "Benediction", note = "With the Splinter of Nordrassil, The Eye of Divinity and The Eye of Shadow in your bags, use the splinter wherever you are: it becomes Benediction. Use Benediction to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown).", goals = {
		{ t = "task", text = "Use the Splinter of Nordrassil with both Eyes in your bags: Benediction" },
	} },
} end)

Waypost.RegisterSteps("class/priest/blood-of-morphaz", function() return {
	{ title = "Cenarion Aid: High Priest Rohan", note = "At 50 in Ironforge, High Priest Rohan in the Hall of Mysteries (Mystic Ward) offers Cenarion Aid. Before you leave a city, buy an Ichor of Undeath at the Auction House (a few silver): the third quest asks for one and it drops rarely.", only = { factions = {"Alliance"} }, when = {{ k = "zone", name = "Ironforge", area = 1537 }, { k = "onquest", neg = true, q = {8254} }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8254, title = "Cenarion Aid", npc = "High Priest Rohan", map = 1455, x = 24.73, y = 8.16, era = true, qlvl = 52 },
	} },
	{ title = "Cenarion Aid: Brother Joshua", note = "At 50, Brother Joshua at the altar of Stormwind's Cathedral of Light offers Cenarion Aid (High Priest Rohan in Ironforge has it too). Before you leave, buy an Ichor of Undeath at the Auction House in the Trade District (a few silver): the third quest asks for one and it drops rarely.", only = { factions = {"Alliance"} }, when = {{ k = "onquest", neg = true, q = {8254} }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8254, title = "Cenarion Aid", npc = "Brother Joshua", map = 1453, x = 49.5, y = 45.21, qlvl = 52 },
	} },
	{ title = "Cenarion Aid: Ur'kyo", note = "At 50, Ur'kyo in Orgrimmar's Valley of Spirits offers Cenarion Aid. Before you leave, buy an Ichor of Undeath at the Auction House (a few silver): the third quest asks for one and it drops rarely.", only = { factions = {"Horde"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8254, title = "Cenarion Aid", npc = "Ur'kyo", map = 1454, x = 35.59, y = 87.82, era = true, qlvl = 52 },
	} },
	{ title = "Ogtinc", note = "Ogtinc, a furbolg, lives on the clifftop north-east of the Ruins of Eldarath. Alliance: fly to Talrendis Point; Horde: fly to Valormok. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up.", goals = {
		{ t = "getfp", npc = "Jarrodenus", map = 1447, x = 11.9, y = 77.59, era = true, location = "Talrendis Point", only = { factions = {"Alliance"} } },
		{ t = "getfp", npc = "Kroum", map = 1447, x = 21.96, y = 49.62, era = true, location = "Valormok", only = { factions = {"Horde"} } },
		{ t = "turnin", quest = 8254, title = "Cenarion Aid", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
		{ t = "accept", quest = 8255, title = "Of Coursers We Know", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true, qlvl = 52 },
	} },
	{ title = "Of Coursers We Know", note = "Mosshoof Coursers (level 52-53, not elite) graze all over Azshara, thickest north-east of Ogtinc and south of the mountains; about one in three drops a Healthy Courser Gland, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any Ichor of Undeath you loot.", goals = {
		{ t = "collect", quest = 8255, title = "Of Coursers We Know", map = 1447, x = 52.1, y = 35.39, era = true, count = 4, item = 20027, itemName = "Healthy Courser Gland", oi = 1, mobLevel = 53, spots = "52.1,35.4;52.4,25.2;53,14.7;46.2,18.6;62.5,16.1" },
	} },
	{ title = "Ogtinc", goals = {
		{ t = "turnin", quest = 8255, title = "Of Coursers We Know", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
		{ t = "accept", quest = 8256, title = "The Ichor of Undeath", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true, qlvl = 52 },
	} },
	{ title = "The Ichor of Undeath", note = "Carrying an Ichor of Undeath already? It counts at once. Otherwise any undead may drop one, rarely: the Lingering Highborne (level 48) in the Ruins of Eldarath below Ogtinc's cliff drop it about one kill in ten, the highborne ghosts on Azshara's border with Ashenvale (level 45-46) a little less, the Anguished and Suffering Highborne in Winterspring (54-55) about one in eight. The Auction House is usually quicker.", goals = {
		{ t = "collect", quest = 8256, title = "The Ichor of Undeath", map = 1447, x = 40.28, y = 46.13, era = true, count = 1, item = 7972, itemName = "Ichor of Undeath", oi = 1, mobLevel = 50, spots = "40.3,46.1;39.4,50.3;39.1,55.3;38.8,60.6;35.2,51.8" },
	} },
	{ title = "Ogtinc", goals = {
		{ t = "turnin", quest = 8256, title = "The Ichor of Undeath", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true },
		{ t = "accept", quest = 8257, title = "Blood of Morphaz", npc = "Ogtinc", map = 1447, x = 42.4, y = 42.62, era = true, qlvl = 52 },
	} },
	{ title = "Morphaz in the Sunken Temple", note = "Morphaz is a level 52 elite green dragon inside the Sunken Temple, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to Stonard; Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north. The temple stands in the middle of the Pool of Tears: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then Jammal'an the Prophet below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops.", goals = {
		{ t = "collect", quest = 8257, title = "Blood of Morphaz", map = 1435, x = 69, y = 54, era = true, count = 1, item = 20025, itemName = "Blood of Morphaz", oi = 1, group = true, note = "Blood of Morphaz: the Sunken Temple entrance" },
	} },
	{ title = "Greta Mosshoof", note = "Greta Mosshoof is at the Emerald Sanctuary in southern Felwood. Horde: fly to Bloodvenom Post and ride south-east; Alliance: fly to Astranaar in Ashenvale and ride north into Felwood. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick Blessed Prayer Beads, Circle of Hope or Woestave, and Forever's notes say that choice may be gone.", goals = {
		{ t = "turnin", quest = 8257, title = "Blood of Morphaz", npc = "Greta Mosshoof", map = 1448, x = 51.21, y = 82.11, era = true },
	} },
} end)

Waypost.RegisterSteps("class/rogue/ravenholdt", function() return {
	{ title = "The Elegant Letter", note = "At 24 any capital's rogue trainer (Master Mathias Shaw or Osborne the Night Man in Stormwind, Gest or Ormok in Orgrimmar, and the others) has an Elegant Letter from Ravenholdt for you: ask for it in their talk window. Open it: the quest gives you the Seal of Ravenholdt for Fahrad. Learn Detect Traps from your trainer first if you have not; the way in is a test of it.", goals = {
		{ t = "level", level = 24 },
		{ t = "accept", quest = 6681, title = "The Manor, Ravenholdt", item = 17126, itemName = "Elegant Letter", qlvl = 24 },
	} },
	{ title = "Ravenholdt Manor", note = "Horde fly to Tarren Mill, Alliance to Southshore. The trail to the manor is hard to see: it starts behind the plateau north of Durnholde Keep, east of Tarren Mill, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast Detect Traps near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies Ravenholdt Manor: Fahrad is upstairs inside. Do not attack anyone at the manor: it costs Ravenholdt reputation.", goals = {
		{ t = "kill", quest = 6681, title = "The Manor, Ravenholdt", map = 1424, x = 78.64, y = 17.84, era = true, count = 1, target = "Ravenholdt", oi = 1, note = "Rite of Cunning: Detect Traps beside the tunnel chest" },
		{ t = "turnin", quest = 6681, title = "The Manor, Ravenholdt", npc = "Fahrad", map = 1416, x = 84.45, y = 80.32, era = true },
		{ t = "accept", quest = 96779, title = "Syndicate Sabotage", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 24 },
	} },
	{ title = "Lord Tomas", note = "Lord Tomas is inside Durnholde Keep, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says Myrokos. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry Syndicate Emblems for the guards' repeatable reputation quest.", goals = {
		{ t = "kill", quest = 96779, title = "Syndicate Sabotage", map = 1424, x = 79.35, y = 46.02, era = true, count = 1, target = "Lord Tomas", oi = 1, mobLevel = 24 },
		{ t = "collect", map = 1424, x = 79.28, y = 46.37, era = true, item = 17124, itemName = "Syndicate Emblem", mobLevel = 22, optional = true, text = "Pick Pocket Syndicate members for Syndicate Emblems", spots = "78.2,45.4;81.1,45.5;82.3,41;79.2,40.9;75.7,41.1" },
	} },
	{ title = "Myrokos Silentform", goals = {
		{ t = "turnin", quest = 96779, title = "Syndicate Sabotage", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true },
		{ t = "turnin", quest = 6701, title = "Syndicate Emblems", npc = "Ravenholdt Guard", map = 1416, x = 85.27, y = 79.56, era = true, qlvl = 60, optional = true, note = "Ravenholdt Guard: one emblem each time, 100 reputation" },
	} },
	{ title = "What's the Big Idea?", note = "In your mid 30s Myrokos has two more jobs; take both. Barton leads a Syndicate scouting party at Strahnbrad, in the east of the Alterac Mountains, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. Pick Pocket can miss several times in a row.", goals = {
		{ t = "level", level = 34 },
		{ t = "accept", quest = 96781, title = "What's the Big Idea?", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 36 },
		{ t = "accept", quest = 96783, title = "A Way In", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 36 },
		{ t = "collect", quest = 96781, title = "What's the Big Idea?", map = 1416, x = 62.6, y = 46.9, era = true, count = 1, item = 275482, itemName = "Barton's Scouting Report", oi = 1, text = "Pick Pocket Barton for Barton's Scouting Report" },
	} },
	{ title = "Covert Extraction", note = "Back to Myrokos; the report sends you after the Perenolde heirlooms. Two towers stand among the Ruins of Alterac, in the middle of the Alterac Mountains, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside.", goals = {
		{ t = "turnin", quest = 96781, title = "What's the Big Idea?", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true },
		{ t = "accept", quest = 96782, title = "Covert Extraction", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 36 },
		{ t = "collect", quest = 96782, title = "Covert Extraction", map = 1416, x = 41.35, y = 40.16, era = true, count = 1, item = 275636, itemName = "Royal Aegis of Perenolde", oi = 2, note = "Royal Aegis of Perenolde, in the northern tower" },
		{ t = "collect", quest = 96782, title = "Covert Extraction", map = 1416, x = 38.5, y = 58, era = true, count = 1, item = 275635, itemName = "Blade of House Perenolde", oi = 1, note = "Blade of House Perenolde, in the southern tower" },
		{ t = "turnin", quest = 96782, title = "Covert Extraction", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true },
	} },
	{ title = "A Way In", note = "Stromgarde Keep in western Arathi is a Syndicate stronghold; to get in you need a uniform. Northfold Manor, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the Syndicate Footlocker there and take the uniform; that ends A Way In.", goals = {
		{ t = "turnin", quest = 96783, title = "A Way In", npc = "Syndicate Footlocker", map = 1417, x = 32.3, y = 26.6, era = true, note = "Syndicate Footlocker, Northfold Manor" },
		{ t = "accept", quest = 96784, title = "Master of Disguise", npc = "Syndicate Footlocker", map = 1417, x = 32.3, y = 26.6, era = true, qlvl = 36, only = { factions = {"Horde"} }, note = "Master of Disguise: the Syndicate Uniform" },
	} },
	{ title = "Anastasia Miller", note = "Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the Syndicate Uniform (Master of Disguise hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with Ain't No Telling. Anastasia Miller is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge.", goals = {
		{ t = "turnin", quest = 96784, title = "Master of Disguise", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true, only = { factions = {"Horde"} } },
		{ t = "accept", quest = 96785, title = "Ain't No Telling", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true, qlvl = 36, note = "Ain't No Telling" },
	} },
	{ title = "Ain't No Telling", note = "She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the Stolen Funds. If it is already open, wait for it to come back.", goals = {
		{ t = "collect", quest = 96785, title = "Ain't No Telling", map = 1417, x = 29.5, y = 65.1, era = true, count = 1, item = 275709, itemName = "Stolen Funds", oi = 1, note = "Stolen Funds: Anastasia's Stash" },
		{ t = "turnin", quest = 96785, title = "Ain't No Telling", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true },
		{ t = "accept", quest = 96786, title = "The Syndicate Sting", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true, qlvl = 36, note = "The Syndicate Sting" },
	} },
	{ title = "The Syndicate Sting", note = "Falconcrest's men make the handoff at the southern end of Thoradin's Wall, the old wall between Arathi and Hillsbrad. Kill the two guarding the box and take the Intercepted Shipment. Keep the Syndicate Uniform: Myrokos wants it back with the shipment.", goals = {
		{ t = "collect", quest = 96786, title = "The Syndicate Sting", map = 1417, x = 15.5, y = 43, era = true, count = 1, item = 275882, itemName = "Intercepted Shipment", oi = 1 },
	} },
	{ title = "Back to Myrokos", goals = {
		{ t = "turnin", quest = 96786, title = "The Syndicate Sting", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, note = "Myrokos Silentform: 70 silver, 300 Ravenholdt reputation" },
	} },
} end)

Waypost.RegisterSteps("class/rogue/the-azure-key", function() return {
	{ title = "A Simple Request (Alliance)", note = "At 50 Osborne the Night Man in Stormwind's Old Town has it; so do Syurna in Darnassus and Hulfdan Blackbeard in Ironforge.", only = { factions = {"Alliance"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8233, title = "A Simple Request", npc = "Osborne the Night Man", map = 1453, x = 77.43, y = 65.31, qlvl = 52 },
	} },
	{ title = "A Simple Request (Horde)", note = "At 50 Ormok in the Cleft of Shadow has it; so does Miles Dexter in the Undercity's Rogues' Quarter.", only = { factions = {"Horde"} }, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8233, title = "A Simple Request", npc = "Ormok", map = 1454, x = 43.9, y = 54.63, era = true, qlvl = 52 },
	} },
	{ title = "Lord Jorach Ravenholdt", note = "Ravenholdt Manor hides in the hills east of Tarren Mill. Horde fly to Tarren Mill, Alliance to Southshore. The trail starts behind the plateau north of Durnholde Keep, climbs into the hills and runs through a small tunnel into the Alterac Mountains; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you.", goals = {
		{ t = "turnin", quest = 8233, title = "A Simple Request", npc = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, era = true },
		{ t = "accept", quest = 8234, title = "Sealed Azure Bag", npc = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, era = true, qlvl = 52 },
	} },
	{ title = "Sealed Azure Bag", note = "Alliance fly to Talrendis Point, Horde to Valormok. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern Azshara carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. Pick Pocket them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with Timbermaw Hold, mark them At War in your reputation panel first. They cast Lightning Bolt and Lightning Cloud, heal each other and run at low health.", goals = {
		{ t = "getfp", npc = "Jarrodenus", map = 1447, x = 11.9, y = 77.59, era = true, location = "Talrendis Point", only = { factions = {"Alliance"} } },
		{ t = "getfp", npc = "Kroum", map = 1447, x = 21.96, y = 49.62, era = true, location = "Valormok", only = { factions = {"Horde"} } },
		{ t = "collect", quest = 8234, title = "Sealed Azure Bag", map = 1447, x = 44.2, y = 26.6, era = true, count = 1, item = 19775, itemName = "Sealed Azure Bag", oi = 1, mobLevel = 51, note = "Sealed Azure Bag: Timbermaw Shaman", spots = "44.2,26.6;45.5,25.4;45.8,22.3;44.6,21.4;42.8,18.5" },
	} },
	{ title = "Archmage Xylem", note = "Sanath Lim-yo, camped below the cliffs just east of Valormok, teleports you up (dismount first); a trail leads to Xylem's tower.", goals = {
		{ t = "turnin", quest = 8234, title = "Sealed Azure Bag", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 8235, title = "Encoded Fragments", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52 },
	} },
	{ title = "Encoded Fragments", note = "The Forest Oozes (level 52-53, Diseased Slime up close) drop a fragment four times in five: the biggest group, seven of them, is in the Bitter Reaches hills of north-eastern Azshara, four more south-east of Valormok. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear.", goals = {
		{ t = "collect", quest = 8235, title = "Encoded Fragments", map = 1447, x = 36.16, y = 67.86, era = true, count = 10, item = 20023, itemName = "Encoded Fragment", oi = 1, mobLevel = 53, note = "Encoded Fragment: Forest Ooze", spots = "37.5,69.6;43.1,70.5;69.5,27.9;75.7,27.5;80.4,24.5" },
	} },
	{ title = "Back to Xylem", goals = {
		{ t = "turnin", quest = 8235, title = "Encoded Fragments", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 8236, title = "The Azure Key", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52 },
	} },
	{ title = "Morphaz in the Sunken Temple", note = "Morphaz, a level 52 elite green drake, lives deep in the Sunken Temple: a group of five, level 50-54. The temple stands in the Pool of Tears; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to Jammal'an the Prophet in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their Acid Breath is nature damage: nature protection potions help; poisons and Blind do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all.", goals = {
		{ t = "collect", quest = 8236, title = "The Azure Key", map = 1435, x = 69.9, y = 53.6, era = true, count = 1, item = 20022, itemName = "Azure Key", oi = 1, group = true, note = "Azure Key: Morphaz, inside the temple" },
	} },
	{ title = "Lord Ravenholdt", note = "Look at the reward window before you hand in: Classic offered the Duskbat Drape, the Ebon Mask or the Whisperwalk Boots, and Forever's notes say the choice may be gone.", goals = {
		{ t = "turnin", quest = 8236, title = "The Azure Key", npc = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, era = true },
	} },
} end)

Waypost.RegisterSteps("class/rogue/the-eye-of-bhossca", function() return {
	{ title = "C's dead drop", note = "C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the Dead Drop near Pyrewood Village, in southern Silverpine just south of Shadowfang Keep, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30.", goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 78676, title = "The Eye of Bhossca", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true, qlvl = 35 },
	} },
	{ title = "The Scarlet Monastery", note = "The monastery stands in the far north-east of Tirisfal Glades. Go in alone, out of any group. Before entering, take the Scarlet Initiate's Uniform from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), Pick Pocket a Scarlet Scryer or Scarlet Crier for the Scryer's Key. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the Reliquary Key from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance.", goals = {
		{ t = "goto", map = 1420, x = 82.6, y = 33.8, text = "Scarlet Monastery" },
		{ t = "note", text = "Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings." },
	} },
	{ title = "Back to the dead drop", note = "Place the eye in the Dead Drop near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared.", goals = {
		{ t = "turnin", quest = 78676, title = "The Eye of Bhossca", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true },
		{ t = "accept", quest = 78699, title = "The Eye of Bhossca", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true, qlvl = 35 },
		{ t = "turnin", quest = 78699, title = "The Eye of Bhossca", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true, note = "Ruby-Adorned Blade" },
	} },
} end)

Waypost.RegisterSteps("class/rogue/the-horn-of-xelthos", function() return {
	{ title = "C's dead drop", note = "The Dead Drop is a chest in a house just outside Pyrewood Village in southern Silverpine, south of Shadowfang Keep. Open it and read C's note: the job has to be done alone, out of any group.", goals = {
		{ t = "level", level = 23 },
		{ t = "accept", quest = 78261, title = "The Horn of Xelthos", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true, qlvl = 23 },
	} },
	{ title = "Veenix", note = "Veenix, a goblin friendly to both factions, stands among the Venture Co. in the Windshear Crag, east Stonetalon, a short way north-east of Sun Rock Retreat. Horde fly to Sun Rock Retreat; Alliance to Stonetalon Peak. He wants a Venture Co. Work Order before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and Pick Pocket it; killing them does not give it.", goals = {
		{ t = "talk", npc = "Veenix", map = 1442, x = 58.22, y = 51.74, era = true },
		{ t = "accept", quest = 78270, title = "Goblin Lockpicks", npc = "Veenix", map = 1442, x = 58.22, y = 51.74, era = true, qlvl = 23 },
		{ t = "collect", map = 1442, x = 59.44, y = 52.26, era = true, count = 1, item = 210187, itemName = "Venture Co. Work Order", mobLevel = 19, text = "Pick Pocket a Venture Co. Logger for a Venture Co. Work Order", spots = "60.3,53.6;63.1,55.1;64.8,57.1;68,57.2;71.2,55.9" },
		{ t = "turnin", quest = 78270, title = "Goblin Lockpicks", npc = "Veenix", map = 1442, x = 58.22, y = 51.74, era = true },
	} },
	{ title = "Shadowfang Keep", note = "Go in alone and use the Breaching Charge at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring Flash Powder and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the Sister's Half-Key, then the brother in the room reached by turning right at the top of the stairs for the Brother's Half-Key (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach.", goals = {
		{ t = "collect", quest = 78261, title = "The Horn of Xelthos", map = 1421, x = 44.8, y = 67.8, count = 1, item = 210183, itemName = "Horn of Xelthos", oi = 1, note = "Horn of Xelthos, inside Shadowfang Keep" },
	} },
	{ title = "Back to the dead drop", note = "Place the horn in the Dead Drop near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered.", goals = {
		{ t = "turnin", quest = 78261, title = "The Horn of Xelthos", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true },
		{ t = "accept", quest = 78307, title = "The Horn of Xelthos", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true, qlvl = 23 },
		{ t = "turnin", quest = 78307, title = "The Horn of Xelthos", npc = "Dead Drop", map = 1421, x = 47.12, y = 70.99, era = true, note = "Pyrewood Signet Ring" },
	} },
} end)

