		{ t = "accept", quest = 4967, title = "Knowledge of the Orb of Orahil", npc = "Zevrost", map = 1454, x = 48.47, y = 45.43, era = true, qlvl = 35 },
	} },
	{ title = "Knowledge of the Orb of Orahil (Undercity)", note = "At 35 Kaal Soulreaper in the Magic Quarter sends you to Menara Voidrender in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar.", only = { races = {"Scourge"} }, goals = {
		{ t = "level", level = 35 },
		{ t = "accept", quest = 4969, title = "Knowledge of the Orb of Orahil", npc = "Kaal Soulreaper", map = 1458, x = 86.21, y = 15.93, era = true, qlvl = 35 },
	} },
	{ title = "Menara Voidrender", note = "Menara Voidrender and her two acolytes stand in Strahad Farsan's tower on the hill above Ratchet.", goals = {
		{ t = "turnin", quest = 4968, title = "Knowledge of the Orb of Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, only = { races = {"Human"} } },
		{ t = "turnin", quest = 4965, title = "Knowledge of the Orb of Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, only = { races = {"Gnome"} } },
		{ t = "turnin", quest = 4967, title = "Knowledge of the Orb of Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, only = { races = {"Orc", "Troll"} } },
		{ t = "turnin", quest = 4969, title = "Knowledge of the Orb of Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, only = { races = {"Scourge"} } },
		{ t = "accept", quest = 1799, title = "Fragments of the Orb of Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, qlvl = 40 },
	} },
	{ title = "Choose an acolyte", note = "Pick one acolyte: you can take only one of their quests. Acolyte Wytula's felhound path ends with the Orb or Staff of Dar'Orahil, the shadow versions; Acolyte Magaz's infernal path with the Orb or Staff of Noh'Orahil, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back.", goals = {
		{ t = "accept", quest = 4962, title = "Shard of a Felhound", npc = "Acolyte Wytula", map = 1413, x = 62.64, y = 35.3, era = true, qlvl = 40, note = "Acolyte Wytula: she gives you the Felhas Ruby" },
		{ t = "accept", quest = 4963, title = "Shard of an Infernal", npc = "Acolyte Magaz", map = 1413, x = 62.56, y = 35.23, era = true, qlvl = 40, note = "Acolyte Magaz: he gives you the Infus Emerald" },
	} },
	{ title = "Mannoroc Coven", note = "Mannoroc Coven fills south-central Desolace, east of Shadowprey Village. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the Infernal Orb every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with Drain Soul: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant).", goals = {
		{ t = "collect", quest = 1799, title = "Fragments of the Orb of Orahil", map = 1443, x = 66.49, y = 77.94, era = true, count = 1, item = 7291, itemName = "Infernal Orb", oi = 1, mobLevel = 39, note = "Infernal Orb, from the Burning Blade Summoners", spots = "54.9,71.7;50.3,72.3;49.6,77.2;52.7,80.2;80.5,77.1" },
		{ t = "collect", quest = 4962, title = "Shard of a Felhound", map = 1443, x = 52.91, y = 68.14, era = true, count = 1, item = 12648, itemName = "Imprisoned Felhound Spirit", oi = 1, mobLevel = 38, note = "Imprisoned Felhound Spirit, from a Mana Eater, Mage Hunter or Ley Hunter" },
		{ t = "collect", quest = 4963, title = "Shard of an Infernal", map = 1443, x = 54.31, y = 71.14, era = true, count = 1, item = 12649, itemName = "Imprisoned Infernal Spirit", oi = 1, mobLevel = 37, note = "Imprisoned Infernal Spirit, from a Lesser Infernal", spots = "53.1,71.8;50,76.1;54.3,80.1;53.7,84;56.8,71.1" },
	} },
	{ title = "The demon's spirit", note = "Back to Menara in the tower above Ratchet with the spirit and the gem first: her orb follows from it.", goals = {
		{ t = "turnin", quest = 4962, title = "Shard of a Felhound", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true },
		{ t = "turnin", quest = 4963, title = "Shard of an Infernal", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true },
	} },
	{ title = "Tabetha", note = "Tabetha lives at her farm in the middle of Dustwallow Marsh, south of the road from the Barrens and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 38. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the Demon of the Orb out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or Banish and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from Tabetha again.", goals = {
		{ t = "turnin", quest = 1799, title = "Fragments of the Orb of Orahil", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "level", level = 38 },
		{ t = "accept", quest = 4961, title = "Cleansing of the Orb of Orahil", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
		{ t = "kill", quest = 4961, title = "Cleansing of the Orb of Orahil", map = 1445, x = 45.79, y = 56.97, era = true, count = 1, target = "Demon of the Orb", oi = 1, group = true },
		{ t = "turnin", quest = 4961, title = "Cleansing of the Orb of Orahil", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true },
		{ t = "accept", quest = 4976, title = "Returning the Cleansed Orb", npc = "Tabetha", map = 1445, x = 46.06, y = 57.09, era = true, qlvl = 40 },
	} },
	{ title = "The Orb of Dar'Orahil", note = "Back to Menara in the tower above Ratchet with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the Orb of Dar'Orahil (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff.", goals = {
		{ t = "turnin", quest = 4976, title = "Returning the Cleansed Orb", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true },
		{ t = "accept", quest = 4964, title = "The Completed Orb of Dar'Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, qlvl = 40 },
		{ t = "complete", quest = 4964, title = "The Completed Orb of Dar'Orahil", map = 1413, x = 62.5, y = 35.4, era = true, note = "Wait beside Menara while she makes the orb", objs = {"Menara Voidrender"} },
		{ t = "turnin", quest = 4964, title = "The Completed Orb of Dar'Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true },
	} },
	{ title = "The Orb of Noh'Orahil", note = "On the infernal path, accept her last quest and wait beside Menara while she completes the Orb of Noh'Orahil, then speak to her again and pick the off-hand orb or the staff.", goals = {
		{ t = "accept", quest = 4975, title = "The Completed Orb of Noh'Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true, qlvl = 40 },
		{ t = "complete", quest = 4975, title = "The Completed Orb of Noh'Orahil", map = 1413, x = 62.5, y = 35.4, era = true, note = "Wait beside Menara while she makes the orb", objs = {"Menara Voidrender"} },
		{ t = "turnin", quest = 4975, title = "The Completed Orb of Noh'Orahil", npc = "Menara Voidrender", map = 1413, x = 62.51, y = 35.45, era = true },
	} },
} end)

Waypost.RegisterSteps("class/warlock/orb-of-soranruk", function() return {
	{ title = "Doan Karhan", note = "Doan Karhan camps beside Takar the Seer, at a tent just north-east of Camp Taurajo in the southern Barrens. Alliance warlocks reach him from Ratchet or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your Blackfathom Deeps and Shadowfang Keep runs.", goals = {
		{ t = "level", level = 20 },
		{ t = "accept", quest = 1740, title = "The Orb of Soran'ruk", npc = "Doan Karhan", map = 1413, x = 49.31, y = 57.21, era = true, qlvl = 25 },
	} },
	{ title = "Blackfathom Deeps", note = "Blackfathom Deeps (level 24-32, a group of five) opens in the ruins on the north-west coast of Ashenvale, under the water at Zoram Strand. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around Twilight Lord Kelris and the altar before Aku'mai; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest.", goals = {
		{ t = "collect", quest = 1740, title = "The Orb of Soran'ruk", map = 1440, x = 14.5, y = 14.2, count = 3, item = 6914, itemName = "Soran'ruk Fragment", oi = 1, group = true, note = "Soran'ruk Fragments, from the Twilight Acolytes inside" },
	} },
	{ title = "Shadowfang Keep", note = "Shadowfang Keep (level 22-30, a group of five) stands on the hill south of the Sepulcher. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop.", goals = {
		{ t = "collect", quest = 1740, title = "The Orb of Soran'ruk", map = 1421, x = 44.8, y = 67.8, count = 1, item = 6915, itemName = "Large Soran'ruk Fragment", oi = 2, group = true, note = "Large Soran'ruk Fragment, from the Shadowfang Darksouls inside" },
	} },
	{ title = "Back to Doan Karhan", note = "Choose the off-hand Orb of Soran'ruk or the two-handed Staff of Soran'ruk.", goals = {
		{ t = "turnin", quest = 1740, title = "The Orb of Soran'ruk", npc = "Doan Karhan", map = 1413, x = 49.31, y = 57.21, era = true },
	} },
} end)

Waypost.RegisterSteps("class/warlock/shard-of-the-green-flame", function() return {
	{ title = "Niby the Almighty", note = "At 50 Niby the Almighty and his imp Impsy wait on a rise in central Felwood just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Niby sends you to Impsy, beside him, who wants three Flawless Fel Essences from three places.", goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 7601, title = "What Niby Commands", npc = "Niby the Almighty", map = 1448, x = 41.38, y = 44.85, era = true, qlvl = 50 },
		{ t = "turnin", quest = 7601, title = "What Niby Commands", npc = "Impsy", map = 1448, x = 41.36, y = 45.02, era = true },
		{ t = "accept", quest = 7602, title = "Flawless Fel Essence", npc = "Impsy", map = 1448, x = 41.36, y = 45.02, era = true, qlvl = 55 },
	} },
	{ title = "Azshara", note = "The Legashi satyrs (level 51-53) hold the Legash Encampment on Azshara's northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly.", goals = {
		{ t = "collect", quest = 7602, title = "Flawless Fel Essence", map = 1447, x = 61.42, y = 20.92, era = true, count = 1, item = 18624, itemName = "Flawless Fel Essence (Azshara)", oi = 1, mobLevel = 53, spots = "62.2,24;60.9,24.5;62.1,26.2;66.6,18.6;65.7,16.9" },
	} },
	{ title = "Jaedenar", note = "Jaedenar lies just south of Bloodvenom Post, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, Shadow Hold is the northern one, further up the hill; the other has no Legionnaires. Shadow Hold's tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward Lord Banehollow's chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of Jaedenar and Shadow Hold are all hostile.", goals = {
		{ t = "level", level = 53 },
		{ t = "collect", quest = 7602, title = "Flawless Fel Essence", map = 1448, x = 37.58, y = 50.21, era = true, count = 1, item = 18622, itemName = "Flawless Fel Essence (Jaedenar)", oi = 2, mobLevel = 55, spots = "39.3,50;37.3,54.5;36.7,46" },
	} },
	{ title = "The Dark Portal", note = "The Felguard Sentries (level 54) walk around the Dark Portal in the south of the Blasted Lands, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest.", goals = {
		{ t = "collect", quest = 7602, title = "Flawless Fel Essence", map = 1419, x = 58.52, y = 51.23, era = true, count = 1, item = 18623, itemName = "Flawless Fel Essence (Dark Portal)", oi = 3, mobLevel = 55, spots = "57.8,50;61,52.3;54.9,51.5" },
	} },
	{ title = "Impsy", note = "Back to Impsy. He hands you the Fel Fire: keep it, it wakes the infernal Kroshius.", goals = {
		{ t = "turnin", quest = 7602, title = "Flawless Fel Essence", npc = "Impsy", map = 1448, x = 41.36, y = 45.02, era = true },
		{ t = "accept", quest = 7603, title = "Kroshius' Infernal Core", npc = "Impsy", map = 1448, x = 41.36, y = 45.02, era = true, qlvl = 55 },
	} },
	{ title = "Kroshius", note = "Kroshius' remains lie in Shatter Scar Vale, the burnt crater north of Niby: follow the road north from his camp; the remains lie a little east of it. Use the Fel Fire beside them and wait for him to rise. Kroshius is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull Kroshius away from it. He always drops his core. Lost the Fel Fire? Abandon the quest and take it again from Impsy.", goals = {
		{ t = "use", map = 1448, x = 45.7, y = 34.8, era = true, item = 18626, itemName = "Fel Fire", note = "Fel Fire, at Kroshius' Remains" },
		{ t = "kill", quest = 7603, title = "Kroshius' Infernal Core", map = 1448, x = 45.7, y = 34.76, era = true, count = 1, target = "Kroshius", oi = 1, group = true },
		{ t = "collect", quest = 7603, title = "Kroshius' Infernal Core", map = 1448, x = 45.7, y = 34.76, era = true, count = 1, item = 18625, itemName = "Kroshius' Infernal Core", oi = 2, group = true },
	} },
	{ title = "Back to Niby", goals = {
		{ t = "turnin", quest = 7603, title = "Kroshius' Infernal Core", npc = "Niby the Almighty", map = 1448, x = 41.38, y = 44.85, era = true, note = "Niby the Almighty: Shard of the Green Flame" },
	} },
} end)

Waypost.RegisterSteps("class/warlock/tome-of-sacrifice", function() return {
	{ title = "Daio the Decrepit", note = "At 60 Daio the Decrepit waits in the Tainted Scar, the demon-filled hollow in the west of the Blasted Lands. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. Daio gives you two errands at once.", goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7581, title = "The Prison's Bindings", npc = "Daio the Decrepit", map = 1419, x = 34.13, y = 50.14, era = true, qlvl = 60 },
		{ t = "accept", quest = 7582, title = "The Prison's Casing", npc = "Daio the Decrepit", map = 1419, x = 34.13, y = 50.14, era = true, qlvl = 60 },
	} },
	{ title = "Satyr Blood", note = "The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, Dire Maul's eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at Lariss Pavilion needs the Crescent Key, which drops inside this wing; until someone has it, go in by Dire Maul's main gate in central Feralas.", goals = {
		{ t = "collect", quest = 7581, title = "The Prison's Bindings", map = 1444, x = 59.2, y = 45.1, era = true, count = 15, item = 18603, itemName = "Satyr Blood", oi = 1, group = true, note = "Satyr Blood, from the Wildspawn inside" },
	} },
	{ title = "Tears of the Hederine", note = "The Hederine demons (level 57-60, elite) hold Darkwhisper Gorge in the far south of Winterspring: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their Dominate Mind). A warlock can solo them one at a time with Fear or Banish and damage over time, but slowly. Any of them can drop the Tears, four kills in five.", goals = {
		{ t = "collect", quest = 7582, title = "The Prison's Casing", map = 1452, x = 58.3, y = 82.25, era = true, count = 5, item = 18604, itemName = "Tears of the Hederine", oi = 1, mobLevel = 60, group = true, spots = "58.7,83.6;59.2,87.6;57.5,88.4;55.5,84.2;52.8,84.9" },
	} },
	{ title = "Suppression", note = "Hand both in to Daio and take the Glowing Crystal Prison. Find a Doomguard Commander (level 61, elite) standing alone in the Tainted Scar, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his War Stomp can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the Imprisoned Doomguard: click it. If the channel breaks, kill him or run, and try another.", goals = {
		{ t = "turnin", quest = 7581, title = "The Prison's Bindings", npc = "Daio the Decrepit", map = 1419, x = 34.13, y = 50.14, era = true },
		{ t = "turnin", quest = 7582, title = "The Prison's Casing", npc = "Daio the Decrepit", map = 1419, x = 34.13, y = 50.14, era = true },
		{ t = "accept", quest = 7583, title = "Suppression", npc = "Daio the Decrepit", map = 1419, x = 34.13, y = 50.14, era = true, qlvl = 60 },
		{ t = "use", quest = 7583, title = "Suppression", map = 1419, x = 34.5, y = 63.7, era = true, item = 18601, itemName = "Glowing Crystal Prison", oi = 1, note = "Glowing Crystal Prison, on a Doomguard Commander" },
		{ t = "collect", quest = 7583, title = "Suppression", map = 1419, x = 34.55, y = 63.73, era = true, count = 1, item = 18605, itemName = "Imprisoned Doomguard", oi = 1, note = "Imprisoned Doomguard, click it", spots = "34.7,63.7;39,67.9;40.1,63.3;44.2,74;41.6,78.1" },
	} },
	{ title = "Back to Daio", goals = {
		{ t = "turnin", quest = 7583, title = "Suppression", npc = "Daio the Decrepit", map = 1419, x = 34.13, y = 50.14, era = true, note = "Daio the Decrepit: Tome of Sacrifice" },
	} },
} end)

Waypost.RegisterSteps("class/warrior/quelserrar", function() return {
	{ title = "Nostro's Compendium of Dragon Slaying", note = "The book is a rare random drop from the bosses of all three Dire Maul wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, Immol'thar and the West, King Gordok and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. Dire Maul is a five-player dungeon in the ruins of central Feralas: needs a group of five. Right-click the book to start the quest; it stays in your bags.", goals = {
		{ t = "accept", quest = 7507, title = "Foror's Compendium", item = 18401, itemName = "Nostro's Compendium of Dragon Slaying", qlvl = 60, group = true, note = "from Nostro's Compendium of Dragon Slaying" },
	} },
	{ title = "Lorekeeper Lydros", note = "Lorekeeper Lydros stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the Crescent Key, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you A Dull and Flat Elven Blade to give straight back, then the Unfired Ancient Blade. Keep that blade: lose it, and you must abandon the quest and take it again.", goals = {
		{ t = "turnin", quest = 7507, title = "Foror's Compendium", npc = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, era = true, group = true, note = "Lorekeeper Lydros, in the Athenaeum" },
		{ t = "accept", quest = 7508, title = "The Forging of Quel'Serrar", npc = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, era = true, qlvl = 60, group = true },
		{ t = "turnin", quest = 7508, title = "The Forging of Quel'Serrar", npc = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, era = true, group = true, note = "Lorekeeper Lydros: hand back the Dull and Flat Elven Blade" },
		{ t = "accept", quest = 7509, title = "The Forging of Quel'Serrar", npc = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, era = true, qlvl = 60, group = true },
	} },
	{ title = "Onyxia's breath", note = "Onyxia is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the Unfired Ancient Blade to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the Ancient Heated Blade to take the Heated Ancient Blade: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade.", goals = {
		{ t = "use", map = 1445, x = 52.1, y = 75.8, era = true, item = 18489, itemName = "Unfired Ancient Blade", group = true, note = "Unfired Ancient Blade: plant it in her breath" },
		{ t = "collect", map = 1445, x = 52.1, y = 75.8, era = true, item = 18488, itemName = "Heated Ancient Blade", note = "click the heated blade on the ground" },
	} },
	{ title = "Onyxia's corpse", note = "Kill Onyxia, then target her corpse and use the Heated Ancient Blade on it before the 20 minutes run out. It becomes the Treated Ancient Blade, with no time limit.", goals = {
		{ t = "kill", map = 1445, x = 52.1, y = 75.8, era = true, target = "Onyxia", group = true },
		{ t = "use", quest = 7509, title = "The Forging of Quel'Serrar", map = 1445, x = 52.1, y = 75.8, era = true, item = 18488, itemName = "Heated Ancient Blade", oi = 1, group = true, note = "Heated Ancient Blade, on her corpse" },
		{ t = "collect", quest = 7509, title = "The Forging of Quel'Serrar", map = 1445, x = 52.1, y = 75.8, era = true, count = 1, item = 18492, itemName = "Treated Ancient Blade", oi = 1, group = true },
	} },
	{ title = "The Forging of Quel'Serrar", note = "Back to Lorekeeper Lydros in the Athenaeum of Dire Maul West: through the West door with the Crescent Key again, and a group to reach the library.", goals = {
		{ t = "turnin", quest = 7509, title = "The Forging of Quel'Serrar", npc = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, era = true, group = true, note = "Lorekeeper Lydros: Quel'Serrar" },
	} },
} end)

