		{ t = "accept", quest = 8417, title = "A Troubled Spirit", npc = "Christoph Walker", map = 1458, x = 46.93, y = 15.23, era = true, qlvl = 52 },
	} },
	{ title = "The Fallen Hero of the Horde", note = "The Fallen Hero of the Horde, a ghost, stands in the south-west of the Swamp of Sorrows, at the pass into the Blasted Lands, a short ride south-west of Stonard. Horde: fly to Stonard. Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north through the pass. High-level beasts roam the way.", goals = {
		{ t = "turnin", quest = 8417, title = "A Troubled Spirit", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true },
		{ t = "accept", quest = 8423, title = "Warrior Kinship", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true, qlvl = 52 },
	} },
	{ title = "Helboars", note = "Seven Helboars (level 52-53, not elite) roam the north-west of the Blasted Lands, south-west of Nethergarde Keep; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast Fire Nova. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes.", goals = {
		{ t = "kill", quest = 8423, title = "Warrior Kinship", map = 1419, x = 49.8, y = 42.69, era = true, count = 7, target = "Helboar", oi = 1, mobLevel = 53, spots = "53,41;54.8,43.2;53.8,37.2;51.3,37.3;48.2,36.8" },
	} },
	{ title = "War on the Shadowsworn", goals = {
		{ t = "turnin", quest = 8423, title = "Warrior Kinship", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true },
		{ t = "accept", quest = 8424, title = "War on the Shadowsworn", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true, qlvl = 52 },
	} },
	{ title = "Shadowsworn camps", note = "The Shadowsworn camp around the mouth of the Serpent's Coil cave, south of Nethergarde Keep on the way to the Dark Portal. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and Kick). Thugs can run short before the others: kill every Shadowsworn you pass.", goals = {
		{ t = "kill", quest = 8424, title = "War on the Shadowsworn", map = 1419, x = 65.02, y = 38.21, era = true, count = 20, target = "Shadowsworn Adept", oi = 1, mobLevel = 53, spots = "64.9,34.5;62.6,41.5;66.7,30.8;64.3,47.1;69.1,31.1" },
		{ t = "kill", quest = 8424, title = "War on the Shadowsworn", map = 1419, x = 63.91, y = 40.94, era = true, count = 10, target = "Shadowsworn Cultist", oi = 2, mobLevel = 52, spots = "62.7,41.1;63.5,46.1;64.9,33.7;66.9,30.8" },
		{ t = "kill", quest = 8424, title = "War on the Shadowsworn", map = 1419, x = 63.86, y = 42.31, era = true, count = 20, target = "Shadowsworn Thug", oi = 3, mobLevel = 53, spots = "63.9,43.2;63.2,39.8;63.4,46.9;65.3,31.7;68,30.6" },
	} },
	{ title = "Voodoo Feathers", goals = {
		{ t = "turnin", quest = 8424, title = "War on the Shadowsworn", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true },
		{ t = "accept", quest = 8425, title = "Voodoo Feathers", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true, qlvl = 52 },
	} },
	{ title = "The Sunken Temple", note = "You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the Sunken Temple's balcony, who hold the barrier in front of Jammal'an the Prophet: Gasher and Zul'Lor drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The Sunken Temple is a five-player dungeon: needs a group of five. It lies in the Pool of Tears in eastern Swamp of Sorrows: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts Shadow Bolt Volley and Curse of Blood; Mijan heals the others (Renew, a Healing Ward, Healing Wave below half health): kill her or her ward fast; Zul'Lor cleaves.", goals = {
		{ t = "collect", quest = 8425, title = "Voodoo Feathers", map = 1435, x = 69.9, y = 53.6, era = true, count = 2, item = 20606, itemName = "Amber Voodoo Feather", oi = 1, note = "Amber Voodoo Feather, from Gasher and Zul'Lor" },
		{ t = "collect", quest = 8425, title = "Voodoo Feathers", map = 1435, x = 69.9, y = 53.6, era = true, count = 2, item = 20607, itemName = "Blue Voodoo Feather", oi = 2, note = "Blue Voodoo Feather, from Hukku and Mijan" },
		{ t = "collect", quest = 8425, title = "Voodoo Feathers", map = 1435, x = 69.9, y = 53.6, era = true, count = 2, item = 20608, itemName = "Green Voodoo Feather", oi = 3, note = "Green Voodoo Feather, from Zolo and Loro" },
	} },
	{ title = "Back to the Fallen Hero", note = "In Classic the Fallen Hero let you choose the Diamond Flask, the Fury Visor or the Razorsteel Shoulders here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in.", goals = {
		{ t = "turnin", quest = 8425, title = "Voodoo Feathers", npc = "Fallen Hero of the Horde", map = 1435, x = 34.29, y = 66.14, era = true },
	} },
} end)

Waypost.RegisterSteps("class/warrior/whirlwind-weapon", function() return {
	{ title = "The Islander (Stormwind)", note = "At 30, Wu Shen, beside Ilsa Corbin in the warrior trainers' building of Old Town, sends you to Klannoc Macleod on Fray Island in the Barrens.", only = { races = {"Human", "NightElf", "Skyborne"}, factions = {"Alliance"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1718, title = "The Islander", npc = "Wu Shen", map = 1453, x = 80.55, y = 59.87, qlvl = 30 },
	} },
	{ title = "The Islander (Ironforge)", note = "At 30, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to Klannoc Macleod on Fray Island in the Barrens.", only = { races = {"Dwarf", "Gnome"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1718, title = "The Islander", npc = "Kelv Sternhammer", map = 1455, x = 70.34, y = 90.65, era = true, qlvl = 30 },
	} },
	{ title = "The Islander (Orgrimmar)", note = "At 30, Sorek in the Valley of Honor sends you to Klannoc Macleod on Fray Island in the Barrens.", only = { races = {"Orc", "Troll", "Skyborne"}, factions = {"Horde"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1718, title = "The Islander", npc = "Sorek", map = 1454, x = 80.39, y = 32.38, era = true, qlvl = 30 },
	} },
	{ title = "The Islander (Thunder Bluff)", note = "At 30, Torm Ragetotem, the warrior trainer of Thunder Bluff, sends you to Klannoc Macleod on Fray Island in the Barrens.", only = { races = {"Tauren"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1718, title = "The Islander", npc = "Torm Ragetotem", map = 1456, x = 57.24, y = 87.37, era = true, qlvl = 30 },
	} },
	{ title = "The Islander (Undercity)", note = "At 30, Baltus Fowler, a warrior trainer of the Undercity, sends you to Klannoc Macleod on Fray Island in the Barrens.", only = { races = {"Scourge"} }, goals = {
		{ t = "level", level = 30 },
		{ t = "accept", quest = 1718, title = "The Islander", npc = "Baltus Fowler", map = 1458, x = 47.4, y = 17.29, era = true, qlvl = 30 },
	} },
	{ title = "Fray Island", note = "Fly to Ratchet and go south along the Merchant Coast. Fray Island lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. Klannoc Macleod stands by the arena.", goals = {
		{ t = "turnin", quest = 1718, title = "The Islander", npc = "Klannoc Macleod", map = 1413, x = 68.62, y = 49.16, era = true },
		{ t = "accept", quest = 1719, title = "The Affray", npc = "Klannoc Macleod", map = 1413, x = 68.62, y = 49.16, era = true, qlvl = 30 },
	} },
	{ title = "The Affray", note = "You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: Twiggy Flathead announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then Big Will (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use Demoralizing Shout: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again.", goals = {
		{ t = "kill", quest = 1719, title = "The Affray", map = 1413, x = 68.6, y = 48.7, era = true, count = 1, target = "Big Will", oi = 1 },
		{ t = "turnin", quest = 1719, title = "The Affray", npc = "Klannoc Macleod", map = 1413, x = 68.62, y = 49.16, era = true, note = "Klannoc Macleod: Berserker Stance" },
		{ t = "accept", quest = 1791, title = "The Windwatcher", npc = "Klannoc Macleod", map = 1413, x = 68.62, y = 49.16, era = true, qlvl = 30 },
	} },
	{ title = "Bath'rah the Windwatcher", note = "Bath'rah the Windwatcher camps by ruins on the east bank of the river that runs past Tarren Mill, a short walk north-east of the town, just over the border in Alterac Mountains; his cauldron stands beside him. Horde: fly to Tarren Mill. Alliance: fly to Southshore and go north along the river; Tarren Mill's guards are level 42 elites, so keep away from the town. Accepting Cyclonian gives you Bath'rah's Parchment, the list of what he needs: 8 Liferoot, 30 Bloodscalp Tusks and the Essence of the Exile from his cauldron. The cauldron's Essence of the Exile is not a quest you take: it never shows in your quest log. Come back with its charms and hand them in at the cauldron.", goals = {
		{ t = "turnin", quest = 1791, title = "The Windwatcher", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true },
		{ t = "accept", quest = 1712, title = "Cyclonian", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true, qlvl = 40 },
	} },
	{ title = "Liferoot", note = "You need 8 Liferoot. Herbalists pick it by rivers and lakes in the Wetlands, Arathi Highlands and Stranglethorn Vale; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: Bernard Gump and Maria Lumere in Stormwind, Antonio Perelli on the road in eastern Elwynn, Jeeda at Sun Rock Retreat in Stonetalon, Montarr in Thousand Needles. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve.", goals = {
		{ t = "collect", quest = 1712, title = "Cyclonian", map = 1416, x = 77.21, y = 64.4, era = true, count = 8, item = 3357, itemName = "Liferoot", oi = 1, spots = "76.7,63.4;72.6,69.3;83.5,52.6;37.7,20.8;36.1,25.4" },
	} },
	{ title = "Bloodscalp Tusks", note = "You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of Grom'gol Base Camp and around the Bal'lal Ruins on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes.", goals = {
		{ t = "collect", quest = 1712, title = "Cyclonian", map = 1434, x = 32.26, y = 17.17, era = true, count = 30, item = 3901, itemName = "Bloodscalp Tusk", oi = 2, mobLevel = 34, spots = "30.5,17.4;30,21.2;34.3,14.6;31.4,12.2;27.5,11.3" },
	} },
	{ title = "The exiles of Arathi", note = "The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite: the guide waits for level 37 first, and a friend helps. Burning Exiles (fire) by the Circle of West Binding in the north-west, north-west of Refuge Pointe; Thundering Exiles (air) by the Circle of Outer Binding south-east of Refuge Pointe, casting Lightning Bolt from 40 yards; Cresting Exiles (water) by the Circle of East Binding, north-west of Hammerfall, with Frost Nova. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning).", goals = {
		{ t = "level", level = 37 },
		{ t = "collect", map = 1417, x = 25.61, y = 30.4, era = true, count = 8, item = 4479, itemName = "Burning Charm", mobLevel = 39, note = "Burning Charm, from Burning Exiles", spots = "25.3,30.1;26.8,31.7" },
		{ t = "collect", map = 1417, x = 50.39, y = 50.83, era = true, count = 8, item = 4480, itemName = "Thundering Charm", mobLevel = 39, note = "Thundering Charm, from Thundering Exiles", spots = "51.5,51.3;52.7,49.3" },
		{ t = "collect", map = 1417, x = 65.36, y = 31.01, era = true, count = 8, item = 4481, itemName = "Cresting Charm", mobLevel = 39, note = "Cresting Charm, from Cresting Exiles" },
	} },
	{ title = "Essence of the Exile", note = "Click Bath'rah's Cauldron with the 24 charms in your bags and Cyclonian in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the Essence of the Exile.", goals = {
		{ t = "turnin", quest = 1714, title = "Essence of the Exile", npc = "Bath'rah's Cauldron", map = 1416, x = 79.32, y = 66.8, era = true, qlvl = 37, note = "Bath'rah's Cauldron: Essence of the Exile" },
		{ t = "collect", quest = 1712, title = "Cyclonian", map = 1416, x = 80.5, y = 66.9, era = true, count = 1, item = 6851, itemName = "Essence of the Exile", oi = 3, note = "Essence of the Exile, from the cauldron by Bath'rah" },
	} },
	{ title = "The Summoning", note = "Back to Bath'rah. Accepting The Summoning starts his ritual, and Cyclonian appears just north of his camp. Cyclonian is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a Nature Protection Potion soaks it), whirls, and Knock Away throws you far while it heals itself as you run back: fight with your back to a slope or rock. The Whirlwind Heart always drops. If the fight fails Bath'rah stops answering: abandon The Summoning and take it again for a new summon; the earlier items are not needed again.", goals = {
		{ t = "turnin", quest = 1712, title = "Cyclonian", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true },
		{ t = "level", level = 38 },
		{ t = "accept", quest = 1713, title = "The Summoning", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true, qlvl = 40 },
		{ t = "kill", map = 1416, x = 80.32, y = 62.14, era = true, target = "Cyclonian", group = true },
		{ t = "collect", quest = 1713, title = "The Summoning", map = 1416, x = 80.32, y = 62.14, era = true, count = 1, item = 6894, itemName = "Whirlwind Heart", oi = 1, group = true, note = "Whirlwind Heart, from Cyclonian" },
		{ t = "turnin", quest = 1713, title = "The Summoning", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true },
		{ t = "accept", quest = 1792, title = "Whirlwind Weapon", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true, qlvl = 40 },
		{ t = "turnin", quest = 1792, title = "Whirlwind Weapon", npc = "Bath'rah the Windwatcher", map = 1416, x = 80.5, y = 66.92, era = true, note = "Bath'rah the Windwatcher: Whirlwind Axe, Sword or Warhammer" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/neutral/deathcharger", function() return {
	{ title = "Journeyman Riding", note = "Deathcharger's Reins needs level 60 and Journeyman Riding to ride (Forever client). Train it at your race's riding trainer; see the Level 60 mount guides.", goals = {
		{ t = "level", level = 60 },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
	{ title = "Stratholme: Baron Rivendare", note = "Stratholme is a group of five, level 58-60. The Service Entrance at Elders' Square, in north-western Eastern Plaguelands, leads to the undead side; Baron Rivendare waits in the Slaughter House at its end. Our data gives the reins a 0.02% drop chance (pfQuest, Era): one in about five thousand kills. Nothing shows Forever changing it.", goals = {
		{ t = "goto", map = 1423, x = 41.5, y = 17.7, era = true, text = "Stratholme Service Entrance" },
		{ t = "collect", map = 1423, x = 41.5, y = 17.7, era = true, item = 13335, itemName = "Deathcharger's Reins", group = true, note = "Baron Rivendare" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/neutral/galestrider", function() return {
	{ title = "Learn to ride", note = "Galestriders need level 40 and Riding. Train it at your own race's riding trainer; see the Level 40 mount guides for where.", only = { races = {"Human", "Dwarf", "NightElf", "Gnome", "Orc", "Troll", "Tauren", "Scourge"} }, goals = {
		{ t = "level", level = 40 },
		{ t = "skill", level = 75, skillName = "Riding" },
	} },
	{ title = "Skyboat from Dalaran", note = "Zephras Isle is the Skyborne starting island; anyone may visit. A skyboat leaves the north side of Dalaran about every five minutes (another flies from north of Thunder Bluff; either faction may take either). Skip this if you are already on the island.", only = { factions = {"Alliance"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1416, x = 12.5, y = 51.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Skyboat from Thunder Bluff", note = "Zephras Isle is the Skyborne starting island; anyone may visit. A skyboat leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes (another flies from Dalaran; either faction may take either). Skip this if you are already on the island.", only = { factions = {"Horde"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1412, x = 34.3, y = 25.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Riding with Genn Fairweather", note = "Skyborne learn Riding from Genn Fairweather himself for 100g, and it comes with a Galestrider. He stands at the Fairweather Stables in Valanaar, near the skyboat docks.", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 40 },
		{ t = "train", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, note = "Genn Fairweather, riding trainer" },
		{ t = "skill", level = 75, skillName = "Riding" },
	} },
	{ title = "Galestrider Riding for other races", note = "Any race can buy Galestriders, but riding one also takes Galestrider Riding, which only the Skyborne get with Riding. Other races can learn it too, but how is not known yet: in Classic another race's riding needed Exalted with its home faction, here the High Order (Alliance) or the Windshapers (Horde). Ask Genn Fairweather before you buy.", only = { races = {"Human", "Dwarf", "NightElf", "Gnome", "Orc", "Troll", "Tauren", "Scourge"} }, when = {{ k = "knows", neg = true, spell = 1285849 }}, goals = {
		{ t = "talk", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33 },
	} },
	{ title = "Genn Fairweather", note = "Genn Fairweather is at the Fairweather Stables in Valanaar, the island's harbour town, near the skyboat docks. The Forever client lists each Galestrider at 20g; choose one.", goals = {
		{ t = "vendor", npc = "Genn Fairweather", map = 2521, x = 53.8, y = 81.2 },
		{ t = "buy", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, item = 269681, itemName = "Empyrean Galestrider", optional = true, note = "20g" },
		{ t = "buy", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, item = 269683, itemName = "Stormy Galestrider", optional = true, note = "20g" },
		{ t = "buy", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, item = 274930, itemName = "Umber Galestrider", optional = true, note = "20g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/neutral/spectral-bear", function() return {
	{ title = "55 Legacy Points", note = "Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, professions, PvP, exploring) is worth one, and every point the account earns counts here, spent or not. The Legacy Challenges guide plans them. The Progress Track gives the Replica Ironforge Air Rifle at 15, the Spectral Bear Cub at 25, the Spectral Bear Tabard at 40 and the reins at 55. Claim each one from Innkeeper Wiley at the inn in Ratchet, on the Barrens coast: he offers a \"Legacy Reward\" quest once you have the points.", goals = {
		{ t = "talk", npc = "Innkeeper Wiley", map = 1413, x = 62.05, y = 39.41, era = true, note = "Innkeeper Wiley, Ratchet" },
		{ t = "collect", map = 1413, x = 62, y = 39.4, era = true, item = 277718, itemName = "Reins of the Spectral Bear", note = "from Innkeeper Wiley" },
	} },
	{ title = "Journeyman Riding", note = "The bear runs at full speed: riding it needs level 60 and Journeyman Riding (Forever client), from your race's riding trainer; see the Level 60 mount guides.", goals = {
		{ t = "level", level = 60 },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/neutral/swift-galestrider", function() return {
	{ title = "Journeyman Riding", note = "Swift Galestriders need level 60 and Journeyman Riding. Train it at your own race's riding trainer; see the Level 60 mount guides for where.", only = { races = {"Human", "Dwarf", "NightElf", "Gnome", "Orc", "Troll", "Tauren", "Scourge"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
	{ title = "Skyboat from Dalaran", note = "Zephras Isle is the Skyborne starting island; anyone may visit. A skyboat leaves the north side of Dalaran about every five minutes (another flies from north of Thunder Bluff; either faction may take either). Skip this if you are already on the island.", only = { factions = {"Alliance"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1416, x = 12.5, y = 51.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Skyboat from Thunder Bluff", note = "Zephras Isle is the Skyborne starting island; anyone may visit. A skyboat leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes (another flies from Dalaran; either faction may take either). Skip this if you are already on the island.", only = { factions = {"Horde"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1412, x = 34.3, y = 25.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Journeyman Riding with Genn Fairweather", note = "Skyborne train Journeyman Riding with Genn Fairweather himself for 1,000g; Blizzard says it comes with a mount. He stands at the Fairweather Stables in Valanaar, near the skyboat docks.", only = { races = {"Skyborne"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "train", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, note = "Genn Fairweather, riding trainer" },
		{ t = "skill", level = 150, skillName = "Riding" },
	} },
	{ title = "Galestrider Riding for other races", note = "Any race can buy Galestriders, but riding one also takes Galestrider Riding, which only the Skyborne get with Riding. Other races can learn it too, but how is not known yet: in Classic another race's riding needed Exalted with its home faction, here the High Order (Alliance) or the Windshapers (Horde). Ask Genn Fairweather before you buy.", only = { races = {"Human", "Dwarf", "NightElf", "Gnome", "Orc", "Troll", "Tauren", "Scourge"} }, when = {{ k = "knows", neg = true, spell = 1285849 }}, goals = {
		{ t = "talk", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33 },
	} },
	{ title = "Genn Fairweather", note = "Genn Fairweather is at the Fairweather Stables in Valanaar, the island's harbour town, near the skyboat docks. The Forever client lists each Swift Galestrider at 200g; choose one.", goals = {
		{ t = "vendor", npc = "Genn Fairweather", map = 2521, x = 53.8, y = 81.2 },
		{ t = "buy", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, item = 269671, itemName = "Swift Empyrean Galestrider", optional = true, note = "200g" },
		{ t = "buy", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, item = 269678, itemName = "Swift Stormy Galestrider", optional = true, note = "200g" },
		{ t = "buy", npc = "Genn Fairweather", map = 2521, x = 53.83, y = 81.33, item = 274933, itemName = "Swift Umber Galestrider", optional = true, note = "200g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/neutral/warlock-dreadsteed", function() return {
	{ title = "Mor'zul Bloodbringer (Stormwind)", note = "At 60 Spackle Thornberry, the demon trainer in the Slaughtered Lamb, sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = { races = {"Human"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7562, title = "Mor'zul Bloodbringer", npc = "Spackle Thornberry", map = 1453, x = 39.53, y = 84.53, qlvl = 58 },
	} },
	{ title = "Mor'zul Bloodbringer (Ironforge)", note = "At 60 Jubahl Corpseseeker, the demon trainer in Ironforge, sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = { races = {"Gnome"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7562, title = "Mor'zul Bloodbringer", npc = "Jubahl Corpseseeker", map = 1455, x = 52.7, y = 6.08, era = true, qlvl = 58 },
	} },
	{ title = "Mor'zul Bloodbringer (Orgrimmar)", note = "At 60 Kurgul, the demon trainer in the Cleft of Shadow, sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7562, title = "Mor'zul Bloodbringer", npc = "Kurgul", map = 1454, x = 47.52, y = 46.72, era = true, qlvl = 58 },
	} },
	{ title = "Mor'zul Bloodbringer (Undercity)", note = "At 60 Martha Strain, the demon trainer in the Magic Quarter, sends you to Mor'zul Bloodbringer in the Burning Steppes.", only = { races = {"Scourge"} }, goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7562, title = "Mor'zul Bloodbringer", npc = "Martha Strain", map = 1458, x = 85.7, y = 16.08, era = true, qlvl = 58 },
	} },
	{ title = "Mor'zul Bloodbringer", note = "Mor'zul Bloodbringer and his goblin Gorzeeki Wildeyes camp on the hill across the road from the Altar of Storms, in the far north-west of the Burning Steppes, west of Blackrock Mountain. The chain is long: about 420 gold in Gorzeeki's and Ur'dan's goods, a pile of crafted materials, the Scholomance and Dire Maul. Start buying or gathering the materials of the next steps now.", goals = {
		{ t = "turnin", quest = 7562, title = "Mor'zul Bloodbringer", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true },
		{ t = "accept", quest = 7563, title = "Rage of Blood", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true, qlvl = 58 },
	} },
	{ title = "Raging Beast's Blood", note = "Every owlbeast of Winterspring (level 53-58, none elite) drops the blood about one time in three: about ninety kills for thirty. Owl Wing Thicket, in the north-east, and the Hidden Grove's surroundings are packed with them, and they respawn in five and a half minutes.", goals = {
		{ t = "collect", quest = 7563, title = "Rage of Blood", map = 1452, x = 43.16, y = 39.43, era = true, count = 30, item = 18590, itemName = "Raging Beast's Blood", oi = 1, mobLevel = 55, spots = "44.4,38;48.2,46.4;51.5,39.3;56.6,32.1;62.2,31.8" },
	} },
	{ title = "Wildeyes", note = "Back to Mor'zul: he gives you the Case of Blood for Gorzeeki beside him. Then Mor'zul asks for the bell, the wheel and the candle, and Gorzeeki sends you to Lord Banehollow in Jaedenar: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after Ulathek, and a spare in case one runs out) and bring 150 gold for the stardust.", goals = {
		{ t = "turnin", quest = 7563, title = "Rage of Blood", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true },
		{ t = "accept", quest = 7564, title = "Wildeyes", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true, qlvl = 58, note = "he gives you the Case of Blood" },
		{ t = "turnin", quest = 7564, title = "Wildeyes", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
		{ t = "accept", quest = 7626, title = "Bell of Dethmoora", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true, qlvl = 60, note = "Mor'zul Bloodbringer: Bell of Dethmoora" },
		{ t = "accept", quest = 7627, title = "Wheel of the Black March", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true, qlvl = 60, note = "Mor'zul Bloodbringer: Wheel of the Black March" },
		{ t = "accept", quest = 7628, title = "Doomsday Candle", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true, qlvl = 60, note = "Mor'zul Bloodbringer: Doomsday Candle" },
		{ t = "accept", quest = 7623, title = "Lord Banehollow", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, qlvl = 58, note = "Gorzeeki Wildeyes: Lord Banehollow" },
		{ t = "buy", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, count = 3, item = 18802, itemName = "Shadowy Potion", note = "Shadowy Potion, from Gorzeeki" },
	} },
	{ title = "The ritual pieces", note = "Gorzeeki wants 10 Elixirs of Shadow Power (Alchemy: 3 Ghost Mushrooms and a Crystal Vial each), 6 Large Brilliant Shards (Enchanting: disenchant level 51+ blue items), 25 Dark Iron Ore (Mining 230: the Dark Iron Deposits of the Burning Steppes and Blackrock Depths) and 35 Black Dragonscales (Skinning: the black dragonkin of the Burning Steppes, a few percent a kill, best from the Flamescale Wyrmkin). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales.", goals = {
		{ t = "collect", quest = 7626, title = "Bell of Dethmoora", map = 1453, x = 61.2, y = 71.3, count = 10, item = 9264, itemName = "Elixir of Shadow Power", oi = 1, only = { factions = {"Alliance"} }, note = "Elixir of Shadow Power: the Auction House" },
		{ t = "collect", quest = 7626, title = "Bell of Dethmoora", map = 1454, x = 55.9, y = 62.7, era = true, count = 10, item = 9264, itemName = "Elixir of Shadow Power", oi = 1, only = { factions = {"Horde"} }, note = "Elixir of Shadow Power: the Auction House" },
		{ t = "collect", quest = 7627, title = "Wheel of the Black March", map = 1453, x = 61.2, y = 71.3, count = 6, item = 14344, itemName = "Large Brilliant Shard", oi = 1, only = { factions = {"Alliance"} }, note = "Large Brilliant Shard: the Auction House" },
		{ t = "collect", quest = 7627, title = "Wheel of the Black March", map = 1454, x = 55.9, y = 62.7, era = true, count = 6, item = 14344, itemName = "Large Brilliant Shard", oi = 1, only = { factions = {"Horde"} }, note = "Large Brilliant Shard: the Auction House" },
		{ t = "collect", quest = 7627, title = "Wheel of the Black March", map = 1428, x = 56.05, y = 47.78, era = true, count = 25, item = 11370, itemName = "Dark Iron Ore", oi = 2, spots = "56.9,42.9;65.9,21.9;79.2,25.3;81.4,47.9;73,64.3" },
		{ t = "collect", quest = 7628, title = "Doomsday Candle", map = 1428, x = 56.33, y = 60.61, era = true, count = 35, item = 15416, itemName = "Black Dragonscale", oi = 1, mobLevel = 54, spots = "56.3,60.6;76.9,62.1;91.8,55.2;91,51.3;89.9,43.9" },
	} },
	{ title = "Arcanite", note = "Hand the three pieces to Gorzeeki. He then wants 3 Arcanite Bars for the Black Lodestone: alchemists transmute them (an Arcane Crystal and a Thorium Bar each, on a long cooldown); everyone else buys them.", goals = {
		{ t = "turnin", quest = 7626, title = "Bell of Dethmoora", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
		{ t = "turnin", quest = 7627, title = "Wheel of the Black March", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
		{ t = "turnin", quest = 7628, title = "Doomsday Candle", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
		{ t = "accept", quest = 7630, title = "Arcanite", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, qlvl = 60 },
		{ t = "collect", quest = 7630, title = "Arcanite", map = 1453, x = 61.2, y = 71.3, count = 3, item = 12360, itemName = "Arcanite Bar", oi = 1, only = { factions = {"Alliance"} }, note = "Arcanite Bar: the Auction House" },
		{ t = "collect", quest = 7630, title = "Arcanite", map = 1454, x = 55.9, y = 62.7, era = true, count = 3, item = 12360, itemName = "Arcanite Bar", oi = 1, only = { factions = {"Horde"} }, note = "Arcanite Bar: the Auction House" },
		{ t = "turnin", quest = 7630, title = "Arcanite", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
	} },
	{ title = "Lord Banehollow", note = "Jaedenar lies just south of Bloodvenom Post in western Felwood, west of the road; of its two caves, Shadow Hold is the northern one, further up the hill. Drink a Shadowy Potion at its mouth: for 20 minutes the Shadow Council there treat you as one of their own (Taint of Shadow). The oozes in the red pool and the succubus Rakaiah beyond them still attack: hug the wall past them. Go down past the second, red pool, up the ramp and across two bridges to Lord Banehollow, a great winged dreadlord at the back. He talks to you only while the potion lasts.", goals = {
		{ t = "goto", map = 1448, x = 35.4, y = 58.6, era = true, text = "Shadow Hold" },
		{ t = "turnin", quest = 7623, title = "Lord Banehollow", npc = "Lord Banehollow", map = 1448, x = 35.9, y = 44.4, era = true },
		{ t = "accept", quest = 7624, title = "Ulathek the Traitor", npc = "Lord Banehollow", map = 1448, x = 35.93, y = 44.42, era = true, qlvl = 58 },
	} },
	{ title = "Ulathek the Traitor", note = "Ulathek waits in a small side room up a bridge you passed on the way down. Speak to him and he and four guards attack (all level 57, none elite): let your voidwalker hold the guards and burn Ulathek, sacrificing it if you must. Or click off your Taint of Shadow aura to start the fight, kill Ulathek, then drink another potion: the guards stop at once. Take his heart back to Lord Banehollow with a potion active.", goals = {
		{ t = "kill", map = 1448, x = 40.76, y = 48.42, era = true, target = "Ulathek", optional = true },
		{ t = "collect", quest = 7624, title = "Ulathek the Traitor", map = 1448, x = 40.76, y = 48.42, era = true, count = 1, item = 18719, itemName = "The Traitor's Heart", oi = 1 },
		{ t = "turnin", quest = 7624, title = "Ulathek the Traitor", npc = "Lord Banehollow", map = 1448, x = 35.9, y = 44.4, era = true },
		{ t = "accept", quest = 7625, title = "Xorothian Stardust", npc = "Lord Banehollow", map = 1448, x = 35.93, y = 44.42, era = true, qlvl = 60 },
	} },
	{ title = "Xorothian Stardust", note = "Ur'dan, beside Lord Banehollow, sells the Xorothian Stardust for 150 gold. He deals with you only while a Shadowy Potion is active.", goals = {
		{ t = "buy", npc = "Ur'dan", map = 1448, x = 36.18, y = 44.46, era = true, item = 18687, itemName = "Xorothian Stardust", note = "Xorothian Stardust, from Ur'dan" },
	} },
	{ title = "Imp Delivery", note = "Back to Gorzeeki with the stardust; with the Arcanite also done he gives you the Imp in a Jar for the Scholomance. Put a group of five together now: a party, not a raid group.", goals = {
		{ t = "buy", npc = "Ur'dan", map = 1448, x = 36.18, y = 44.46, era = true, item = 18687, itemName = "Xorothian Stardust", note = "Xorothian Stardust, from Ur'dan" },
		{ t = "turnin", quest = 7625, title = "Xorothian Stardust", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
		{ t = "accept", quest = 7629, title = "Imp Delivery", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, qlvl = 60 },
	} },
	{ title = "The Scholomance", note = "The Scholomance (level 58-60, a group of five) lies under Caer Darrow, the island town in the south-east of the Western Plaguelands: someone needs the Skeleton Key or a rogue to open the door. Fight down to Ras Frostwhisper's room and use the Imp in a Jar at the alchemy lab tables to the right: J'eevee makes the parchment. You need not kill Ras, but it only counts at this lab and only in a party.", goals = {
		{ t = "complete", quest = 7629, title = "Imp Delivery", map = 1422, x = 69.7, y = 73.2, era = true, group = true, note = "Use the Imp in a Jar at the alchemy lab inside", objs = {"J'eevee"}, startItem = 18688, startItemName = "Imp in a Jar" },
	} },
	{ title = "Dreadsteed of Xoroth", note = "Back to Gorzeeki, then Mor'zul hands you his instructions. Buy J'eevee's Jar (150 gold), the Black Lodestone (50) and the Xorothian Glyphs (50) from Gorzeeki; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards.", goals = {
		{ t = "turnin", quest = 7629, title = "Imp Delivery", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true },
		{ t = "accept", quest = 7631, title = "Dreadsteed of Xoroth", npc = "Mor'zul Bloodbringer", map = 1428, x = 12.69, y = 31.64, era = true, qlvl = 60 },
		{ t = "buy", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, item = 18663, itemName = "J'eevee's Jar", note = "J'eevee's Jar, 150 gold" },
		{ t = "buy", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, item = 18629, itemName = "Black Lodestone", note = "Black Lodestone, 50 gold" },
		{ t = "buy", npc = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, era = true, item = 18670, itemName = "Xorothian Glyphs", note = "Xorothian Glyphs, 50 gold" },
	} },
	{ title = "Into Dire Maul West", note = "Dire Maul stands in the ruins of central Feralas: from the gate at the foot of the ruins, walk up through the outer courtyards to the west wing's door at the north end. That door and an inner door need the Crescent Key (it drops from Pusillin in Dire Maul East) or a rogue with 300 Lockpicking. Bring a party of five. Lower Immol'thar's shield by killing the guardians of the five pylons (two stand in his own room), then kill Immol'thar: his dais is the summoning circle. Rest and rebuff before you start.", goals = {
		{ t = "kill", map = 1444, x = 60.3, y = 30.2, era = true, target = "Immol'thar", group = true, note = "Immol'thar, inside the west wing" },
	} },
	{ title = "The ritual", note = "Stand on the dais and use J'eevee's Jar: J'eevee sets out the Bell, the Wheel and the Candle. The Bell heals warlocks, the Wheel shields the party, the Candle burns the imps: ignore the imps and kill the Dread Guards (elite felguards, about ten, sometimes two at once); Banish or Enslave helps. Give one player each node to watch: when one sags, tilts and sounds, a warlock with a Lodestone recharges it, a 3-second cast that any hit breaks (a Soul Shard each), so keep attackers off them. If all three fail, the ritual ends and you start again; while one stands it survives even a wipe. After about six minutes nine symbols glow and a red vortex closes the circle: walk out and the remaining demons vanish at its edge. Rest, then use the Xorothian Glyphs. Kill the Xorothian Dreadsteed (level 62, elite); at half health Lord Hel'nurath joins, a hard hitter who knocks you back. Speak to the Dreadsteed Spirit: every warlock in the party who is on this quest can bind it.", goals = {
		{ t = "use", map = 1444, x = 60.3, y = 30.2, era = true, item = 18663, itemName = "J'eevee's Jar", note = "J'eevee's Jar, on Immol'thar's dais" },
		{ t = "use", map = 1444, x = 60.3, y = 30.2, era = true, item = 18670, itemName = "Xorothian Glyphs", note = "Xorothian Glyphs, once the circle is complete" },
		{ t = "kill", quest = 7631, title = "Dreadsteed of Xoroth", map = 1444, x = 60.3, y = 30.2, era = true, count = 1, target = "Xorothian Dreadsteed", oi = 1, group = true },
		{ t = "turnin", quest = 7631, title = "Dreadsteed of Xoroth", npc = "Dreadsteed Spirit", map = 1444, x = 60.3, y = 30.2, era = true, note = "Dreadsteed Spirit: Summon Dreadsteed" },
	} },
} end)

Waypost.RegisterSteps("collectibles/mounts/neutral/warlock-felsteed", function() return {
	{ title = "Summon Felsteed (Stormwind)", note = "At 40 Demisette Cloyce, in the cellar of the Slaughtered Lamb in the Mage Quarter, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = {"Human"} }, goals = {
		{ t = "level", level = 40 },
		{ t = "accept", quest = 4488, title = "Summon Felsteed", npc = "Demisette Cloyce", map = 1453, x = 39.24, y = 84.96, qlvl = 40 },
	} },
	{ title = "Summon Felsteed (Ironforge)", note = "At 40 Briarthorn, by the warlock trainers in Ironforge, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = {"Gnome"} }, goals = {
		{ t = "level", level = 40 },
		{ t = "accept", quest = 4487, title = "Summon Felsteed", npc = "Briarthorn", map = 1455, x = 50.35, y = 5.66, era = true, qlvl = 40 },
	} },
	{ title = "Summon Felsteed (Orgrimmar)", note = "At 40 Zevrost, in the Cleft of Shadow, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = {"Orc", "Troll"} }, goals = {
		{ t = "level", level = 40 },
		{ t = "accept", quest = 3631, title = "Summon Felsteed", npc = "Zevrost", map = 1454, x = 48.47, y = 45.43, era = true, qlvl = 40 },
	} },
	{ title = "Summon Felsteed (Undercity)", note = "At 40 Kaal Soulreaper, in the Magic Quarter, sends you to Strahad Farsan in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar; Ratchet is a short flight from Orgrimmar. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", only = { races = {"Scourge"} }, goals = {
		{ t = "level", level = 40 },
		{ t = "accept", quest = 4489, title = "Summon Felsteed", npc = "Kaal Soulreaper", map = 1458, x = 86.21, y = 15.93, era = true, qlvl = 40 },
	} },
	{ title = "Strahad Farsan in Ratchet", note = "Ratchet is the goblin port on the Barrens coast, east of the Crossroads; from the Alliance side take the boat from Booty Bay. Strahad Farsan stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own Summon Felsteed and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing.", goals = {
		{ t = "turnin", quest = 4488, title = "Summon Felsteed", npc = "Strahad Farsan", map = 1413, x = 62.63, y = 35.5, era = true, only = { races = {"Human"} } },
		{ t = "turnin", quest = 4487, title = "Summon Felsteed", npc = "Strahad Farsan", map = 1413, x = 62.63, y = 35.5, era = true, only = { races = {"Gnome"} } },
