Waypost.RegisterSteps("collectibles/pets/baby-crocolisk", function() return {
	{ title = "Sewer Beast", note = "The Sewer Beast is a rare level 50 crocolisk, much tougher than a normal mob of its level. It swims Stormwind's canals and appears at one of six spots, about two hours after it last died; the arrow takes you round them. Below 60, bring a group; at 60, a well-geared character can try it alone. It drops the Baby Crocolisk about once in 70 kills, and the pet binds when picked up, so the Auction House never has it. Horde players can farm it too, but inside an enemy capital.", goals = {
		{ t = "collect", map = 1453, x = 32.4, y = 62.5, era = true, item = 282047, itemName = "Baby Crocolisk", note = "Sewer Beast", spots = "32.4,62.5;49.8,69.8;66.9,57.3;66.4,31.8;49.9,22.2" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/bitter-baitling", function() return {
	{ title = "Riggle Bassbait", note = "The Bitter Baitling costs one Extravagant Extravaganza Coin, the prize for winning the Stranglethorn Fishing Extravaganza. The contest runs on Sundays from 2 to 4 pm server time: be on the Booty Bay docks by Riggle Bassbait when it starts. Master Angler is not a quest you take: Riggle takes the fish straight from his window when you bring them. Bring your best Fishing skill and lures so no fish gets away, a mount and empty bags, and bind your hearthstone in Booty Bay.", goals = {
		{ t = "goto", map = 1434, x = 27.4, y = 76.9, era = true, text = "Riggle Bassbait" },
	} },
	{ title = "Schools of Tastyfish", note = "While the contest runs, schools of Speckled Tastyfish appear along the Stranglethorn coast, none inside Booty Bay. Fish 40 Speckled Tastyfish from them; each school lasts only a few casts, so ride on to the next as soon as one is gone. The arrow takes you up the west coast north of Booty Bay; more schools lie further north and just south of Booty Bay.", goals = {
		{ t = "collect", map = 1434, x = 24.9, y = 66.2, era = true, count = 40, item = 19807, itemName = "Speckled Tastyfish", spots = "24.9,66.2;23.8,62.5;26.2,58.3;22.9,56.4;26,48.8" },
	} },
	{ title = "Back to Riggle", note = "Hurry back and hand the 40 Tastyfish to Riggle: the first players to do so win, and the winners get the coin with their prize. If you are too late to win, Jang still pays a little gold for every 5 Tastyfish.", goals = {
		{ t = "turnin", quest = 8193, title = "Master Angler", npc = "Riggle Bassbait", map = 1434, x = 27.35, y = 76.88, era = true, qlvl = 60 },
		{ t = "collect", map = 1434, x = 27.4, y = 76.9, era = true, item = 274026, itemName = "Extravagant Extravaganza Coin", note = "The winner's coin, from Riggle" },
	} },
	{ title = "Jang", note = "Jang, Riggle's apprentice, stands beside him on the Booty Bay docks and trades the Bitter Baitling for the coin.", goals = {
		{ t = "vendor", npc = "Jang", map = 1434, x = 26.74, y = 76.35, era = true },
		{ t = "buy", npc = "Jang", map = 1434, x = 26.74, y = 76.35, era = true, item = 276275, itemName = "Bitter Baitling", note = "1 Extravagant Extravaganza Coin" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/condor-hatchling", function() return {
	{ title = "Lord Condar", note = "Lord Condar is a rare level 15-16 condor in south-eastern Loch Modan. He appears at one of four spots, hours after he last died; the arrow takes you round them. He drops the Shaking Egg only about once in 500 kills, so this is a pet for players who pass through Loch Modan often: check his spots each time, and kill him whenever you see him.", goals = {
		{ t = "collect", map = 1432, x = 77.7, y = 74.9, era = true, item = 282637, itemName = "Shaking Egg", spots = "77.7,74.9;74.6,70.8;74.7,66.9;62.6,78.5" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/dark-whelpling", function() return {
	{ title = "Black whelps", note = "The Searing Whelps of the Wyrmbog in southern Dustwallow Marsh (level 42-43) and the Scalding Whelps of eastern Badlands (level 41-43) drop it about once in 900 kills. The waypoint is the Wyrmbog, where the whelps stand thickest; the Badlands whelps are the same grind. The whelpling can be traded, so the Auction House may be quicker.", goals = {
		{ t = "collect", map = 1445, x = 46.9, y = 72.5, era = true, item = 10822, itemName = "Dark Whelpling", mobLevel = 43, note = "The Wyrmbog", spots = "46.9,72.5;45.4,73;44.5,74.7;45,69.2;46.4,77" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/disgusting-oozeling", function() return {
	{ title = "Oozes", note = "Oozes drop the Oozing Bag about once in 20-30 kills; the best are the Vile Slimes, Devouring Oozes and the Large Vile Slime in the ooze field of eastern Western Plaguelands (level 54-57). Open every bag: most hold potions or herbs, and only about one bag in 50 holds the Disgusting Oozeling, so expect over a thousand kills. Both the bags and the pet can be traded: unopened bags on the Auction House are lottery tickets, the pet itself the sure buy.", goals = {
		{ t = "collect", map = 1422, x = 64.9, y = 38.7, era = true, item = 20769, itemName = "Disgusting Oozeling", note = "Open your Oozing Bags" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/flik", function() return {
	{ title = "Flik at the Darkmoon Faire", note = "Flik sells two frogs (1g each) while the Darkmoon Faire is in town; Forever has not shown the Faire yet. In Classic it sets up south of Goldshire in Elwynn Forest one month and near Thunder Bluff in Mulgore the next; go to whichever is up. Flik runs all over the Faire grounds, so look around for him. He carries only one Wood Frog Box at a time and restocks it about every 30 minutes: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goals stay ticked afterwards.", goals = {
		{ t = "vendor", npc = "Flik", map = 1429, x = 41.76, y = 68.1, era = true },
		{ t = "buy", npc = "Flik", map = 1429, x = 41.76, y = 68.1, era = true, item = 11026, itemName = "Tree Frog Box", optional = true, note = "Tree Frog Box, 1g" },
		{ t = "buy", npc = "Flik", map = 1429, x = 41.76, y = 68.1, era = true, item = 11027, itemName = "Wood Frog Box", optional = true, note = "Wood Frog Box, 1g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/green-wing-macaw", function() return {
	{ title = "The Deadmines: Defias Pirates", note = "The Deadmines is a group of five at level 17-26, under Moonbrook: go in at the Moonbrook mine and follow the tunnel down to the instance portal. The Defias Pirates (elite, level 19-20) on and around the ship at the far end drop the macaw about once in 30 kills, so plan on several runs; a character well past the dungeon's level clears it alone. The cage can be traded: look at the Auction House too.", goals = {
		{ t = "goto", map = 1436, x = 42.5, y = 71.7, text = "The Deadmines, in the Moonbrook mine" },
		{ t = "goto", map = 1436, x = 38, y = 77.5, era = true, text = "The Deadmines portal, at the bottom of the mine" },
		{ t = "collect", map = 1436, x = 38, y = 77.5, era = true, item = 8492, itemName = "Parrot Cage (Green Wing Macaw)", group = true, note = "Defias Pirates, on the ship" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/hyacinth-macaw", function() return {
	{ title = "Bloodsail pirates", note = "Every Bloodsail pirate on the Stranglethorn coast (level 39-45) can drop it, but only about once in 5,000 kills; the Swabbies on the ships off the southern tip, about once in 2,500. That is a grind of many hours, so most players kill pirates while doing something else there, or buy the cage on the Auction House. The waypoint is the Swashbucklers' and Warlocks' camp on the Wild Shore, south of Booty Bay. Every pirate kill also lowers your Bloodsail Buccaneers standing.", goals = {
		{ t = "collect", map = 1434, x = 27.2, y = 83, era = true, item = 8494, itemName = "Parrot Cage (Hyacinth Macaw)", mobLevel = 43, note = "Bloodsail camp, the Wild Shore", spots = "27.2,83;29.7,81.1;31,81.1;29.9,87.6;32,79.5" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/lil-timmy", function() return {
	{ title = "Lil Timmy", note = "Lil Timmy sells the White Kitten (60s). He starts at Cathedral Square and walks through the Trade District, Old Town and the Dwarven District before he vanishes near the square again; if he is not around, wait for him at Cathedral Square. By beta reports he carries one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards.", only = { factions = {"Alliance"} }, goals = {
		{ t = "vendor", npc = "Lil Timmy", map = 1453, x = 46.65, y = 55.73 },
		{ t = "buy", npc = "Lil Timmy", map = 1453, x = 46.65, y = 55.73, item = 8489, itemName = "Cat Carrier (White Kitten)", optional = true, note = "Cat Carrier (White Kitten), 60s" },
	} },
	{ title = "Xaphod Bizznox", note = "Horde players buy the White Kitten (60s) from Xaphod Bizznox, a trader new in Forever, at Malaka'jin, the Darkspear camp at the southern tip of Stonetalon Mountains, on the way up from the Barrens. He keeps one kitten at a time: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goal stays ticked afterwards.", only = { factions = {"Horde"} }, goals = {
		{ t = "vendor", npc = "Xaphod Bizznox", map = 1442, x = 71.28, y = 99, era = true },
		{ t = "buy", npc = "Xaphod Bizznox", map = 1442, x = 71.4, y = 99.47, era = true, item = 8489, itemName = "Cat Carrier (White Kitten)", optional = true, note = "Cat Carrier (White Kitten), 60s" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/magus-tirth", function() return {
	{ title = "Magus Tirth", note = "Magus Tirth at the Mirage Raceway, the goblin and gnome racetrack in the Shimmering Flats of south-eastern Thousand Needles, sells the Ancona Chicken (1g) to both sides. The nearest flight paths are Freewind Post (Horde) and Gadgetzan in Tanaris (both sides); from Gadgetzan, ride north into the Shimmering Flats. Each pet item teaches its companion when you use it; the goal stays ticked afterwards.", goals = {
		{ t = "vendor", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true },
		{ t = "buy", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true, item = 11023, itemName = "Ancona Chicken", optional = true, note = "Ancona Chicken, 1g" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/mechanical-chicken", function() return {
	{ title = "OOX-22/FE Distress Beacon in Feralas", note = "Each robot starts with a distress beacon that mobs in its zone drop, about one kill in 40 to 100 in Classic's data. In Feralas the best are the Coast Crawl Snapclaws and Deepseers (levels 43-45) on the Forgotten Coast and the Sprite Dragons (47-48), about 2.5%; ogres, harpies, naga and Grimtotems drop it about 1%. You can loot it from level 40.", goals = {
		{ t = "collect", count = 1, item = 8705, itemName = "OOX-22/FE Distress Beacon" },
	} },
	{ title = "Rescue OOX-22/FE", note = "Right-click the beacon. OOX-22/FE sits in a cave near Feral Scar Vale, among yetis and apes. Its escort runs west along the road to the dock on the Forgotten Coast with three ambushes: three yetis, then three gorillas, then four or five gnolls with a caster. Bring a friend if you are under 47. The robot keeps walking unless it is hit, so stay close; if it will not move, another player has it: wait for it to come back. Its turn-in is in Booty Bay; keep the quest for later.", goals = {
		{ t = "accept", quest = 2766, title = "Find OOX-22/FE!", item = 8705, itemName = "OOX-22/FE Distress Beacon", qlvl = 45 },
		{ t = "turnin", quest = 2766, title = "Find OOX-22/FE!", npc = "Homing Robot OOX-22/FE", map = 1444, x = 53.35, y = 55.7, era = true },
		{ t = "accept", quest = 2767, title = "Rescue OOX-22/FE!", npc = "Homing Robot OOX-22/FE", map = 1444, x = 53.35, y = 55.7, era = true, qlvl = 45, escort = true },
		{ t = "complete", quest = 2767, title = "Rescue OOX-22/FE!", escort = true, note = "Escort OOX-22/FE", objs = {"Escort OOX-22/FE to the dock along the Forgotten Coast"} },
	} },
	{ title = "OOX-17/TN Distress Beacon in Tanaris", note = "Tanaris mobs drop OOX-17/TN's beacon about one kill in 50 to 150. Best: the Treasure Hunting Pirates and Buccaneers on the south shore (44-45) and the Ground Pounders in the north (41-43), about 2%. You can loot it from level 43.", goals = {
		{ t = "collect", count = 1, item = 8623, itemName = "OOX-17/TN Distress Beacon" },
	} },
	{ title = "Rescue OOX-17/TN", note = "OOX-17/TN stands in the hills near the Gaping Chasm in south-east Tanaris. Its escort to Steamwheedle Port has two ambushes: three scorpids near the start, three Wastewander bandits near the end. The robot has about 3,000 health and stops to fight what you attack, so it can tank for a moment while you recover. Its turn-in is in Booty Bay too.", goals = {
		{ t = "accept", quest = 351, title = "Find OOX-17/TN!", item = 8623, itemName = "OOX-17/TN Distress Beacon", qlvl = 48 },
		{ t = "turnin", quest = 351, title = "Find OOX-17/TN!", npc = "Homing Robot OOX-17/TN", map = 1446, x = 60.23, y = 64.72, era = true },
		{ t = "accept", quest = 648, title = "Rescue OOX-17/TN!", npc = "Homing Robot OOX-17/TN", map = 1446, x = 60.23, y = 64.72, era = true, qlvl = 48, escort = true },
		{ t = "complete", quest = 648, title = "Rescue OOX-17/TN!", escort = true, note = "Escort OOX-17/TN", objs = {"Escort OOX-17/TN to Steamwheedle Port"} },
	} },
	{ title = "OOX-09/HL Distress Beacon in the Hinterlands", note = "Most Hinterlands mobs drop OOX-09/HL's beacon about once in 100 kills: Silvermane wolves, owlbeasts, Highvale elves, Witherbark and Vilebranch trolls. You can loot it from level 43.", goals = {
		{ t = "collect", count = 1, item = 8704, itemName = "OOX-09/HL Distress Beacon" },
	} },
	{ title = "Rescue OOX-09/HL", note = "OOX-09/HL waits on the largest island of the lake west of Skulk Rock. Its escort to the shore beyond Overlook Cliff has two ambushes of three: Marauding Owlbeasts, then Vilebranch Ambushers; the robot warns you just before each.", goals = {
		{ t = "accept", quest = 485, title = "Find OOX-09/HL!", item = 8704, itemName = "OOX-09/HL Distress Beacon", qlvl = 48 },
		{ t = "turnin", quest = 485, title = "Find OOX-09/HL!", npc = "Homing Robot OOX-09/HL", map = 1425, x = 49.35, y = 37.66, era = true },
		{ t = "accept", quest = 836, title = "Rescue OOX-09/HL!", npc = "Homing Robot OOX-09/HL", map = 1425, x = 49.35, y = 37.66, era = true, qlvl = 48, escort = true },
		{ t = "complete", quest = 836, title = "Rescue OOX-09/HL!", escort = true, note = "Escort OOX-09/HL", objs = {"Escort OOX-09/HL to the shoreline beyond Overlook Cliff"} },
	} },
	{ title = "Oglethorpe Obnoticus in Booty Bay", note = "Oglethorpe Obnoticus is in Booty Bay, upstairs in the building north of the inn, above First Mate Crazz. Hand in all three rescues; at level 45 he then offers An OOX of Your Own, which you turn straight back in for the Mechanical Chicken.", goals = {
		{ t = "turnin", quest = 2767, title = "Rescue OOX-22/FE!", npc = "Oglethorpe Obnoticus", map = 1434, x = 28.36, y = 76.35, era = true },
		{ t = "turnin", quest = 648, title = "Rescue OOX-17/TN!", npc = "Oglethorpe Obnoticus", map = 1434, x = 28.36, y = 76.35, era = true },
		{ t = "turnin", quest = 836, title = "Rescue OOX-09/HL!", npc = "Oglethorpe Obnoticus", map = 1434, x = 28.36, y = 76.35, era = true },
		{ t = "level", level = 45 },
		{ t = "accept", quest = 3721, title = "An OOX of Your Own", npc = "Oglethorpe Obnoticus", map = 1434, x = 28.36, y = 76.35, era = true, qlvl = 50 },
		{ t = "turnin", quest = 3721, title = "An OOX of Your Own", npc = "Oglethorpe Obnoticus", map = 1434, x = 28.36, y = 76.35, era = true },
		{ t = "collect", map = 1434, x = 28.4, y = 76.4, era = true, item = 10398, itemName = "Mechanical Chicken" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/minimule", function() return {
	{ title = "Azeroth Commerce Authority", note = "The Alliance camp is at Three Corners in western Redridge Mountains. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Marcy Baker, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with the Azeroth Commerce Authority. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there.", only = { factions = {"Alliance"} }, goals = {
		{ t = "vendor", npc = "Tamelyn Aldridge", map = 1433, x = 10.6, y = 71.3 },
		{ t = "buy", npc = "Tamelyn Aldridge", map = 1433, x = 10.6, y = 71.3, item = 284664, itemName = "Packmule Treat", note = "1,500 Merchant's Favor" },
	} },
	{ title = "Durotar Supply and Logistics", note = "The Horde camp is just outside the west gate of the Crossroads. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Dokimi, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with Durotar Supply and Logistics. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there. (Another Gishah stands in the Undercity; this is the one at the camp.)", only = { factions = {"Horde"} }, goals = {
		{ t = "vendor", npc = "Gishah", map = 1413, x = 49.4, y = 29.4, era = true },
		{ t = "buy", npc = "Gishah", map = 1413, x = 49.4, y = 29.4, era = true, item = 284664, itemName = "Packmule Treat", note = "1,500 Merchant's Favor" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/musical-gustjumper", function() return {
	{ title = "Skyboat from Dalaran", note = "Zephras Isle is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the north side of Dalaran about every five minutes (another flies from north of Thunder Bluff; either faction may take either).", only = { factions = {"Alliance"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1416, x = 12.5, y = 51.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Skyboat from Thunder Bluff", note = "Zephras Isle is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes (another flies from Dalaran; either faction may take either).", only = { factions = {"Horde"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1412, x = 34.3, y = 25.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Sing to the frogs", note = "From Thendal Village follow the road south, then cut across the field to the top of the waterfall: five frogs sit together on a rock there, by a log. Mobs patrol nearby, so a level 1 character should watch its back. Stand by the rock, target a frog and type /sing. The frogs sing back, the group disappears and one frog hops onto the log beside you: click it to take the Musical Gustjumper, then use it to learn the pet. The item is not bound until you use it, so a friend on the island can sing again and trade you one.", goals = {
		{ t = "collect", map = 2521, x = 51.5, y = 72.1, item = 268109, itemName = "Musical Gustjumper" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/narkk", function() return {
	{ title = "Narkk", note = "Narkk, the pirate supplier in Booty Bay, sells two parrots (40s each), with no stock limit. He stands next to Kelsey Yance, the cook. Booty Bay is neutral: the boat from Ratchet and the Stranglethorn road both arrive there. Each pet item teaches its companion when you use it; the goals stay ticked afterwards.", goals = {
		{ t = "vendor", npc = "Narkk", map = 1434, x = 28.13, y = 74.42, era = true },
		{ t = "buy", npc = "Narkk", map = 1434, x = 28.13, y = 74.42, era = true, item = 8495, itemName = "Parrot Cage (Senegal)", optional = true, note = "Parrot Cage (Senegal), 40s" },
		{ t = "buy", npc = "Narkk", map = 1434, x = 28.13, y = 74.42, era = true, item = 8496, itemName = "Parrot Cage (Cockatiel)", optional = true, note = "Parrot Cage (Cockatiel), 40s" },
	} },
} end)

