Waypost.RegisterSteps("collectibles/pets/siamese-cat", function() return {
	{ title = "The Deadmines: Cookie", note = "The Deadmines is a group of five under Moonbrook: the mine mouth is in Moonbrook, the instance portal deep inside the mine. Cookie, the murloc cook, waits on a small island under the pirate ship at the far end, an optional boss; his cooking heals him, so interrupt it. He drops the Siamese about 15% of the time in Classic's data: expect several runs. The carrier can be traded, so check the Auction House too.", goals = {
		{ t = "goto", map = 1436, x = 42.5, y = 71.7, text = "The Deadmines, in the Moonbrook mine" },
		{ t = "goto", map = 1436, x = 38, y = 77.5, era = true, text = "The Deadmines portal, inside the Moonbrook mine" },
		{ t = "collect", map = 1436, x = 38, y = 77.5, era = true, item = 8490, itemName = "Cat Carrier (Siamese)", group = true, note = "Cookie" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/smolderweb-carrier", function() return {
	{ title = "Kibler at Flame Crest", note = "Kibler stands inside the cave at Flame Crest, the camp in northern Burning Steppes east of Blackrock Mountain. He also gives Kibler's Exotic Pets (the Worg Carrier): take both, they are done in the same run.", goals = {
		{ t = "accept", quest = 4862, title = "En-Ay-Es-Tee-Why", npc = "Kibler", map = 1428, x = 65.89, y = 21.92, era = true, qlvl = 59, group = true },
	} },
	{ title = "Lower Blackrock Spire", note = "Lower Blackrock Spire is a group of five, level 55-60, inside Blackrock Mountain. The Spire Spider Eggs lie around Mother Smolderweb's nest in the Skitterweb Tunnels, the spider halls: click them until you have 15 (each gives one to three). Hard-hitting spiderlings can hatch as you loot. By player reports the eggs cannot be looted in a raid group, so keep the party at five or fewer.", goals = {
		{ t = "collect", quest = 4862, title = "En-Ay-Es-Tee-Why", map = 1428, x = 33.2, y = 24.9, era = true, count = 15, item = 12530, itemName = "Spire Spider Egg", oi = 1, group = true, note = "Lower Blackrock Spire" },
	} },
	{ title = "Back to Kibler", goals = {
		{ t = "turnin", quest = 4862, title = "En-Ay-Es-Tee-Why", npc = "Kibler", map = 1428, x = 65.89, y = 21.92, era = true, group = true },
		{ t = "collect", map = 1428, x = 65.9, y = 21.9, era = true, item = 12529, itemName = "Smolderweb Carrier" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/spectral-bear-cub", function() return {
	{ title = "Innkeeper Wiley in Ratchet", note = "Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, a crafting profession at 150, 225 and 300, PvP ranks and battleground reputations, exploring, dungeons and raids) is worth one, and the track counts points earned, not spent. It gives the Replica Ironforge Air Rifle at 15, the Spectral Bear Cub at 25, the Spectral Bear Tabard at 40 and the Reins of the Spectral Bear at 55. The rewards are claimed as quests from Innkeeper Wiley in the inn at Ratchet, the goblin port on the Barrens coast (Alliance players come by the boat from Booty Bay): with 25 points he offers Legacy Reward: Spectral Bear Cub; hand it straight back for the cub.", goals = {
		{ t = "note", text = "Without PvP one character can earn 17 points: its class at 25, 45 and 60, two professions to 300, the two adventure challenges, the three dungeon tiers and the three raids. A second class or more professions on an alt make up the rest; the Legacy Challenges guide plans them." },
		{ t = "accept", quest = 96383, title = "Legacy Reward: Spectral Bear Cub", npc = "Innkeeper Wiley", map = 1413, x = 62.05, y = 39.41, era = true, qlvl = 60 },
		{ t = "turnin", quest = 96383, title = "Legacy Reward: Spectral Bear Cub", npc = "Innkeeper Wiley", map = 1413, x = 62.05, y = 39.41, era = true },
		{ t = "collect", map = 1413, x = 62, y = 39.4, era = true, item = 277714, itemName = "Spectral Bear Cub" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/tallstrider-hatchling", function() return {
	{ title = "Strider Clutchmother", note = "The Strider Clutchmother is a rare level 20 tallstrider in southern Darkshore, near the Master's Glaive. Kill counts so far give her about 0.6% per kill, roughly one in 170, and in Classic she comes back only every few hours: check her spot whenever you pass, rather than camping. The hatchling binds when you loot it, so it never reaches the Auction House.", goals = {
		{ t = "collect", map = 1439, x = 34.8, y = 87.3, era = true, item = 284176, itemName = "Tallstrider Hatchling" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/tiny-crimson-whelpling", function() return {
	{ title = "Wetlands whelps", note = "The red whelps live in the hills of the eastern Wetlands, towards Grim Batol: about 50 of them, back about five minutes after a kill in Classic's data. Red Whelps (levels 23-24) and Crimson Whelps (25-26) drop the whelpling about once in 650 kills, the Flamesnorting Whelps (26-27) mixed in with them only once in 1,600, so expect a long farm. It can be traded, so the Auction House may be quicker.", goals = {
		{ t = "collect", map = 1437, x = 64.6, y = 42.2, era = true, item = 8499, itemName = "Tiny Crimson Whelpling", mobLevel = 26, note = "Wetlands whelps", spots = "64.6,42.2;65.7,44.5;62,46.7;67.9,45.7;63.2,36.4" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/tiny-emerald-whelpling", function() return {
	{ title = "Dreaming Whelps", note = "The Dreaming Whelps (levels 35-36) live in western Swamp of Sorrows, near the Deadwind Pass border. They drop it about once in 1,250 kills, and there are only a handful, back about every five minutes, so expect days of farming; it can be traded, so the Auction House may be quicker.", goals = {
		{ t = "collect", map = 1435, x = 11.5, y = 62.9, era = true, item = 8498, itemName = "Tiny Emerald Whelpling", note = "Dreaming Whelps", spots = "11.5,62.9;13.6,64.5;12.2,58.5;16.7,56.2" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/weevil-k-neevil", function() return {
	{ title = "My Little Friends", note = "Amaryllis Webb, a Forsaken bug collector, keeps her menagerie in western Swamp of Sorrows. She hands you an Entomology Starter Kit: open it for the tools that catch the three bugs. The bugs are far apart (northern Stranglethorn, Arathi Highlands and Desolace), so do them while you pass. If you lose the kit, she sells another for 50s.", goals = {
		{ t = "accept", quest = 93176, title = "My Little Friends", npc = "Amaryllis Webb", map = 1435, x = 25.1, y = 54.21, era = true, qlvl = 35 },
	} },
	{ title = "Arbor Tarantula in Stranglethorn Vale", note = "The Arbor Tarantulas sit in northern Stranglethorn. Use the kit's tool on one to catch it.", goals = {
		{ t = "collect", map = 1434, x = 43.1, y = 16.7, era = true, item = 213566, itemName = "Arbor Tarantula Specimen" },
	} },
	{ title = "Hay Weevil in Arathi Highlands", note = "The Hay Weevils crawl in the north-west of Arathi Highlands. Use the kit's tool on one.", goals = {
		{ t = "collect", map = 1417, x = 31.9, y = 28.2, era = true, item = 213568, itemName = "Hay Weevil Specimen" },
	} },
	{ title = "Flesh Picker in Desolace", note = "The Flesh Pickers feed in the Kodo Graveyard in the middle of southern Desolace. Use the kit's tool on one.", goals = {
		{ t = "collect", map = 1443, x = 48.1, y = 57.1, era = true, item = 213567, itemName = "Flesh Picker Specimen" },
	} },
	{ title = "Back to Amaryllis Webb", note = "Hand Amaryllis the three specimens: she gives you Weevil K. Neevil and 35s.", goals = {
		{ t = "turnin", quest = 93176, title = "My Little Friends", npc = "Amaryllis Webb", map = 1435, x = 25.1, y = 54.21, era = true },
		{ t = "collect", map = 1435, x = 25, y = 54.1, era = true, item = 280456, itemName = "Weevil K. Neevil" },
	} },
} end)

Waypost.RegisterSteps("collectibles/pets/worg-carrier", function() return {
	{ title = "Kibler at Flame Crest", note = "Kibler stands inside the cave at Flame Crest, the camp in northern Burning Steppes east of Blackrock Mountain. He gives you an Empty Worg Pup Cage. He also gives En-Ay-Es-Tee-Why (the Smolderweb Carrier): take both, they are done in the same run.", goals = {
		{ t = "accept", quest = 4729, title = "Kibler's Exotic Pets", npc = "Kibler", map = 1428, x = 65.89, y = 21.92, era = true, qlvl = 59, group = true },
	} },
	{ title = "Lower Blackrock Spire: Halycon's pups", note = "The pups are in Lower Blackrock Spire (a group of five, level 55-60), not Upper: they run with Halycon, the great worg, deep in the dungeon beyond Urok Doomhowl's ogres. Use the cage on a living Bloodaxe Worg Pup before the pack is dead. Taking damage interrupts the cast, so let the tank hold the pups and cage one from the side. A rogue or druid can sneak in, cage a pup from a corner, then vanish.", goals = {
		{ t = "collect", quest = 4729, title = "Kibler's Exotic Pets", map = 1428, x = 33.2, y = 24.9, era = true, count = 1, item = 12263, itemName = "Caged Worg Pup", oi = 1, group = true, note = "Lower Blackrock Spire" },
	} },
	{ title = "Back to Kibler", goals = {
		{ t = "turnin", quest = 4729, title = "Kibler's Exotic Pets", npc = "Kibler", map = 1428, x = 65.89, y = 21.92, era = true, group = true },
		{ t = "collect", map = 1428, x = 65.9, y = 21.9, era = true, item = 12264, itemName = "Worg Carrier" },
	} },
} end)

