	{ title = "Expert Blacksmithing", note = "Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs Blacksmithing 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Bengus Deepforge (Ironforge); Horde Saru Steelfury (Orgrimmar). The arrow picks the nearest of your faction. Learn now: Green Iron Bracers (from 140) and Heavy Grinding Stone (from 100, 10s). 150-225 takes about 10s of recipes and 28s of vendor goods, plus 234 Heavy Stone, 168 Iron Bar, 195 Steel Bar, 320 Mithril Bar and 30 Solid Stone to gather or buy.", section = 3, goals = {
		{ t = "level", level = 20 },
		{ t = "train" },
		{ t = "learn", spell = 3501, spellName = "Green Iron Bracers" },
		{ t = "learn", spell = 3337, spellName = "Heavy Grinding Stone" },
	} },
	{ title = "Blacksmithing 150-225: vendor goods", note = "Buy the whole bracket's share in one go: 28 Green Dye (28s); about 28s in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra). If you smelt the 195 Steel Bar yourself (Mining 165: an Iron Bar and a Coal each), buy 195 Coal too (9g 75s, trade and blacksmithing suppliers); skip them if you buy the bars.", section = 3, goals = {
		{ t = "buy", count = 28, item = 2605, itemName = "Green Dye" },
		{ t = "buy", count = 195, item = 3857, itemName = "Coal", optional = true },
	} },
	{ title = "Heavy Stone (Alliance)", note = "234 Heavy Stone for Golden Scale Bracers: Mining: Iron Deposit (skill 125) in Arathi Highlands (30-40), Stranglethorn Vale (30-45) and Desolace (30-40); or the Auction House. The densest cluster of Iron Deposit in Arathi Highlands is marked.", only = { factions = {"Alliance"} }, section = 3, goals = {
		{ t = "collect", map = 1417, x = 15.8, y = 63.2, era = true, count = 234, item = 2838, itemName = "Heavy Stone", spots = "15.8,63.2;15.7,67.2;18.5,56.2;16.7,71.2;18.7,71.6" },
	} },
	{ title = "Heavy Stone (Horde)", note = "234 Heavy Stone for Golden Scale Bracers: Mining: Iron Deposit (skill 125) in Thousand Needles (25-35), Arathi Highlands (30-40) and Stranglethorn Vale (30-45); or the Auction House. The densest cluster of Iron Deposit in Thousand Needles is marked.", only = { factions = {"Horde"} }, section = 3, goals = {
		{ t = "collect", map = 1441, x = 8.9, y = 34.3, era = true, count = 234, item = 2838, itemName = "Heavy Stone", spots = "8.9,34.3;12.4,37.7;14.9,34.5;14.3,27.2;12.2,24.3" },
	} },
	{ title = "Solid Stone (Alliance)", note = "30 Solid Stone for Solid Sharpening Stone: Mining: Mithril Deposit (skill 175) in Stranglethorn Vale (30-45), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Stranglethorn Vale is marked.", only = { factions = {"Alliance"} }, section = 3, goals = {
		{ t = "collect", map = 1434, x = 29.4, y = 60.1, era = true, count = 30, item = 7912, itemName = "Solid Stone", spots = "29.4,60.1;27.8,63.4;26.3,63;33,62;31.4,65.3" },
	} },
	{ title = "Solid Stone (Horde)", note = "30 Solid Stone for Solid Sharpening Stone: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = {"Horde"} }, section = 3, goals = {
		{ t = "collect", map = 1443, x = 31.5, y = 59.4, era = true, count = 30, item = 7912, itemName = "Solid Stone" },
	} },
	{ title = "Green Iron Bracers to 175", note = "Green Iron Bracers is orange at 150 (yellow 165, green 177, grey 190): about 28 crafts to 175. Each takes 6 Iron Bar and 1 Green Dye. Six Iron Bars and a Green Dye a craft; Green Dye comes from tailoring, leatherworking and trade supplies vendors. Orange to 165 on Forever, so a point every craft for the first fifteen. Needs an anvil nearby. Iron Bar (168 for 150-225): Mining: smelt Iron Ore; or the Auction House.", section = 3, goals = {
		{ t = "craft", item = 3835, itemName = "Green Iron Bracers", spell = 3501, spellName = "Green Iron Bracers" },
	} },
	{ title = "Blacksmithing recipes at 175", note = "Back to a Blacksmithing trainer: Solid Sharpening Stone (from 175).", section = 3, goals = {
		{ t = "learn", spell = 9918, spellName = "Solid Sharpening Stone" },
	} },
	{ title = "Solid Sharpening Stone to 185", note = "Solid Sharpening Stone is yellow at 175 (yellow 175, green 180, grey 185): about 30 crafts to 185. Each takes 1 Solid Stone. One Solid Stone a craft (Mithril Deposits): cheap points between the iron and the steel bracers. Use the stones on your weapons or sell them.", section = 3, goals = {
		{ t = "craft", item = 7964, itemName = "Solid Sharpening Stone", spell = 9918, spellName = "Solid Sharpening Stone" },
	} },
	{ title = "Blacksmithing recipes at 185", note = "Back to a Blacksmithing trainer: Golden Scale Bracers (from 160).", section = 3, goals = {
		{ t = "learn", spell = 7223, spellName = "Golden Scale Bracers" },
	} },
	{ title = "Golden Scale Bracers to 205", note = "Golden Scale Bracers is yellow at 185 (yellow 185, green 197, grey 210): about 39 crafts to 205. Each takes 5 Steel Bar and 2 Heavy Grinding Stone. Make the 78 Heavy Grinding Stone first. Steel Bars are smelted from an Iron Bar and a Coal (Mining 165; Coal from trade and blacksmithing suppliers), so each bracer is five of each. Each bracer takes two Heavy Grinding Stones: make them first. Specialisation (optional): at 200 and character level 40, Grumnus Steelshaper (Ironforge) or Okothos Ironrager (Orgrimmar) starts The Art of the Armorsmith: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots and an Ornate Mithril Breastplate, whose plans come from a Mithril Order quest chain. Ironus Coldsteel (Ironforge) or Borgosh Corebender (Orgrimmar) starts The Way of the Weaponsmith: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes and 2 Big Black Maces; on Forever the Moonsteel Broadsword plans (Zarena Cromwind, Booty Bay) and Massive Iron Axe plans bind when picked up, so buy and use them yourself. You can take only one; neither is needed for 300, and the beta never tested them (it stopped at level 30). Needs an anvil nearby. Steel Bar (195 for 150-225): Mining: smelt Iron Bar and Coal; or the Auction House.", section = 3, goals = {
		{ t = "craft", count = 78, item = 3486, itemName = "Heavy Grinding Stone", spell = 3337, spellName = "Heavy Grinding Stone" },
		{ t = "craft", item = 6040, itemName = "Golden Scale Bracers", spell = 7223, spellName = "Golden Scale Bracers" },
	} },
	{ title = "Blacksmithing recipes at 205", note = "Back to a Blacksmithing trainer: Heavy Mithril Breastplate (from 205).", section = 3, goals = {
		{ t = "learn", spell = 9959, spellName = "Heavy Mithril Breastplate" },
	} },
	{ title = "Heavy Mithril Breastplate to 225", note = "Heavy Mithril Breastplate is orange at 205 (yellow 225, green 235, grey 245): about 20 crafts to 225, a point every craft. Each takes 16 Mithril Bar. Sixteen Mithril Bars a craft and nothing else; orange to 225 on Forever, so a point every craft to the Artisan cap. Needs an anvil nearby. Mithril Bar (320 for 150-225): Mining: smelt Mithril Ore; or the Auction House. Blacksmithing 225 is a Legacy System milestone.", section = 3, goals = {
		{ t = "craft", item = 7930, itemName = "Heavy Mithril Breastplate", spell = 9959, spellName = "Heavy Mithril Breastplate" },
		{ t = "skill", level = 225, skillName = "Blacksmithing" },
	} },
	{ title = "Artisan Blacksmithing", note = "Artisan raises the cap from 225 to 300 for 5g (Classic's price; Forever's is not in the data); it needs Blacksmithing 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance Brikk Keencraft (Stranglethorn Vale); Horde Brikk Keencraft (Stranglethorn Vale). The arrow picks the nearest of your faction. Learn now: Dense Weightstone (from 225), Heavy Mithril Boots (from 210), Solid Grinding Stone (from 175), Big Black Mace (from 205) and Dense Grinding Stone (from 225). 225-300 takes about 3g 60s of recipes, plus 44 Shadowgem, 596 Mithril Bar, 142 Thick Leather, 19 Aquamarine, 19 Star Ruby, 44 Solid Stone, 11 Black Pearl, 206 Rugged Leather, 2026 Thorium Bar, 801 Dense Stone and 10 Large Opal to gather or buy.", section = 4, goals = {
		{ t = "level", level = 35 },
		{ t = "train" },
		{ t = "learn", spell = 16640, spellName = "Dense Weightstone" },
		{ t = "learn", spell = 9968, spellName = "Heavy Mithril Boots" },
		{ t = "learn", spell = 9920, spellName = "Solid Grinding Stone" },
		{ t = "learn", spell = 10001, spellName = "Big Black Mace" },
		{ t = "learn", spell = 16639, spellName = "Dense Grinding Stone" },
	} },
	{ title = "Plans: Ornate Thorium Handaxe", note = "Plans: Ornate Thorium Handaxe teaches Ornate Thorium Handaxe (Blacksmithing 250) for 1g 60s. Sold by Magnus Frostwake (Western Plaguelands).", section = 4, goals = {
		{ t = "buy", item = 12819, itemName = "Plans: Ornate Thorium Handaxe" },
	} },
	{ title = "Plans: Huge Thorium Battleaxe", note = "Plans: Huge Thorium Battleaxe teaches Huge Thorium Battleaxe (Blacksmithing 255) for 2g. Sold by Magnus Frostwake (Western Plaguelands).", section = 4, goals = {
		{ t = "buy", item = 12823, itemName = "Plans: Huge Thorium Battleaxe" },
	} },
	{ title = "Thick Leather (Alliance)", note = "142 Thick Leather for Heavy Mithril Boots and Big Black Mace: Skinning: beasts of level 38-50; or the Auction House. Skin Elder Crag Coyote, Rabid Crag Coyote, Ridge Huntress and Ridge Stalker Patriarch here (level 38-50); the Skinning guide routes this.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1418, x = 35, y = 64.3, era = true, count = 142, item = 4304, itemName = "Thick Leather" },
	} },
	{ title = "Thick Leather (Horde)", note = "142 Thick Leather for Heavy Mithril Boots and Big Black Mace: Skinning: beasts of level 38-50; or the Auction House. Skin Feral Scar Yeti, Frayfeather Hippogryph, Frayfeather Stagwing, Grizzled Ironfur Bear, Groddoc Ape, Groddoc Thunderer, Ironfur Bear, Ironfur Patriarch, Longtooth Howler, Longtooth Runner and Rage Scar Yeti here (level 38-50); the Skinning guide routes this.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1444, x = 54.9, y = 60.8, era = true, count = 142, item = 4304, itemName = "Thick Leather" },
	} },
	{ title = "Solid Stone (Alliance)", note = "44 Solid Stone for Big Black Mace: Mining: Mithril Deposit (skill 175) in The Hinterlands (40-50), Feralas (40-50) and Azshara (45-55); or the Auction House. The densest cluster of Mithril Deposit in The Hinterlands is marked.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1425, x = 20.8, y = 58.8, era = true, count = 44, item = 7912, itemName = "Solid Stone", spots = "20.8,58.8;23.3,59.8;24.7,66.6;28,58.9;27.3,69.3" },
	} },
	{ title = "Solid Stone (Horde)", note = "44 Solid Stone for Big Black Mace: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1443, x = 31.5, y = 59.4, era = true, count = 44, item = 7912, itemName = "Solid Stone" },
	} },
	{ title = "Rugged Leather (Alliance)", note = "206 Rugged Leather for Ornate Thorium Handaxe and Huge Thorium Battleaxe: Skinning: beasts of level 48-60; or the Auction House. Skin Frenzied Plaguehound, Plaguehound and Plaguehound Runt here (level 48-60); the Skinning guide routes this.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1423, x = 56, y = 46.8, count = 206, item = 8170, itemName = "Rugged Leather" },
	} },
	{ title = "Rugged Leather (Horde)", note = "206 Rugged Leather for Ornate Thorium Handaxe and Huge Thorium Battleaxe: Skinning: beasts of level 48-60; or the Auction House. Skin Coralshell Tortoise, Mosshoof Stag, Thunderhead Consort, Thunderhead Patriarch, Thunderhead Skystormer and Thunderhead Stagwing here (level 48-60); the Skinning guide routes this.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1447, x = 58.8, y = 21.5, era = true, count = 206, item = 8170, itemName = "Rugged Leather" },
	} },
	{ title = "Dense Stone (Alliance)", note = "801 Dense Stone for Dense Weightstone, Ornate Thorium Handaxe and Huge Thorium Battleaxe: Mining: Small Thorium Vein (skill 245) in Blasted Lands (45-55), Felwood (48-55) and Winterspring (55-60); or the Auction House. The densest cluster of Small Thorium Vein in Blasted Lands is marked.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1419, x = 43.5, y = 30.8, era = true, count = 801, item = 12365, itemName = "Dense Stone", spots = "43.5,30.8;46,29.3;41.9,37.1;42.1,24.2;38.9,28.9" },
	} },
	{ title = "Dense Stone (Horde)", note = "801 Dense Stone for Dense Weightstone, Ornate Thorium Handaxe and Huge Thorium Battleaxe: Mining: Small Thorium Vein (skill 245) in Felwood (48-55), Silithus (55-60) and Winterspring (55-60); or the Auction House. The densest cluster of Small Thorium Vein in Felwood is marked.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1448, x = 34.7, y = 61.8, era = true, count = 801, item = 12365, itemName = "Dense Stone", spots = "34.7,61.8;36.3,55.4;36.2,68.9;38.2,45.7;43.2,46.7" },
	} },
	{ title = "Dense Weightstone to 235", note = "Dense Weightstone is orange at 225 (yellow 230, green 232, grey 235): about 17 crafts to 235. Each takes 1 Dense Stone. One Dense Stone a craft (Thorium veins): cheap points at the start of Artisan.", section = 4, goals = {
		{ t = "craft", item = 12643, itemName = "Dense Weightstone", spell = 16640, spellName = "Dense Weightstone" },
	} },
	{ title = "Heavy Mithril Boots to 247", note = "Heavy Mithril Boots is yellow at 235 (yellow 230, green 240, grey 250): about 30 crafts to 247. Each takes 14 Mithril Bar and 4 Thick Leather. Mithril Bars from Mithril Deposits; Thick Leather from skinners or the Auction House. Needs an anvil nearby. Mithril Bar (596 for 225-300): Mining: smelt Mithril Ore; or the Auction House.", section = 4, goals = {
		{ t = "craft", item = 7933, itemName = "Heavy Mithril Boots", spell = 9968, spellName = "Heavy Mithril Boots" },
	} },
	{ title = "Big Black Mace to 250", note = "Big Black Mace is green at 247 (yellow 230, green 242, grey 255): about 11 crafts to 250. Each takes 16 Mithril Bar, 1 Black Pearl, 4 Shadowgem, 1 Solid Grinding Stone and 2 Thick Leather. Make the 11 Solid Grinding Stone first. Only about 11 crafts to bridge 247-250, but each wants four Shadowgems (about one Tin Vein in a hundred) and a Black Pearl: buy those at the Auction House unless your bags already hold them. Needs an anvil nearby. Shadowgem (44 for 225-300): Shadowgem turns up in about one Copper Vein, Tin Vein or Silver Vein in 100: buy it at the Auction House, or keep the ones you find while mining. Black Pearl (11 for 225-300): Black Pearl is a rare drop (no mob gives it one time in 50): buy it at the Auction House, or keep the ones you find.", section = 4, goals = {
		{ t = "craft", count = 11, item = 7966, itemName = "Solid Grinding Stone", spell = 9920, spellName = "Solid Grinding Stone" },
		{ t = "craft", item = 7945, itemName = "Big Black Mace", spell = 10001, spellName = "Big Black Mace" },
	} },
	{ title = "Ornate Thorium Handaxe to 255", note = "Ornate Thorium Handaxe is orange at 250 (yellow 275, green 287, grey 300): about 5 crafts to 255, a point every craft. Each takes 20 Thorium Bar, 2 Large Opal, 2 Dense Grinding Stone and 4 Rugged Leather. Make the 10 Dense Grinding Stone first. Large Opal turns up in about one Thorium vein in 130: buy the ten at the Auction House. Five crafts only, until the battleaxe plans can be used at 255. Needs an anvil nearby. Thorium Bar (2026 for 225-300): Mining: smelt Thorium Ore; or the Auction House. Large Opal (10 for 225-300): Large Opal turns up in about one Rich Thorium Vein, Ooze Covered Rich Thorium Vein or Hakkari Thorium Vein in 143: buy it at the Auction House, or keep the ones you find while mining.", section = 4, goals = {
		{ t = "learn", item = 12819, itemName = "Plans: Ornate Thorium Handaxe", spell = 16969, spellName = "Ornate Thorium Handaxe", note = "from the recipe in your bags" },
		{ t = "craft", count = 10, item = 12644, itemName = "Dense Grinding Stone", spell = 16639, spellName = "Dense Grinding Stone" },
		{ t = "craft", item = 12773, itemName = "Ornate Thorium Handaxe", spell = 16969, spellName = "Ornate Thorium Handaxe" },
	} },
	{ title = "Huge Thorium Battleaxe to 285", note = "Huge Thorium Battleaxe is orange at 255 (yellow 280, green 292, grey 305): about 31 crafts to 285. Each takes 40 Thorium Bar, 6 Dense Grinding Stone and 6 Rugged Leather. Make the 186 Dense Grinding Stone first. Plans from Magnus Frostwake (Caer Darrow, Western Plaguelands), unlimited stock, but they bind when picked up. Forty Thorium Bars and six Dense Grinding Stones a craft: the dearest stretch, so stop where the Imperial Plate Boots take over. Other ways through: world-drop plans from the Auction House (the Radiant pieces: about 820 Thorium Bars and 190 Hearts of Fire for the Radiant route) or the Merchant's Favor sets. Needs an anvil nearby.", section = 4, goals = {
		{ t = "learn", item = 12823, itemName = "Plans: Huge Thorium Battleaxe", spell = 16971, spellName = "Huge Thorium Battleaxe", note = "from the recipe in your bags" },
		{ t = "craft", count = 186, item = 12644, itemName = "Dense Grinding Stone", spell = 16639, spellName = "Dense Grinding Stone" },
		{ t = "craft", item = 12775, itemName = "Huge Thorium Battleaxe", spell = 16971, spellName = "Huge Thorium Battleaxe" },
	} },
	{ title = "Plans: Imperial Plate Boots", note = "Derotain Mudsipper (Tanaris) trades Plans: Imperial Plate Boots (Blacksmithing 270) for 40 Thorium Bar in Imperial Plate Boots, which needs Blacksmithing 265 and character level 50; take A Blue Light Bargain first (it asks for nothing). The plans bind when picked up.", section = 4, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 7652, title = "A Blue Light Bargain", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60 },
		{ t = "turnin", quest = 7652, title = "A Blue Light Bargain", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265 },
		{ t = "accept", quest = 7654, title = "Imperial Plate Boots", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60 },
		{ t = "turnin", quest = 7654, title = "Imperial Plate Boots", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265 },
	} },
	{ title = "Imperial Plate Boots to 300", note = "Imperial Plate Boots is orange at 285 (yellow 290, green 300, grey 310): about 19 crafts to 300. Each takes 34 Thorium Bar, 1 Star Ruby and 1 Aquamarine. About 34 Thorium Bars a craft against the battleaxe's 40 and its grinding stones, orange to 290. Below character level 50 Derotain has no quest for you: keep making Huge Thorium Battleaxes to 300 instead (yellow to 292, grey at 305: about twice the Thorium Bars). Needs an anvil nearby. Aquamarine (19 for 225-300): Aquamarine turns up in about one Truesilver Deposit or Ooze Covered Truesilver Deposit in 500: buy it at the Auction House, or keep the ones you find while mining. Star Ruby (19 for 225-300): Star Ruby turns up in about one Truesilver Deposit or Ooze Covered Truesilver Deposit in 143: buy it at the Auction House, or keep the ones you find while mining. Blacksmithing 300 is a Legacy System milestone.", section = 4, goals = {
		{ t = "learn", item = 12700, itemName = "Plans: Imperial Plate Boots", spell = 16657, spellName = "Imperial Plate Boots", note = "from the recipe in your bags" },
		{ t = "craft", item = 12426, itemName = "Imperial Plate Boots", spell = 16657, spellName = "Imperial Plate Boots" },
		{ t = "skill", level = 300, skillName = "Blacksmithing" },
	} },
} end)

Waypost.RegisterSteps("professions/cooking", function() return {
	{ title = "Learn Cooking", note = "Any Cooking trainer of your faction teaches Apprentice Cooking (any character level, 1s); the arrow picks the nearest. Forever: every cook knows Basic Campfire. Craft a Basic Campfire Kit from one Simple Wood (38c) with Flint and Tinder (1s 35c, kept in your bags), then place the kit to light a cooking fire anywhere; make a few in advance (one use every 5 minutes). The first kits also raise Cooking to about 5. The Camping 101: Cooking quest at your starting area's camp sends you to this trainer.", section = 1, goals = {
		{ t = "train" },
	} },
	{ title = "Charred Wolf Meat: ingredients", only = { races = {"Human"} }, section = 1, goals = {
		{ t = "collect", count = 50, item = 2672, itemName = "Stringy Wolf Meat", note = "Prowler (86%) in Elwynn Forest, or wherever the arrow points" },
	} },
	{ title = "Charred Wolf Meat (1-50)", note = "Charred Wolf Meat is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own Basic Campfire.", only = { races = {"Human"} }, section = 1, goals = {
		{ t = "craft", item = 2679, itemName = "Charred Wolf Meat", spell = 2538, spellName = "Charred Wolf Meat" },
	} },
	{ title = "Roasted Boar Meat: ingredients", only = { races = {"Dwarf", "Gnome"} }, section = 1, goals = {
		{ t = "collect", count = 50, item = 769, itemName = "Chunk of Boar Meat", note = "Large Crag Boar (36%), Crag Boar (34%) in Dun Morogh, or wherever the arrow points" },
	} },
	{ title = "Roasted Boar Meat (1-50)", note = "Roasted Boar Meat is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own Basic Campfire.", only = { races = {"Dwarf", "Gnome"} }, section = 1, goals = {
		{ t = "craft", item = 2681, itemName = "Roasted Boar Meat", spell = 2540, spellName = "Roasted Boar Meat" },
	} },
	{ title = "Herb Baked Egg: shopping", note = "The arrow picks the nearest vendor of your faction for each item. You need 50 Mild Spices (1s).", only = { races = {"NightElf"} }, section = 1, goals = {
		{ t = "buy", count = 50, item = 2678, itemName = "Mild Spices" },
	} },
	{ title = "Herb Baked Egg: ingredients", only = { races = {"NightElf"} }, section = 1, goals = {
		{ t = "collect", count = 50, item = 6889, itemName = "Small Egg", note = "Strigid Owl (58%) in Teldrassil, or wherever the arrow points" },
	} },
	{ title = "Herb Baked Egg (1-50)", note = "Herb Baked Egg is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own Basic Campfire. Herb Baked Egg comes with Cooking (the client teaches it with the skill); Mild Spices are a cooking vendor's. The Strigid owls of Teldrassil drop a Small Egg more often than not, and Darkshore's moonkin drop them too. Fishers can cook Brilliant Smallfish (recipe 40c) from Rut'theran's waters instead, and Zarrin in Dolanaar gives Recipe of the Kaldorei (seven Small Spider Legs from the Webwood spiders) for Kaldorei Spider Kabob, orange from 10 to 50.", only = { races = {"NightElf"} }, section = 1, goals = {
		{ t = "craft", item = 6888, itemName = "Herb Baked Egg", spell = 8604, spellName = "Herb Baked Egg" },
	} },
	{ title = "Charred Wolf Meat: ingredients", only = { races = {"Skyborne"} }, section = 1, goals = {
		{ t = "collect", count = 50, item = 2672, itemName = "Stringy Wolf Meat", note = "Juvenile Vuldren in Zephras Isle, or wherever the arrow points" },
	} },
	{ title = "Charred Wolf Meat (1-50)", note = "Charred Wolf Meat is orange from 1 (yellow at 45, green at 65, grey at 85): about 50 crafts to 50. Cook at any fire: a town hearth or your own Basic Campfire. The Vuldren of Zephras Isle drop Stringy Wolf Meat.", only = { races = {"Skyborne"} }, section = 1, goals = {
		{ t = "craft", item = 2679, itemName = "Charred Wolf Meat", spell = 2538, spellName = "Charred Wolf Meat" },
	} },
	{ title = "Roasted Boar Meat: ingredients", only = { races = {"Orc", "Troll"} }, section = 1, goals = {
		{ t = "collect", count = 50, item = 769, itemName = "Chunk of Boar Meat", note = "Dire Mottled Boar (99%) in Durotar, or wherever the arrow points" },
