	{ title = "Roast Raptor: ingredients", section = 4, goals = {
		{ t = "collect", count = 52, item = 12184, itemName = "Raptor Flesh", note = "Highland Thrasher (38%) in Arathi Highlands, or wherever the arrow points" },
	} },
	{ title = "Roast Raptor (175-225)", note = "Roast Raptor is orange from 175 (yellow at 215, green at 235, grey at 255): about 52 crafts to 225. Cook at any fire: a town hearth or your own Basic Campfire. Recipe: Roast Raptor costs 50s at its vendor; the arrow picks the nearest one of your faction. Arathi Highlands: Hammon Karwn at Refuge Pointe (Alliance) and Keena at Hammerfall (Horde) sell the recipe and Hot Spices beside the raptors. Spider Sausage (any trainer from 200, 40s) is the alternative, but it takes two White Spider Meat a craft and Dustwallow's spiders drop one about two kills in five.", section = 4, goals = {
		{ t = "learn", item = 12228, itemName = "Recipe: Roast Raptor", spell = 15855, spellName = "Roast Raptor" },
		{ t = "craft", item = 12210, itemName = "Roast Raptor", spell = 15855, spellName = "Roast Raptor" },
	} },
	{ title = "Dirge Quikcleave", note = "Artisan Cooking comes from Dirge Quikcleave in Gadgetzan (Tanaris). The cooking trainer in Ironforge sends you; it needs skill 225 and level 35.", only = { factions = {"Alliance"} }, section = 5, goals = {
