		{ t = "accept", quest = 6610, title = "Clamlette Surprise", npc = "Dirge Quikcleave", map = 1446, x = 52.63, y = 28.11, era = true, skillName = "Cooking", skillRank = 225, qlvl = 45 },
		{ t = "turnin", quest = 6610, title = "Clamlette Surprise", npc = "Dirge Quikcleave", map = 1446, x = 52.63, y = 28.11, era = true, skillName = "Cooking", skillRank = 225, note = "Artisan Cooking" },
