	{ title = "Monster Omelet: ingredients", section = 5, goals = {
		{ t = "collect", count = 120, item = 12207, itemName = "Giant Egg", note = "Savage Owlbeast (54%) in The Hinterlands, or wherever the arrow points" },
	} },
	{ title = "Monster Omelet (225-300)", note = "Monster Omelet is orange from 225 (yellow at 265, green at 285, grey at 305): about 120 crafts to 300. Cook at any fire: a town hearth or your own Basic Campfire. Recipe: Monster Omelet costs 1g 20s at its vendor; the arrow picks the nearest one of your faction. Monster Omelet is orange to 265 and green from 285, yet it still carries you to 300. Fishers can finish on Nightfin Soup (Gikkix, Steamwheedle Port; yellow to 310) instead; Poached Sunscale Salmon needs an Iron Oven on Forever.", section = 5, goals = {
		{ t = "learn", item = 16110, itemName = "Recipe: Monster Omelet", spell = 15933, spellName = "Monster Omelet" },
