	{ title = "Heavy Stone (Arathi Highlands)", note = "27 Heavy Stone for Heavy Blasting Powder: Mining: Iron Deposit (skill 125); or the Auction House. The densest cluster of Iron Deposit in Arathi Highlands is marked.", only = { races = {"Scourge"} }, section = 2, goals = {
		{ t = "collect", map = 1417, x = 15.8, y = 63.2, era = true, count = 27, item = 2838, itemName = "Heavy Stone", spots = "15.8,63.2;15.7,67.2;18.5,56.2;16.7,71.2;18.7,71.6" },
	} },
	{ title = "Crafted Heavy Shot to 94", note = "Crafted Heavy Shot is orange at 75 (yellow 85, green 90, grey 95): about 15 crafts to 94. Each takes 1 Coarse Blasting Powder and 1 Copper Bar and makes 200. Make the 15 Coarse Blasting Powder first: it gives points too while not grey. The Coarse Blasting Powder in each gives its own point while it is not grey: two chances a craft. Sell the shot to hunters or a vendor. Copper Bar (72 for 75-150): Mining: smelt Copper Ore; or the Auction House.", section = 2, goals = {
		{ t = "craft", count = 15, item = 4364, itemName = "Coarse Blasting Powder", spell = 3929, spellName = "Coarse Blasting Powder" },
		{ t = "craft", item = 8068, itemName = "Crafted Heavy Shot", spell = 3930, spellName = "Crafted Heavy Shot" },
	} },
	{ title = "Copper Tube to 100", note = "Copper Tube is yellow at 94 (yellow 80, green 95, grey 110): about 14 crafts to 100. Each takes 2 Copper Bar and 1 Weak Flux. Two Copper Bars and a Weak Flux a craft (blacksmithing and engineering suppliers). Needs an anvil nearby.", section = 2, goals = {
		{ t = "craft", item = 4361, itemName = "Copper Tube", spell = 3924, spellName = "Copper Tube" },
	} },
	{ title = "Engineering recipes at 100", note = "Back to an Engineering trainer: Practice Lock (from 100).", section = 2, goals = {
		{ t = "learn", spell = 8334, spellName = "Practice Lock" },
	} },
	{ title = "Practice Lock to 125", note = "Practice Lock is orange at 100 (yellow 115, green 122, grey 130): about 31 crafts to 125. Each takes 1 Bronze Bar, 2 Handful of Copper Bolts and 1 Weak Flux. Make the 29 Handful of Copper Bolts first. Use the 33 Handful of Copper Bolts you made earlier; the counts above leave them out. Practice Locks sell to rogues, or open them yourself. Needs an anvil nearby. Bronze Bar (61 for 75-150): Mining: smelt Copper Bar and Tin Bar; or the Auction House.", section = 2, goals = {
		{ t = "craft", count = 29, item = 4359, itemName = "Handful of Copper Bolts", spell = 3922, spellName = "Handful of Copper Bolts" },
		{ t = "craft", item = 6712, itemName = "Practice Lock", spell = 8334, spellName = "Practice Lock" },
	} },
	{ title = "Engineering recipes at 125", note = "Back to an Engineering trainer: Heavy Blasting Powder (from 125).", section = 2, goals = {
		{ t = "learn", spell = 3945, spellName = "Heavy Blasting Powder" },
	} },
	{ title = "Heavy Blasting Powder to 140", note = "Heavy Blasting Powder is yellow at 125 (yellow 125, green 135, grey 145): about 27 crafts to 140. Each takes 1 Heavy Stone. One Heavy Stone a craft (Iron Deposits). Keep some: Iron Grenades take one each.", section = 2, goals = {
		{ t = "craft", item = 4377, itemName = "Heavy Blasting Powder", spell = 3945, spellName = "Heavy Blasting Powder" },
	} },
	{ title = "Engineering recipes at 140", note = "Back to an Engineering trainer: Silver Contact (from 90) and Big Bronze Bomb (from 140).", section = 2, goals = {
		{ t = "learn", spell = 3973, spellName = "Silver Contact" },
		{ t = "learn", spell = 3950, spellName = "Big Bronze Bomb" },
	} },
	{ title = "Big Bronze Bomb to 150", note = "Big Bronze Bomb is yellow at 140 (yellow 140, green 165, grey 190): about 10 crafts to 150. Each takes 2 Heavy Blasting Powder, 3 Bronze Bar and 1 Silver Contact and makes 3. Make the 10 Silver Contact (2 crafts) first. Use the 20 Heavy Blasting Powder you made earlier; the counts above leave them out. The trainer teaches it, and it is the cheapest way through these points in the data. Needs an anvil nearby. Silver Bar (2 for 75-150): Mining: smelt Silver Ore; or the Auction House. Engineering 150 is a Legacy System milestone.", section = 2, goals = {
		{ t = "craft", count = 10, item = 4404, itemName = "Silver Contact", spell = 3973, spellName = "Silver Contact" },
		{ t = "craft", item = 4380, itemName = "Big Bronze Bomb", spell = 3950, spellName = "Big Bronze Bomb" },
		{ t = "skill", level = 150, skillName = "Engineering" },
	} },
	{ title = "Expert Engineering", note = "Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs Engineering 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Springspindle Fizzlegear (Ironforge); Horde Roxxik (Orgrimmar). The arrow picks the nearest of your faction. Learn now: Aquadynamic Fish Attractor (from 150) and Bronze Framework (from 145). 150-225 takes about 31s of vendor goods, plus 19 Medium Leather, 19 Wool Cloth, 31 Coarse Stone, 74 Heavy Stone, 100 Bronze Bar, 6 Silver Bar, 81 Iron Bar, 19 Mithril Bar and 62 Solid Stone to gather or buy.", section = 3, goals = {
		{ t = "level", level = 20 },
		{ t = "train" },
		{ t = "learn", spell = 9271, spellName = "Aquadynamic Fish Attractor" },
		{ t = "learn", spell = 3953, spellName = "Bronze Framework" },
	} },
	{ title = "Engineering 150-225: vendor goods", note = "Buy the whole bracket's share in one go: 31 Nightcrawlers (31s); about 31s in all. The arrow picks the nearest seller of your faction (Stormwind City: Catherine Leland and Edna Mullby; Orgrimmar: Felika, Shankys and Shimra).", section = 3, goals = {
		{ t = "buy", count = 31, item = 6530, itemName = "Nightcrawlers" },
	} },
	{ title = "Medium Leather (Alliance)", note = "19 Medium Leather for Bronze Framework: Skinning: beasts of level 18-30; or the Auction House. Skin Cave Yeti, Elder Gray Bear, Feral Mountain Lion, Gray Bear, Snapjaw, Starving Mountain Lion and Vicious Gray Bear here (level 18-30); the Skinning guide routes this.", only = { factions = {"Alliance"} }, section = 3, goals = {
		{ t = "collect", map = 1424, x = 45.4, y = 34.9, era = true, count = 19, item = 2319, itemName = "Medium Leather" },
	} },
	{ title = "Medium Leather (Horde)", note = "19 Medium Leather for Bronze Framework: Skinning: beasts of level 18-30; or the Auction House. Skin Ashenvale Bear, Elder Ashenvale Bear, Elder Shadowhorn Stag, Ghostpaw Runner, Giant Ashenvale Bear and Shadowhorn Stag here (level 18-30); the Skinning guide routes this.", only = { factions = {"Horde"} }, section = 3, goals = {
		{ t = "collect", map = 1440, x = 68.7, y = 50.2, era = true, count = 19, item = 2319, itemName = "Medium Leather" },
	} },
	{ title = "Wool Cloth", note = "19 Wool Cloth for Bronze Framework: humanoids of level 15-30 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 3, goals = {
		{ t = "collect", count = 19, item = 2592, itemName = "Wool Cloth" },
	} },
	{ title = "Coarse Stone (Alliance)", note = "31 Coarse Stone for Aquadynamic Fish Attractor: Mining: Tin Vein (skill 65) in Loch Modan (10-20), Ashenvale (18-30) and Hillsbrad Foothills (20-30); or the Auction House. The densest cluster of Tin Vein in Loch Modan is marked.", only = { factions = {"Alliance"} }, section = 3, goals = {
