	{ title = "Engineering recipes at 175", note = "Back to an Engineering trainer: Solid Blasting Powder (from 175).", section = 3, goals = {
		{ t = "learn", spell = 12585, spellName = "Solid Blasting Powder" },
	} },
	{ title = "Solid Blasting Powder to 191", note = "Solid Blasting Powder is yellow at 175 (yellow 175, green 185, grey 195): about 31 crafts to 191. Each takes 2 Solid Stone. Two Solid Stone a craft (Mithril Deposits). Make plenty: the triggers, slugs and Gyro-Shot all use it.", section = 3, goals = {
		{ t = "craft", item = 10505, itemName = "Solid Blasting Powder", spell = 12585, spellName = "Solid Blasting Powder" },
	} },
	{ title = "Engineering recipes at 191", note = "Back to an Engineering trainer: Big Iron Bomb (from 190).", section = 3, goals = {
		{ t = "learn", spell = 3967, spellName = "Big Iron Bomb" },
	} },
	{ title = "Big Iron Bomb to 210", note = "Big Iron Bomb is yellow at 191 (yellow 190, green 210, grey 230): about 27 crafts to 210. Each takes 3 Iron Bar, 3 Heavy Blasting Powder and 1 Silver Contact and makes 2. Make the 74 Heavy Blasting Powder and 30 Silver Contact (6 crafts) first. Use the 7 Heavy Blasting Powder you made earlier; the counts above leave them out. A Silver Bar makes five Silver Contacts (grey by now: no points, but no trip to a vendor either); the Heavy Blasting Powder comes from Heavy Stone. Each craft makes two bombs. Specialisation (optional): at 200 and character level 30, Springspindle Fizzlegear (Ironforge), Lilliam Sparkspindle (Stormwind), Graham Van Talen (Undercity) or Tinkerwiz (Ratchet) sends you to Gnomish Engineering (Tinkmaster Overspark, Ironforge, or Oglethorpe Obnoticus, Booty Bay: 6 Mithril Tubes, an Accurate Scope and 2 Advanced Target Dummies) or Goblin Engineering (Nixx Sprocketspring, Gadgetzan: 20 Big Iron Bombs, 20 Solid Dynamite and 5 Explosive Sheep). The Accurate Scope schematic now binds when picked up, but the quest takes a scope someone else made. The membership card lasts 14 days of play; renewing it costs 2g. You can take only one; neither is needed for 300, and the beta never tested them (it stopped at level 30). Needs an anvil nearby. Silver Bar (6 for 150-225): Mining: smelt Silver Ore; or the Auction House. Iron Bar (81 for 150-225): Mining: smelt Iron Ore; or the Auction House.", section = 3, goals = {
		{ t = "craft", count = 74, item = 4377, itemName = "Heavy Blasting Powder", spell = 3945, spellName = "Heavy Blasting Powder" },
		{ t = "craft", count = 30, item = 4404, itemName = "Silver Contact", spell = 3973, spellName = "Silver Contact" },
		{ t = "craft", item = 4394, itemName = "Big Iron Bomb", spell = 3967, spellName = "Big Iron Bomb" },
	} },
	{ title = "Engineering recipes at 210", note = "Back to an Engineering trainer: Hi-Impact Mithril Slugs (from 210).", section = 3, goals = {
		{ t = "learn", spell = 12596, spellName = "Hi-Impact Mithril Slugs" },
	} },
	{ title = "Hi-Impact Mithril Slugs to 225", note = "Hi-Impact Mithril Slugs is yellow at 210 (yellow 210, green 230, grey 250): about 19 crafts to 225. Each takes 1 Mithril Bar and 1 Solid Blasting Powder and makes 200. Use the 19 Solid Blasting Powder you made earlier; the counts above leave them out. One Mithril Bar and one Solid Blasting Powder a craft; hunters buy the slugs. Needs an anvil nearby. Mithril Bar (19 for 150-225): Mining: smelt Mithril Ore; or the Auction House. Engineering 225 is a Legacy System milestone.", section = 3, goals = {
		{ t = "craft", item = 10512, itemName = "Hi-Impact Mithril Slugs", spell = 12596, spellName = "Hi-Impact Mithril Slugs" },
		{ t = "skill", level = 225, skillName = "Engineering" },
	} },
	{ title = "Artisan Engineering", note = "Artisan raises the cap from 225 to 300 for 4g 50s (Classic's price; Forever's is not in the data); it needs Engineering 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance Buzzek Bracketswing (Tanaris); Horde Buzzek Bracketswing (Tanaris). The arrow picks the nearest of your faction. 225-300 takes about 2g 80s of recipes, plus 118 Mithril Bar, 212 Solid Stone, 156 Thorium Bar and 24 Runecloth to gather or buy.", section = 4, goals = {
		{ t = "level", level = 35 },
		{ t = "train" },
	} },
	{ title = "Schematic: Thorium Widget", note = "Schematic: Thorium Widget teaches Thorium Widget (Engineering 260) for 1g 20s. Sold by Alliance: Gearcutter Cogspinner (Ironforge), limited stock; Horde: Sovik (Orgrimmar), limited stock. Its sellers keep one or two in stock that come back some time after a sale; the Auction House often has it too.", section = 4, goals = {
		{ t = "buy", item = 16042, itemName = "Schematic: Thorium Widget" },
	} },
	{ title = "Schematic: Thorium Tube", note = "Schematic: Thorium Tube teaches Thorium Tube (Engineering 275) for 1g 60s. Sold by Kor'gar (Riverglades) and Xizzer Fizzbolt (Winterspring), limited stock.", section = 4, goals = {
		{ t = "buy", item = 16047, itemName = "Schematic: Thorium Tube" },
	} },
	{ title = "Solid Stone (Alliance)", note = "212 Solid Stone for Hi-Impact Mithril Slugs and Mithril Gyro-Shot: Mining: Mithril Deposit (skill 175) in The Hinterlands (40-50), Feralas (40-50) and Azshara (45-55); or the Auction House. The densest cluster of Mithril Deposit in The Hinterlands is marked.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1425, x = 20.8, y = 58.8, era = true, count = 212, item = 7912, itemName = "Solid Stone", spots = "20.8,58.8;23.3,59.8;24.7,66.6;28,58.9;27.3,69.3" },
	} },
	{ title = "Solid Stone (Horde)", note = "212 Solid Stone for Hi-Impact Mithril Slugs and Mithril Gyro-Shot: Mining: Mithril Deposit (skill 175) in Desolace (30-40), The Hinterlands (40-50) and Feralas (40-50); or the Auction House. The densest cluster of Mithril Deposit in Desolace is marked.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1443, x = 31.5, y = 59.4, era = true, count = 212, item = 7912, itemName = "Solid Stone" },
	} },
	{ title = "Runecloth", note = "24 Runecloth for Thorium Widget: humanoids of level 45-60 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 4, goals = {
		{ t = "collect", count = 24, item = 14047, itemName = "Runecloth" },
	} },
	{ title = "Hi-Impact Mithril Slugs to 245", note = "Hi-Impact Mithril Slugs is yellow at 225 (yellow 210, green 230, grey 250): about 62 crafts to 245. Each takes 1 Mithril Bar and 1 Solid Blasting Powder and makes 200. Make the 50 Solid Blasting Powder first. Use the 12 Solid Blasting Powder you made earlier; the counts above leave them out. One Mithril Bar and one Solid Blasting Powder a craft; hunters buy the slugs. Needs an anvil nearby. Mithril Bar (118 for 225-300): Mining: smelt Mithril Ore; or the Auction House.", section = 4, goals = {
		{ t = "craft", count = 50, item = 10505, itemName = "Solid Blasting Powder", spell = 12585, spellName = "Solid Blasting Powder" },
		{ t = "craft", item = 10512, itemName = "Hi-Impact Mithril Slugs", spell = 12596, spellName = "Hi-Impact Mithril Slugs" },
	} },
	{ title = "Engineering recipes at 245", note = "Back to an Engineering trainer: Mithril Gyro-Shot (from 245).", section = 4, goals = {
		{ t = "learn", spell = 12621, spellName = "Mithril Gyro-Shot" },
	} },
	{ title = "Mithril Gyro-Shot to 265", note = "Mithril Gyro-Shot is yellow at 245 (yellow 245, green 265, grey 285): about 28 crafts to 265. Each takes 2 Mithril Bar and 2 Solid Blasting Powder and makes 200. Make the 56 Solid Blasting Powder first. Two Mithril Bars and two Solid Blasting Powder a craft. Needs an anvil nearby.", section = 4, goals = {
		{ t = "craft", count = 56, item = 10505, itemName = "Solid Blasting Powder", spell = 12585, spellName = "Solid Blasting Powder" },
		{ t = "craft", item = 10513, itemName = "Mithril Gyro-Shot", spell = 12621, spellName = "Mithril Gyro-Shot" },
	} },
	{ title = "Thorium Widget to 287", note = "Thorium Widget is orange at 265 (yellow 280, green 290, grey 300): about 24 crafts to 287. Each takes 3 Thorium Bar and 1 Runecloth. Three Thorium Bars and a Runecloth a craft; the widgets are parts for the later Thorium gadgets. Needs an anvil nearby. Thorium Bar (156 for 225-300): Mining: smelt Thorium Ore; or the Auction House.", section = 4, goals = {
		{ t = "learn", item = 16042, itemName = "Schematic: Thorium Widget", spell = 19791, spellName = "Thorium Widget", note = "from the recipe in your bags" },
		{ t = "craft", item = 15994, itemName = "Thorium Widget", spell = 19791, spellName = "Thorium Widget" },
	} },
	{ title = "Thorium Tube to 300", note = "Thorium Tube is orange at 287 (yellow 295, green 305, grey 315): about 14 crafts to 300. Each takes 6 Thorium Bar. The schematic binds when picked up; six Thorium Bars a craft. Needs an anvil nearby. Engineering 300 is a Legacy System milestone.", section = 4, goals = {
