		{ t = "skill", level = 300, skillName = "Engineering" },
	} },
} end)

Waypost.RegisterSteps("professions/first-aid", function() return {
	{ title = "Learn First Aid", note = "Any First Aid trainer of your faction teaches Apprentice First Aid (any character level, 1s); the arrow picks the nearest. Forever teaches Minor Healing Potion with it: Peacebloom, Mild Spices and an Empty Vial, orange to 55. With Herbalism it can replace the Linen Bandages below.", section = 1, goals = {
		{ t = "train" },
	} },
	{ title = "Linen Bandage: cloth", note = "Linen Cloth drops from humanoids of level 5-20: keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 1, goals = {
		{ t = "collect", count = 41, item = 2589, itemName = "Linen Cloth" },
	} },
	{ title = "Linen Bandage (1-40)", note = "Linen Bandage is orange from 1 (yellow at 30, green at 45, grey at 60): about 41 crafts to 40. Bandages need no fire: craft them anywhere. At 20 the trainer also teaches First Aid Kit (1s; the Camping 101: First Aid quest at your starting area's camp teaches it free), Forever's camping item for First Aid: three Linen Bandages and a Refreshing Spring Water; it gives a few points until 25.", section = 1, goals = {
		{ t = "craft", item = 1251, itemName = "Linen Bandage", spell = 3275, spellName = "Linen Bandage" },
	} },
	{ title = "Heavy Linen Bandage: cloth", note = "Linen Cloth drops from humanoids of level 5-20: keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 2, goals = {
		{ t = "collect", count = 20, item = 2589, itemName = "Linen Cloth" },
	} },
	{ title = "Heavy Linen Bandage (40-50)", note = "Heavy Linen Bandage is orange from 40 (yellow at 50, green at 75, grey at 100): about 10 crafts to 50. Bandages need no fire: craft them anywhere. Any First Aid trainer of your faction teaches it from skill 40 for 1s; the arrow picks the nearest.", section = 2, goals = {
		{ t = "learn", spell = 3276, spellName = "Heavy Linen Bandage" },
		{ t = "craft", item = 2581, itemName = "Heavy Linen Bandage", spell = 3276, spellName = "Heavy Linen Bandage" },
	} },
	{ title = "Journeyman First Aid", note = "Journeyman First Aid raises the cap to 150; it needs skill 50 and no character level: the arrow picks the nearest First Aid trainer of your faction; training costs 5s.", section = 3, goals = {
		{ t = "train" },
	} },
	{ title = "Heavy Linen Bandage: cloth", note = "Linen Cloth drops from humanoids of level 5-20: keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 3, goals = {
