Waypost.RegisterSteps("professions/fishing", function() return {
	{ title = "Learn Fishing", note = "Any Fishing trainer of your faction teaches Apprentice Fishing at any character level (1s); the arrow picks the nearest, and every starting area has one on its lake or shore. Buy a Fishing Pole (23c) from a trade goods or fishing vendor and equip it (you can only fish with a pole in your hands), and two or three Shiny Baubles (+25, 50c each): a lure adds its bonus to your skill for ten minutes, so fewer fish get away at the start. If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: Fishing, handed in to the fishing trainer it names at skill 20 for the Fish Bowl recipe.", section = 1, goals = {
		{ t = "train" },
		{ t = "buy", count = 1, item = 6256, itemName = "Fishing Pole" },
	} },
	{ title = "Fishing: Elwynn Forest (1-50)", note = "Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast Fishing from your spellbook, click the bobber when it splashes. Keep the fish: they are your first Cooking ingredients. Fish get away here below skill 25; a lure on the pole adds to your skill for ten minutes and closes the gap.", only = { races = {"Human"} }, section = 1, goals = {
		{ t = "goto", map = 1429, x = 47.6, y = 62.3, era = true, text = "Crystal Lake" },
		{ t = "skill", level = 50, skillName = "Fishing" },
	} },
	{ title = "Fishing: Dun Morogh (1-50)", note = "Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast Fishing from your spellbook, click the bobber when it splashes. Keep the fish: they are your first Cooking ingredients. Fish get away here below skill 25; a lure on the pole adds to your skill for ten minutes and closes the gap.", only = { races = {"Dwarf", "Gnome"} }, section = 1, goals = {
