		{ t = "skill", level = 125, skillName = "Fishing" },
	} },
	{ title = "Expert Fishing", note = "Expert Fishing (cap 225) is a book, not a trainer rank: Old Man Heming sells Expert Fishing - The Bass and You (1g) on the lowest dock of Booty Bay, at the south tip of Stranglethorn Vale, to both factions. Buy it and read it; it needs skill 125 and level 20. At level 20 the safe way in is the boat from Ratchet in The Barrens, not the road through Stranglethorn. He also sells Bright Baubles (+75 from skill 100, 2s 50c each), the lure for the rest of the way.", section = 3, goals = {
		{ t = "level", level = 20 },
		{ t = "train", text = "Buy and read Expert Fishing - The Bass and You (Expert Fishing)" },
