Waypost.RegisterSteps("professions/leatherworking", function() return {
	{ title = "Learn Leatherworking", note = "Apprentice Leatherworking lets you craft up to 75 for 10c, at any character level. Not every Leatherworking trainer teaches it: Alliance Adele Fielder (Elwynn Forest), Darianna (Darnassus), Emerii Tallgust (Zephras Isle), Gretta Finespindle (Ironforge), Indari Sunseam (Zephras Isle), Nadyia Maneweaver (Teldrassil) and Randal Worth (Stormwind City); Horde Chaw Stronghide (Mulgore), Dan Golthas (Undercity), Emerii Tallgust (Zephras Isle), Indari Sunseam (Zephras Isle), Kamari (Orgrimmar), Mak (Thunder Bluff) and Shelene Rhobart (Tirisfal Glades). The arrow picks the nearest of your faction. Pair it with Skinning: Light Leather comes from the beasts of every starting zone. Coarse Thread and Salt are sold by leatherworking and trade supplies vendors. 1-75 takes about 1s 50c of recipes and 5s of vendor goods, plus 349 Light Leather to gather or buy.", section = 1, goals = {
		{ t = "train" },
		{ t = "skill", level = 1, skillName = "Leatherworking" },
	} },
	{ title = "Leatherworking 1-75: vendor goods", note = "Buy the whole bracket's share in one go: 50 Coarse Thread (5s); about 5s in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = 1, goals = {
		{ t = "buy", count = 50, item = 2320, itemName = "Coarse Thread" },
	} },
	{ title = "Light Leather (Elwynn Forest)", note = "349 Light Leather for Light Armor Kit, Embossed Leather Gloves and Fine Leather Belt (210 of them for 75-150: pick them all now): Skinning: beasts of level 5-20; or the Auction House. Skin Gray Forest Wolf, Mangy Wolf, Prowler, Rockhide Boar, Stonetusk Boar and Young Forest Bear here (level 5-20); the Skinning guide routes this.", only = { races = {"Human"} }, section = 1, goals = {
		{ t = "collect", map = 1429, x = 55.5, y = 76.6, era = true, count = 349, item = 2318, itemName = "Light Leather" },
	} },
	{ title = "Light Leather (Dun Morogh)", note = "349 Light Leather for Light Armor Kit, Embossed Leather Gloves and Fine Leather Belt (210 of them for 75-150: pick them all now): Skinning: beasts of level 5-20; or the Auction House. Skin Crag Boar, Elder Crag Boar, Ice Claw Bear, Juvenile Snow Leopard, Large Crag Boar, Scarred Crag Boar, Snow Leopard, Snow Tracker Wolf, Winter Wolf and Young Black Bear here (level 5-20); the Skinning guide routes this.", only = { races = {"Dwarf", "Gnome"} }, section = 1, goals = {
