	} },
	{ title = "Thick Leather (Horde)", note = "373 Thick Leather for Nightscape Headband and Nightscape Pants: Skinning: beasts of level 38-50; or the Auction House. Skin Feral Scar Yeti, Frayfeather Hippogryph, Frayfeather Stagwing, Grizzled Ironfur Bear, Groddoc Ape, Groddoc Thunderer, Ironfur Bear, Ironfur Patriarch, Longtooth Howler, Longtooth Runner and Rage Scar Yeti here (level 38-50); the Skinning guide routes this.", only = { factions = {"Horde"} }, section = 3, goals = {
		{ t = "collect", map = 1444, x = 54.9, y = 60.8, era = true, count = 373, item = 4304, itemName = "Thick Leather" },
	} },
	{ title = "Expert Leatherworking", note = "Expert raises the cap from 150 to 225; it needs Leatherworking 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Telonis (Darnassus); Horde Una (Thunder Bluff). The arrow picks the nearest of your faction. Learn now: Cured Heavy Hide (from 125, 5s) and Barbaric Shoulders (from 150). 150-225 takes about 5s of recipes and 7g 87s of vendor goods, plus 22 Heavy Hide and 373 Thick Leather to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach Guardian Gloves (from 165), Nightscape Headband (from 180) and Nightscape Pants (from 210), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 4.", section = 3, goals = {
		{ t = "level", level = 20 },
		{ t = "train" },
		{ t = "learn", spell = 3818, spellName = "Cured Heavy Hide" },
		{ t = "learn", spell = 7151, spellName = "Barbaric Shoulders" },
	} },
	{ title = "Heavy Armor Kit to 158", note = "Heavy Armor Kit is yellow at 150 (yellow 145, green 155, grey 165): about 15 crafts to 158. Each takes 5 Heavy Leather and 1 Fine Thread. Five Heavy Leather a craft (beasts of level 28-40); the kits sell to vendors.", section = 3, goals = {
		{ t = "craft", item = 4265, itemName = "Heavy Armor Kit", spell = 3780, spellName = "Heavy Armor Kit" },
	} },
	{ title = "Barbaric Shoulders to 165", note = "Barbaric Shoulders is orange at 158 (yellow 170, green 180, grey 190): about 7 crafts to 165, a point every craft. Each takes 8 Heavy Leather, 1 Cured Heavy Hide and 2 Fine Thread. Make the 7 Cured Heavy Hide first. The trainer teaches it, and it is the cheapest way through these points in the data.", section = 3, goals = {
		{ t = "craft", count = 7, item = 4236, itemName = "Cured Heavy Hide", spell = 3818, spellName = "Cured Heavy Hide" },
		{ t = "craft", item = 5964, itemName = "Barbaric Shoulders", spell = 7151, spellName = "Barbaric Shoulders" },
