	} },
	{ title = "Pattern: Wicked Leather Gauntlets", note = "Pattern: Wicked Leather Gauntlets teaches Wicked Leather Gauntlets (Leatherworking 235) for 1g 20s. Sold by Alliance: Leonard Porter (Western Plaguelands), limited stock; Horde: Werg Thickblade (Western Plaguelands), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = 4, goals = {
		{ t = "buy", item = 15725, itemName = "Pattern: Wicked Leather Gauntlets" },
	} },
	{ title = "Pattern: Runic Leather Headband", note = "Pattern: Runic Leather Headband teaches Runic Leather Headband (Leatherworking 265) for 2g 20s. Sold by Jase Farlane (Eastern Plaguelands), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = 4, goals = {
		{ t = "buy", item = 15756, itemName = "Pattern: Runic Leather Headband" },
	} },
	{ title = "Rugged Leather (Alliance)", note = "1029 Rugged Leather for Rugged Armor Kit, Wicked Leather Gauntlets and Runic Leather Headband: Skinning: beasts of level 48-60; or the Auction House. Skin Frenzied Plaguehound, Plaguehound and Plaguehound Runt here (level 48-60); the Skinning guide routes this.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1423, x = 56, y = 46.8, count = 1029, item = 8170, itemName = "Rugged Leather" },
	} },
	{ title = "Rugged Leather (Horde)", note = "1029 Rugged Leather for Rugged Armor Kit, Wicked Leather Gauntlets and Runic Leather Headband: Skinning: beasts of level 48-60; or the Auction House. Skin Coralshell Tortoise, Mosshoof Stag, Thunderhead Consort, Thunderhead Patriarch, Thunderhead Skystormer and Thunderhead Stagwing here (level 48-60); the Skinning guide routes this.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1447, x = 58.8, y = 21.5, era = true, count = 1029, item = 8170, itemName = "Rugged Leather" },
	} },
	{ title = "Runecloth", note = "430 Runecloth for Runic Leather Headband: humanoids of level 45-60 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 4, goals = {
		{ t = "collect", count = 430, item = 14047, itemName = "Runecloth" },
	} },
	{ title = "Rugged Armor Kit to 239", note = "Rugged Armor Kit is yellow at 225 (yellow 225, green 235, grey 245): about 23 crafts to 239. Each takes 5 Rugged Leather. Five Rugged Leather a craft. Specialisation (optional): at 225 and character level 40. Dragonscale: Peter Galen (Azshara) or Thorkaf Dragoneye (Badlands) wants 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves (patterns drop from the Wastewander bandits in Tanaris) and 10 Worn Dragonscale. Elemental: Sarah Tanner (Searing Gorge) or Brumn Winterhoof (Arathi Highlands) wants 2 each of Heart of Fire, Globe of Water, Core of Earth and Breath of Wind. Tribal (from 235): Caryssia Moonhunter (Feralas) or Se'Jib (Stranglethorn Vale) wants a Wild Leather Vest and Helmet, after the Wild Leather quests from Pratt McGrubben or Jangdor Swiftstrider in Feralas. On Forever the specialisation patterns need a Tanning Rack. You can take only one; none is needed for 300, and the beta never tested them (it stopped at level 30).", section = 4, goals = {
		{ t = "craft", item = 15564, itemName = "Rugged Armor Kit", spell = 19058, spellName = "Rugged Armor Kit" },
	} },
	{ title = "Wicked Leather Gauntlets to 269", note = "Wicked Leather Gauntlets is orange at 239 (yellow 255, green 265, grey 275): about 39 crafts to 269. Each takes 8 Rugged Leather, 1 Black Dye and 1 Rune Thread. Eight Rugged Leather a craft; Black Dye and Rune Thread from leatherworking or tailoring vendors.", section = 4, goals = {
		{ t = "learn", item = 15725, itemName = "Pattern: Wicked Leather Gauntlets", spell = 19049, spellName = "Wicked Leather Gauntlets", note = "from the recipe in your bags" },
		{ t = "craft", item = 15083, itemName = "Wicked Leather Gauntlets", spell = 19049, spellName = "Wicked Leather Gauntlets" },
	} },
	{ title = "Runic Leather Headband to 300", note = "Runic Leather Headband is orange at 269 (yellow 285, green 295, grey 305): about 43 crafts to 300. Each takes 14 Rugged Leather, 10 Runecloth and 1 Rune Thread. 14 Rugged Leather and 10 Runecloth a craft: the dearest stretch. Leatherworking 300 is a Legacy System milestone.", section = 4, goals = {
		{ t = "learn", item = 15756, itemName = "Pattern: Runic Leather Headband", spell = 19082, spellName = "Runic Leather Headband", note = "from the recipe in your bags" },
		{ t = "craft", item = 15094, itemName = "Runic Leather Headband", spell = 19082, spellName = "Runic Leather Headband" },
		{ t = "skill", level = 300, skillName = "Leatherworking" },
	} },
} end)

Waypost.RegisterSteps("professions/mining", function() return {
	{ title = "Learn Mining", note = "Any Mining trainer of your faction teaches Apprentice Mining at any level (10c), and so does the Junior Mining Trainer in each starting area; the arrow picks the nearest. Buy a Mining Pick from a trade goods or general vendor: keep it in your bags, you cannot mine without it. Turn on Find Minerals (spellbook, General tab) so veins show on the minimap. Forever's starting areas also have Poor Copper Veins (Copper Ore and Rough Stone, from skill 1). The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's Cactus Apple Surprise, A Humble Task, Marla's Last Wish) offers Mining for Dummies as a reward: reading it gives 2 skill, up to 15. Trade goods vendors and the junior trainers sell the Apprentice's Mining Pack, a four-slot bag for ore and stone (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: Mining: hand it in to the mining trainer it names once you reach skill 20, for the Lodestone recipe.", section = 1, goals = {
