Waypost.RegisterSteps("professions/tailoring", function() return {
	{ title = "Learn Tailoring", note = "Apprentice Tailoring lets you craft up to 75 for 10c, at any character level. Any Tailoring trainer of your faction teaches it; the arrow picks the nearest. Keep every Linen Cloth you loot: humanoids of level 5-20 drop it. 1-75 takes about 50c of recipes and 7s 20c of vendor goods, plus 144 Linen Cloth to gather or buy.", section = 1, goals = {
		{ t = "train" },
		{ t = "skill", level = 1, skillName = "Tailoring" },
	} },
	{ title = "Tailoring 1-75: vendor goods", note = "Buy the whole bracket's share in one go: 72 Coarse Thread (7s 20c); about 7s 20c in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = 1, goals = {
		{ t = "buy", count = 72, item = 2320, itemName = "Coarse Thread" },
	} },
	{ title = "Linen Cloth", note = "144 Linen Cloth for Linen Cloak and Linen Belt: humanoids of level 5-20 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 1, goals = {
		{ t = "collect", count = 144, item = 2589, itemName = "Linen Cloth" },
	} },
	{ title = "Linen Cloak to 15", note = "Linen Cloak is orange at 1 (yellow 35, green 47, grey 60): about 7 crafts to 15, a point every craft. Each takes 1 Bolt of Linen Cloth and 1 Coarse Thread. Make the 7 Bolt of Linen Cloth first: it gives points too while not grey. The trainer teaches it, and it is the cheapest way through these points in the data.", section = 1, goals = {
		{ t = "craft", count = 7, item = 2996, itemName = "Bolt of Linen Cloth", spell = 2963, spellName = "Bolt of Linen Cloth" },
		{ t = "craft", item = 2570, itemName = "Linen Cloak", spell = 2387, spellName = "Linen Cloak" },
	} },
	{ title = "Tailoring recipes at 15", note = "Back to a Tailoring trainer: Linen Belt (from 15, 50c).", section = 1, goals = {
		{ t = "learn", spell = 8776, spellName = "Linen Belt" },
	} },
	{ title = "Linen Belt to 75", note = "Linen Belt is orange at 15 (yellow 50, green 67, grey 85): about 65 crafts to 75. Each takes 1 Bolt of Linen Cloth and 1 Coarse Thread. Make the 65 Bolt of Linen Cloth first: it gives points too while not grey. Each belt takes one bolt; the belts sell to vendors.", section = 1, goals = {
		{ t = "craft", count = 65, item = 2996, itemName = "Bolt of Linen Cloth", spell = 2963, spellName = "Bolt of Linen Cloth" },
		{ t = "craft", item = 7026, itemName = "Linen Belt", spell = 8776, spellName = "Linen Belt" },
		{ t = "skill", level = 75, skillName = "Tailoring" },
	} },
	{ title = "Journeyman Tailoring", note = "Journeyman raises the cap from 75 to 150 for 5s; it needs Tailoring 50 and character level 10, so you can take it on any visit from 50. Not every Tailoring trainer teaches it: Alliance Grarnik Goodstitch (Stranglethorn Vale), Jormund Stonebrow (Ironforge), Me'lynn (Darnassus), Othesia Evengale (Zephras Isle), Sellandus (Stormwind City) and Taleen Shimmerthread (Zephras Isle); Horde Grarnik Goodstitch (Stranglethorn Vale), Magar (Orgrimmar), Mahani (The Barrens), Othesia Evengale (Zephras Isle), Rhiannon Davis (Undercity), Taleen Shimmerthread (Zephras Isle) and Tepa (Thunder Bluff). The arrow picks the nearest of your faction. Learn now: Bolt of Woolen Cloth (from 55, 1s) and Woolen Cape (from 55, 2s 50c). Also learn Faction Banner (1s): Forever's Tailoring camp item, a Bolt of Linen Cloth and a Coarse Thread; each faction has its own. The Camping 101: Tailoring quest from your starting area's camping guide (after The Great Outdoors) sends you to a tailoring trainer who teaches it free. 75-150 takes about 11s of recipes and 1g 65s 50c of vendor goods, plus 567 Wool Cloth and 204 Silk Cloth to gather or buy.", section = 2, goals = {
		{ t = "level", level = 10 },
		{ t = "train" },
		{ t = "learn", spell = 2964, spellName = "Bolt of Woolen Cloth" },
		{ t = "learn", spell = 2402, spellName = "Woolen Cape" },
		{ t = "learn", spell = 1263425, spellName = "Faction Banner", only = { factions = {"Alliance"} } },
		{ t = "learn", spell = 1229504, spellName = "Faction Banner", only = { factions = {"Horde"} } },
	} },
	{ title = "Tailoring 75-150: vendor goods", note = "Buy the whole bracket's share in one go: 108 Fine Thread (1g 8s), 34 Bleach (8s 50c) and 98 Red Dye (49s); about 1g 65s 50c in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = 2, goals = {
		{ t = "buy", count = 108, item = 2321, itemName = "Fine Thread" },
		{ t = "buy", count = 34, item = 2324, itemName = "Bleach" },
		{ t = "buy", count = 98, item = 2604, itemName = "Red Dye" },
	} },
	{ title = "Wool Cloth", note = "567 Wool Cloth for Woolen Cape and Stylish Red Shirt: humanoids of level 15-30 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 2, goals = {
		{ t = "collect", count = 567, item = 2592, itemName = "Wool Cloth" },
	} },
	{ title = "Silk Cloth", note = "204 Silk Cloth for Formal White Shirt: humanoids of level 25-45 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 2, goals = {
		{ t = "collect", count = 204, item = 4306, itemName = "Silk Cloth" },
	} },
	{ title = "Woolen Cape to 104", note = "Woolen Cape is orange at 75 (yellow 80, green 97, grey 115): about 42 crafts to 104. Each takes 1 Bolt of Woolen Cloth and 1 Fine Thread. Make the 42 Bolt of Woolen Cloth first: it gives points too while not grey. Bolt of Woolen Cloth is taught from 55 on Forever.", section = 2, goals = {
		{ t = "craft", count = 42, item = 2997, itemName = "Bolt of Woolen Cloth", spell = 2964, spellName = "Bolt of Woolen Cloth" },
		{ t = "craft", item = 2584, itemName = "Woolen Cape", spell = 2402, spellName = "Woolen Cape" },
	} },
	{ title = "Tailoring recipes at 104", note = "Back to a Tailoring trainer: Stylish Red Shirt (from 85, 2s 50c).", section = 2, goals = {
		{ t = "learn", spell = 3866, spellName = "Stylish Red Shirt" },
	} },
	{ title = "Stylish Red Shirt to 135", note = "Stylish Red Shirt is orange at 104 (yellow 110, green 127, grey 145): about 49 crafts to 135. Each takes 3 Bolt of Woolen Cloth, 2 Red Dye and 1 Fine Thread. Make the 147 Bolt of Woolen Cloth first. Three woolen bolts and two Red Dye a shirt; Wool Cloth drops from humanoids of level 15-30.", section = 2, goals = {
		{ t = "craft", count = 147, item = 2997, itemName = "Bolt of Woolen Cloth", spell = 2964, spellName = "Bolt of Woolen Cloth" },
		{ t = "craft", item = 4330, itemName = "Stylish Red Shirt", spell = 3866, spellName = "Stylish Red Shirt" },
	} },
	{ title = "Tailoring recipes at 135", note = "Back to a Tailoring trainer: Bolt of Silk Cloth (from 100, 5s) and Formal White Shirt (from 135).", section = 2, goals = {
		{ t = "learn", spell = 3839, spellName = "Bolt of Silk Cloth" },
		{ t = "learn", spell = 3871, spellName = "Formal White Shirt" },
	} },
	{ title = "Formal White Shirt to 150", note = "Formal White Shirt is orange at 135 (yellow 145, green 150, grey 155): about 17 crafts to 150. Each takes 3 Bolt of Silk Cloth, 2 Bleach and 1 Fine Thread. Make the 51 Bolt of Silk Cloth first. Silk bolts from here on: Silk Cloth drops from humanoids of level 25-45. Bleach from tailoring and trade supplies vendors. Tailoring 150 is a Legacy System milestone.", section = 2, goals = {
		{ t = "craft", count = 51, item = 4305, itemName = "Bolt of Silk Cloth", spell = 3839, spellName = "Bolt of Silk Cloth" },
		{ t = "craft", item = 4334, itemName = "Formal White Shirt", spell = 3871, spellName = "Formal White Shirt" },
		{ t = "skill", level = 150, skillName = "Tailoring" },
	} },
	{ title = "Tailoring 150-225: vendor goods", note = "Buy the whole bracket's share in one go: 44 Fine Thread (44s), 90 Silken Thread (4g 50s), 44 Blue Dye (22s) and 80 Heavy Silken Thread (16g); about 21g 16s in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = 3, goals = {
		{ t = "buy", count = 44, item = 2321, itemName = "Fine Thread" },
		{ t = "buy", count = 90, item = 4291, itemName = "Silken Thread" },
		{ t = "buy", count = 44, item = 6260, itemName = "Blue Dye" },
		{ t = "buy", count = 80, item = 8343, itemName = "Heavy Silken Thread" },
	} },
	{ title = "Pattern: Azure Silk Cloak", note = "Pattern: Azure Silk Cloak teaches Azure Silk Cloak (Tailoring 140) for 15s. Sold by Alliance: Brienna Starglow (Feralas), limited stock and Norvin Alderman (Alterac Mountains); Horde: Jun'ha (Arathi Highlands), limited stock and Norvin Alderman (Alterac Mountains).", section = 3, goals = {
		{ t = "buy", item = 7089, itemName = "Pattern: Azure Silk Cloak" },
	} },
	{ title = "Silk Cloth", note = "264 Silk Cloth for Azure Silk Cloak: humanoids of level 25-45 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 3, goals = {
		{ t = "collect", count = 264, item = 4306, itemName = "Silk Cloth" },
	} },
	{ title = "Mageweave Cloth", note = "900 Mageweave Cloth for Black Mageweave Vest and Black Mageweave Headband: humanoids of level 35-50 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 3, goals = {
		{ t = "collect", count = 900, item = 4338, itemName = "Mageweave Cloth" },
	} },
	{ title = "Expert Tailoring", note = "Expert raises the cap from 150 to 225; it needs Tailoring 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance Georgio Bolero (Stormwind City); Horde Josef Gregorian (Undercity). The arrow picks the nearest of your faction. Learn now: Bolt of Mageweave (from 140). 150-225 takes about 15s of recipes and 21g 16s of vendor goods, plus 264 Silk Cloth and 900 Mageweave Cloth to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach Black Mageweave Vest (from 170) and Black Mageweave Headband (from 190), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3.", section = 3, goals = {
		{ t = "level", level = 20 },
		{ t = "train" },
		{ t = "learn", spell = 3865, spellName = "Bolt of Mageweave" },
	} },
	{ title = "Azure Silk Cloak to 170", note = "Azure Silk Cloak is orange at 150 (yellow 160, green 175, grey 190): about 22 crafts to 170. Each takes 3 Bolt of Silk Cloth, 2 Blue Dye and 2 Fine Thread. Make the 66 Bolt of Silk Cloth first. Its recipe is the one bought above; it is the cheapest way through these points in the data.", section = 3, goals = {
		{ t = "learn", item = 7089, itemName = "Pattern: Azure Silk Cloak", spell = 8786, spellName = "Azure Silk Cloak", note = "from the recipe in your bags" },
		{ t = "craft", count = 66, item = 4305, itemName = "Bolt of Silk Cloth", spell = 3839, spellName = "Bolt of Silk Cloth" },
		{ t = "craft", item = 7053, itemName = "Azure Silk Cloak", spell = 8786, spellName = "Azure Silk Cloak" },
	} },
	{ title = "Tailoring recipes at 170", note = "Still at the Expert trainer: Black Mageweave Vest (from 170).", section = 3, goals = {
		{ t = "learn", spell = 12048, spellName = "Black Mageweave Vest" },
	} },
	{ title = "Black Mageweave Vest to 197", note = "Black Mageweave Vest is orange at 170 (yellow 185, green 200, grey 215): about 30 crafts to 197. Each takes 2 Bolt of Mageweave and 3 Silken Thread. Make the 60 Bolt of Mageweave first. The trainer teaches it, and it is the cheapest way through these points in the data.", section = 3, goals = {
		{ t = "craft", count = 60, item = 4339, itemName = "Bolt of Mageweave", spell = 3865, spellName = "Bolt of Mageweave" },
		{ t = "craft", item = 9998, itemName = "Black Mageweave Vest", spell = 12048, spellName = "Black Mageweave Vest" },
	} },
	{ title = "Tailoring recipes at 197", note = "Still at the Expert trainer: Black Mageweave Headband (from 190).", section = 3, goals = {
		{ t = "learn", spell = 12072, spellName = "Black Mageweave Headband" },
	} },
	{ title = "Black Mageweave Headband to 225", note = "Black Mageweave Headband is orange at 197 (yellow 205, green 220, grey 235): about 40 crafts to 225. Each takes 3 Bolt of Mageweave and 2 Heavy Silken Thread. Make the 120 Bolt of Mageweave first. The trainer teaches it, and it is the cheapest way through these points in the data. Tailoring 225 is a Legacy System milestone.", section = 3, goals = {
		{ t = "craft", count = 120, item = 4339, itemName = "Bolt of Mageweave", spell = 3865, spellName = "Bolt of Mageweave" },
		{ t = "craft", item = 10024, itemName = "Black Mageweave Headband", spell = 12072, spellName = "Black Mageweave Headband" },
		{ t = "skill", level = 225, skillName = "Tailoring" },
	} },
	{ title = "Artisan Tailoring", note = "Artisan raises the cap from 225 to 300; it needs Tailoring 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance Timothy Worthington (Dustwallow Marsh); Horde Daryl Stack (Hillsbrad Foothills). The arrow picks the nearest of your faction. Learn now: Bolt of Runecloth (from 205) and Runecloth Belt (from 210). 225-300 takes about 1g 60s of recipes and 58g of vendor goods, plus 420 Rugged Leather, 3195 Runecloth and 124 Ironweb Spider Silk to gather or buy.", section = 4, goals = {
		{ t = "level", level = 35 },
		{ t = "train" },
		{ t = "learn", spell = 18401, spellName = "Bolt of Runecloth" },
		{ t = "learn", spell = 18402, spellName = "Runecloth Belt" },
	} },
	{ title = "Tailoring 225-300: vendor goods", note = "Buy the whole bracket's share in one go: 116 Rune Thread (58g); about 58g in all. The arrow picks the nearest seller of your faction (Stormwind City: Alexandra Bolero, Edna Mullby and Jillian Tanner; Orgrimmar: Borya, Felika and Shimra).", section = 4, goals = {
		{ t = "buy", count = 116, item = 14341, itemName = "Rune Thread" },
	} },
	{ title = "Pattern: Runecloth Gloves", note = "Pattern: Runecloth Gloves teaches Runecloth Gloves (Tailoring 230) for 1g 60s. Sold by Qia (Winterspring), limited stock. Its sellers keep one or two in stock that come back some time after a sale; it binds when picked up, so the Auction House never has it.", section = 4, goals = {
		{ t = "buy", item = 14481, itemName = "Pattern: Runecloth Gloves" },
	} },
	{ title = "Rugged Leather (Alliance)", note = "420 Rugged Leather for Runecloth Gloves and Runecloth Shoulders: Skinning: beasts of level 48-60; or the Auction House. Skin Frenzied Plaguehound, Plaguehound and Plaguehound Runt here (level 48-60); the Skinning guide routes this.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1423, x = 56, y = 46.8, count = 420, item = 8170, itemName = "Rugged Leather" },
	} },
	{ title = "Rugged Leather (Horde)", note = "420 Rugged Leather for Runecloth Gloves and Runecloth Shoulders: Skinning: beasts of level 48-60; or the Auction House. Skin Coralshell Tortoise, Mosshoof Stag, Thunderhead Consort, Thunderhead Patriarch, Thunderhead Skystormer and Thunderhead Stagwing here (level 48-60); the Skinning guide routes this.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1447, x = 58.8, y = 21.5, era = true, count = 420, item = 8170, itemName = "Rugged Leather" },
	} },
	{ title = "Runecloth", note = "3195 Runecloth for Runecloth Belt, Runecloth Gloves and Runecloth Shoulders: humanoids of level 45-60 drop it. Keep what you loot as you level, take it from your bank, or buy it at the Auction House.", section = 4, goals = {
		{ t = "collect", count = 3195, item = 14047, itemName = "Runecloth" },
	} },
	{ title = "Ironweb Spider Silk (Alliance)", note = "124 Ironweb Spider Silk for Runecloth Shoulders: it drops from Plague Lurker (level 54-55) at the marked spot, or buy it at the Auction House.", only = { factions = {"Alliance"} }, section = 4, goals = {
		{ t = "collect", map = 1422, x = 57.1, y = 53.5, era = true, count = 124, item = 14227, itemName = "Ironweb Spider Silk", mobLevel = 55, spots = "57.1,53.5;55.9,50.6;60,53.9;60,50.8;56.5,59.1" },
	} },
	{ title = "Ironweb Spider Silk (Horde)", note = "124 Ironweb Spider Silk for Runecloth Shoulders: it drops from Rock Stalker (level 57-59) at the marked spot, or buy it at the Auction House.", only = { factions = {"Horde"} }, section = 4, goals = {
		{ t = "collect", map = 1451, x = 24.7, y = 81.8, era = true, count = 124, item = 14227, itemName = "Ironweb Spider Silk", mobLevel = 59, spots = "24.7,81.8;23.1,78.2;27.7,83.5;26.9,76.4;23.1,88.6" },
	} },
	{ title = "Runecloth Belt to 234", note = "Runecloth Belt is yellow at 225 (yellow 225, green 240, grey 255): about 11 crafts to 234. Each takes 3 Bolt of Runecloth and 1 Rune Thread. Make the 33 Bolt of Runecloth first. Rune Thread from tailoring vendors.", section = 4, goals = {
		{ t = "craft", count = 33, item = 14048, itemName = "Bolt of Runecloth", spell = 18401, spellName = "Bolt of Runecloth" },
		{ t = "craft", item = 13856, itemName = "Runecloth Belt", spell = 18402, spellName = "Runecloth Belt" },
	} },
	{ title = "Runecloth Gloves to 265", note = "Runecloth Gloves is orange at 234 (yellow 245, green 260, grey 275): about 43 crafts to 265. Each takes 4 Bolt of Runecloth, 4 Rugged Leather and 1 Rune Thread. Make the 172 Bolt of Runecloth first. Qia in Everlook keeps one pattern at a time; the Timbermaw Hold tunnel from Felwood is the road in, so never kill Timbermaw furbolgs on the way.", section = 4, goals = {
		{ t = "learn", item = 14481, itemName = "Pattern: Runecloth Gloves", spell = 18417, spellName = "Runecloth Gloves", note = "from the recipe in your bags" },
		{ t = "craft", count = 172, item = 14048, itemName = "Bolt of Runecloth", spell = 18401, spellName = "Bolt of Runecloth" },
		{ t = "craft", item = 13863, itemName = "Runecloth Gloves", spell = 18417, spellName = "Runecloth Gloves" },
	} },
	{ title = "Runecloth Shoulders to 300", note = "Runecloth Shoulders is orange at 265 (yellow 275, green 290, grey 305): about 62 crafts to 300. Each takes 7 Bolt of Runecloth, 2 Ironweb Spider Silk, 4 Rugged Leather and 1 Rune Thread. Make the 434 Bolt of Runecloth first. Its pattern (Pattern: Runecloth Shoulders) drops from mobs all over the world and does not bind: buy it at the Auction House. Seven bolts, two Ironweb Spider Silk and four Rugged Leather a craft: the dearest stretch. The spiders of Western Plaguelands and Silithus drop the silk (the marked spots), or the Auction House. No pattern on the Auction House? Runecloth Gloves still give a point now and then to 275, and Runecloth Boots (Darnall, Moonglade) to 280, at 4 bolts a craft. Mooncloth (pattern from Qia or Evie Whirlbrew in Everlook; 2 Felcloth at a Moonwell) stays orange to 270 and yellow to 285, but it can be made once every four days. The Spinning Wheel patterns (Merchant's Favor sandals and waistcords from Jim'bek or Mivin Shadowweave; the wheel's blueprint drops from the Unstable Sentinel in the City of Dalaran) and Runecloth Cuffs (Pexmit in Mount Hyjal, 10g; we could not confirm that vendor yet) are the other ways on. Tailoring 300 is a Legacy System milestone.", section = 4, goals = {
		{ t = "learn", item = 14504, itemName = "Pattern: Runecloth Shoulders", spell = 18449, spellName = "Runecloth Shoulders", note = "from the pattern bought at the Auction House" },
		{ t = "craft", count = 434, item = 14048, itemName = "Bolt of Runecloth", spell = 18401, spellName = "Bolt of Runecloth" },
		{ t = "craft", item = 13867, itemName = "Runecloth Shoulders", spell = 18449, spellName = "Runecloth Shoulders" },
		{ t = "skill", level = 300, skillName = "Tailoring" },
	} },
} end)

Waypost.RegisterSteps("reputation/alterac-valley", function() return {
	{ title = "Lieutenant Rotimer", note = "Alterac Valley is a 40 against 40 battle for level 51 and up, and the fastest of the four battleground reputations: it has about 2,000 reputation of one-time quests, and a full win pays several hundred. The same one-time quests also pay 1,870 Ironforge reputation. Lieutenant Rotimer recruits outside the Great Forge. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = {"Alliance"} }, goals = {
		{ t = "accept", quest = 7261, title = "The Sovereign Imperative", npc = "Lieutenant Rotimer", map = 1455, x = 32.21, y = 63.26, era = true, qlvl = 60, note = "The Sovereign Imperative, 100" },
	} },
	{ title = "Lieutenant Haggerdin", note = "The Stormpike camp stands outside the Alterac Valley gate, on the Alterac Mountains side above Hillsbrad. Take every quest here: they all pay 100 or more, once.", only = { factions = {"Alliance"} }, goals = {
		{ t = "turnin", quest = 7261, title = "The Sovereign Imperative", npc = "Lieutenant Haggerdin", map = 1416, x = 39.46, y = 81.23, era = true },
		{ t = "accept", quest = 7162, title = "Proving Grounds", npc = "Lieutenant Haggerdin", map = 1416, x = 39.46, y = 81.23, era = true, qlvl = 60, note = "Proving Grounds: the Stormpike Banner in Icewing Cavern, 100" },
		{ t = "accept", quest = 7081, title = "Alterac Valley Graveyards", npc = "Sergeant Durgen Stormpike", map = 1416, x = 36.76, y = 77.19, era = true, qlvl = 60, note = "Sergeant Durgen Stormpike: assault a graveyard, 100" },
		{ t = "accept", quest = 7102, title = "Towers and Bunkers", npc = "Sergeant Durgen Stormpike", map = 1416, x = 36.76, y = 77.19, era = true, qlvl = 60, note = "destroy a tower or bunker banner, 100" },
		{ t = "accept", quest = 7122, title = "Capture a Mine", npc = "Sergeant Durgen Stormpike", map = 1416, x = 36.76, y = 77.19, era = true, qlvl = 60, note = "capture a mine, 100" },
	} },
	{ title = "Dun Baldar", note = "Queue at the gate, at any battlemaster or from the battleground screen; you enter at Dun Baldar in the north. Before the gates open, take the quests in the town: they are done during the battle.", only = { factions = {"Alliance"} }, goals = {
		{ t = "accept", quest = 7121, title = "The Quartermaster", npc = "Mountaineer Boombellow", map = 1459, x = 45.59, y = 16.71, era = true, qlvl = 60, note = "Mountaineer Boombellow: The Quartermaster, 10" },
		{ t = "turnin", quest = 7121, title = "The Quartermaster", npc = "Stormpike Quartermaster", map = 1459, x = 43.12, y = 17.62, era = true },
		{ t = "accept", quest = 7223, title = "Armor Scraps", npc = "Murgot Deepforge", map = 1459, x = 43.48, y = 15.5, era = true, qlvl = 60, note = "Murgot Deepforge: 20 Armor Scraps, 100" },
		{ t = "accept", quest = 7282, title = "Brotherly Love", npc = "Commander Karl Philips", map = 1459, x = 50.6, y = 31.45, era = true, qlvl = 60, note = "Commander Karl Philips: Brotherly Love, 100" },
		{ t = "accept", quest = 7301, title = "Fallen Sky Lords", npc = "Commander Duffy", map = 1459, x = 49.03, y = 14.61, era = true, qlvl = 60, note = "Commander Duffy: Fallen Sky Lords, 100" },
		{ t = "accept", quest = 7367, title = "Defusing the Threat", npc = "Stormpike Explosives Expert", map = 1459, x = 42.8, y = 17, era = true, qlvl = 60, note = "Stormpike Explosives Expert: Defusing the Threat, 100" },
	} },
	{ title = "Icewing Cavern", note = "Icewing Cavern lies southwest of Dun Baldar. The Stormpike Banner stands at the back of the cave, past the yetis and harpies.", only = { factions = {"Alliance"} }, goals = {
		{ t = "collect", quest = 7162, title = "Proving Grounds", map = 1459, x = 41.9, y = 36.18, era = true, count = 1, item = 17849, itemName = "Stormpike Banner", oi = 1 },
	} },
	{ title = "The battle", note = "Most of this happens on the way to Drek'Thar. Loot Armor Scraps from Horde players and guards you kill. Assault the Snowfall Graveyard or any Horde graveyard, burn a Horde tower (click its banner), and take Coldtooth Mine. Commander Louis Philips stands at Tower Point; the Frostwolf Explosives Expert at Frostwolf Village. Fallen Sky Lords asks you to find where the three wing commanders landed. In Classic every tower, graveyard or mine paid 12 reputation, Captain Galvangar 125 and Drek'Thar about 300.", only = { factions = {"Alliance"} }, goals = {
		{ t = "collect", quest = 7223, title = "Armor Scraps", map = 1459, x = 44.59, y = 45.57, era = true, count = 20, item = 17422, itemName = "Armor Scraps", oi = 1, mobLevel = 60, spots = "44.6,45.6;46.5,56.9;48.9,58.8;49.7,55.4;51.3,60.1" },
		{ t = "kill", quest = 7081, title = "Alterac Valley Graveyards", map = 1459, x = 51.8, y = 36, era = true, count = 1, target = "PvP Graveyard Credit Marker", oi = 1, mobLevel = 60, note = "assault a graveyard", spots = "51.8,36;51.6,57.1;49.3,76.7;49.3,88.5;42.4,15.6" },
		{ t = "kill", quest = 7102, title = "Towers and Bunkers", map = 1459, x = 48.2, y = 58.7, era = true, count = 1, target = "PvP Tower Credit Marker", oi = 1, note = "Iceblood Tower banner" },
