		{ t = "kill", quest = 7282, title = "Brotherly Love", map = 1459, x = 50.68, y = 65.69, era = true, count = 1, target = "Commander Louis Philips", oi = 1, group = true },
		{ t = "kill", quest = 7301, title = "Fallen Sky Lords", map = 1459, x = 48, y = 84, era = true, count = 1, target = "Trigger Ichman", oi = 1, note = "Wing Commander Ichman's spot" },
		{ t = "kill", quest = 7301, title = "Fallen Sky Lords", map = 1459, x = 50, y = 81, era = true, count = 1, target = "Trigger Vipore", oi = 2, note = "Wing Commander Vipore's spot" },
		{ t = "kill", quest = 7301, title = "Fallen Sky Lords", map = 1459, x = 50, y = 65, era = true, count = 1, target = "Trigger Slidore", oi = 3, note = "Wing Commander Slidore's spot" },
		{ t = "kill", quest = 7367, title = "Defusing the Threat", map = 1459, x = 49.6, y = 82.3, era = true, count = 1, target = "Frostwolf Explosives Expert", oi = 1, group = true },
	} },
	{ title = "Back in Dun Baldar", only = { factions = {"Alliance"} }, goals = {
		{ t = "turnin", quest = 7223, title = "Armor Scraps", npc = "Murgot Deepforge", map = 1459, x = 43.48, y = 15.5, era = true },
