Waypost.RegisterSteps("reputation/argent-dawn", function() return {
	{ title = "Argent Dawn Commission (Alliance)", note = "Argent Officer Pureheart stands in Chillwind Camp, in the south of the Western Plaguelands. The Argent Dawn starts at Neutral 200 for everyone. Wear the Commission trinket while you fight the Scourge: Scourgestones only drop while you wear it. Duke Nicholas Zverenhoff at Light's Hope Chapel gives the same Commission; you can only take one.", only = { factions = {"Alliance"} }, goals = {
		{ t = "accept", quest = 5401, title = "Argent Dawn Commission", npc = "Argent Officer Pureheart", map = 1422, x = 42.97, y = 83.55, era = true, qlvl = 55 },
		{ t = "turnin", quest = 5401, title = "Argent Dawn Commission", npc = "Argent Officer Pureheart", map = 1422, x = 42.97, y = 83.55, era = true },
	} },
	{ title = "Argent Dawn Commission (Horde)", note = "Argent Officer Garush stands at the Bulwark, on the road from Tirisfal Glades into the Western Plaguelands. The Argent Dawn starts at Neutral 200 for everyone. Wear the Commission trinket while you fight the Scourge: Scourgestones only drop while you wear it. Duke Nicholas Zverenhoff at Light's Hope Chapel gives the same Commission; you can only take one.", only = { factions = {"Horde"} }, goals = {
		{ t = "accept", quest = 5405, title = "Argent Dawn Commission", npc = "Argent Officer Garush", map = 1420, x = 83.19, y = 68.45, era = true, qlvl = 55 },
		{ t = "turnin", quest = 5405, title = "Argent Dawn Commission", npc = "Argent Officer Garush", map = 1420, x = 83.19, y = 68.45, era = true },
	} },
	{ title = "Neutral to Friendly: Scourge of the Western Plaguelands", note = "Every Scourge kill in the Plaguelands gives 5 reputation (named ones 15), from the level 50 ghouls and skeletons up; at level 60 pick the level 53 and up ones, since in Classic grey mobs give only about a fifth. Neutral to Friendly is 2,800: about 560 kills, fewer with the Plaguelands quests on the way. The densest Scourge stand around the four Scourge Cauldrons: Felstone Field west of Andorhal (skeletons, 50-53), Dalson's Tears north of Andorhal (zombies and ghouls, 52-55), the Writhing Haunt in the south (ghouls, 54-55) and Gahrron's Withering in the east (ghosts, 56-57). Keep every Scourgestone and every quest you can save: turn-ins never stop counting, kills do. Minion's Scourgestones drop from about four in ten of these Scourge, Invader's from about a third of the level 56 and up ones. If you die, take the Commission off and put it back on: it can lose its effect. Paladins (Human and Dwarf): Commander Ashlam Valorfist at Chillwind Camp asks 20 Minion's Scourgestones once for Dispelling Evil, 100 reputation instead of 25. The Legacy perk Diplomat adds up to 10% to every gain.", goals = {
		{ t = "collect", count = 20, item = 12840, itemName = "Minion's Scourgestone", optional = true, note = "Minion's Scourgestones: keep them" },
		{ t = "kill", map = 1422, x = 60.7, y = 58.3, era = true, target = "Hungering Wraith", mobLevel = 58, optional = true, note = "Hungering Wraiths at Gahrron's Withering; any Scourge counts", spots = "60.7,58.3;63.9,56.9;64.7,59" },
		{ t = "kill", map = 1422, x = 50.26, y = 65.82, era = true, target = "Soulless Ghoul", mobLevel = 55, optional = true, note = "Soulless Ghouls at the Writhing Haunt", spots = "49.5,65.7;48.6,69.1;44.9,69;43.2,67.4;40.3,67.1" },
		{ t = "rep", factionName = "Argent Dawn", faction = 529, standing = 5 },
	} },
	{ title = "Plaguelands quests and the Scourge Cauldrons", note = "The Plaguelands quests pay in full at 60 from level 55 up and never stop counting, about 1,500 in all; the leveling guides walk them. The cauldron chain from High Priestess MacDonnell at Chillwind Camp (Horde: Shadow Priestess Vandis at the Bulwark): 150 per cauldron with its return, then Mission Accomplished! 200. Alas, Andorhal 150 (Araj the Summoner, elite). At Light's Hope Chapel, Carlin Redpath's Darrowshire quests (Brother Carlin 50 from Chromie in Andorhal, Villains of Darrowshire 100, Marauders of Darrowshire 100) and Pamela Redpath's Hidden Treasures 200 at the end of the Darrowshire story; Zaeldarr the Outcast 75 from Caretaker Alen. After Mission Accomplished!, each cauldron takes a repeatable delivery: 25 reputation every time, until Exalted. Alchemist Arbington at Chillwind Camp (Horde: Apothecary Dithers at the Bulwark) gives you a Vitreous Focuser, without which the reagents never drop, and sells Arcane Quickeners for 50 silver (one per delivery; it crumbles after 30 minutes, so buy it last). Each delivery also takes 4 Runecloth. Farm Gahrron's Withering: its ghosts drop an Ectoplasmic Resonator about one time in four, so about 16 kills fill a delivery; the other cauldrons want 5 or 6 reagents that drop one time in ten or less. Once the Plaguelands Scourge stop counting, this earns about four times what their Scourgestones alone do.", goals = {
		{ t = "talk", npc = "Alchemist Arbington", map = 1422, x = 42.66, y = 83.77, era = true, optional = true, only = { factions = {"Alliance"} }, note = "Alchemist Arbington: ask for a Vitreous Focuser" },
		{ t = "talk", npc = "Apothecary Dithers", map = 1420, x = 83.28, y = 69.23, era = true, optional = true, only = { factions = {"Horde"} }, note = "Apothecary Dithers, at the Bulwark: ask for a Vitreous Focuser" },
		{ t = "collect", map = 1422, x = 63.38, y = 58.4, era = true, count = 4, item = 13354, itemName = "Ectoplasmic Resonator", mobLevel = 58, optional = true, note = "Ectoplasmic Resonators: the ghosts around the cauldron", spots = "63.8,56.7;62.1,58.5;64.8,59;62.8,60.6" },
		{ t = "collect", map = 1422, x = 63.64, y = 58.57, era = true, count = 4, item = 14047, itemName = "Runecloth", mobLevel = 56, optional = true, spots = "64.8,59;54.4,65.9;48.1,63.3;45.6,74.3;49.3,82.3" },
		{ t = "buy", npc = "Alchemist Arbington", map = 1422, x = 42.66, y = 83.77, era = true, item = 13320, itemName = "Arcane Quickener", optional = true, only = { factions = {"Alliance"} }, note = "Arcane Quickener, 50 silver" },
		{ t = "buy", npc = "Apothecary Dithers", map = 1420, x = 83.28, y = 69.23, era = true, item = 13320, itemName = "Arcane Quickener", optional = true, only = { factions = {"Horde"} }, note = "Arcane Quickener, 50 silver" },
		{ t = "turnin", quest = 5227, title = "Gahrron's Withering Cauldron", npc = "Scourge Cauldron", map = 1422, x = 62.54, y = 58.47, era = true, qlvl = 58, optional = true, note = "the cauldron at Gahrron's Withering: handed in from its window, never in the log" },
	} },
	{ title = "Light's Hope Chapel quests", note = "Light's Hope Chapel, on the east side of the Eastern Plaguelands, is the Argent Dawn's home: Duke Nicholas Zverenhoff, Betina Bigglezink and Leonid Barthalomew give its dungeon quests, 100 to 200 reputation each and about 1,700 in all. They are group quests for Stratholme and Scholomance (level 58-60, five players): take the ones your group will run. The Duke's chain ends at the Argent Hold, a chest of Argent Dawn gear.", goals = {
		{ t = "level", level = 55 },
		{ t = "accept", quest = 5212, title = "The Flesh Does Not Lie", npc = "Betina Bigglezink", map = 1423, x = 71.66, y = 49.94, qlvl = 60, optional = true, group = true, note = "The Flesh Does Not Lie: Betina Bigglezink" },
		{ t = "accept", quest = 5529, title = "Plagued Hatchlings", npc = "Betina Bigglezink", map = 1423, x = 71.66, y = 49.94, qlvl = 58, optional = true, group = true, note = "Plagued Hatchlings: Betina Bigglezink" },
		{ t = "accept", quest = 5243, title = "Houses of the Holy", npc = "Leonid Barthalomew the Revered", map = 1423, x = 71.89, y = 48.29, qlvl = 60, optional = true, group = true, note = "Houses of the Holy: Leonid Barthalomew" },
		{ t = "accept", quest = 5251, title = "The Archivist", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 60, optional = true, group = true, note = "The Archivist: Duke Nicholas Zverenhoff" },
	} },
	{ title = "Stratholme", note = "Stratholme is a group of five at the north end of the Eastern Plaguelands. Its Scourge give 5 reputation a kill up to the last point of Honored, and its Scourge bosses 25 until Exalted (Baron Rivendare 50), each with a Corruptor's Scourgestone. The Black Guard Sentries by the Baron give 5 until Exalted. The Scourge side, through the service entrance, pays far more than the Scarlet side.", goals = {
		{ t = "goto", map = 1423, x = 26.5, y = 10.4, text = "Stratholme" },
		{ t = "collect", quest = 5212, title = "The Flesh Does Not Lie", map = 1423, x = 26.5, y = 10.4, count = 10, item = 13174, itemName = "Plagued Flesh Sample", oi = 1, group = true, note = "Plagued Flesh Samples: the Scourge inside" },
		{ t = "collect", quest = 5243, title = "Houses of the Holy", map = 1423, x = 26.5, y = 10.4, count = 5, item = 13180, itemName = "Stratholme Holy Water", oi = 1, group = true, note = "Stratholme Holy Water: the supply crates" },
		{ t = "kill", quest = 5251, title = "The Archivist", map = 1423, x = 26.5, y = 10.4, count = 1, target = "Archivist Galford", oi = 1, group = true, note = "Archivist Galford, Scarlet side" },
	} },
	{ title = "Scholomance", note = "Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands; your side's Scholomance quests give the Skeleton Key that opens it. It is the best Argent Dawn run: its mobs give 5 up to the last point of Honored, and its thirteen bosses about 375 reputation a full clear plus ten or so Corruptor's Scourgestones (about 250 more). Ras Frostwhisper and Darkmaster Gandling give 50 each.", goals = {
		{ t = "goto", map = 1422, x = 69.7, y = 73.2, era = true, text = "Scholomance" },
		{ t = "kill", quest = 5529, title = "Plagued Hatchlings", map = 1422, x = 69.7, y = 73.2, era = true, count = 20, target = "Plagued Hatchling", oi = 1, group = true, note = "Plagued Hatchlings, in the hatchery" },
	} },
	{ title = "Back at Light's Hope Chapel", note = "The Flesh Does Not Lie leads to The Active Agent (the Scourge Data in a Stratholme ziggurat), which rewards the Seal of the Dawn or the Rune of the Dawn: better trinkets that also make Scourgestones drop, so they can replace the Commission. The Archivist leads on to the Head of Balnazzar and Baron Rivendare. A Healthy Dragon Scale, a rare drop (about 6%) from the Plagued Hatchlings once Plagued Hatchlings is done, starts a quest worth 50 each time: keep them until Revered. Tinkee Steamboil in the Burning Steppes, at the end of her Blackrock Spire quests, sends you to Leonid Barthalomew (75) and on to Betina's Dawn's Gambit in Scholomance (25 and 200).", goals = {
		{ t = "turnin", quest = 5212, title = "The Flesh Does Not Lie", npc = "Betina Bigglezink", map = 1423, x = 71.66, y = 49.94, group = true },
		{ t = "accept", quest = 5213, title = "The Active Agent", npc = "Betina Bigglezink", map = 1423, x = 71.66, y = 49.94, qlvl = 60, optional = true, group = true },
		{ t = "turnin", quest = 5529, title = "Plagued Hatchlings", npc = "Betina Bigglezink", map = 1423, x = 71.66, y = 49.94, group = true },
		{ t = "turnin", quest = 5243, title = "Houses of the Holy", npc = "Leonid Barthalomew the Revered", map = 1423, x = 71.89, y = 48.29, group = true },
		{ t = "turnin", quest = 5251, title = "The Archivist", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, group = true },
	} },
	{ title = "Friendly to Honored: stones and named Scourge", note = "Normal Scourge outside the dungeons stop giving reputation halfway through Friendly (3,000 of 6,000); Lord Darkscythe, Hed'mush and Gish stop at the end of Friendly. After that only Araj, the Scholomance and Stratholme mobs, the cauldron deliveries and Scourgestones count. Now turn in the stones you saved: Duke Nicholas Zverenhoff at Light's Hope Chapel takes all three kinds, and so do the officers at Chillwind Camp and the Bulwark. Every turn-in pays 25 and an Argent Dawn Valor Token: keep 35 tokens for the mantles at Revered and Exalted. Invader's Scourgestones are worth twice as much per stone: the Dark Adepts, Shadowmages, Dread Weavers and Scourge Champions (level 58-60) at Northdale, just north of Light's Hope Chapel, drop them about a third of the time or more, next to the turn-in. The named Scourge below drop a Corruptor's Scourgestone half the time or more (Putridius two times in three, Araj and Hed'mush half the time) and give 15 a kill, Araj until Exalted; Putridius gives no reputation, only the stone. Friendly opens the Enriched Manna Biscuits (60 silver) at the quartermasters.", goals = {
		{ t = "collect", count = 10, item = 12841, itemName = "Invader's Scourgestone", optional = true, note = "Invader's Scourgestones" },
		{ t = "collect", map = 1423, x = 65.23, y = 43.94, count = 1, item = 12843, itemName = "Corruptor's Scourgestone", mobLevel = 57, optional = true, note = "Corruptor's Scourgestone: the named Scourge below, and dungeon bosses", spots = "65.2,43.9;58.8,41.5;48.2,18.7;22,25.8;34,64.1" },
		{ t = "kill", map = 1423, x = 73.6, y = 34.1, target = "Dark Adept", mobLevel = 59, optional = true, note = "Dark Adepts and Shadowmages at Northdale", spots = "73.6,34.1;73.3,31.8;75.5,36.6;72.1,38.2;57.9,30" },
		{ t = "kill", map = 1422, x = 45.27, y = 69.21, era = true, target = "Araj the Summoner", optional = true, group = true, note = "Araj the Summoner, Andorhal" },
		{ t = "kill", map = 1422, x = 48.05, y = 67.39, era = true, target = "Putridius", optional = true, group = true, note = "Putridius, Western Plaguelands: the stone only" },
		{ t = "kill", map = 1423, x = 21.95, y = 25.76, target = "Lord Darkscythe", optional = true, note = "Lord Darkscythe, Eastern Plaguelands" },
		{ t = "kill", map = 1423, x = 48.16, y = 18.65, target = "Hed'mush the Rotting", mobLevel = 57, optional = true, note = "Hed'mush the Rotting, Eastern Plaguelands", spots = "48.2,18.7;58.8,41.5;34,64.1" },
		{ t = "kill", map = 1423, x = 65.23, y = 43.94, target = "Gish the Unmoving", optional = true, note = "Gish the Unmoving, Eastern Plaguelands" },
		{ t = "turnin", quest = 5510, title = "Minion's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true, note = "Minion's Scourgestones: 20 for 25 reputation" },
		{ t = "turnin", quest = 5509, title = "Invader's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true, note = "Invader's Scourgestones: 10 for 25 reputation" },
		{ t = "turnin", quest = 5508, title = "Corruptor's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true, note = "Corruptor's Scourgestones: 1 for 25 reputation" },
		{ t = "rep", factionName = "Argent Dawn", faction = 529, standing = 6 },
	} },
	{ title = "Honored to Revered: dungeons and stones", note = "Honored to Revered is 12,000: about 2,400 Scholomance and Stratholme mobs, fewer with their bosses. Their mobs stop at 11,999 of 12,000 Honored; a boss or a turn-in takes you over. Solo, only Scourgestones, the cauldron deliveries and Araj count: 12,000 is 480 turn-ins, or 4,800 Invader's Scourgestones. Keep the stones you get in the dungeons until their mobs stop counting. Honored opens recipes at all three quartermasters: Quartermaster Miranda Breechlock at Light's Hope Chapel, Argent Quartermaster Lightspark at Chillwind Camp, Argent Quartermaster Hasana at the Bulwark. Also the Hallowed Brazier (133 gold) for the Three Kings of Flame quest.", goals = {
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19446, itemName = "Formula: Enchant Bracer - Mana Regeneration", optional = true, note = "Formula: Enchant Bracer - Mana Regeneration, 3 gold" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19216, itemName = "Pattern: Argent Boots", optional = true, note = "Pattern: Argent Boots (Tailoring), 2 gold 20 silver" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19328, itemName = "Pattern: Dawn Treaders", optional = true, note = "Pattern: Dawn Treaders (Leatherworking), 2 gold 20 silver" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19203, itemName = "Plans: Girdle of the Dawn", optional = true, note = "Plans: Girdle of the Dawn (Blacksmithing), 2 gold 20 silver" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 13482, itemName = "Recipe: Transmute Air to Fire", optional = true, note = "Recipe: Transmute Air to Fire (Alchemy), 1 gold 50 silver" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19442, itemName = "Formula: Powerful Anti-Venom", optional = true, note = "Formula: Powerful Anti-Venom (First Aid), 10 gold" },
		{ t = "turnin", quest = 5510, title = "Minion's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true },
		{ t = "turnin", quest = 5509, title = "Invader's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true },
		{ t = "turnin", quest = 5508, title = "Corruptor's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true },
		{ t = "rep", factionName = "Argent Dawn", faction = 529, standing = 7 },
	} },
	{ title = "Mantles of the Dawn", note = "At Revered, Quartermaster Miranda Breechlock takes 10 Argent Dawn Valor Tokens for Mantles of the Dawn (100 reputation). After it, any Argent Dawn quartermaster sells the five shoulder enchants for 10 gold each: Flame, Frost, Arcane, Nature and Shadow Mantle of the Dawn, +5 to that resistance. Revered also opens the Blessed Sunfruit and its juice (60 silver) and the Revered recipes.", goals = {
		{ t = "collect", map = 1423, x = 71.6, y = 50.1, era = true, count = 10, item = 12844, itemName = "Argent Dawn Valor Token", optional = true, note = "Argent Dawn Valor Tokens, from the stone turn-ins" },
		{ t = "accept", quest = 5513, title = "Mantles of the Dawn", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, qlvl = 60 },
		{ t = "turnin", quest = 5513, title = "Mantles of the Dawn", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25 },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 18170, itemName = "Frost Mantle of the Dawn", optional = true, note = "Frost Mantle of the Dawn: pick the resistance you need, 10 gold" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19447, itemName = "Formula: Enchant Bracer - Healing", optional = true, note = "Formula: Enchant Bracer - Healing, 6 gold" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19217, itemName = "Pattern: Argent Shoulders", optional = true, note = "Pattern: Argent Shoulders (Tailoring), 4 gold" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19329, itemName = "Pattern: Golden Mantle of the Dawn", optional = true, note = "Pattern: Golden Mantle of the Dawn (Leatherworking), 4 gold" },
		{ t = "buy", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, item = 19205, itemName = "Plans: Gloves of the Dawn", optional = true, note = "Plans: Gloves of the Dawn (Blacksmithing), 4 gold" },
	} },
	{ title = "Revered to Exalted", note = "Revered to Exalted is 21,000: 840 Scourgestone or cauldron turn-ins, or the dungeon bosses with their Corruptor's Scourgestones (a full Scholomance clear is about 600). Turn in every stone and Healthy Dragon Scale you saved.", goals = {
		{ t = "turnin", quest = 5510, title = "Minion's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true },
		{ t = "turnin", quest = 5509, title = "Invader's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true },
		{ t = "turnin", quest = 5508, title = "Corruptor's Scourgestones", npc = "Duke Nicholas Zverenhoff", map = 1423, x = 71.63, y = 50.09, qlvl = 55, optional = true },
		{ t = "rep", factionName = "Argent Dawn", faction = 529, standing = 8 },
	} },
	{ title = "Chromatic Mantle of the Dawn", note = "At Exalted, Quartermaster Miranda Breechlock takes 25 Argent Dawn Valor Tokens for the Chromatic Mantle of the Dawn (150 reputation): +5 to every resistance, on your shoulders. After it, the quartermasters sell more for 40 gold each.", goals = {
		{ t = "collect", map = 1423, x = 71.6, y = 50.1, era = true, count = 25, item = 12844, itemName = "Argent Dawn Valor Token", optional = true, note = "Argent Dawn Valor Tokens" },
		{ t = "accept", quest = 5517, title = "Chromatic Mantle of the Dawn", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25, qlvl = 60 },
		{ t = "turnin", quest = 5517, title = "Chromatic Mantle of the Dawn", npc = "Quartermaster Miranda Breechlock", map = 1423, x = 71.79, y = 50.25 },
	} },
} end)

Waypost.RegisterSteps("reputation/bloodsail-buccaneers", function() return {
	{ title = "Before you start", note = "Bloodsail standing goes up only by killing the people of Booty Bay, and every kill costs you Booty Bay 125 and the other goblin towns (Gadgetzan, Ratchet, Everlook, and in Forever likely Powderfuse) about 62 each. After the Bruisers this guide asks for, every goblin town is Hated: their guards attack you, and you lose their flight masters, inns, vendors and Gadgetzan's and Everlook's auction houses. Getting back takes longer than getting here (last step). Fly in, bind elsewhere, and do your goblin-town business first. The outfit and the hat need only Friendly; past that Bloodsail has nothing to give. Booty Bay's guards are not your enemies yet: tick At War for Booty Bay in your reputation panel, then attack.", goals = {
		{ t = "goto", map = 1434, x = 27, y = 77.1, era = true, text = "Booty Bay" },
	} },
	{ title = "Booty Bay Bruisers to Neutral", note = "Look at your Bloodsail bar first. A new character starts Hated, 500 short of Hostile: 260 Bruisers to Neutral, at 25 each. But every Booty Bay quest you did while leveling took five times its Booty Bay reward off Bloodsail (An OOX of Your Own, Stranglethorn Fever and Facing Negolash 1,000 each), and every Bloodsail pirate you killed 25 more: after Booty Bay's quests you sit near the bottom of Hated, up to 1,680 Bruisers from Neutral. Divide what the bar still lacks to Hostile, plus 6,000, by 25. Bruisers (level 57) hit hard, net you and knock you back, and new ones come when a goblin calls for help. Fight on the path that turns left from the tunnel up to the blacksmith's house: two Bruisers patrol it and rarely meet. Once they are down, step into the house (or hit one of the goblins inside) and a fresh Bruiser comes running. Players manage 30 to 40 an hour. Booty Bay is Hated after about 53 Bruisers from a fresh Neutral 500. At the New Year celebration the town's goblins are drunk and do not fight back. The Blackwater crew at Faldir's Cove in the Arathi Highlands (level 37-40) are easier but pay only 5 each. Do not kill Bloodsail pirates: each costs 25.", goals = {
		{ t = "goto", map = 1434, x = 29, y = 75.6, era = true, text = "the path to the smithy" },
		{ t = "kill", map = 1434, x = 28.75, y = 75.4, era = true, target = "Booty Bay Bruiser", mobLevel = 57, optional = true, note = "Booty Bay Bruiser: +25", spots = "28.2,74.9;27.6,77.2;29.5,72.4;26.3,73.4" },
		{ t = "rep", factionName = "Bloodsail Buccaneers", faction = 87, standing = 4 },
	} },
	{ title = "Dressing the Part", note = "At Neutral the Bloodsail crew stop attacking you. Fleet Master Firallon is aboard the Crimson Veil, the pirate ship anchored south of Booty Bay, on its middle deck. Swim out; take the quest and hand it in on the spot for the Buccaneer's Uniform: the Bloodsail Shirt, Sash, Pants and Boots.", goals = {
		{ t = "accept", quest = 9272, title = "Dressing the Part", npc = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, era = true, qlvl = 55 },
		{ t = "turnin", quest = 9272, title = "Dressing the Part", npc = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, era = true, note = "Fleet Master Firallon: the Buccaneer's Uniform" },
	} },
	{ title = "Bruisers to Friendly", note = "Neutral to Friendly is 3,000 more: 120 Bruisers. Friendly is the last standing that unlocks anything.", goals = {
		{ t = "goto", map = 1434, x = 29, y = 75.6, era = true, text = "the path to the smithy" },
		{ t = "kill", map = 1434, x = 28.75, y = 75.4, era = true, target = "Booty Bay Bruiser", mobLevel = 57, optional = true, note = "Booty Bay Bruiser: +25", spots = "28.2,74.9;27.6,77.2;29.5,72.4;26.3,73.4" },
		{ t = "rep", factionName = "Bloodsail Buccaneers", faction = 87, standing = 5 },
	} },
	{ title = "Avast Ye, Scallywag", note = "\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of Booty Bay. Booty Bay players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while Booty Bay is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with Booty Bay.", goals = {
		{ t = "accept", quest = 1036, title = "Avast Ye, Scallywag", npc = "\"Pretty Boy\" Duncan", map = 1434, x = 27.39, y = 69.42, era = true, qlvl = 60 },
		{ t = "turnin", quest = 1036, title = "Avast Ye, Scallywag", npc = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, era = true, note = "Fleet Master Firallon, on the Crimson Veil: 25" },
		{ t = "accept", quest = 4621, title = "Avast Ye, Admiral!", npc = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, era = true, qlvl = 60 },
	} },
	{ title = "Avast Ye, Admiral!", note = "Baron Revilgaz and Fleet Master Seahorn stand on the top floor of the Booty Bay inn, out on the balcony. Both are level 60 and Bruisers come to their aid: clear the stairs first and pull them one at a time. They come back, so a friend can kill them too.", goals = {
		{ t = "kill", quest = 4621, title = "Avast Ye, Admiral!", map = 1434, x = 27.23, y = 76.87, era = true, count = 1, target = "Baron Revilgaz", oi = 1 },
		{ t = "kill", quest = 4621, title = "Avast Ye, Admiral!", map = 1434, x = 27.17, y = 77.01, era = true, count = 1, target = "Fleet Master Seahorn", oi = 2 },
	} },
	{ title = "The Admiral's Hat", note = "Back to Firallon for the Bloodsail Admiral's Hat (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less Booty Bay. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the Badlands, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached.", goals = {
		{ t = "turnin", quest = 4621, title = "Avast Ye, Admiral!", npc = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, era = true, note = "Fleet Master Firallon: Bloodsail Admiral's Hat" },
	} },
	{ title = "The way back", note = "Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside Ratchet, Booty Bay, Gadgetzan and Everlook, so the climb back is the Cartel's own: Zorbin Fandazzle in Feralas serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give Booty Bay 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did.", goals = {
		{ t = "talk", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, optional = true, note = "Zorbin Fandazzle: Zapped Giants, open to the Hated" },
	} },
} end)

Waypost.RegisterSteps("reputation/brood-of-nozdormu", function() return {
	{ title = "Baristolth in Cenarion Hold", note = "The Brood of Nozdormu is not in your reputation list until you meet Anachronos. Baristolth of the Shifting Sands, in the main building of Cenarion Hold, sends you to him. Meeting him sets you at Hated, 0 of 36,000: Neutral is 42,000 reputation away, and almost all of it comes from raids. Blackwing Lair and the Temple of Ahn'Qiraj are not among the first raids Blizzard has announced for Forever: until one of them opens, the 100 from Baristolth's first quest is all the Brood reputation there is. The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it.", goals = {
		{ t = "getfp", location = "Cenarion Hold" },
		{ t = "accept", quest = 8286, title = "What Tomorrow Brings", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, qlvl = 60 },
	} },
	{ title = "Anachronos at the Caverns of Time", note = "Anachronos, a bronze dragon in elf form, stands at the mouth of the Caverns of Time in eastern Tanaris, south-east of Gadgetzan. Walk up to him.", goals = {
		{ t = "complete", quest = 8286, title = "What Tomorrow Brings", map = 1446, x = 65.3, y = 50, era = true, note = "Meet Anachronos", objs = {"Anachronos", "Discover the Brood of Nozdormu."} },
	} },
	{ title = "Back to Baristolth", note = "Only One May Rise wants the head of Broodlord Lashlayer, the third boss of Blackwing Lair (a 40-player raid in Blackrock Mountain). Everything after it needs the head, the fragment turn-ins included: until you have it, What Tomorrow Brings is all the Brood reputation there is, solo or not.", goals = {
		{ t = "turnin", quest = 8286, title = "What Tomorrow Brings", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, note = "100" },
		{ t = "accept", quest = 8288, title = "Only One May Rise", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, qlvl = 60, optional = true, group = true },
	} },
	{ title = "Broodlord Lashlayer", note = "Blackwing Lair is a 40-player raid at the top of Blackrock Mountain. Broodlord Lashlayer always drops his head.", goals = {
		{ t = "collect", quest = 8288, title = "Only One May Rise", map = 1428, x = 32.5, y = 32.4, era = true, count = 1, item = 20383, itemName = "Head of the Broodlord Lashlayer", oi = 1, optional = true, group = true, note = "Head of the Broodlord Lashlayer: raid of 40" },
	} },
	{ title = "The Path of the Righteous", note = "The Path of the Righteous wants 200 Silithid Carapace Fragments. Every hive silithid drops one to three on most kills: the Hive'Ashi Workers, Stingers, Swarmers and Defenders north and north-west of Cenarion Hold, and those of Hive'Zora in the west and Hive'Regal in the south. Almost all of them are elites of level 57 to 60: one at a time solo, faster in a group.", goals = {
		{ t = "turnin", quest = 8288, title = "Only One May Rise", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, optional = true, group = true, note = "200" },
		{ t = "accept", quest = 8301, title = "The Path of the Righteous", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, qlvl = 60, optional = true },
		{ t = "collect", quest = 8301, title = "The Path of the Righteous", map = 1451, x = 37.1, y = 62.1, era = true, count = 200, item = 20384, itemName = "Silithid Carapace Fragment", oi = 1, mobLevel = 59, optional = true, spots = "37.1,62.1;33.2,68.4;27.2,69.4;27.9,61.3;26.6,58.5" },
		{ t = "turnin", quest = 8301, title = "The Path of the Righteous", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, optional = true, note = "200" },
	} },
	{ title = "Hated to Neutral", note = "After The Path, Baristolth takes 200 more fragments for The Hand of the Righteous: 200 reputation, again and again, but only until Neutral. From Hated 500 that is 208 turn-ins, 41,600 fragments, 20,000 to 30,000 elite kills: the only way without the Temple, and a very long one. With the Temple of Ahn'Qiraj open (a 40-player raid) it is far quicker: every Temple trash mob gives 100 until 2,999 of 3,000 Neutral, about 9,500 a full clear, so four to five clears reach Neutral. Save every Ancient Qiraji Artifact and Qiraji Lord's Insignia you loot until the trash stops counting: they pay the same later.", goals = {
		{ t = "collect", map = 1451, x = 37.1, y = 62.1, era = true, count = 200, item = 20384, itemName = "Silithid Carapace Fragment", mobLevel = 59, optional = true, spots = "37.1,62.1;33.2,68.4;27.2,69.4;27.9,61.3;26.6,58.5" },
		{ t = "turnin", quest = 8302, title = "The Hand of the Righteous", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, qlvl = 60, optional = true, note = "The Hand of the Righteous: 200 fragments, 200" },
		{ t = "rep", factionName = "Brood of Nozdormu", faction = 910, standing = 4 },
	} },
	{ title = "Anachronos's quests", note = "Neutral opens the rest of the Scepter of the Shifting Sands chain. Baristolth sends you back to Anachronos.", goals = {
		{ t = "accept", quest = 8303, title = "Anachronos", npc = "Baristolth of the Shifting Sands", map = 1451, x = 49.45, y = 36.45, era = true, qlvl = 60 },
	} },
	{ title = "Long Forgotten Memories", goals = {
		{ t = "turnin", quest = 8303, title = "Anachronos", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, note = "Anachronos: 200" },
		{ t = "accept", quest = 8305, title = "Long Forgotten Memories", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60 },
	} },
	{ title = "The Crystalline Tear", note = "The Crystalline Tear is a small red crystal on the ground just outside the gates of Ahn'Qiraj, in the far south-west of Silithus. Click it, then stay and watch the vision of the War of the Shifting Sands to its end. If it is cut short, abandon the quest and click the Tear again.", goals = {
		{ t = "turnin", quest = 8305, title = "Long Forgotten Memories", npc = "Crystalline Tear", map = 1451, x = 28.68, y = 89.14, era = true, note = "Crystalline Tear: 50" },
		{ t = "accept", quest = 8519, title = "A Pawn on the Eternal Board", npc = "Crystalline Tear", map = 1451, x = 28.68, y = 89.14, era = true, qlvl = 60 },
		{ t = "complete", quest = 8519, title = "A Pawn on the Eternal Board", map = 1451, x = 28.7, y = 89.1, era = true, note = "Watch the vision", objs = {"The War of the Shifting Sands"} },
	} },
	{ title = "The Charge of the Dragonflights", note = "Anachronos now offers the Signet Ring of the Bronze Dragonflight in three kinds: the Path of the Protector (tanks), of the Conqueror (melee fighters) or of the Invoker (casters). Take one: the other two close. Each standing from Friendly to Exalted brings an upgrade of the same ring, 100 reputation each. The Charge of the Dragonflights sends you after the three shards of the Scepter of the Shifting Sands.", goals = {
		{ t = "turnin", quest = 8519, title = "A Pawn on the Eternal Board", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, note = "100" },
		{ t = "accept", quest = 8555, title = "The Charge of the Dragonflights", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60 },
		{ t = "turnin", quest = 8555, title = "The Charge of the Dragonflights", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, note = "10" },
		{ t = "talk", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Pick one: The Path of the Protector, the Conqueror or the Invoker, 100" },
	} },
	{ title = "The red shard: Vaelastrasz", note = "The red shard: Vaelastrasz the Corrupt, the second boss of Blackwing Lair, gives Nefarius's Corruption before his fight; Nefarian, the last boss, drops the Red Scepter Shard for one raider on the quest each kill. The quest lasts five hours.", goals = {
		{ t = "accept", quest = 8730, title = "Nefarius's Corruption", npc = "Vaelastrasz the Corrupt", map = 1428, x = 32.5, y = 32.4, era = true, qlvl = 60, optional = true, group = true, note = "Vaelastrasz the Corrupt, Blackwing Lair: raid of 40" },
		{ t = "collect", quest = 8730, title = "Nefarius's Corruption", map = 1428, x = 32.5, y = 32.4, era = true, count = 1, item = 21138, itemName = "Red Scepter Shard", oi = 1, optional = true, group = true, note = "Red Scepter Shard, Nefarian" },
	} },
	{ title = "The blue shard: Azuregos's ledger", note = "The Spirit of Azuregos stands on the south coast of Azshara. His ledger starts Narain Soothfancy's long chain in Tanaris.", goals = {
		{ t = "accept", quest = 8575, title = "Azuregos's Magical Ledger", npc = "Spirit of Azuregos", map = 1447, x = 52.98, y = 81.73, era = true, qlvl = 60, optional = true },
	} },
	{ title = "Narain Soothfancy", note = "Narain Soothfancy, a goblin seer, lives in a hut north-east of Gadgetzan. He sends you three ways at once: to Stewvul's crate in Silverpine Forest, to an island off the south coast of Tanaris, and to Dirge Quikcleave in Gadgetzan.", goals = {
		{ t = "turnin", quest = 8575, title = "Azuregos's Magical Ledger", npc = "Narain Soothfancy", map = 1446, x = 65.24, y = 18.58, era = true, optional = true, note = "10" },
