	} },
	{ title = "Stewvul's crate", note = "The Inconspicuous Crate leans on the Greymane Wall at the south end of Silverpine Forest, left of the closed gate.", goals = {
		{ t = "turnin", quest = 8577, title = "Stewvul, Ex-B.F.F.", npc = "Inconspicuous Crate", map = 1421, x = 46.19, y = 86.68, era = true, optional = true, note = "Inconspicuous Crate: 10" },
