	} },
	{ title = "Meridith the Mermaiden", note = "The Freshly Dug Dirt lies on the farther of two islands south of Land's End Beach, past the fatigue line. Meridith the Mermaiden, on the sea floor south of the beach's crashed gyrocopter, gives Love Song for Narain and a three-minute swim-speed blessing that gets you across.", goals = {
		{ t = "accept", quest = 8599, title = "Love Song for Narain", npc = "Meridith the Mermaiden", map = 1446, x = 59.43, y = 96.05, era = true, qlvl = 60, optional = true },
