	} },
	{ title = "Keeper Remulos", note = "The Nightmare's Corruption wants a fragment from each of the four Dragons of Nightmare portals: elite dragonkin at the Ashenvale, Feralas and Hinterlands portals (5% each) and the Twilight Corrupter in Duskwood. Raid content.", goals = {
		{ t = "turnin", quest = 8734, title = "Tyrande and Remulos", npc = "Keeper Remulos", map = 1450, x = 36.18, y = 41.79, era = true, optional = true, note = "10 (and 100 Cenarion Circle)" },
