	} },
	{ title = "The Scepter of the Shifting Sands", note = "With the three shards, Anachronos makes the Scepter of the Shifting Sands. In Classic its first holder rings the Scarab Gong once for the whole realm, opening the gates of Ahn'Qiraj, and those who finish within ten hours earn the black qiraji crystal mount; whether Forever's realms get that event is not known.", goals = {
		{ t = "turnin", quest = 8730, title = "Nefarius's Corruption", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, group = true, note = "Red Scepter Shard: 200" },
		{ t = "turnin", quest = 8729, title = "The Wrath of Neptulon", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Blue Scepter Shard: 200" },
		{ t = "turnin", quest = 8741, title = "The Champion Returns", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Green Scepter Shard: 100" },
		{ t = "accept", quest = 8742, title = "The Might of Kalimdor", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, qlvl = 60, optional = true },
		{ t = "turnin", quest = 8742, title = "The Might of Kalimdor", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "200 (and 200 Cenarion Circle)" },
	} },
	{ title = "The Scarab Gong", note = "The Scarab Gong hangs before the gates of Ahn'Qiraj. Jonathan the Revelator appears beside it once the gong has been rung, with Treasure of the Timeless One: a weapon and 200 reputation.", goals = {
		{ t = "accept", quest = 8743, title = "Bang a Gong!", npc = "The Scarab Gong", map = 1451, x = 25.72, y = 90.86, era = true, qlvl = 60, optional = true },
		{ t = "turnin", quest = 8743, title = "Bang a Gong!", npc = "The Scarab Gong", map = 1451, x = 25.72, y = 90.86, era = true, optional = true, note = "200 (and 200 Cenarion Circle)" },
		{ t = "accept", quest = 8745, title = "Treasure of the Timeless One", npc = "Jonathan the Revelator", map = 1451, x = 25.94, y = 90.96, era = true, qlvl = 60, optional = true },
		{ t = "turnin", quest = 8745, title = "Treasure of the Timeless One", npc = "Jonathan the Revelator", map = 1451, x = 25.94, y = 90.96, era = true, optional = true, note = "200" },
	} },
	{ title = "Neutral to Friendly in the Temple", note = "Neutral to Friendly is 3,000 reputation. Every trash mob of the Temple of Ahn'Qiraj (a 40-player raid behind the Scarab Wall) gives 100, and the Twin Emperors 210 each, until 2,999 of 3,000 Neutral, one point short of Friendly; there they stop. Then hand in one saved Ancient Qiraji Artifact (1,000, to Andorgos) or Qiraji Lord's Insignia (500, to Kandrostrasz) to tip you over. The shoulder and boot exchanges of the Temple's tier set need no standing: the token, two idols and ten scarabs to Andorgos (shoulders) or Kandrostrasz (boots) pay 200 each. The Ruins of Ahn'Qiraj (20 players) give a little from bosses: Kurinnaxx, Moam, Buru and Ayamiss 50 each, Rajaxx 34, Ossirian 100, to Exalted.", goals = {
		{ t = "accept", quest = 8784, title = "Secrets of the Qiraji", map = 1451, x = 29, y = 92.8, era = true, item = 21230, itemName = "Ancient Qiraji Artifact", qlvl = 60, optional = true, group = true },
		{ t = "turnin", quest = 8784, title = "Secrets of the Qiraji", npc = "Andorgos", map = 1451, x = 29, y = 92.8, era = true, optional = true, group = true, note = "Andorgos: 1,000" },
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21229, itemName = "Qiraji Lord's Insignia", optional = true, group = true, note = "Qiraji Lord's Insignia, Temple bosses" },
		{ t = "turnin", quest = 8579, title = "Mortal Champions", npc = "Kandrostrasz", map = 1451, x = 29, y = 92.8, era = true, qlvl = 60, optional = true, group = true, note = "Kandrostrasz: 500, handed in from his window" },
		{ t = "rep", factionName = "Brood of Nozdormu", faction = 910, standing = 5 },
	} },
	{ title = "The ring at Friendly", note = "At Friendly, Anachronos upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation.", goals = {
		{ t = "talk", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Anachronos: the Friendly ring quest of your path" },
	} },
	{ title = "Friendly to Honored: the turn-ins", note = "Now hand in what you saved. Each Ancient Qiraji Artifact (any Temple trash, 1% to 9%) starts Secrets of the Qiraji: 1,000 reputation from Andorgos, one of the three bronze dragons inside the Temple. Each Qiraji Lord's Insignia (nearly every Temple boss) goes to Kandrostrasz for Mortal Champions: 500 here and 100 Cenarion Circle. C'Thun gives 2,500, to Exalted. Friendly to Honored is 6,000: six artifacts or twelve insignias. Friendly also opens the helm and leg exchanges of the Temple's tier set (200 reputation each) at Andorgos and Kandrostrasz.", goals = {
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21230, itemName = "Ancient Qiraji Artifact", optional = true, group = true, note = "Ancient Qiraji Artifact: right-click it, then Andorgos" },
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21229, itemName = "Qiraji Lord's Insignia", optional = true, group = true },
		{ t = "turnin", quest = 8595, title = "Mortal Champions", npc = "Kandrostrasz", map = 1451, x = 29, y = 92.8, era = true, qlvl = 60, optional = true, group = true, note = "Mortal Champions: 1 insignia, 500" },
		{ t = "rep", factionName = "Brood of Nozdormu", faction = 910, standing = 6 },
	} },
	{ title = "The ring at Honored", note = "At Honored, Anachronos upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation.", goals = {
		{ t = "talk", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Anachronos: the Honored ring quest of your path" },
	} },
	{ title = "Honored to Revered", note = "Honored to Revered is 12,000: twelve artifacts, 24 insignias, or a mix with C'Thun (2,500). After the first, each insignia is the repeatable Mortal Champions. Every Temple boss sometimes drops an Imperial Qiraji Armaments or Regalia (about one time in twenty): Arygos and Merithra of the Dream, inside the Temple once C'Thun is dead, take it with 3 Elementium Ore for 200 and a weapon. Honored opens the chest exchange of the tier set (200).", goals = {
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21229, itemName = "Qiraji Lord's Insignia", optional = true, group = true },
		{ t = "turnin", quest = 8595, title = "Mortal Champions", npc = "Kandrostrasz", map = 1451, x = 29, y = 92.8, era = true, qlvl = 60, optional = true, group = true, note = "Mortal Champions: 1 insignia, 500" },
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21232, itemName = "Imperial Qiraji Armaments", optional = true, group = true },
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21237, itemName = "Imperial Qiraji Regalia", optional = true, group = true },
		{ t = "collect", map = 1428, x = 32.5, y = 32.4, era = true, count = 3, item = 18562, itemName = "Elementium Ore", optional = true, group = true, note = "Elementium Ore, Blackwing Lair or the auction house" },
		{ t = "turnin", quest = 8789, title = "Imperial Qiraji Armaments", npc = "Arygos", map = 1451, x = 29, y = 92.8, era = true, qlvl = 60, optional = true, group = true, note = "Arygos: Armaments and 3 Elementium Ore, 200" },
		{ t = "turnin", quest = 8790, title = "Imperial Qiraji Regalia", npc = "Merithra of the Dream", map = 1451, x = 29, y = 92.8, era = true, qlvl = 60, optional = true, group = true, note = "Merithra of the Dream: Regalia and 3 Elementium Ore, 200" },
		{ t = "rep", factionName = "Brood of Nozdormu", faction = 910, standing = 7 },
	} },
	{ title = "The ring at Revered", note = "At Revered, Anachronos upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation.", goals = {
		{ t = "talk", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Anachronos: the Revered ring quest of your path" },
	} },
	{ title = "Revered to Exalted", note = "Revered to Exalted is 21,000: 21 artifacts or 42 insignias, with C'Thun's 2,500 a week. C'Thun's eye starts C'Thun's Legacy for Caelestrasz (200, and 200 Cenarion Circle). At Exalted Anachronos gives the last ring: The Protector of Kalimdor, The Qiraji Conqueror or The Grand Invoker.", goals = {
		{ t = "collect", map = 1451, x = 29, y = 92.8, era = true, item = 21229, itemName = "Qiraji Lord's Insignia", optional = true, group = true },
		{ t = "turnin", quest = 8595, title = "Mortal Champions", npc = "Kandrostrasz", map = 1451, x = 29, y = 92.8, era = true, qlvl = 60, optional = true, group = true, note = "Mortal Champions: 1 insignia, 500" },
		{ t = "accept", quest = 8801, title = "C'Thun's Legacy", map = 1451, x = 29, y = 92.8, era = true, item = 21221, itemName = "Eye of C'Thun", qlvl = 60, optional = true, group = true },
		{ t = "turnin", quest = 8801, title = "C'Thun's Legacy", npc = "Caelestrasz", map = 1451, x = 29, y = 92.8, era = true, optional = true, group = true, note = "Caelestrasz: 200" },
		{ t = "rep", factionName = "Brood of Nozdormu", faction = 910, standing = 8 },
	} },
	{ title = "The Exalted ring", note = "At Exalted, Anachronos gives the last ring of your path: The Protector of Kalimdor, The Qiraji Conqueror or The Grand Invoker. Bring the Revered ring; 100 reputation.", goals = {
		{ t = "talk", npc = "Anachronos", map = 1446, x = 65.27, y = 50.03, era = true, optional = true, note = "Anachronos: the Exalted ring quest of your path" },
	} },
} end)

Waypost.RegisterSteps("reputation/cenarion-circle", function() return {
	{ title = "The emissary in Ironforge", note = "Optional, and needed only for the Dredge quests later: Cenarion Emissary Jademoon sends you to Silithus with Taking Back Silithus, a 10-reputation letter. Skip it if you are already in Silithus.", only = { factions = {"Alliance"} }, goals = {
		{ t = "accept", quest = 8275, title = "Taking Back Silithus", npc = "Cenarion Emissary Jademoon", map = 1455, x = 58.54, y = 47.32, era = true, qlvl = 55, optional = true },
	} },
	{ title = "The emissary in Orgrimmar", note = "Optional, and needed only for the Dredge quests later: Cenarion Emissary Blackhoof sends you to Silithus with Taking Back Silithus, a 10-reputation letter. Skip it if you are already in Silithus.", only = { factions = {"Horde"} }, goals = {
		{ t = "accept", quest = 8276, title = "Taking Back Silithus", npc = "Cenarion Emissary Blackhoof", map = 1454, x = 47.64, y = 65.76, era = true, qlvl = 55, optional = true },
	} },
	{ title = "Cenarion Hold", note = "Cenarion Hold is the walled druid camp in north-central Silithus, with flight points for both sides. Everyone starts Neutral with the Cenarion Circle (druids at 2,000 of 3,000). Bor and Huum Wildmane stand together in the main building. Secret Communication opens the Encrypted Twilight Text turn-ins for good. The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it.", goals = {
		{ t = "getfp", location = "Cenarion Hold" },
		{ t = "turnin", quest = 8275, title = "Taking Back Silithus", npc = "Windcaller Proudhorn", map = 1451, x = 51.15, y = 38.29, era = true, optional = true, only = { factions = {"Alliance"} } },
		{ t = "turnin", quest = 8276, title = "Taking Back Silithus", npc = "Windcaller Proudhorn", map = 1451, x = 51.15, y = 38.29, era = true, optional = true, only = { factions = {"Horde"} } },
		{ t = "accept", quest = 8318, title = "Secret Communication", npc = "Bor Wildmane", map = 1451, x = 48.57, y = 37.78, era = true, qlvl = 60 },
		{ t = "accept", quest = 8320, title = "Twilight Geolords", npc = "Huum Wildmane", map = 1451, x = 48.62, y = 37.87, era = true, qlvl = 60, optional = true, note = "Huum Wildmane, level 60" },
	} },
	{ title = "The cultist camp west of Cenarion Hold", note = "The nearest Twilight's Hammer camp lies just south-west of the Hold. Avengers, Geolords and Stonecallers (level 57 to 59) each drop an Encrypted Twilight Text about a third of the time, and every cultist kill is 1 reputation. Twilight Keeper Havunth walks the edge of the camp. Keep every cultist robe, cowl and mantle you loot: they are the Twilight Trappings for the Wind Stones later.", goals = {
		{ t = "collect", quest = 8318, title = "Secret Communication", map = 1451, x = 41.84, y = 44.13, era = true, count = 10, item = 20404, itemName = "Encrypted Twilight Text", oi = 1, mobLevel = 60, spots = "40.9,44.7;39,41.7;27.5,32.8;24.9,36.7;18,31.2" },
		{ t = "kill", quest = 8320, title = "Twilight Geolords", map = 1451, x = 41.08, y = 44.03, era = true, count = 10, target = "Twilight Geolord", oi = 1, mobLevel = 60, optional = true, spots = "40.4,45.7;37.8,43.7;38.7,41.6;28,33.4;25.6,34" },
	} },
	{ title = "Back to Cenarion Hold", goals = {
		{ t = "turnin", quest = 8318, title = "Secret Communication", npc = "Bor Wildmane", map = 1451, x = 48.57, y = 37.78, era = true },
		{ t = "turnin", quest = 8320, title = "Twilight Geolords", npc = "Huum Wildmane", map = 1451, x = 48.62, y = 37.87, era = true, optional = true },
		{ t = "accept", quest = 8321, title = "Vyral the Vile", npc = "Huum Wildmane", map = 1451, x = 48.62, y = 37.87, era = true, qlvl = 60, optional = true, note = "Vyral the Vile" },
	} },
	{ title = "Cultists until the top of Friendly, texts saved", note = "Neutral to Honored is 9,000 reputation (7,000 for druids). Every Twilight Avenger, Geolord, Stonecaller, Master and Overlord gives 1 reputation until 5,999 of 6,000 Friendly, one point short of Honored; there they stop. Save every Encrypted Twilight Text and leave the quests of the next steps for later: each kill below that point is a free point on top of its text, and the texts and quests pay the same at any standing. A text drops about every third kill, so 30 kills make 30 reputation and 10 texts (100 reputation later). Four camps: south-west of the Hold (39,44), the far west (26,34), the far south-west (19,84) and the north-east below Hive'Ashi (66,18: Overlords, and Flamereavers that count until the top of Honored). The Twilight Prophet (87% text) walks between 18,31 and 23,69. Texts sell on the auction house if you would rather buy. At 5,999 Friendly the last point into Honored comes from a Flamereaver, Twilight Keeper or Marauder, or from your first 10 texts at Bor Wildmane.", goals = {
		{ t = "note", text = "Kills alone to the top of Friendly is 8,999 kills (6,999 for druids), but the texts they drop (about 3,000) are worth 30,000 more: most of the way to Exalted." },
		{ t = "note", text = "Friendly (3,000) opens Kania's Formula: Enchant Cloak - Greater Fire Resistance (10g), Mishta's Cenarion Herb Bag (2g) and Sylvan Shoulders (5g), and Forever's new Friendly gloves patterns (7g 50s)." },
		{ t = "collect", count = 10, item = 20404, itemName = "Encrypted Twilight Text", optional = true, note = "Encrypted Twilight Text: save them" },
		{ t = "kill", map = 1451, x = 41.84, y = 44.13, era = true, target = "Twilight Avenger", mobLevel = 59, optional = true, spots = "40.9,43.2;38.1,45.5;27.9,31.1;25.2,35.7;18,31.2" },
		{ t = "kill", map = 1451, x = 39.32, y = 44.1, era = true, target = "Twilight Stonecaller", mobLevel = 60, optional = true, spots = "39,44.2;26.4,32.9;18.6,84.4" },
		{ t = "kill", map = 1451, x = 65.57, y = 22.05, era = true, target = "Twilight Overlord", mobLevel = 61, optional = true, spots = "66.2,21.3;67.9,17.5;65.6,15.7;72.8,15.6;71.5,12.4" },
		{ t = "kill", map = 1451, x = 69.8, y = 14.3, era = true, target = "Twilight Flamereaver", mobLevel = 60, optional = true, note = "Twilight Flamereaver: still counts at 5,999 Friendly", spots = "69.8,14.3;73.1,12.9" },
		{ t = "turnin", quest = 8319, title = "Encrypted Twilight Texts", npc = "Bor Wildmane", map = 1451, x = 48.57, y = 37.78, era = true, qlvl = 60, optional = true, note = "Bor Wildmane: 10 texts, 100, for the last point" },
		{ t = "rep", factionName = "Cenarion Circle", faction = 609, standing = 6 },
	} },
	{ title = "Vyral the Vile", note = "Vyral the Vile (level 61, not elite) waits at the back of Twilight's Run, the cave in the north-east of Silithus. Flamereavers and Twilight Masters guard the way: the Flamereavers count until the top of Honored, the Masters stop at the top of Friendly like the other cultists.", goals = {
		{ t = "collect", quest = 8321, title = "Vyral the Vile", map = 1451, x = 72.4, y = 15.6, era = true, count = 1, item = 20466, itemName = "Vyral's Signet Ring", oi = 1, optional = true },
		{ t = "turnin", quest = 8321, title = "Vyral the Vile", npc = "Huum Wildmane", map = 1451, x = 48.62, y = 37.87, era = true, optional = true },
	} },
	{ title = "Silithus quests at Cenarion Hold", note = "Now cash in the one-time quests: about 1,700 reputation alone, 2,400 with the group quests. They are level 55 to 60, so they pay in full at 60. Securing the Supply Lines needs Taking Back Silithus first. Deathclasp is an elite scorpid with two guards (group of 2 or 3). Calandrath's Desert Recipe is for Cooks: its recipe makes the Smoked Desert Dumplings he wants. Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", goals = {
		{ t = "accept", quest = 8277, title = "Deadly Desert Venom", npc = "Beetix Ficklespragg", map = 1451, x = 51.61, y = 38.63, era = true, qlvl = 55 },
