		{ t = "accept", quest = 8284, title = "The Twilight Mystery", npc = "Geologist Larksbane", map = 1451, x = 49.67, y = 37.46, era = true, qlvl = 58 },
		{ t = "accept", quest = 8304, title = "Dearest Natalia", npc = "Commander Mar'alith", map = 1451, x = 49.2, y = 34.18, era = true, qlvl = 60 },
		{ t = "accept", quest = 8283, title = "Wanted - Deathclasp, Terror of the Sands", npc = "Wanted Poster: Deathclasp", map = 1451, x = 51.35, y = 38.27, era = true, qlvl = 59, optional = true, note = "Wanted poster: Deathclasp, elite" },
		{ t = "accept", quest = 8307, title = "Desert Recipe", npc = "Calandrath", map = 1451, x = 51.89, y = 39.16, era = true, skillName = "Cooking", skillRank = 285, qlvl = 57, optional = true, note = "Calandrath, for Cooks" },
		{ t = "accept", quest = 9415, title = "Report to Marshal Bluewall", npc = "Rifleman Torrig", map = 1451, x = 50.68, y = 34.71, era = true, qlvl = 60, optional = true, only = { factions = {"Alliance"} }, note = "Rifleman Torrig: Report to Marshal Bluewall" },
		{ t = "accept", quest = 9416, title = "Report to General Kirika", npc = "Scout Bloodfist", map = 1451, x = 48.95, y = 36.69, era = true, qlvl = 60, optional = true, only = { factions = {"Horde"} }, note = "Scout Bloodfist: Report to General Kirika" },
	} },
	{ title = "Around Cenarion Hold", note = "Stonelash Scorpids and Sand Skitterers roam the sands around the Hold; Dredge Strikers dig north-east of it. The Sandy Cookbook lies in the cultist camp south-west of the Hold.", goals = {
		{ t = "collect", quest = 8277, title = "Deadly Desert Venom", map = 1451, x = 44.4, y = 37.06, era = true, count = 8, item = 20373, itemName = "Stonelash Scorpid Stinger", oi = 1, mobLevel = 55, spots = "43.4,38.8;39.9,32;33.5,28.9;37,16.7;48.9,13.4" },
