	{ title = "Quests elsewhere", note = "The Cenarion Circle's other quests are spread over Kalimdor and the Plaguelands. Forever pays them in full at any level: The Wildlife Suffers Too (Mulgris Deepriver, Western Plaguelands, levels 54 and 56) 75 and 75, Corruption of Earth and Seed (Maraudon, level 51) 150. Shards of the Felvine (Rabine Saturna, level 60, the Felvine Shard from Alzzin in Dire Maul) pays 150 and its Reliquary 100 at any level.", goals = {
		{ t = "note", text = "Do the Western Plaguelands and Maraudon quests while you level; at 60 they may pay a fraction." },
	} },
	{ title = "Encrypted Twilight Texts to Revered", note = "Honored to Revered is 12,000 reputation. Bor Wildmane takes 10 Encrypted Twilight Texts for 100 reputation, again and again, until Exalted: 120 turn-ins (1,200 texts) to Revered without the quests, or about 950 texts after them. Hand in the texts you saved now. The cultists no longer count, but the Flamereavers, Twilight Keepers, Marauders and Templars count until 11,999 of 12,000 Honored, and the Twilight Lord Everun and Prophet until Exalted. Honored opens Kania's Formula: Enchant Cloak - Greater Nature Resistance (10g), Mishta's Pattern: Sylvan Crown (5g) and Forever's new Honored patterns (7g 50s each).", goals = {
		{ t = "collect", count = 10, item = 20404, itemName = "Encrypted Twilight Text", optional = true },
		{ t = "turnin", quest = 8319, title = "Encrypted Twilight Texts", npc = "Bor Wildmane", map = 1451, x = 48.57, y = 37.78, era = true, qlvl = 60, optional = true, note = "Bor Wildmane: 10 texts, 100" },
		{ t = "rep", factionName = "Cenarion Circle", faction = 609, standing = 7 },
	} },
	{ title = "Field Duty, level 60", note = "Windcaller Kaldon stands by the moonwell of Cenarion Hold. Field Duty (25 reputation, repeatable) sends you with unsigned papers to your side's captain: Captain Blackanvil's Ironforge Brigade outside Hive'Zora (Alliance) or Krug Skullsplit's Orgrimmar Legion outside Hive'Regal (Horde). Use the papers first, then talk to the captain: a level 60 elite silithid attacks; keep the captain alive and he signs. Kaldon then lets you pick a Combat, Logistics or Tactical Assignment, each holding a random briefing worth 50 reputation and a badge: 30 hive silithid kills (elites), goods such as 30 Heavy Runecloth Bandages or 3 Ornate Mithril Boots, or one Templar, Twilight Marauder or scout report. One badge of each kind buys Allegiance to Cenarion Circle at Kaldon: 200 reputation, repeatable. A full round is about 375 reputation.", goals = {
		{ t = "accept", quest = 8507, title = "Field Duty", npc = "Windcaller Kaldon", map = 1451, x = 49.98, y = 36.35, era = true, qlvl = 60, optional = true, only = { factions = {"Alliance"} } },
		{ t = "accept", quest = 8731, title = "Field Duty", npc = "Windcaller Kaldon", map = 1451, x = 49.98, y = 36.35, era = true, qlvl = 60, optional = true, only = { factions = {"Horde"} } },
		{ t = "collect", quest = 8507, title = "Field Duty", map = 1451, x = 32.8, y = 52.6, era = true, count = 1, item = 20810, itemName = "Signed Field Duty Papers", oi = 1, optional = true, only = { factions = {"Alliance"} }, note = "Signed Field Duty Papers, Captain Blackanvil" },
		{ t = "collect", quest = 8731, title = "Field Duty", map = 1451, x = 51.4, y = 68.4, era = true, count = 1, item = 20810, itemName = "Signed Field Duty Papers", oi = 1, optional = true, only = { factions = {"Horde"} }, note = "Signed Field Duty Papers, Krug Skullsplit" },
		{ t = "turnin", quest = 8507, title = "Field Duty", npc = "Windcaller Kaldon", map = 1451, x = 49.98, y = 36.35, era = true, optional = true, only = { factions = {"Alliance"} } },
		{ t = "turnin", quest = 8731, title = "Field Duty", npc = "Windcaller Kaldon", map = 1451, x = 49.98, y = 36.35, era = true, optional = true, only = { factions = {"Horde"} } },
		{ t = "turnin", quest = 9338, title = "Allegiance to Cenarion Circle", npc = "Windcaller Kaldon", map = 1451, x = 49.98, y = 36.35, era = true, qlvl = 60, optional = true, note = "Allegiance: one Combat, Logistics and Tactical badge, 200" },
		{ t = "accept", quest = 8800, title = "Cenarion Battlegear", npc = "Windcaller Kaldon", map = 1451, x = 49.98, y = 36.35, era = true, qlvl = 60, optional = true, note = "Cenarion Battlegear: Vargus's badge gear" },
		{ t = "turnin", quest = 8800, title = "Cenarion Battlegear", npc = "Vargus", map = 1451, x = 51.23, y = 38.86, era = true, optional = true },
	} },
	{ title = "Silithyst", note = "Optional, 100 reputation once: Scouring the Desert. Your side's camp sits by a hive: Marshal Bluewall's by Hive'Zora (Alliance), General Kirika's by Hive'Regal (Horde). Silithyst rises from glowing geysers around the desert: walk through one, carry the Silithyst to your camp's Silithyst Extractor, then talk to the camp's leader. It is a world PvP objective: players of the other side can take it from you.", goals = {
		{ t = "turnin", quest = 9415, title = "Report to Marshal Bluewall", npc = "Marshal Bluewall", map = 1451, x = 33.3, y = 51.1, era = true, optional = true, only = { factions = {"Alliance"} } },
		{ t = "accept", quest = 9419, title = "Scouring the Desert", npc = "Marshal Bluewall", map = 1451, x = 33.29, y = 51.06, era = true, qlvl = 60, optional = true, only = { factions = {"Alliance"} } },
