Waypost.RegisterSteps("reputation/centaur-clans", function() return {
	{ title = "Pick your clan", note = "The Gelkis (south-west Desolace) and the Magram (south-east) are at war: every kill of one clan gives the other 20 and costs its own clan 100, so you can only climb with one. Both start Neutral. Forever's quests are worth far more than kills now, and the choice quests no longer cost the other clan anything. Alliance: Captain Pentigast at Nijel's Point offers Strange Alliance (Gelkis) and Brutal Politics (Magram). Horde: Gurda Wildmane offers Gelkis Alliance and Magram Alliance. Take the one of your clan, and Carved Centaur Totems: each clan's Buying Friendship (3,000) is offered once you bring the totems back. Then tick the task. The guide goes on with the Gelkis; take the Magram's quests instead and it goes to the Magram half. Forever pays these quests in full at any level.", goals = {
		{ t = "accept", quest = 1382, title = "Strange Alliance", npc = "Captain Pentigast", map = 1443, x = 66.66, y = 10.93, era = true, qlvl = 35, optional = true, only = { factions = {"Alliance"} }, note = "Strange Alliance: Gelkis" },
		{ t = "accept", quest = 1368, title = "Gelkis Alliance", npc = "Gurda Wildmane", map = 1443, x = 56.29, y = 59.68, era = true, qlvl = 33, optional = true, only = { factions = {"Horde"} }, note = "Gelkis Alliance" },
		{ t = "accept", quest = 93224, title = "Carved Centaur Totems", npc = "Captain Pentigast", map = 1443, x = 66.66, y = 10.93, era = true, qlvl = 40, only = { factions = {"Alliance"} }, note = "Carved Centaur Totems" },
		{ t = "accept", quest = 93225, title = "Carved Centaur Totems", npc = "Gurda Wildmane", map = 1443, x = 56.29, y = 59.68, era = true, qlvl = 40, only = { factions = {"Horde"} }, note = "Carved Centaur Totems" },
		{ t = "task", text = "Take the quests of one clan" },
	} },
	{ title = "Carved Centaur Totems", note = "The Kolkar centaurs (level 30-33) in the camps along the eastern road, south of Nijel's Point, drop the totems, and so do the Magram and the Maraudine. Bring five back, then take your clan's Buying Friendship (Gelkis below; the Magram's instead for the Magram).", goals = {
