		{ t = "turnin", quest = 93224, title = "Carved Centaur Totems", npc = "Captain Pentigast", map = 1443, x = 66.66, y = 10.93, era = true, only = { factions = {"Alliance"} } },
		{ t = "turnin", quest = 93225, title = "Carved Centaur Totems", npc = "Gurda Wildmane", map = 1443, x = 56.29, y = 59.68, era = true, only = { factions = {"Horde"} } },
		{ t = "accept", quest = 93227, title = "Buying Friendship: Gelkis", npc = "Captain Pentigast", map = 1443, x = 66.66, y = 10.93, era = true, qlvl = 45, optional = true, only = { factions = {"Alliance"} }, note = "Buying Friendship: Gelkis" },
		{ t = "accept", quest = 94873, title = "Buying Friendship: Gelkis", npc = "Gurda Wildmane", map = 1443, x = 56.29, y = 59.68, era = true, qlvl = 45, optional = true, only = { factions = {"Horde"} }, note = "Buying Friendship: Gelkis" },
	} },
	{ title = "Gelkis or Magram", note = "No clan's quests in your log: the guide goes on with the Gelkis. For the Magram, take their choice quest and Buying Friendship and the guide goes to the Magram half.", goals = {
		{ t = "goto", map = 1443, x = 66.7, y = 10.9, era = true, only = { factions = {"Alliance"} }, text = "Captain Pentigast" },
		{ t = "goto", map = 1443, x = 56.3, y = 59.7, era = true, only = { factions = {"Horde"} }, text = "Gurda Wildmane" },
	} },
	{ title = "Gelkis: the choice quest", note = "The Gelkis half starts with the clan's choice quest from the giver you just handed the totems to: Uthek's quests in Gelkis Village follow from it, and Buying Friendship alone does not open them.", label = "gelkis", goals = {
		{ t = "accept", quest = 1382, title = "Strange Alliance", npc = "Captain Pentigast", map = 1443, x = 66.66, y = 10.93, era = true, qlvl = 35, only = { factions = {"Alliance"} }, note = "Strange Alliance, Captain Pentigast" },
