		{ t = "accept", quest = 93041, title = "Facing the Truth", npc = "Nerlokh", map = 2652, x = 21.2, y = 23.2, qlvl = 38, optional = true },
	} },
	{ title = "Gelkis: Khan Jehn", note = "Khan Jehn (level 37) leads the Magram from the west side of Magram Village, with his bodyguards. The kill costs the Magram 500. Uthek pays 6,000, a title, and your pick of three rare level 35 weapons: Abandoned Ferocity (two-handed axe: Strength, Stamina, Agility), Bludgeon of Betrayed Virtues (one-handed mace: Strength, Stamina, Agility) or Thrice-Damned Effigy (off-hand: Spirit, Intellect, Stamina).", when = {{ k = "available", q = 93128, minLevel = 35 }}, goals = {
		{ t = "accept", quest = 93128, title = "Khan Jehn", npc = "Nerlokh", map = 2652, x = 21.2, y = 23.2, qlvl = 42 },
