		{ t = "accept", quest = 93226, title = "Buying Friendship: Magram", npc = "Captain Pentigast", map = 1443, x = 66.66, y = 10.93, era = true, qlvl = 45, only = { factions = {"Alliance"} }, note = "Buying Friendship: Magram, Captain Pentigast" },
