		{ t = "turnin", quest = 94872, title = "Buying Friendship: Magram", npc = "Gorhak", map = 1443, x = 66.21, y = 79.36, era = true, only = { factions = {"Horde"} }, note = "Gorhak: 3,000" },
	} },
	{ title = "Magram: the Kolkar camps", note = "The Kolkar centaurs (level 30-33) hold the camps south of Nijel's Point.", only = { factions = {"Alliance"} }, goals = {
