		{ t = "turnin", quest = 1369, title = "Broken Tears", npc = "Warug", map = 1443, x = 74.97, y = 68.16, era = true, note = "Warug: 500" },
		{ t = "accept", quest = 1371, title = "Gizmo for Warug", npc = "Warug", map = 1443, x = 74.97, y = 68.16, era = true, qlvl = 35, optional = true, note = "Gizmo for Warug" },
	} },
	{ title = "Magram: Gizmo for Warug", note = "Warug wants an Advanced Target Dummy: engineers make it (4 Heavy Leather, a Gyrochronatom, a Bronze Framework and an Iron Strut); others buy one. It pays 1,000 and a choice of two engineering schematics, the Centaur Banner Deployment Device or the Hoof-Shaped Foot Pedal.", goals = {
		{ t = "collect", quest = 1371, title = "Gizmo for Warug", map = 1443, x = 75, y = 68.2, era = true, count = 1, item = 4392, itemName = "Advanced Target Dummy", oi = 1, optional = true, note = "Advanced Target Dummy: made by engineers, or bought" },
		{ t = "turnin", quest = 1371, title = "Gizmo for Warug", npc = "Warug", map = 1443, x = 74.97, y = 68.16, era = true, optional = true, note = "Warug: 1,000" },
	} },
	{ title = "Magram: totems and kills to Honored", note = "Friendly to Honored is 6,000; after the clan's quests you are about 3,000 into it (4,000 with Gizmo for Warug), so 2,000 to 3,000 to go. Gorhak's Economic Warfare takes 5 Carved Centaur Totems for 750, again and again; the Maraudine centaurs (level 36-40) of western Desolace drop them, and the totems do not bind, so the auction house is the other source. Gelkis kills add 20 each, but Forever's kill data stops them at the end of Friendly, 1 short of Honored. At Friendly the village has two craft orders for 1,000 each: Mirda's 3 Greater Shadow Protection Potions and Grolkar's 2 Massive Iron Axes (blacksmithing). Warug's A Conqueror's Crown (1,000) is no craft order: he wants a Conqueror's Helm from a crypt in the Badlands, and Forever's quest pages put it in his chain before the Valley of Bones, so bring it before you reach Honored. Legacy Diplomat adds up to 10%.", goals = {
		{ t = "accept", quest = 92743, title = "A Conqueror's Crown", npc = "Warug", map = 1443, x = 74.97, y = 68.16, era = true, qlvl = 40, optional = true, note = "A Conqueror's Crown: Warug" },
		{ t = "turnin", quest = 92743, title = "A Conqueror's Crown", npc = "Warug", map = 1443, x = 74.97, y = 68.16, era = true, optional = true, note = "Warug: 1,000" },
		{ t = "collect", map = 1443, x = 29.5, y = 58, era = true, count = 5, item = 254432, itemName = "Carved Centaur Totem", mobLevel = 38, optional = true, note = "Carved Centaur Totem: Maraudine centaurs", spots = "29.5,58;29.8,61.3;30,54.1;31.9,60.2;32.5,54.6" },
		{ t = "accept", quest = 92811, title = "Economic Warfare", npc = "Gorhak", map = 1443, x = 66.21, y = 79.36, era = true, qlvl = 60, optional = true, note = "Economic Warfare" },
		{ t = "turnin", quest = 92811, title = "Economic Warfare", npc = "Gorhak", map = 1443, x = 66.21, y = 79.36, era = true, optional = true, note = "Gorhak: 750" },
		{ t = "rep", factionName = "Magram Clan Centaur", faction = 93, standing = 6 },
	} },
	{ title = "Magram: the Valley of Bones", note = "At Honored, and after A Conqueror's Crown, Warug sends you to Orgrul at the northern entrance of the Valley of Bones, in Shen'dralas. Orgrul's quests (500 each: Mountain of Bones, Outcast Necromancers, Corrupting Tears, Proof of Concept, No Mercy for the Weak, Bone Raising) and Hagiak's at the Magram Front (Bristleback Retreat, Long-Term Solutions, Threat of Starvation, Return to Orgrul) end with Khan Jehn: raise the dead khan with Orgrul's staff at the tent by the lake in Magram Village, for 6,000, a title and a rare level 35 weapon. They all ask you to stay Honored or better. Honored to Revered is 12,000: the valley's quests pay about 11,000 of it, two Economic Warfare turn-ins the rest.", goals = {
		{ t = "level", level = 35 },
		{ t = "accept", quest = 92841, title = "Valley of Bones", npc = "Warug", map = 1443, x = 74.97, y = 68.16, era = true, qlvl = 40, note = "Warug: Valley of Bones" },
		{ t = "turnin", quest = 92841, title = "Valley of Bones", npc = "Orgrul", map = 2652, x = 35.7, y = 12.5, note = "Orgrul: 125" },
		{ t = "accept", quest = 92844, title = "Mountain of Bones", npc = "Orgrul", map = 2652, x = 35.8, y = 13, qlvl = 42, optional = true },
		{ t = "accept", quest = 92846, title = "Outcast Necromancers", npc = "Orgrul", map = 2652, x = 35.8, y = 13, qlvl = 40, optional = true },
	} },
	{ title = "Magram: Khan Jehn", note = "The ritual site is a tent by the lake in the middle of Magram Village. Orgrul pays 6,000, a title, and your pick of three rare level 35 weapons: Scavenged Magram Armament (polearm: Stamina, attack power, Agility), Greatstaff of the Necrokhans (staff: Intellect, Stamina, Spirit) or Soulsplatter Mace (main-hand mace: Intellect, Stamina, Spirit).", when = {{ k = "available", q = 93196, minLevel = 35 }}, goals = {
		{ t = "accept", quest = 93196, title = "Khan Jehn", npc = "Orgrul", map = 2652, x = 35.8, y = 13, qlvl = 42 },
		{ t = "turnin", quest = 93196, title = "Khan Jehn", npc = "Orgrul", map = 2652, x = 35.8, y = 13, note = "Orgrul: 6,000" },
	} },
	{ title = "Magram: totems to Exalted", note = "From Revered on only Economic Warfare is left: Revered to Exalted is 21,000, 28 turn-ins, 140 totems.", goals = {
		{ t = "collect", map = 1443, x = 29.5, y = 58, era = true, count = 5, item = 254432, itemName = "Carved Centaur Totem", mobLevel = 38, optional = true, spots = "29.5,58;29.8,61.3;30,54.1;31.9,60.2;32.5,54.6" },
		{ t = "accept", quest = 92811, title = "Economic Warfare", npc = "Gorhak", map = 1443, x = 66.21, y = 79.36, era = true, qlvl = 60, optional = true },
		{ t = "turnin", quest = 92811, title = "Economic Warfare", npc = "Gorhak", map = 1443, x = 66.21, y = 79.36, era = true, optional = true },
		{ t = "rep", factionName = "Magram Clan Centaur", faction = 93, standing = 7 },
		{ t = "rep", factionName = "Magram Clan Centaur", faction = 93, standing = 8, optional = true },
	} },
	{ title = "The totem recipes", note = "Both quartermasters sell the same 12 recipes for Carved Centaur Totems, no standing needed: Enchant Bracer - Lesser Agility and - Lesser Healing Power; Greater Spellblasting and Greater Frenzy Potion; Hard Gold Gauntlet and Iron Morningstar plans; Mystic Thick Armor Kit, Silk Reagent Bag, Stormcloth Gloves and Centaur Hoofwarmers patterns; the Centaur Banner Deployment Device and Hoof-Shaped Foot Pedal schematics. Keep the totems you need for them before you hand the rest in.", label = "recipes", goals = {
		{ t = "talk", npc = "Gorhak", map = 1443, x = 66.21, y = 79.36, era = true, optional = true, note = "Gorhak, Magram Village" },
		{ t = "talk", npc = "Molkar", map = 1443, x = 35.6, y = 92, era = true, optional = true, note = "Molkar, Gelkis Village" },
	} },
} end)

Waypost.RegisterSteps("reputation/darkspear-islands", function() return {
	{ title = "Merchant Coast", note = "The Darkspear Islands lie off the coast of Dustwallow Marsh: 15 against 15, from level 30. Hold the four capture points to gain points, faster the more you hold, and carry the flag from the middle to a base your team holds for more; the first team to 2000 points wins. The sea kills: cross on the bridges. Queue at any battlemaster or step through the portal here at the Merchant Coast, north of Ratchet. Nizook Boof pays 200 reputation for your first win. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = {"Horde"} }, when = {{ k = "level", op = "<", n = 40 }}, goals = {
