	{ title = "Darkspear Raiders to Friendly", note = "Neutral to Friendly is 3000 reputation. Forever has not said how much a game pays by itself; the sure part is the Warbringer's 100 for every 3 marks, which is one win, so at most 30 wins from Neutral even before the games' own reputation. Each new bracket (40, 50, 60) brings a new first win for Nizook Boof (200) and a new first mark quest (150).", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: Conflict at Darkspear Islands again, 100 for 3 marks" },
		{ t = "rep", factionName = "Darkspear Raiders", faction = 2798, standing = 5 },
	} },
	{ title = "Darkspear Raiders to Honored", note = "Friendly to Honored is 6000 reputation. Friendly opens the first rewards at Creeg Bothunk, the quartermaster beside Nizook Boof: the trinkets Darkspear Voodoo Seal and Relentless Raider's Seal for levels 33 and 48 (1g49s to 11g85s), and food, bandages and draughts for the battleground (5s to 20s). A Darkspear care package for Friendly also exists in Forever's data.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Creeg Bothunk", map = 1413, x = 64.69, y = 34.24, era = true, optional = true, note = "Creeg Bothunk: Friendly rewards" },
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: 100 for 3 marks" },
		{ t = "rep", factionName = "Darkspear Raiders", faction = 2798, standing = 6 },
	} },
	{ title = "Darkspear Raiders to Revered", note = "Honored to Revered is 12000 reputation. Honored opens Insurgent's Band, Darkspear Signet, Darkspear Warding Pendant and Darkspear Raider's Cloak for levels 28, 38, 48 and 58 (1g11s to 12g6s): rings, neck and cloak that fit the bracket you are in.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Creeg Bothunk", map = 1413, x = 64.69, y = 34.24, era = true, optional = true, note = "Creeg Bothunk: Honored rewards" },
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: 100 for 3 marks" },
		{ t = "rep", factionName = "Darkspear Raiders", faction = 2798, standing = 7 },
	} },
	{ title = "Darkspear Raiders to Exalted", note = "Revered to Exalted is 21000 reputation, half the climb. Revered opens the weapons for levels 28, 38, 48 and 58: Darkspear Raider's Reaper (two-handed axe), Darkspear Insurgent's Spellblade (dagger), Darkspear Skirmisher's Bludgeon (mace) and the Tome of the Darkspear Prophecy (off-hand), 1g44s to 37g15s.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Creeg Bothunk", map = 1413, x = 64.69, y = 34.24, era = true, optional = true, note = "Creeg Bothunk: Revered rewards" },
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: 100 for 3 marks" },
		{ t = "rep", factionName = "Darkspear Raiders", faction = 2798, standing = 8 },
	} },
	{ title = "Creeg Bothunk", note = "Exalted gives the Legacy Point \"Master of Darkspear Islands\" and opens the epics: gloves in plate, mail, leather and cloth for levels 50 and 60 (Raider Gauntlets, Gloves, Handguards and Handwraps, 3g94s to 15g16s) and level 60 shoulders in every armor type (Darkspear Pauldrons, Shoulders, Spaulders, Mantle, Epaulets, Shoulderpads and Shoulderguards, 9g44s to 16g86s). The Darkspear Battle Tabard comes from a short questline that Exalted opens here.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Creeg Bothunk", map = 1413, x = 64.69, y = 34.24, era = true, note = "Creeg Bothunk: Exalted rewards" },
	} },
	{ title = "Northwatch Hold", note = "The Darkspear Islands lie off the coast of Dustwallow Marsh: 15 against 15, from level 30. Hold the four capture points to gain points, faster the more you hold, and carry the flag from the middle to a base your team holds for more; the first team to 2000 points wins. The sea kills: cross on the bridges. Queue at any battlemaster or step through the portal here at Northwatch Hold, south of Ratchet. Brelinda McFarry pays 200 reputation for your first win. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = {"Alliance"} }, when = {{ k = "level", op = "<", n = 40 }}, goals = {
		{ t = "accept", quest = 98903, title = "The Battle for Darkspear Islands!", npc = "Brelinda McFarry", map = 1413, x = 63.4, y = 58.7, era = true, qlvl = 39 },
		{ t = "turnin", quest = 98903, title = "The Battle for Darkspear Islands!", npc = "Brelinda McFarry", map = 1413, x = 63.4, y = 58.7, era = true, note = "after a win" },
	} },
	{ title = "Northwatch Hold", note = "The Darkspear Islands lie off the coast of Dustwallow Marsh: 15 against 15, from level 30. Hold the four capture points to gain points, faster the more you hold, and carry the flag from the middle to a base your team holds for more; the first team to 2000 points wins. The sea kills: cross on the bridges. Queue at any battlemaster or step through the portal here at Northwatch Hold, south of Ratchet. Brelinda McFarry pays 200 reputation for your first win. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = {"Alliance"} }, when = {{ k = "level", op = ">=", n = 40 }, { k = "level", op = "<", n = 50 }}, goals = {
