		{ t = "turnin", quest = 98905, title = "The Battle for Darkspear Islands!", npc = "Brelinda McFarry", map = 1413, x = 63.4, y = 58.7, era = true, note = "after a win" },
	} },
	{ title = "Alliance Brigadier General", note = "The Alliance Brigadier General pays 150 reputation for 3 Darkspear Islands Marks of Honor the first time (Darkspear Islands Clash), then 100 for every 3 more. He stands in Stormwind, Ironforge and Darnassus, at Silverwing Grove in southern Ashenvale, at Refuge Pointe in the Arathi Highlands and at both gates of Alterac Valley. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Darkspear Islands marks: hand in or spend them before you reach that.", only = { factions = {"Alliance"} }, when = {{ k = "level", op = "<", n = 40 }}, goals = {
