		{ t = "collect", quest = 98895, title = "Darkspear Islands Clash", map = 1413, x = 63.4, y = 58.7, era = true, count = 3, item = 274895, itemName = "Darkspear Islands Mark of Honor", oi = 1, note = "Darkspear Islands Marks of Honor: play games" },
		{ t = "turnin", quest = 98895, title = "Darkspear Islands Clash", npc = "Alliance Brigadier General", map = 1417, x = 45.65, y = 45.75, era = true },
	} },
	{ title = "Alliance Brigadier General", note = "The Alliance Brigadier General pays 150 reputation for 3 Darkspear Islands Marks of Honor the first time in each bracket (Darkspear Islands Clash), then keeps taking 3 more. He stands in Stormwind, Ironforge and Darnassus, at Silverwing Grove in southern Ashenvale and at Refuge Pointe. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Darkspear Islands marks.", only = { factions = {"Alliance"} }, when = {{ k = "level", op = ">=", n = 40 }, { k = "level", op = "<", n = 50 }}, goals = {
