Waypost.RegisterSteps("reputation/hydraxian-waterlords", function() return {
	{ title = "Duke Hydraxis", note = "Duke Hydraxis stands on a small island off the east coast of Azshara; swim out to him. Everyone starts Neutral with the Waterlords, and nearly all of their reputation comes from killing the servants of fire, air and earth: the quests themselves pay nothing until the last one. Take both quests: the chain goes on only when both are done. Everything past Honored happens in the Molten Core, a raid of 40 that is not among the first raids Blizzard has announced for Forever; until it opens, Honored is as far as the Waterlords go. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%.", goals = {
		{ t = "accept", quest = 6804, title = "Poisoned Water", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, qlvl = 56 },
		{ t = "accept", quest = 6805, title = "Stormers and Rumblers", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, qlvl = 57 },
	} },
	{ title = "Stormers and Rumblers", note = "Dust Stormers and Desert Rumblers drift around the Crystal Vale in the north-west of Silithus. Each kill also pays 5 reputation while you are Neutral or Friendly, so stay if you mean to farm (next steps).", goals = {
		{ t = "kill", quest = 6805, title = "Stormers and Rumblers", map = 1451, x = 25.04, y = 21.23, era = true, count = 15, target = "Dust Stormer", oi = 1, mobLevel = 57, spots = "21.8,22.6;18.9,21.7;20.1,18.8;17.8,26.1;19.2,31.2" },
		{ t = "kill", quest = 6805, title = "Stormers and Rumblers", map = 1451, x = 22, y = 20, era = true, count = 15, target = "Desert Rumbler", oi = 2, mobLevel = 58, spots = "22.5,19.4;22.3,16.7;19.8,16.5;21.5,12.7;24.9,12.2" },
	} },
	{ title = "Poisoned Water", note = "Use the Aspect of Neptulon on a Blighted Horror or a Plague Monstrosity: it turns into a Discordant Surge. Kill the surge and loot its Discordant Bracers. Twelve are needed, and the vial must still be in your bags at the turn-in.", goals = {
		{ t = "use", map = 1423, x = 44, y = 41, era = true, item = 17310, itemName = "Aspect of Neptulon", optional = true, note = "Aspect of Neptulon, on the poisoned elementals" },
		{ t = "collect", quest = 6804, title = "Poisoned Water", map = 1423, x = 44.01, y = 40.96, count = 12, item = 17309, itemName = "Discordant Bracers", oi = 1, mobLevel = 56, spots = "44.2,41.9;44.4,39.5;62.4,28.4;62.8,26.9;53.6,66.4" },
	} },
	{ title = "Back to Duke Hydraxis", goals = {
		{ t = "turnin", quest = 6804, title = "Poisoned Water", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true },
		{ t = "turnin", quest = 6805, title = "Stormers and Rumblers", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true },
		{ t = "accept", quest = 6821, title = "Eye of the Emberseer", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, qlvl = 60 },
	} },
	{ title = "Eye of the Emberseer", note = "Pyroguard Emberseer is a boss in Upper Blackrock Spire, inside Blackrock Mountain: a group of up to ten, and someone needs the Seal of Ascension to open the door. He drops the Eye and pays 50 reputation per kill up to 11,999 of 12,000 Honored. Lord Incendius in Blackrock Depths pays 15 the same way.", goals = {
		{ t = "collect", quest = 6821, title = "Eye of the Emberseer", map = 1428, x = 26.4, y = 24.5, era = true, count = 1, item = 17322, itemName = "Eye of the Emberseer", oi = 1, optional = true, group = true, note = "Eye of the Emberseer: raid of ten" },
		{ t = "turnin", quest = 6821, title = "Eye of the Emberseer", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, optional = true },
		{ t = "accept", quest = 6822, title = "The Molten Core", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, qlvl = 60, optional = true },
	} },
	{ title = "Attunement to the Core", note = "Lothos Riftwaker in Blackrock Mountain attunes you to the Molten Core: bring him a Core Fragment from beside the Molten Core's portal at the bottom of Blackrock Depths. Once attuned, he can send you straight into the Molten Core.", goals = {
		{ t = "accept", quest = 7848, title = "Attunement to the Core", npc = "Lothos Riftwaker", map = 1428, x = 26.4, y = 24.5, era = true, qlvl = 60, optional = true, group = true },
		{ t = "collect", quest = 7848, title = "Attunement to the Core", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 18412, itemName = "Core Fragment", oi = 1, optional = true, group = true, note = "Core Fragment, at the portal in Blackrock Depths" },
		{ t = "turnin", quest = 7848, title = "Attunement to the Core", npc = "Lothos Riftwaker", map = 1428, x = 26.4, y = 24.5, era = true, optional = true, group = true },
	} },
	{ title = "The Molten Core", note = "The Molten Core is a raid of 40. Kill one Molten Giant, Firelord, Ancient Core Hound and Lava Surger for Duke Hydraxis. Every elemental there pays: Firewalkers, Flameguards, Lava Elementals, Lava Reavers and Molten Destroyers 40, Firelords, Lava Surgers, Molten Giants and Ancient Core Hounds 20, up to 11,999 of 12,000 Honored; about 3,360 for a full clear of the trash. The bosses pay 100 each (Golemagg 150, Ragnaros 200).", goals = {
		{ t = "kill", quest = 6822, title = "The Molten Core", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, target = "Molten Giant", oi = 1, optional = true, group = true, note = "Molten Giant: raid of 40" },
		{ t = "kill", quest = 6822, title = "The Molten Core", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, target = "Firelord", oi = 2, optional = true, group = true },
		{ t = "kill", quest = 6822, title = "The Molten Core", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, target = "Ancient Core Hound", oi = 3, optional = true, group = true },
		{ t = "kill", quest = 6822, title = "The Molten Core", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, target = "Lava Surger", oi = 4, optional = true, group = true },
	} },
	{ title = "Elementals to Honored", note = "Neutral to Honored is 9,000 reputation, and Agent of Hydraxis asks for Honored. One Molten Core clear pays about 4,000 of it. Without a raid it comes from the elementals: 5 per Dust Stormer, Desert Rumbler or Greater Obsidian Elemental (the Burning Steppes), about 1,800 kills from Neutral. They stop at 5,999 of 6,000 Friendly, one point short, so the last point needs a kill that still counts there: Huricanian, a rare air elemental in the Crystal Vale (25), or Lord Incendius at the Black Anvil in Blackrock Depths (15, a five-player dungeon). Those two and Pyroguard Emberseer keep paying through Honored as well.", goals = {
		{ t = "kill", map = 1451, x = 25.04, y = 21.23, era = true, target = "Dust Stormer", mobLevel = 57, optional = true, note = "Dust Stormer, 5", spots = "21.8,22.6;18.9,21.7;20.1,18.8;17.8,26.1;19.2,31.2" },
		{ t = "kill", map = 1451, x = 22, y = 20, era = true, target = "Desert Rumbler", mobLevel = 58, optional = true, note = "Desert Rumbler, 5", spots = "22.5,19.4;22.3,16.7;19.8,16.5;21.5,12.7;24.9,12.2" },
		{ t = "kill", map = 1451, x = 21.56, y = 24.12, era = true, target = "Huricanian", optional = true, note = "Huricanian, rare, 25" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Lord Incendius", optional = true, group = true, note = "Lord Incendius, Blackrock Depths: 15, group up" },
		{ t = "rep", factionName = "Hydraxian Waterlords", faction = 749, standing = 6 },
	} },
	{ title = "Agent of Hydraxis", note = "Back to Duke Hydraxis. Agent of Hydraxis is done the moment you are Honored.", goals = {
		{ t = "turnin", quest = 6822, title = "The Molten Core", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, optional = true },
		{ t = "accept", quest = 6823, title = "Agent of Hydraxis", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, qlvl = 60, optional = true },
		{ t = "turnin", quest = 6823, title = "Agent of Hydraxis", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, optional = true },
