	} },
	{ title = "Hands of the Enemy", note = "Lucifron, Gehennas, Shazzrah and Sulfuron Harbinger are Molten Core bosses: each drops his hand for the quest.", goals = {
		{ t = "collect", quest = 6824, title = "Hands of the Enemy", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 17332, itemName = "Hand of Shazzrah", oi = 1, optional = true, group = true, note = "Hand of Shazzrah: raid of 40" },
		{ t = "collect", quest = 6824, title = "Hands of the Enemy", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 17329, itemName = "Hand of Lucifron", oi = 2, optional = true },
		{ t = "collect", quest = 6824, title = "Hands of the Enemy", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 17331, itemName = "Hand of Gehennas", oi = 3, optional = true, group = true },
		{ t = "collect", quest = 6824, title = "Hands of the Enemy", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 17330, itemName = "Hand of Sulfuron", oi = 4, optional = true, group = true },
	} },
	{ title = "A Hero's Reward", note = "Hand in the hands, then dive under the surf at the southern foot of the island: Hydraxis' Coffer holds your ring and pays the only quest reputation the Waterlords give, 200. From now on, while you are Honored or better, the Duke hands you Aqual Quintessence: pour it on a rune in the Molten Core to douse it. With every rune doused, Majordomo Executus comes out, and after him Ragnaros.", goals = {
		{ t = "turnin", quest = 6824, title = "Hands of the Enemy", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, optional = true },
		{ t = "accept", quest = 7486, title = "A Hero's Reward", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7486, title = "A Hero's Reward", npc = "Hydraxis' Coffer", map = 1447, x = 79.24, y = 74.87, era = true, optional = true },
