	} },
	{ title = "Molten Core to Revered", note = "Honored to Revered is 12,000 reputation. The trash still counts, so a full clear pays about 3,360 plus 700 from the seven bosses, 150 from Golemagg and 200 from Ragnaros: about three clears. Lord Incendius (15) and Pyroguard Emberseer (50) count too while you are Honored. The trash stops at 11,999 of 12,000 Honored; the bosses carry you over.", goals = {
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Firewalker", optional = true, group = true, note = "Firewalker, 40" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Flameguard", optional = true, group = true, note = "Flameguard, 40" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Lava Elemental", optional = true, group = true, note = "Lava Elemental, 40" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Lucifron", optional = true, group = true, note = "Lucifron and the other bosses, 100: they carry you past 11,999" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Golemagg the Incinerator", optional = true, group = true, note = "Golemagg the Incinerator, 150" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Ragnaros", optional = true, group = true, note = "Ragnaros, 200" },
		{ t = "rep", factionName = "Hydraxian Waterlords", faction = 749, standing = 7 },
	} },
	{ title = "The Eternal Quintessence", note = "At Revered the Duke gives you the Eternal Quintessence: it does the Aqual Quintessence's work and is not used up, so you never come back for another vial.", goals = {
		{ t = "collect", npc = "Duke Hydraxis", map = 1447, x = 79.28, y = 73.7, era = true, item = 22754, itemName = "Eternal Quintessence", optional = true, note = "Eternal Quintessence, ask the Duke" },
	} },
	{ title = "Molten Core to Exalted", note = "Revered to Exalted is 21,000 reputation. The trash has stopped, but all nine bosses still pay while you are Revered: 100 each from the seven, 150 from Golemagg and 200 from Ragnaros, 1,050 a clear: about 20 clears. The seven stop at 20,999 of 21,000 Revered, so the last point comes from Golemagg or Ragnaros, and from Exalted on only those two pay.", goals = {
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Lucifron", optional = true, group = true, note = "Lucifron, 100" },
