		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Baron Geddon", optional = true, group = true, note = "Baron Geddon, 100" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Shazzrah", optional = true, group = true, note = "Shazzrah, 100" },
		{ t = "kill", map = 1427, x = 32.1, y = 94.7, era = true, target = "Sulfuron Harbinger", optional = true, group = true, note = "Sulfuron Harbinger, 100" },
