Waypost.RegisterSteps("reputation/merchants-favor", function() return {
	{ title = "Your first Waylaid Crate or writ", note = "From level 10, mobs anywhere drop Waylaid Crates and sealed writs (Journeyman's, Expert's and Artisan's). Fill a crate with one of the bundles it lists (right-click it), or open a sealed writ: by beta reports, the first time you do either you also get a Shipping Label. Right-click the label to start its quest. Crates and writs can be traded, so the Auction House sells them too.", goals = {
		{ t = "accept", quest = 98247, title = "Shipping Label", item = 280179, itemName = "Shipping Label", qlvl = 60, only = { factions = {"Alliance"} } },
		{ t = "accept", quest = 98248, title = "Shipping Label", item = 280180, itemName = "Shipping Label", qlvl = 60, only = { factions = {"Horde"} } },
	} },
	{ title = "Three Corners: the Shipping Label", note = "The Azeroth Commerce Authority camp is at Three Corners, where the roads from Elwynn Forest, Duskwood and Lakeshire meet in western Redridge. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to Marcy Baker too, but they pay only Merchant's Favor and silver, never reputation.", only = { factions = {"Alliance"} }, goals = {
		{ t = "turnin", quest = 98247, title = "Shipping Label", npc = "Marcy Baker", map = 1433, x = 9.71, y = 70.86 },
	} },
	{ title = "The Crossroads camp: the Shipping Label", note = "The Durotar Supply and Logistics camp stands just outside the west gate of the Crossroads. The label pays 2000 reputation once (and, by beta reports, 50 Merchant's Favor): two thirds of the way to Friendly. Filled crates go to Dokimi too, but they pay only Merchant's Favor and silver, never reputation.", only = { factions = {"Horde"} }, goals = {
		{ t = "turnin", quest = 98248, title = "Shipping Label", npc = "Dokimi", map = 1413, x = 50.13, y = 29.37, era = true },
	} },
	{ title = "Gather your writs", note = "Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, the one its title names. Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for.", goals = {
		{ t = "task", text = "Take the quests of the writs you can fill" },
	} },
	{ title = "Duskwood writ customers", note = "Kzixx stands about 450 yards north of Darkshire. Customers show no quest mark: right-click them anyway.", when = {{ k = "onquest", q = {94214, 94232, 94241, 94250} }}, goals = {
		{ t = "turnin", quest = 94214, title = "Craftsman's Writ: Shadow Protection Potion", npc = "Kzixx", map = 1431, x = 81.82, y = 19.77, era = true, note = "Shadow Protection Potion, 75 reputation" },
		{ t = "turnin", quest = 94232, title = "Craftsman's Writ: Minor Recombobulator", npc = "Kzixx", map = 1431, x = 81.82, y = 19.77, era = true, note = "Minor Recombobulator, 75 reputation" },
		{ t = "turnin", quest = 94241, title = "Craftsman's Writ: Dark Leather Tunic", npc = "Kzixx", map = 1431, x = 81.82, y = 19.77, era = true, note = "Dark Leather Tunic, 75 reputation" },
