	} },
	{ title = "Stranglethorn Vale writ customers", note = "Booty Bay holds three customers: \"Sea Wolf\" MacKinley (on the inn's top floor), Scooty, the goblin transporter's engineer, and Narkk. Short John Mithril stands at the Gurubashi Arena, about 800 yards south of Grom'gol; Hekshi is in northern Stranglethorn. Customers show no quest mark: right-click them anyway.", when = {{ k = "onquest", q = {94226, 94235, 94244, 94217, 94253} }}, goals = {
		{ t = "turnin", quest = 94226, title = "Craftsman's Writ: Green Iron Gauntlets", npc = "\"Sea Wolf\" MacKinley", map = 1434, x = 27.78, y = 77.07, era = true, note = "Green Iron Gauntlets, 75 reputation" },
		{ t = "turnin", quest = 94235, title = "Craftsman's Writ: Gnomish Universal Remote", npc = "Scooty", map = 1434, x = 27.6, y = 77.48, era = true, note = "Gnomish Universal Remote, 75 reputation" },
		{ t = "turnin", quest = 94244, title = "Craftsman's Writ: Dark Leather Shoulders", npc = "Narkk", map = 1434, x = 28.13, y = 74.42, era = true, note = "Dark Leather Shoulders, 75 reputation" },
