	{ title = "Neutral to Friendly", note = "After the Shipping Label, Friendly is 1000 more: 14 Journeyman writs, 8 Expert or 5 Artisan. Expert and Artisan customers are mostly not in Polestar's data yet: follow the mark the quest puts on your map. Journeyman envelopes drop from mobs of about level 11 to 31; Expert and Artisan ones from higher mobs.", goals = {
		{ t = "rep", factionName = "Azeroth Commerce Authority", faction = 2586, standing = 5, only = { factions = {"Alliance"} } },
		{ t = "rep", factionName = "Durotar Supply and Logistics", faction = 2587, standing = 5, only = { factions = {"Horde"} } },
	} },
	{ title = "Gather your writs again", note = "Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, the one its title names. Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for.", goals = {
		{ t = "task", text = "Take the quests of the writs you can fill" },
	} },
	{ title = "Duskwood writ customers again", note = "Kzixx stands about 450 yards north of Darkshire, by the road. Customers show no quest mark: right-click them anyway.", when = {{ k = "onquest", q = {94214, 94232, 94241, 94250} }}, goals = {
