		{ t = "turnin", quest = 94241, title = "Craftsman's Writ: Dark Leather Tunic", npc = "Kzixx", map = 1431, x = 81.82, y = 19.77, era = true, note = "Dark Leather Tunic, 75 reputation" },
		{ t = "turnin", quest = 94250, title = "Craftsman's Writ: Small Silk Pack", npc = "Kzixx", map = 1431, x = 81.82, y = 19.77, era = true, note = "Small Silk Pack, 75 reputation" },
	} },
	{ title = "Stranglethorn Vale writ customers again", note = "Booty Bay holds three customers: \"Sea Wolf\" MacKinley (on the inn's top floor), Scooty at the zeppelin-style transporter pad and Narkk. Short John Mithril stands about 800 yards south of Grom'gol, by the Gurubashi Arena; Hekshi is in northern Stranglethorn. Customers show no quest mark: right-click them anyway.", when = {{ k = "onquest", q = {94226, 94235, 94244, 94217, 94253} }}, goals = {
		{ t = "turnin", quest = 94226, title = "Craftsman's Writ: Green Iron Gauntlets", npc = "\"Sea Wolf\" MacKinley", map = 1434, x = 27.78, y = 77.07, era = true, note = "Green Iron Gauntlets, 75 reputation" },
