	{ title = "A Heavy Quiver for the writ again", note = "Leatherworkers make the Heavy Quiver; the bow and gun vendors of Stormwind, Ironforge and the Undercity sell it. Otherwise buy one at the Auction House.", when = {{ k = "onquest", q = {94243} }, { k = "has", neg = true, n = 1, item = 7371 }}, goals = {
