	} },
	{ title = "Stonetalon Mountains writ customers again", note = "Ziz Fizziks has a small hut about 550 yards east of Sun Rock Retreat. Four Journeyman writs go to him. Customers show no quest mark: right-click them anyway.", when = {{ k = "onquest", q = {94216, 94225, 94234, 94243} }}, goals = {
		{ t = "turnin", quest = 94216, title = "Craftsman's Writ: Elixir of Lesser Agility", npc = "Ziz Fizziks", map = 1442, x = 58.99, y = 62.6, era = true, note = "Elixir of Lesser Agility, 75 reputation" },
