	} },
	{ title = "Thousand Needles writ customers again", note = "All five stand at the Mirage Raceway on the Shimmering Flats, south-east of Freewind Post: Rizzle Brassbolts, the chicken \"Plucky\" Johnson, Razzeric, the Goblin Pit Boss and Magus Tirth. Customers show no quest mark: right-click them anyway.", when = {{ k = "onquest", q = {94218, 94227, 94236, 94245, 94254} }}, goals = {
		{ t = "collect", quest = 94218, title = "Craftsman's Writ: Elixir of Defense", map = 1441, x = 77.22, y = 77.4, era = true, count = 1, item = 8951, itemName = "Elixir of Defense", oi = 2, note = "bring it: craft it or buy it at the Auction House" },
		{ t = "turnin", quest = 94218, title = "Craftsman's Writ: Elixir of Defense", npc = "Rizzle Brassbolts", map = 1441, x = 77.22, y = 77.4, era = true, note = "Elixir of Defense, 75 reputation" },
		{ t = "turnin", quest = 94227, title = "Craftsman's Writ: Big Bronze Knife", npc = "\"Plucky\" Johnson", map = 1441, x = 79.61, y = 75.63, era = true, note = "Big Bronze Knife, 75 reputation" },
		{ t = "turnin", quest = 94236, title = "Craftsman's Writ: Big Bronze Bomb", npc = "Razzeric", map = 1441, x = 80.33, y = 76.09, era = true, note = "Big Bronze Bomb, 75 reputation" },
		{ t = "turnin", quest = 94245, title = "Craftsman's Writ: Barbaric Gloves", npc = "Goblin Pit Boss", map = 1441, x = 79.9, y = 76.74, era = true, note = "Barbaric Gloves, 75 reputation" },
		{ t = "turnin", quest = 94254, title = "Craftsman's Writ: Greater Adept's Robe", npc = "Magus Tirth", map = 1441, x = 78.29, y = 75.7, era = true, note = "Greater Adept's Robe, 75 reputation" },
	} },
	{ title = "Friendly to Honored", note = "Friendly opens the first gated recipes at the camp's profession vendors (Tailoring 25, Leatherworking 17, Enchanting 13, Blacksmithing 10, Engineering 10, Alchemy 5, Cooking 2) and the Uncertified Scribe: Dianne Softstep at Three Corners, Kurvelk Shadowhoof at the south end of the Crossroads camp. The scribe's Forged Delivery Receipt (15 Merchant's Favor) turns an empty Waylaid Crate into a Notarized Shipping Container; hand it to Marcy Baker or Dokimi for 50 reputation (Crate Return). Any crate works, so buy the cheapest one the Auction House has. Honored is 6000 more: 80 Journeyman writs, 48 Expert, 30 Artisan, or 120 crate returns (1,800 Favor and 120 crates). Mix both: every writ you can fill, returns with spare Favor. The Legacy perk Diplomat adds up to 10% to every gain.", goals = {
		{ t = "rep", factionName = "Azeroth Commerce Authority", faction = 2586, standing = 6, only = { factions = {"Alliance"} } },
		{ t = "rep", factionName = "Durotar Supply and Logistics", faction = 2587, standing = 6, only = { factions = {"Horde"} } },
		{ t = "buy", npc = "Dianne Softstep", map = 1433, x = 9.29, y = 77.01, item = 262902, itemName = "Forged Delivery Receipt", optional = true, only = { factions = {"Alliance"} }, note = "Forged Delivery Receipt, 15 Merchant's Favor" },
		{ t = "buy", npc = "Kurvelk Shadowhoof", map = 1413, x = 49.91, y = 30.26, era = true, item = 262902, itemName = "Forged Delivery Receipt", optional = true, only = { factions = {"Horde"} }, note = "Forged Delivery Receipt, 15 Merchant's Favor" },
		{ t = "turnin", quest = 93862, title = "Crate Return", npc = "Marcy Baker", map = 1433, x = 9.71, y = 70.86, qlvl = 60, optional = true, only = { factions = {"Alliance"} }, note = "Crate Return: 50 reputation" },
		{ t = "turnin", quest = 93862, title = "Crate Return", npc = "Dokimi", map = 1413, x = 50.13, y = 29.37, era = true, qlvl = 60, optional = true, only = { factions = {"Horde"} }, note = "Crate Return: 50 reputation" },
	} },
	{ title = "Badlands writ customer", note = "Lotwil Veriatus works about 550 yards east of Kargath. He is the only Expert customer Polestar's data knows.", when = {{ k = "onquest", q = {94256} }}, goals = {
		{ t = "turnin", quest = 94256, title = "Craftsman's Writ: Frost Protection Potion", npc = "Lotwil Veriatus", map = 1418, x = 25.95, y = 44.87, era = true, note = "Frost Protection Potion, 125 reputation" },
	} },
	{ title = "Honored to Revered", note = "Honored opens the rest of the gated recipes (Leatherworking 28, Blacksmithing 21, Enchanting 16, Alchemy 15, Engineering 9, Tailoring 6, Cooking 1), the Advertising License Application (1,200 Favor from Tamelyn Aldridge or Gishah: it starts the quest for a Tradeskill Sign toy) and the scribe's Forger's Quill (15 Favor), which swaps a writ you cannot fill for a random one of the same rank. Revered is 12000 more: 160 Journeyman writs, 96 Expert, 60 Artisan, or 240 crate returns (3,600 Favor). Forever's quest data sets no standing limit on Journeyman writs: their customers are the ones in the zone steps above.", goals = {
		{ t = "rep", factionName = "Azeroth Commerce Authority", faction = 2586, standing = 7, only = { factions = {"Alliance"} } },
		{ t = "rep", factionName = "Durotar Supply and Logistics", faction = 2587, standing = 7, only = { factions = {"Horde"} } },
		{ t = "buy", npc = "Tamelyn Aldridge", map = 1433, x = 10.39, y = 70.84, item = 270888, itemName = "Advertising License Application", optional = true, only = { factions = {"Alliance"} }, note = "Advertising License Application, 1,200 Merchant's Favor" },
		{ t = "buy", npc = "Gishah", map = 1413, x = 49.07, y = 29.24, era = true, item = 270887, itemName = "Advertising License Application", optional = true, only = { factions = {"Horde"} }, note = "Advertising License Application, 1,200 Merchant's Favor" },
		{ t = "turnin", quest = 93862, title = "Crate Return", npc = "Marcy Baker", map = 1433, x = 9.71, y = 70.86, qlvl = 60, optional = true, only = { factions = {"Alliance"} }, note = "Crate Return: 50 reputation" },
		{ t = "turnin", quest = 93862, title = "Crate Return", npc = "Dokimi", map = 1413, x = 50.13, y = 29.37, era = true, qlvl = 60, optional = true, only = { factions = {"Horde"} }, note = "Crate Return: 50 reputation" },
	} },
	{ title = "Revered to Exalted", note = "Revered opens the Packmule Treat, the Minimule pet (1,500 Favor from Tamelyn Aldridge or Gishah). Exalted is 21000 more: 280 Journeyman writs, 168 Expert, 105 Artisan, or 420 crate returns (6,300 Favor). Keep 6,000 Favor for the Pack Kodo if you want it.", goals = {
		{ t = "rep", factionName = "Azeroth Commerce Authority", faction = 2586, standing = 8, only = { factions = {"Alliance"} } },
		{ t = "rep", factionName = "Durotar Supply and Logistics", faction = 2587, standing = 8, only = { factions = {"Horde"} } },
		{ t = "buy", npc = "Tamelyn Aldridge", map = 1433, x = 10.39, y = 70.84, item = 284664, itemName = "Packmule Treat", optional = true, only = { factions = {"Alliance"} }, note = "Packmule Treat, 1,500 Merchant's Favor" },
		{ t = "buy", npc = "Gishah", map = 1413, x = 49.07, y = 29.24, era = true, item = 284664, itemName = "Packmule Treat", optional = true, only = { factions = {"Horde"} }, note = "Packmule Treat, 1,500 Merchant's Favor" },
		{ t = "turnin", quest = 93862, title = "Crate Return", npc = "Marcy Baker", map = 1433, x = 9.71, y = 70.86, qlvl = 60, optional = true, only = { factions = {"Alliance"} }, note = "Crate Return: 50 reputation" },
		{ t = "turnin", quest = 93862, title = "Crate Return", npc = "Dokimi", map = 1413, x = 50.13, y = 29.37, era = true, qlvl = 60, optional = true, only = { factions = {"Horde"} }, note = "Crate Return: 50 reputation" },
	} },
	{ title = "Exalted", note = "Exalted opens the camp's tabard (200 Favor) at Tamelyn Aldridge or Gishah, and the Reins of the Pack Kodo (6,000 Favor; the mount needs level 60 and Journeyman mount training) at Huey Sunnydale in Three Corners or Okamache at the Crossroads camp. The Pack Kodo guide under Collectibles leads you there.", goals = {
		{ t = "buy", npc = "Tamelyn Aldridge", map = 1433, x = 10.39, y = 70.84, item = 262765, itemName = "Azeroth Commerce Authority Tabard", only = { factions = {"Alliance"} }, note = "Azeroth Commerce Authority Tabard, 200 Merchant's Favor" },
		{ t = "buy", npc = "Gishah", map = 1413, x = 49.07, y = 29.24, era = true, item = 262764, itemName = "Durotar Supply and Logistics Tabard", only = { factions = {"Horde"} }, note = "Durotar Supply and Logistics Tabard, 200 Merchant's Favor" },
	} },
} end)

Waypost.RegisterSteps("reputation/nightclaw-druids", function() return {
	{ title = "Skyboat from Dalaran", note = "Zephras Isle is the Skyborne starting island, open to everyone. A skyboat leaves the north side of Dalaran about every five minutes; another flies from north of Thunder Bluff, and either faction may take either.", only = { factions = {"Alliance"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1416, x = 12.5, y = 51.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Skyboat from Thunder Bluff", note = "Zephras Isle is the Skyborne starting island, open to everyone. A skyboat leaves the cliffs south of Skywatcher Plateau, north of Thunder Bluff, about every five minutes; another flies from Dalaran, and either faction may take either.", only = { factions = {"Horde"} }, when = {{ k = "zone", neg = true, name = "Zephras Isle", area = 16593 }}, goals = {
		{ t = "goto", map = 1412, x = 34.3, y = 25.8, text = "Skyboat to Zephras Isle" },
	} },
	{ title = "Lotheluum Starbreeze", note = "Lotheluum stands in Valanaar, the Skyborne town in the south of the isle, and has heard nothing from the druids up north. His errand is the start of the Nightclaw storyline (level 8 and up, any race). Every quest of it pays Nightclaw reputation: 4100 in all, enough for Friendly. Players' turn-ins paid their full reputation well above these quests' level.", goals = {
		{ t = "accept", quest = 94484, title = "Unnerving Silence", npc = "Lotheluum Starbreeze", map = 2521, x = 63.99, y = 75.08, qlvl = 11 },
	} },
	{ title = "Elegael Thornpaw", note = "Head north into the Shadowgale Forest. Elegael Thornpaw holds the druids' camp in its north-east.", goals = {
		{ t = "turnin", quest = 94484, title = "Unnerving Silence", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22 },
		{ t = "accept", quest = 94485, title = "Tears of the Lady", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, qlvl = 12 },
		{ t = "accept", quest = 94486, title = "Feathers for Binding", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, qlvl = 11 },
		{ t = "accept", quest = 94487, title = "Unwanted and Unworthy", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, qlvl = 11 },
	} },
	{ title = "Vayn Moongaze", note = "Vayn Moongaze, the druids' quartermaster, waits inside their den: the cave just across the clearing north-east of Elegael (Nightclaw Cavern on the map; Elegael calls it the Nightfang Den). Take his ear quest now: the cultists you fight for Elegael drop ears for it.", goals = {
		{ t = "accept", quest = 93165, title = "Mercy Falls on Deaf Ears", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, qlvl = 13 },
	} },
	{ title = "Shadowgale Forest", note = "The Al'Aketh Footsoldiers and Stormchasers camp just north of Elegael and drop the Bloody Heirlooms (and ears, about one kill in four). The Shadowgale Shrieklings flying west of her drop the feathers; the Lady's Tear Moss grows on the trees along the stream west of her.", goals = {
		{ t = "collect", quest = 94487, title = "Unwanted and Unworthy", map = 2521, x = 63.76, y = 36.06, count = 10, item = 265141, itemName = "Bloody Heirloom", oi = 1, mobLevel = 11, spots = "63.8,35.9;62.6,36.5;64.4,38.2;62.7,38.3;65.6,36.5" },
		{ t = "collect", quest = 94486, title = "Feathers for Binding", map = 2521, x = 63.91, y = 37.5, count = 20, item = 265140, itemName = "Pristine Shriekling Feather", oi = 1, mobLevel = 11, spots = "63.5,37.1;64.4,41;63.6,43.6;59.4,42.9;59.4,40.1" },
