		{ t = "collect", quest = 94488, title = "The Ties That Bind", map = 2521, x = 65.53, y = 36.32, count = 1, item = 265475, itemName = "Commander Haalien's Severed Head", oi = 1 },
		{ t = "accept", quest = 94490, title = "Ripped Missive", item = 265476, itemName = "Ripped Missive", qlvl = 12, note = "from Commander Haalien" },
	} },
	{ title = "Elegael, the den's fate", goals = {
		{ t = "turnin", quest = 94488, title = "The Ties That Bind", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, note = "1000 reputation" },
		{ t = "turnin", quest = 94489, title = "The Wounds of Betrayal", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, note = "500 reputation" },
		{ t = "turnin", quest = 94490, title = "Ripped Missive", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, note = "500 reputation" },
		{ t = "accept", quest = 94491, title = "The Fate of the Den", npc = "Elegael Thornpaw", map = 2521, x = 61.7, y = 39.22, qlvl = 12 },
	} },
	{ title = "Ears at the Shrine of Akir", note = "The best ears are south of the forest at the Shrine of Akir: Skypriests drop one in more than half their kills, Guardians in four of ten, Spiritcallers and Honor Guards in a third. The Gustberry Lowlands just north-west of Valanaar are next best (Brawlers and Pillagers, about four in ten). All cultists are level 8 to 10.", goals = {
		{ t = "collect", quest = 93165, title = "Mercy Falls on Deaf Ears", map = 2521, x = 61.9, y = 45.11, count = 10, item = 258771, itemName = "Al'Aketh Cultist's Ear", oi = 1, mobLevel = 11, spots = "63.3,46.2;66.3,47.7;66.3,52;62.4,52.4;59.3,53" },
	} },
	{ title = "Mercy Falls on Deaf Ears", note = "Back to Vayn inside the den. Ten ears for 1000 reputation and a green piece: leather gloves, cloth pants or mail boots. Vayn then takes ears five at a time, for 1000 each, as often as you like, up to level 18; in Classic the pay drops from level 19 and is 200 from level 22. The Legacy perk Diplomat adds up to 10% to every gain.", goals = {
		{ t = "turnin", quest = 93165, title = "Mercy Falls on Deaf Ears", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, note = "1000 reputation" },
	} },
	{ title = "Back to Valanaar", note = "Lotheluum waits in Valanaar. Hand in on your way to a skyboat or to the Gustberry Lowlands.", goals = {
		{ t = "turnin", quest = 94491, title = "The Fate of the Den", npc = "Lotheluum Starbreeze", map = 2521, x = 63.99, y = 75.08, note = "500 reputation" },
	} },
	{ title = "Friendly to Honored", note = "The storyline and Vayn's first quest leave you at Friendly with 2100 to spare. Honored is 3900 more: four turn-ins of five ears up to level 18, twenty from level 22. Friendly opens 32 of Vayn's patterns, in two colours, Cloudy and Azure: Blacksmithing Skyforged Wristguards and Chain (skill 50, 9s 50c), Gauntlets and Greaves (55, 11s); Leatherworking Gustwoven and Windraveled bracers and belts (50) and gloves and boots (55); Tailoring Stormsewn Cuffs and Cord (50), Handwraps and Shoes (55). They bind when you buy them, so buy them on the crafter.", goals = {
		{ t = "rep", factionName = "Nightclaw Druids", faction = 2758, standing = 6 },
		{ t = "collect", map = 2521, x = 65.42, y = 71.96, count = 5, item = 258771, itemName = "Al'Aketh Cultist's Ear", mobLevel = 11, optional = true, note = "five ears per turn-in", spots = "65.5,71.4;64.8,67.9;66.3,64.1;68.4,67.5;64.9,58.3" },
		{ t = "turnin", quest = 93459, title = "More Al'Aketh Ears", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, qlvl = 13, optional = true, note = "More Al'Aketh Ears: 1000 reputation, handed in from Vayn's window" },
		{ t = "vendor", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, optional = true, note = "Vayn's patterns" },
	} },
	{ title = "Honored to Revered", note = "Honored opens the chest and leg patterns (skill 60, 12s 50c): Skyforged chainmail and legguards, Gustwoven harness and trousers, Windraveled jerkin and pants, Stormsewn vest and leggings. Revered is 12000 more: 12 turn-ins (60 ears, about 160 cultist kills at the Shrine) up to level 18, 60 turn-ins (300 ears) from level 22.", goals = {
		{ t = "rep", factionName = "Nightclaw Druids", faction = 2758, standing = 7 },
		{ t = "collect", map = 2521, x = 65.32, y = 44.13, count = 5, item = 258771, itemName = "Al'Aketh Cultist's Ear", mobLevel = 11, optional = true, note = "five ears per turn-in", spots = "65,44.8;64.6,51;61.8,49.9;59.3,53;62.2,61.7" },
		{ t = "turnin", quest = 93459, title = "More Al'Aketh Ears", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, qlvl = 13, optional = true, note = "More Al'Aketh Ears: 1000 reputation, handed in from Vayn's window" },
		{ t = "vendor", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, optional = true, note = "Vayn's patterns" },
	} },
	{ title = "Revered to Exalted", note = "Revered opens the Shadowgale Squirrel, a companion pet, for 50s. Exalted is 21000 more: 21 turn-ins (105 ears, about 280 kills) up to level 18, 105 turn-ins (525 ears) from level 22.", goals = {
		{ t = "rep", factionName = "Nightclaw Druids", faction = 2758, standing = 8 },
		{ t = "collect", map = 2521, x = 65.32, y = 44.13, count = 5, item = 258771, itemName = "Al'Aketh Cultist's Ear", mobLevel = 11, optional = true, note = "five ears per turn-in", spots = "65,44.8;64.6,51;61.8,49.9;59.3,53;62.2,61.7" },
		{ t = "turnin", quest = 93459, title = "More Al'Aketh Ears", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, qlvl = 13, optional = true, note = "More Al'Aketh Ears: 1000 reputation, handed in from Vayn's window" },
		{ t = "buy", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, item = 280347, itemName = "Shadowgale Squirrel", optional = true, note = "Shadowgale Squirrel, 50s" },
	} },
	{ title = "The Nightclaw Mantle", note = "Exalted opens the Nightclaw Mantle, green cloth shoulders for level 15, for 8s 16c.", goals = {
		{ t = "buy", npc = "Vayn Moongaze", map = 2521, x = 63.81, y = 36.01, item = 280363, itemName = "Nightclaw Mantle" },
	} },
} end)

Waypost.RegisterSteps("reputation/ravenholdt", function() return {
	{ title = "The Manor, Ravenholdt", note = "Rogues from level 24: ask your class trainer in a capital \"May I have it, please?\" for the Elegant Letter, and read it. The path up to the manor starts in the hills north of Durnholde Keep. In the tunnel on the way lies a chest: do not open it (an elite guard jumps out), just walk past it to earn the Rite of Cunning. Fahrad waits on the manor's balcony.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "accept", quest = 6681, title = "The Manor, Ravenholdt", item = 17126, itemName = "Elegant Letter", qlvl = 24, note = "Elegant Letter, from your class trainer" },
		{ t = "kill", quest = 6681, title = "The Manor, Ravenholdt", map = 1424, x = 78.64, y = 17.84, era = true, count = 1, target = "Ravenholdt", oi = 1, note = "walk past the trapped chest in the tunnel" },
		{ t = "turnin", quest = 6681, title = "The Manor, Ravenholdt", npc = "Fahrad", map = 1416, x = 84.45, y = 80.32, era = true, note = "Fahrad: 100 reputation" },
	} },
	{ title = "Myrokos Silentform", note = "Myrokos Silentform, in the manor, has Forever's new rogue quests: 100 reputation each for Syndicate Sabotage, What's the Big Idea? and Covert Extraction, which follows it, and 300 for The Syndicate Sting at the end of the Stromgarde chain (A Way In and the two quests after it pay nothing). All can be done solo with stealth from level 30; below that, the Master of Deception talent and a Flash Powder for Vanish help.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "accept", quest = 96779, title = "Syndicate Sabotage", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 24 },
		{ t = "accept", quest = 96781, title = "What's the Big Idea?", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 36 },
		{ t = "accept", quest = 96783, title = "A Way In", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 36 },
	} },
	{ title = "Durnholde Keep: Lord Tomas", note = "Lord Tomas is inside Durnholde Keep, the Syndicate fortress east of Southshore. Stealth past the guards in the courtyard.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "kill", quest = 96779, title = "Syndicate Sabotage", map = 1424, x = 79.35, y = 46.02, era = true, count = 1, target = "Lord Tomas", oi = 1, mobLevel = 24 },
	} },
	{ title = "Strahnbrad: Barton", note = "Barton hides in a house in Strahnbrad, among stealthed Syndicate. Pick his pocket for the report; Distract turns him around if you are under his level.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "collect", quest = 96781, title = "What's the Big Idea?", map = 1416, x = 62.6, y = 46.9, era = true, count = 1, item = 275482, itemName = "Barton's Scouting Report", oi = 1, note = "Barton's Scouting Report: pickpocket Barton" },
	} },
	{ title = "Northfold Manor: a uniform", note = "The Syndicate Footlocker stands among the Syndicate camps of Northfold Manor, north of Stromgarde. Open it to finish A Way In and take the Syndicate Uniform.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "turnin", quest = 96783, title = "A Way In", npc = "Syndicate Footlocker", map = 1417, x = 32.3, y = 26.6, era = true },
		{ t = "accept", quest = 96784, title = "Master of Disguise", npc = "Syndicate Footlocker", map = 1417, x = 32.3, y = 26.6, era = true, qlvl = 36 },
	} },
	{ title = "Stromgarde: Anastasia Miller", note = "Put on the Syndicate Uniform and go into Stromgarde. Anastasia Miller waits on a ledge just outside the castle; players reach her by jumping from the roof of the house beside the ledge. Her stash is upstairs in a house near the keep.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "turnin", quest = 96784, title = "Master of Disguise", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true },
		{ t = "accept", quest = 96785, title = "Ain't No Telling", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true, qlvl = 36 },
		{ t = "collect", quest = 96785, title = "Ain't No Telling", map = 1417, x = 29.5, y = 65.1, era = true, count = 1, item = 275709, itemName = "Stolen Funds", oi = 1, note = "Stolen Funds, in Anastasia's Stash upstairs" },
		{ t = "turnin", quest = 96785, title = "Ain't No Telling", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true },
		{ t = "accept", quest = 96786, title = "The Syndicate Sting", npc = "Anastasia Miller", map = 1417, x = 26.8, y = 64.4, era = true, qlvl = 36 },
	} },
	{ title = "Thoradin's Wall: the shipment", note = "The hand-off is at the southern end of Thoradin's Wall, in the west of the Arathi Highlands: two Syndicate guard the box. Kill them or lure them off, then take the Intercepted Shipment. Keep the uniform: Myrokos wants it back.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "collect", quest = 96786, title = "The Syndicate Sting", map = 1417, x = 15.5, y = 43, era = true, count = 1, item = 275882, itemName = "Intercepted Shipment", oi = 1 },
	} },
	{ title = "Back to Myrokos", only = { classes = {"ROGUE"} }, goals = {
		{ t = "turnin", quest = 96779, title = "Syndicate Sabotage", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, note = "100" },
		{ t = "turnin", quest = 96781, title = "What's the Big Idea?", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, note = "100" },
		{ t = "turnin", quest = 96786, title = "The Syndicate Sting", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, note = "300" },
		{ t = "accept", quest = 96782, title = "Covert Extraction", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, qlvl = 36, optional = true, note = "Covert Extraction, after What's the Big Idea?" },
	} },
	{ title = "Ruins of Alterac: the Perenolde heirlooms", note = "The two heirlooms lie in two towers of the Ruins of Alterac, the ogre-held ruin in the middle of the Alterac Mountains. The tower with the sword is ringed by elite ogres: stay in stealth. Neither item is guarded once you are inside.", only = { classes = {"ROGUE"} }, when = {{ k = "onquest", q = {96782} }}, goals = {
		{ t = "collect", quest = 96782, title = "Covert Extraction", map = 1416, x = 41.4, y = 40.2, era = true, count = 1, item = 275636, itemName = "Royal Aegis of Perenolde", oi = 2, note = "Royal Aegis of Perenolde, the shield" },
		{ t = "collect", quest = 96782, title = "Covert Extraction", map = 1416, x = 38.5, y = 58, era = true, count = 1, item = 275635, itemName = "Blade of House Perenolde", oi = 1, note = "Blade of House Perenolde, the sword" },
		{ t = "turnin", quest = 96782, title = "Covert Extraction", npc = "Myrokos Silentform", map = 1416, x = 84.93, y = 80.38, era = true, note = "Myrokos Silentform: 100" },
	} },
	{ title = "Syndicate Emblems to Friendly", note = "Neutral to Friendly is 3,000 reputation; the quests above pay 700 of it. Any Ravenholdt Guard on the path takes Syndicate Emblems, 100 reputation each, until you reach Friendly: 23 emblems after the quests. Pick the pockets of Syndicate humans; they never drop emblems when killed. The Arathi camps pay best: Syndicate Prowlers and Conjurors carry one about a quarter of the time. Kill what you have robbed so the next ones respawn fresh.", only = { classes = {"ROGUE"} }, goals = {
		{ t = "collect", map = 1417, x = 30, y = 27, era = true, count = 5, item = 17124, itemName = "Syndicate Emblem", mobLevel = 33, optional = true, note = "Syndicate Emblem: pickpocket Syndicate", spots = "30,27;33,31.2;34.2,27.7" },
		{ t = "turnin", quest = 6701, title = "Syndicate Emblems", npc = "Ravenholdt Guard", map = 1416, x = 83.69, y = 77.93, era = true, qlvl = 60, optional = true, note = "a Ravenholdt Guard: 100 per emblem, handed in from his window" },
		{ t = "rep", factionName = "Ravenholdt", faction = 349, standing = 5 },
	} },
	{ title = "Syndicate kills to the end of Honored", note = "Everyone, not only rogues: in Classic every Syndicate human gave Ravenholdt 5 reputation up to the end of Honored (11,999 of 12,000) and not one point more, so 0 to there is 4,200 kills (3,600 after a rogue's quests and emblems). This step ticks at Honored; keep killing until the bar stops moving, then go on to the junkboxes. The highest Syndicate are in the north-west of the Alterac Mountains, Syndicate Assassins and Enforcers (level 38-40), with Syndicate Sentries (36-37) nearer the middle. At 60 all Syndicate are grey, and in Classic grey kills gave about a fifth: farm them before 48 if you can. Legacy Diplomat adds up to 10%.", goals = {
		{ t = "kill", map = 1416, x = 38.3, y = 15.4, era = true, target = "Syndicate Assassin", optional = true, note = "Syndicate Assassin, level 38-39", spots = "38.3,15.4;47.4,17.5" },
		{ t = "kill", map = 1416, x = 38.3, y = 15.4, era = true, target = "Syndicate Enforcer", optional = true, note = "Syndicate Enforcer, level 39-40", spots = "38.3,15.4;47.4,17.5" },
		{ t = "kill", map = 1416, x = 38.3, y = 15.4, era = true, target = "Syndicate Sentry", optional = true, note = "Syndicate Sentry, level 36-37", spots = "38.3,15.4;47.4,17.5" },
		{ t = "rep", factionName = "Ravenholdt", faction = 349, standing = 6 },
	} },
	{ title = "A Simple Request, rogues 50+", note = "At level 50 your class trainer has another letter for you, and Lord Jorach Ravenholdt a short chain: 360 reputation in all. The Sealed Azure Bag drops from Timbermaw Shamans in northern Azshara (about 1 in 27, or pick their pockets); the Encoded Fragments from Forest Oozes in Azshara (4 in 5). The Azure Key comes from Morphaz, an elite drake deep in the Temple of Atal'Hakkar: a five-player dungeon, group up.", only = { classes = {"ROGUE"} }, when = {{ k = "level", op = ">=", n = 50 }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8233, title = "A Simple Request", npc = "Osborne the Night Man", map = 1453, x = 77.43, y = 65.31, qlvl = 52, only = { factions = {"Alliance"} }, note = "Osborne the Night Man, Stormwind" },
		{ t = "accept", quest = 8233, title = "A Simple Request", npc = "Ormok", map = 1454, x = 43.9, y = 54.63, era = true, qlvl = 52, only = { factions = {"Horde"} }, note = "Ormok, Orgrimmar" },
		{ t = "turnin", quest = 8233, title = "A Simple Request", npc = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, era = true },
		{ t = "accept", quest = 8234, title = "Sealed Azure Bag", npc = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, era = true, qlvl = 52 },
		{ t = "collect", quest = 8234, title = "Sealed Azure Bag", map = 1447, x = 44.38, y = 24.58, era = true, count = 1, item = 19775, itemName = "Sealed Azure Bag", oi = 1, mobLevel = 51, note = "Sealed Azure Bag: Timbermaw Shamans", spots = "45.5,25.4;44.2,26.6;45.8,22.3;44.6,21.4;42.8,18.5" },
		{ t = "turnin", quest = 8234, title = "Sealed Azure Bag", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 8235, title = "Encoded Fragments", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52 },
		{ t = "collect", quest = 8235, title = "Encoded Fragments", map = 1447, x = 36.16, y = 67.86, era = true, count = 10, item = 20023, itemName = "Encoded Fragment", oi = 1, mobLevel = 53, note = "Encoded Fragment: Forest Oozes", spots = "37.5,69.6;43.1,70.5;69.5,27.9;75.7,27.5;80.4,24.5" },
		{ t = "turnin", quest = 8235, title = "Encoded Fragments", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true },
		{ t = "accept", quest = 8236, title = "The Azure Key", npc = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, era = true, qlvl = 52 },
		{ t = "collect", quest = 8236, title = "The Azure Key", map = 1435, x = 70.2, y = 45.2, era = true, count = 1, item = 20022, itemName = "Azure Key", oi = 1, optional = true, group = true, note = "Azure Key: Morphaz, Temple of Atal'Hakkar (group)" },
		{ t = "turnin", quest = 8236, title = "The Azure Key", npc = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, era = true, optional = true, note = "Lord Jorach Ravenholdt: 150" },
	} },
	{ title = "Heavy Junkboxes to Exalted", note = "From the top of Honored to Exalted is 21,001 reputation, and Junkboxes Needed is the only way: Fahrad pays 50 and a Dusksteel Throwing Knife for every five Heavy Junkboxes (Classic Era paid 75), 421 turn-ins and 2,105 boxes. Boxes count at any standing, so take the cheap kills to their cap first. Any class can hand them in. Rogues get them by picking the pockets of humanoids around level 50 and up: Lower Blackrock Spire and Blackrock Depths are the classic spots, pick every pocket, reset and go again. The boxes do not bind, so everyone else buys them from rogues or at the auction house. Hand them in unopened; an opened box you empty vanishes, so leave one item in it.", goals = {
		{ t = "level", level = 50 },
		{ t = "collect", map = 1427, x = 32.1, y = 94.7, era = true, count = 5, item = 16885, itemName = "Heavy Junkbox", optional = true, note = "Heavy Junkbox: pickpocket level 50+ humanoids, Blackrock Mountain" },
		{ t = "turnin", quest = 8249, title = "Junkboxes Needed", npc = "Fahrad", map = 1416, x = 84.45, y = 80.32, era = true, qlvl = 60, optional = true, note = "Fahrad: 50 per five boxes, handed in from his window" },
		{ t = "rep", factionName = "Ravenholdt", faction = 349, standing = 8 },
	} },
} end)

Waypost.RegisterSteps("reputation/steamwheedle-cartel", function() return {
	{ title = "Zorbin Fandazzle", note = "Five goblin towns share one reputation family, the Steamwheedle Cartel: Ratchet, Booty Bay, Gadgetzan, Everlook and Forever's new Powderfuse in the Riverglades. Everyone starts each at Neutral (500 into it). A gain with one town gives the others half as much; a quest for the Cartel itself, like Zorbin's, pays every town in full. Losses spread the same way: a Booty Bay Bruiser or any goblin of the towns costs 125 (half that with the other towns), and Bloodsail Buccaneers reputation is earned only that way. Zorbin camps on the road through central Feralas and works for anyone, even players the goblins hate. His first two quests are level 48 and open his repeatables (level 55); Forever pays all of them in full at any level.", goals = {
		{ t = "accept", quest = 7003, title = "Zapped Giants", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, qlvl = 48, note = "Zapped Giants: 150 to every town" },
		{ t = "accept", quest = 7721, title = "Fuel for the Zapping", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, qlvl = 48, note = "Fuel for the Zapping: 150 to every town" },
	} },
	{ title = "Zapped giants", note = "Use Zorbin's Ultra-Shrinker on a living giant (Land Walker, Cliff Giant, or a Shore, Deep or Wave Strider, level 47-50) and it shrinks into a zapped version; kill that for its Miniaturization Residue, one every time. The Land Walkers and Cliff Giants in the north-west hills are the thickest; the striders walk the coast and the shallows. The shrinker lasts two hours: if it runs out, abandon the quest and take it again.", goals = {
		{ t = "use", map = 1444, x = 37.8, y = 22, era = true, item = 18904, itemName = "Zorbin's Ultra-Shrinker", optional = true, note = "Zorbin's Ultra-Shrinker, on a living giant" },
		{ t = "collect", quest = 7003, title = "Zapped Giants", map = 1444, x = 37.8, y = 22, era = true, count = 15, item = 18956, itemName = "Miniaturization Residue", oi = 1, note = "Miniaturization Residue, from the zapped giants", spots = "37.8,22;36.4,34;44.3,46.6;45.1,58" },
	} },
	{ title = "Sea Elementals and Sea Sprays", note = "The Sea Elementals and Sea Sprays (level 47-49) drift along the Forgotten Coast and in the shallows below the giants: about half drop a Water Elemental Core.", goals = {
		{ t = "collect", quest = 7721, title = "Fuel for the Zapping", map = 1444, x = 34.4, y = 35.6, era = true, count = 10, item = 18958, itemName = "Water Elemental Core", oi = 1, note = "Water Elemental Core: Sea Elementals and Sea Sprays", spots = "34.4,35.6;44.5,52.5" },
	} },
	{ title = "Back to Zorbin", note = "From now on Zorbin offers Again With the Zapped Giants (10 residue) and Refuel for the Zapping (6 cores), again and again: 25 reputation with every town each time.", goals = {
		{ t = "turnin", quest = 7003, title = "Zapped Giants", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true },
		{ t = "turnin", quest = 7721, title = "Fuel for the Zapping", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true },
	} },
	{ title = "Lost Rigger Cove, below 56", note = "The Southsea pirates of Lost Rigger Cove (level 44-45) on the east coast of Tanaris give Gadgetzan 5 each up to the end of Honored, and the other towns half. Two quests at Steamwheedle Port pay 100 Gadgetzan each: Southsea Shakedown (10 of each pirate) and Pirate Hats Ahoy! (20 Southsea Pirate Hats, one in ten pirates). From level 56 the pirates are grey and pay little: skip this step then.", when = {{ k = "level", op = "<", n = 56 }}, goals = {
		{ t = "accept", quest = 8366, title = "Southsea Shakedown", npc = "Security Chief Bilgewhizzle", map = 1446, x = 67.06, y = 23.89, era = true, qlvl = 45, note = "Security Chief Bilgewhizzle, Steamwheedle Port" },
		{ t = "accept", quest = 8365, title = "Pirate Hats Ahoy!", npc = "Haughty Modiste", map = 1446, x = 66.56, y = 22.27, era = true, qlvl = 45 },
		{ t = "kill", quest = 8366, title = "Southsea Shakedown", map = 1446, x = 70.9, y = 42.48, era = true, count = 10, target = "Southsea Pirate", oi = 1, mobLevel = 45, spots = "71.1,43.1;72.3,44.4;71.4,45.8;73.6,46.2;72.1,47.9" },
		{ t = "kill", quest = 8366, title = "Southsea Shakedown", map = 1446, x = 70.95, y = 43.14, era = true, count = 10, target = "Southsea Freebooter", oi = 2, mobLevel = 45, spots = "71.1,43.3;72,44.6;71.3,46.6;73,45.2;72.4,48" },
		{ t = "kill", quest = 8366, title = "Southsea Shakedown", map = 1446, x = 73.32, y = 47.27, era = true, count = 10, target = "Southsea Dock Worker", oi = 3, mobLevel = 45 },
		{ t = "kill", quest = 8366, title = "Southsea Shakedown", map = 1446, x = 73.29, y = 47.87, era = true, count = 10, target = "Southsea Swashbuckler", oi = 4, mobLevel = 45, spots = "72.7,47.3;75.4,45.6" },
		{ t = "collect", quest = 8365, title = "Pirate Hats Ahoy!", map = 1446, x = 73.29, y = 47.87, era = true, count = 20, item = 20519, itemName = "Southsea Pirate Hat", oi = 1, mobLevel = 45, spots = "73,48;73.4,46.3;74.5,47.4;71.6,46.6;72.2,44.6" },
		{ t = "turnin", quest = 8366, title = "Southsea Shakedown", npc = "Security Chief Bilgewhizzle", map = 1446, x = 67.06, y = 23.89, era = true },
		{ t = "turnin", quest = 8365, title = "Pirate Hats Ahoy!", npc = "Haughty Modiste", map = 1446, x = 66.56, y = 22.27, era = true },
	} },
	{ title = "Tinkee Steamboil", note = "Tinkee Steamboil, a goblin at Flame Crest in the north of the Burning Steppes, has a chain that pays every town 150 and Everlook 150 more. Use her Draco-Incarcinatrix 900 on a broodling, kill it while the device holds it, and pick up the Broodling Essence it leaves. The device takes only Black and Scalding Broodlings, not the Flamescale Broodlings of the west: Scalding Broodlings (level 53-54) roam just west and east of Flame Crest, Black Broodlings (51-52) the north-east corner of the zone, the thickest group. They are few and spread out: the path passes both and ends among the Black Broodlings.", goals = {
		{ t = "accept", quest = 4726, title = "Broodling Essence", npc = "Tinkee Steamboil", map = 1428, x = 65.24, y = 24, era = true, qlvl = 52 },
		{ t = "goto", map = 1428, x = 59.2, y = 32.3, era = true, text = "Scalding Broodlings west of Flame Crest" },
		{ t = "goto", map = 1428, x = 73.2, y = 27.1, era = true, text = "Scalding Broodlings east of Flame Crest" },
		{ t = "goto", map = 1428, x = 87.8, y = 33.5, era = true, text = "Black Broodlings in the north-east" },
		{ t = "use", map = 1428, x = 87.8, y = 33.5, era = true, item = 12284, itemName = "Draco-Incarcinatrix 900", optional = true, note = "Draco-Incarcinatrix 900, on a Black or Scalding Broodling" },
		{ t = "collect", quest = 4726, title = "Broodling Essence", map = 1428, x = 87.8, y = 33.5, era = true, count = 8, item = 12283, itemName = "Broodling Essence", oi = 1, note = "Broodling Essence, left by the broodlings", spots = "87.8,33.5;91.7,35.8;90.2,45.5;80.3,27.4;90.5,50.9" },
		{ t = "turnin", quest = 4726, title = "Broodling Essence", npc = "Tinkee Steamboil", map = 1428, x = 65.24, y = 24, era = true, note = "100 to every town" },
		{ t = "accept", quest = 4808, title = "Felnok Steelspring", npc = "Tinkee Steamboil", map = 1428, x = 65.24, y = 24, era = true, qlvl = 54 },
	} },
	{ title = "Everlook: Felnok Steelspring", note = "Felnok Steelspring is in Everlook. The Chillwind Chimaeras (level 55-57) south-west of Everlook drop the horns one time in five.", goals = {
		{ t = "turnin", quest = 4808, title = "Felnok Steelspring", npc = "Felnok Steelspring", map = 1452, x = 61.63, y = 38.61, era = true, note = "50 Everlook" },
		{ t = "accept", quest = 4809, title = "Chillwind Horns", npc = "Felnok Steelspring", map = 1452, x = 61.63, y = 38.61, era = true, qlvl = 54 },
		{ t = "collect", quest = 4809, title = "Chillwind Horns", map = 1452, x = 55.4, y = 47.5, era = true, count = 8, item = 12444, itemName = "Uncracked Chillwind Horn", oi = 1, mobLevel = 57, note = "Uncracked Chillwind Horn: Chillwind Chimaeras", spots = "55.4,47.5;59.1,44;57.4,40.8;55.6,37.1;61.2,41.7" },
		{ t = "turnin", quest = 4809, title = "Chillwind Horns", npc = "Felnok Steelspring", map = 1452, x = 61.63, y = 38.61, era = true, note = "100 Everlook" },
		{ t = "accept", quest = 4810, title = "Return to Tinkee", npc = "Felnok Steelspring", map = 1452, x = 61.63, y = 38.61, era = true, qlvl = 54 },
	} },
	{ title = "Back to Tinkee", note = "Return to Tinkee gives 50 to every town. Her later quests, Egg Freezing (150 to every town) and Egg Collection (200), are done in the Rookery of Upper Blackrock Spire, a ten-player dungeon: take them up with your group.", goals = {
		{ t = "turnin", quest = 4810, title = "Return to Tinkee", npc = "Tinkee Steamboil", map = 1428, x = 65.24, y = 24, era = true },
	} },
	{ title = "Dire Maul North: Knot Thimblejack", note = "Knot Thimblejack sits shackled in Dire Maul North, the Gordok ogres' wing (a five-player dungeon from level 57: group up). Every Gordok Shackle Key frees him once: 150 to every town, and he is shackled again on your next run. Gordok ogres drop the keys (about one in fifteen; Guard Fengus one in seven): a full run of the wing usually brings one. His Gordok Ogre Suit pays 100 the first time and 50 after, for 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Thread and the Ogre Tannin from the basket in the wing. Under 57 when you get here? Unskip this step later.", when = {{ k = "level", op = ">=", n = 57 }}, goals = {
		{ t = "level", level = 57 },
		{ t = "goto", map = 1444, x = 59.2, y = 45.1, era = true, text = "Dire Maul" },
		{ t = "collect", map = 1444, x = 59.2, y = 45.1, era = true, item = 18250, itemName = "Gordok Shackle Key", optional = true, group = true, note = "Gordok Shackle Key, Gordok ogres" },
		{ t = "turnin", quest = 5525, title = "Free Knot!", npc = "Knot Thimblejack", map = 1444, x = 59.2, y = 45.1, era = true, qlvl = 60, optional = true, group = true, note = "Free Knot!: 150 to every town, handed in from Knot's window" },
		{ t = "turnin", quest = 7429, title = "Free Knot!", npc = "Knot Thimblejack", map = 1444, x = 59.2, y = 45.1, era = true, qlvl = 60, optional = true, group = true, note = "Free Knot!, again on every later run: 150" },
	} },
	{ title = "Every town to Friendly", note = "Neutral 500 to Friendly is 2,500 with each town. The quests above pay every town up to 700 (Zorbin's two 300, Tinkee's 150, the first Free Knot 150 and the first Ogre Suit 100); Zorbin's repeatables do the rest, 25 to every town each: 10 residue (ten giants) or 6 cores (about twelve elementals). The towns' own quests count too, each giving the other towns half: Ratchet's in the Barrens (levels 10-25, about 4,300: the Samophlange chain 625, Mebok Mizzyrix's errands, the Wizzlecrank and Gilthares escorts 150 each), Booty Bay's in Stranglethorn, Arathi and the Badlands (30-50, about 6,500: the three OOX robot rescues 250 each, An OOX of Your Own 200, Stranglethorn Fever 200, Facing Negolash 200, the Sunken Treasure chain at Faldir's Cove), Gadgetzan's in Tanaris (43-55, about 3,000: the Divino-matic Rod 200, Wastewander Justice 100 each, the WANTED posters) and Everlook's in Winterspring (52-60, about 1,450: Donova Snowden's Winterfall chain, Umi's yeti quests). Forever adds a few low ones: A Simmering Storm and Stormy Potential in Durotar and WANTED: Bruuz (Ratchet 100 each), Important Heirlooms in Ironforge (Gadgetzan 100). Forever pays them in full at any level. Kills help while they are not grey, 5 each: Southsea pirates in the Barrens for Ratchet and in Tanaris for Gadgetzan and Stranglethorn's Venture Co. camps for Booty Bay, up to the end of Honored; Wastewander bandits for Gadgetzan and Bloodsail pirates for Booty Bay only up to the end of Neutral. Friendly opens each quartermaster's first gear.", goals = {
		{ t = "accept", quest = 7725, title = "Again With the Zapped Giants", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, qlvl = 55, optional = true, note = "Again With the Zapped Giants: 10 residue" },
		{ t = "collect", map = 1444, x = 44.34, y = 46.61, era = true, count = 10, item = 18956, itemName = "Miniaturization Residue", mobLevel = 49, optional = true, spots = "44.3,46.6;42.5,46.9;44.1,49.6;45.2,52.9;43.1,53" },
		{ t = "turnin", quest = 7725, title = "Again With the Zapped Giants", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, optional = true, note = "25 to every town" },
		{ t = "accept", quest = 7726, title = "Refuel for the Zapping", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, qlvl = 55, optional = true, note = "Refuel for the Zapping: 6 cores" },
		{ t = "collect", map = 1444, x = 44.97, y = 46.29, era = true, count = 6, item = 18958, itemName = "Water Elemental Core", mobLevel = 49, optional = true, spots = "45,46.3;45.4,52;46.5,56.2;46.7,61.2;45.7,65.3" },
		{ t = "turnin", quest = 7726, title = "Refuel for the Zapping", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, optional = true, note = "25 to every town" },
		{ t = "rep", factionName = "Ratchet", faction = 470, standing = 5, note = "Ratchet" },
		{ t = "rep", factionName = "Booty Bay", faction = 21, standing = 5, note = "Booty Bay" },
		{ t = "rep", factionName = "Gadgetzan", faction = 369, standing = 5, note = "Gadgetzan" },
		{ t = "rep", factionName = "Everlook", faction = 577, standing = 5, note = "Everlook" },
		{ t = "rep", factionName = "Powderfuse", faction = 2827, standing = 5, optional = true, note = "Powderfuse" },
	} },
	{ title = "Every town to Honored", note = "Friendly to Honored is 6,000: 240 of Zorbin's turn-ins, or 40 Free Knot runs, or a mix. Nothing can be saved up: residue and cores drop only while their quest is in your log, and you can carry one Gordok Shackle Key at a time, so hand each in before the next run. Honored opens each quartermaster's blue items.", goals = {
		{ t = "accept", quest = 7725, title = "Again With the Zapped Giants", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, qlvl = 55, optional = true },
