		{ t = "collect", map = 1444, x = 44.97, y = 46.29, era = true, count = 6, item = 18958, itemName = "Water Elemental Core", mobLevel = 49, optional = true, spots = "45,46.3;45.4,52;46.5,56.2;46.7,61.2;45.7,65.3" },
		{ t = "turnin", quest = 7726, title = "Refuel for the Zapping", npc = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, era = true, optional = true },
		{ t = "rep", factionName = "Ratchet", faction = 470, standing = 7 },
		{ t = "rep", factionName = "Booty Bay", faction = 21, standing = 7 },
		{ t = "rep", factionName = "Gadgetzan", faction = 369, standing = 7 },
		{ t = "rep", factionName = "Everlook", faction = 577, standing = 7 },
		{ t = "rep", factionName = "Powderfuse", faction = 2827, standing = 7, optional = true },
	} },
	{ title = "Ratchet: Winklespark", note = "Winklespark, Ratchet's quartermaster, by the docks. Friendly, level 20 gear: Quilted Cloak 41s (Stamina, Agility), Rumpled Kilt 54s (Stamina, spell power), Ratchet Wristwraps 34s (Intellect, Agility). Honored: Defective Samophlange, an off-hand, 66s (Intellect, Spirit); Barrens Basher, a one-handed mace, 1g 65s (Stamina, Strength). Revered: the Barrens Headband, a cosmetic hat, 2g.", goals = {
