	} },
	{ title = "Booty Bay: Gezzy Gunkgear", note = "Gezzy Gunkgear, Booty Bay's quartermaster. Friendly, level 30 gear: Deckswabber's Mitts 1g 10s (Strength, Agility), Sea Giant's Toe Ring 1g 48s (healing and spell damage), Soggy Boots 1g 3s (Intellect, Spirit). Honored: Booty Bay Bruiser's Buckshot, a gun, 3g 11s (attack power, Stamina); Souvenir Sea Shell, a necklace, 1g 66s (health regeneration, Stamina). Revered: Tough Guy's Eyepatch, 5g.", goals = {
		{ t = "buy", npc = "Gezzy Gunkgear", map = 1434, x = 28.34, y = 74.83, era = true, item = 274745, itemName = "Deckswabber's Mitts", optional = true, note = "Deckswabber's Mitts, Friendly" },
