		{ t = "buy", npc = "Zippie Fizzbolt", map = 1452, x = 61.47, y = 38.6, era = true, item = 274761, itemName = "Parachute-Priest Pager", optional = true, note = "Parachute-Priest Pager, Honored" },
		{ t = "buy", npc = "Zippie Fizzbolt", map = 1452, x = 61.47, y = 38.6, era = true, item = 274024, itemName = "Fizzbolt's Fashionable Fedora", optional = true, note = "Fizzbolt's Fashionable Fedora, Revered" },
	} },
	{ title = "Powderfuse: Friz Frazzlespark", note = "Friz Frazzlespark sells Powderfuse's rewards in Powderfuse Port, on the east coast of the Riverglades, alongside general goods. Friendly, level 40 gear: Crawler's Clackers 2g 74s (Stamina, attack power), Misplaced Pantaloons 2g 94s (Intellect, Spirit), Disengagement Ring 2g 36s (Agility, Spirit). Honored: Primitive Fishing Pole, a two-handed weapon, 9g 46s (Stamina, Strength, Agility); Thrash's Trash, a shield, 3g 80s (Stamina, spell damage, healing). Revered: Haughty Fellow's Monocle, 10g.", goals = {
