Waypost.RegisterSteps("reputation/thorium-brotherhood", function() return {
	{ title = "Thorium Point", note = "Thorium Point is the scaffolded camp on the north-west rim of the Cauldron, with a flight point. Everyone starts Neutral with the Brotherhood. These seven quests (level 48 to 50) pay 100 reputation each: 700 in all, 800 with the pillow below. Forever pays them in full at any level. Master Smith Burninate's What the Flux? also opens his Fiery Flux turn-ins, so it is needed at any level. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%.", goals = {
		{ t = "accept", quest = 7722, title = "What the Flux?", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true, qlvl = 50 },
		{ t = "accept", quest = 7723, title = "Curse These Fat Fingers", npc = "Hansel Heavyhands", map = 1427, x = 38.58, y = 27.81, era = true, qlvl = 49 },
		{ t = "accept", quest = 7724, title = "Fiery Menace!", npc = "Hansel Heavyhands", map = 1427, x = 38.58, y = 27.81, era = true, qlvl = 49 },
		{ t = "accept", quest = 7727, title = "Incendosaurs? Whateverosaur is More Like It", npc = "Hansel Heavyhands", map = 1427, x = 38.58, y = 27.81, era = true, qlvl = 49 },
		{ t = "accept", quest = 7728, title = "STOLEN: Smithing Tuyere and Lookout's Spyglass", npc = "Wanted/Missing/Lost & Found", map = 1427, x = 37.65, y = 26.47, era = true, qlvl = 48, note = "The Wanted/Missing/Lost & Found board" },
		{ t = "accept", quest = 7729, title = "JOB OPPORTUNITY: Culling the Competition", npc = "Wanted/Missing/Lost & Found", map = 1427, x = 37.65, y = 26.47, era = true, qlvl = 48 },
		{ t = "accept", quest = 7701, title = "WANTED: Overseer Maltorius", npc = "Wanted/Missing/Lost & Found", map = 1427, x = 37.65, y = 26.47, era = true, qlvl = 50, optional = true, note = "Overseer Maltorius is elite" },
	} },
	{ title = "Golems and Dark Iron dwarves", note = "Heavy War Golems and the Dark Iron Taskmasters and Slavers work all over the floor of the Cauldron below Thorium Point. The Smithing Tuyere drops from Dark Iron Steamsmiths at the furnaces in the middle, the Lookout's Spyglass from Dark Iron Lookouts on the southern ridges: about one in ten of each.", goals = {
		{ t = "kill", quest = 7723, title = "Curse These Fat Fingers", map = 1427, x = 35.24, y = 40.91, era = true, count = 20, target = "Heavy War Golem", oi = 1, mobLevel = 49, spots = "33.9,43.4;35.4,47.8;43.1,42;48.3,38.7;36.4,61.1" },
		{ t = "kill", quest = 7729, title = "JOB OPPORTUNITY: Culling the Competition", map = 1427, x = 35.53, y = 42.91, era = true, count = 15, target = "Dark Iron Taskmaster", oi = 1, mobLevel = 48, spots = "34.8,45.4;39.8,44.5;40.1,52.3;44.9,39.7;43.4,33.4" },
		{ t = "kill", quest = 7729, title = "JOB OPPORTUNITY: Culling the Competition", map = 1427, x = 36.22, y = 41.88, era = true, count = 15, target = "Dark Iron Slaver", oi = 2, mobLevel = 46, spots = "39.4,41.2;42.4,31.4;45.3,26.1;47.7,46.9;40.9,52.9" },
		{ t = "collect", quest = 7728, title = "STOLEN: Smithing Tuyere and Lookout's Spyglass", map = 1427, x = 37.69, y = 49.65, era = true, count = 1, item = 18959, itemName = "Smithing Tuyere", oi = 1, mobLevel = 47, note = "Smithing Tuyere, Dark Iron Steamsmiths", spots = "39.1,49.7;43,51.7" },
		{ t = "collect", quest = 7728, title = "STOLEN: Smithing Tuyere and Lookout's Spyglass", map = 1427, x = 33.71, y = 51.92, era = true, count = 1, item = 18960, itemName = "Lookout's Spyglass", oi = 2, mobLevel = 48, note = "Lookout's Spyglass, Dark Iron Lookouts", spots = "33,54;36.1,61.5;42.7,62.8;52.1,58" },
	} },
	{ title = "Greater Lava Spiders", note = "The spiders roam the lava pools and plateaus of the south-west.", goals = {
		{ t = "kill", quest = 7724, title = "Fiery Menace!", map = 1427, x = 29.56, y = 56.52, era = true, count = 20, target = "Greater Lava Spider", oi = 1, mobLevel = 49, spots = "28.9,55.9;30.2,61.9;30.9,69.4;27,68;24,76.1" },
	} },
	{ title = "The Slag Pit", note = "The Slag Pit is the cave in the north of the Cauldron. The Secret Plans: Fiery Flux lie on a bench on its upper ledge, beside Overseer Maltorius: a level 50 elite with guards, easy at 60, worth a group below 55. Incendosaurs swim in the lava pools inside and around the north rim; every one drops two to four Incendosaur Scales. Keep every scale: Burninate's turn-ins take two each. If you find Chambermaid Pillaclencher's ornate pillow in the dwarves' sleeping quarters, take it to Evonice Sootsmoker at Thorium Point for 100 more.", goals = {
		{ t = "collect", quest = 7722, title = "What the Flux?", map = 1427, x = 40.45, y = 35.74, era = true, count = 1, item = 18922, itemName = "Secret Plans: Fiery Flux", oi = 1 },
		{ t = "kill", quest = 7727, title = "Incendosaurs? Whateverosaur is More Like It", map = 1427, x = 43.38, y = 28.26, era = true, count = 20, target = "Incendosaur", oi = 1, mobLevel = 49, spots = "45.4,23.2;49.5,25.3;50.8,31.9;50.8,38.2" },
		{ t = "collect", quest = 7701, title = "WANTED: Overseer Maltorius", map = 1427, x = 40.77, y = 35.89, era = true, count = 1, item = 18946, itemName = "Head of Overseer Maltorius", oi = 1, optional = true, group = true, note = "Head of Overseer Maltorius, elite: group up below 55" },
		{ t = "accept", quest = 7704, title = "Look at the Size of It!", item = 18950, itemName = "Chambermaid Pillaclencher's Pillow", qlvl = 50, optional = true, note = "Chambermaid Pillaclencher's Pillow, if you find it" },
	} },
	{ title = "Back to Thorium Point", goals = {
		{ t = "turnin", quest = 7722, title = "What the Flux?", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true },
		{ t = "turnin", quest = 7723, title = "Curse These Fat Fingers", npc = "Hansel Heavyhands", map = 1427, x = 38.58, y = 27.81, era = true },
		{ t = "turnin", quest = 7724, title = "Fiery Menace!", npc = "Hansel Heavyhands", map = 1427, x = 38.58, y = 27.81, era = true },
		{ t = "turnin", quest = 7727, title = "Incendosaurs? Whateverosaur is More Like It", npc = "Hansel Heavyhands", map = 1427, x = 38.58, y = 27.81, era = true },
		{ t = "turnin", quest = 7728, title = "STOLEN: Smithing Tuyere and Lookout's Spyglass", npc = "Taskmaster Scrange", map = 1427, x = 38.97, y = 27.51, era = true },
		{ t = "turnin", quest = 7729, title = "JOB OPPORTUNITY: Culling the Competition", npc = "Taskmaster Scrange", map = 1427, x = 38.97, y = 27.51, era = true },
		{ t = "turnin", quest = 7701, title = "WANTED: Overseer Maltorius", npc = "Lookout Captain Lolo Longstriker", map = 1427, x = 37.74, y = 26.56, era = true, optional = true },
		{ t = "turnin", quest = 7704, title = "Look at the Size of It!", npc = "Evonice Sootsmoker", map = 1427, x = 38.35, y = 27.74, era = true, optional = true },
	} },
	{ title = "Imperial Plate, for Blacksmiths", note = "Blacksmiths with 265 skill can buy their way up with Thorium Bars: Derotain Mudsipper in Gadgetzan trades the Imperial Plate plans for bars, and each pays Brotherhood reputation. A Blue Light Bargain opens them (100). Belt 20 bars (100), Bracer 20 (100), Shoulders 20 (100), Boots 40 (150), Helm 50 (200), Chest 60 (200), Leggings 60 (200): 1,150 reputation for 270 Thorium Bars. They count at any standing, so do them before Burninate's turn-ins.", when = {{ k = "skill", n = 265, name = "Blacksmithing", skillLine = 164 }, { k = "level", op = ">=", n = 50 }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 7652, title = "A Blue Light Bargain", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7652, title = "A Blue Light Bargain", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, optional = true },
		{ t = "accept", quest = 7653, title = "Imperial Plate Belt", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7653, title = "Imperial Plate Belt", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, optional = true, note = "Belt, 20 Thorium Bars" },
		{ t = "accept", quest = 7655, title = "Imperial Plate Bracer", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7655, title = "Imperial Plate Bracer", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, optional = true, note = "Bracer, 20 Thorium Bars" },
		{ t = "accept", quest = 7659, title = "Imperial Plate Shoulders", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7659, title = "Imperial Plate Shoulders", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, optional = true, note = "Shoulders, 20 Thorium Bars" },
		{ t = "accept", quest = 7654, title = "Imperial Plate Boots", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7654, title = "Imperial Plate Boots", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, optional = true, note = "Boots, 40 Thorium Bars" },
		{ t = "accept", quest = 7657, title = "Imperial Plate Helm", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
		{ t = "turnin", quest = 7657, title = "Imperial Plate Helm", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, optional = true, note = "Helm, 50 Thorium Bars" },
		{ t = "accept", quest = 7656, title = "Imperial Plate Chest", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
