		{ t = "accept", quest = 7658, title = "Imperial Plate Leggings", npc = "Derotain Mudsipper", map = 1446, x = 51.38, y = 28.67, era = true, skillName = "Blacksmithing", skillRank = 265, qlvl = 60, optional = true },
