	} },
	{ title = "Heavy Leather, if you skin (Alliance)", note = "Only if you take the Heavy Leather turn-in below and skin it yourself: the yetis and mountain lions here (level 28 to 40) yield it. Ten per turn-in.", only = { factions = {"Alliance"} }, goals = {
		{ t = "collect", map = 1416, x = 38.2, y = 91.9, era = true, count = 10, item = 4234, itemName = "Heavy Leather", optional = true },
	} },
	{ title = "Heavy Leather, if you skin (Horde)", note = "Only if you take the Heavy Leather turn-in below and skin it yourself: the wyverns, basilisks and scorpids here (level 28 to 40) yield it. Ten per turn-in.", only = { factions = {"Horde"} }, goals = {
		{ t = "collect", map = 1441, x = 78.5, y = 59, era = true, count = 10, item = 4234, itemName = "Heavy Leather", optional = true },
	} },
	{ title = "Fiery Flux to Friendly", note = "Neutral to Friendly is 3,000 reputation. Burninate takes Restoring Fiery Flux Supplies only while you are Neutral: 25 reputation for 2 Incendosaur Scales, 1 Coal and either 4 Iron Bars, 4 Kingsblood or 10 Heavy Leather. These are level 60 quests, so they always pay in full. After the 700 from the Thorium Point quests that is 92 turn-ins: 184 scales (about 60 Incendosaurs), 92 Coal (Burninate sells it at 5 silver: 4g 60s) and 368 Iron Bars, 368 Kingsblood or 920 Heavy Leather. If those quests paid you only 140 at 60, it is 115 turn-ins: 230 scales, 115 Coal (5g 75s) and 460 bars or Kingsblood or 1,150 Heavy Leather. Miners smelt the bars from Iron Ore, herbalists pick Kingsblood, skinners get Heavy Leather from beasts of level 28 to 40; all three sell on the Auction House. Pick whichever is cheapest for you, or mix them. Blacksmiths who did the Imperial Plate quests need 46 fewer turn-ins.", goals = {
		{ t = "collect", map = 1427, x = 48.43, y = 28.01, era = true, count = 20, item = 18944, itemName = "Incendosaur Scale", mobLevel = 49, optional = true, note = "Incendosaur Scale, 2 per turn-in", spots = "49.5,25.3;50.8,31.9;45.4,23.2;50.8,38.2" },
		{ t = "buy", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true, count = 10, item = 3857, itemName = "Coal", optional = true, note = "Coal, 1 per turn-in" },
		{ t = "turnin", quest = 8241, title = "Restoring Fiery Flux Supplies via Iron", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true, qlvl = 60, optional = true, note = "via Iron: 4 Iron Bars" },
		{ t = "collect", map = 1427, x = 39.91, y = 27.83, era = true, count = 4, item = 3356, itemName = "Kingsblood", mobLevel = 49, optional = true, note = "Kingsblood, 4 per turn-in", spots = "40.2,23.6;49.9,26.3;47.2,46.4;51.7,59.3;44.9,63.8" },
		{ t = "turnin", quest = 7736, title = "Restoring Fiery Flux Supplies via Kingsblood", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true, qlvl = 60, optional = true, note = "via Kingsblood: 4 Kingsblood" },
		{ t = "turnin", quest = 8242, title = "Restoring Fiery Flux Supplies via Heavy Leather", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true, qlvl = 60, optional = true, note = "via Heavy Leather: 10 Heavy Leather" },
		{ t = "rep", factionName = "Thorium Brotherhood", faction = 59, standing = 5 },
	} },
	{ title = "Gaining Acceptance to Honored", note = "Friendly to Honored is 6,000 reputation. While you are Friendly Burninate takes Gaining Acceptance instead: 25 reputation for 4 Dark Iron Residue, 240 turn-ins and 960 residue in all. About a third of the Dark Iron dwarves in Blackrock Depths drop residue, sometimes several at once; it also sells on the Auction House. Dark Iron Ore or Molten Core materials at Lokhtos (next steps) count here too. Lokhtos's shop opens at Friendly: Flarecore Gloves 8g, Corehound Boots 15g, Molten Helm 16g, Dark Iron Bracers 7g, Enchant Weapon - Strength 3g, Transmute Elemental Fire 12g.", goals = {
		{ t = "collect", map = 1427, x = 25.2, y = 75.2, era = true, count = 40, item = 18945, itemName = "Dark Iron Residue", mobLevel = 50, optional = true, group = true, note = "Dark Iron Residue, 4 per turn-in", spots = "25.6,77.6;30.2,83.8;27.1,86.9;31.1,88.9" },
		{ t = "turnin", quest = 7737, title = "Gaining Acceptance", npc = "Master Smith Burninate", map = 1427, x = 38.8, y = 28.51, era = true, qlvl = 60, optional = true },
		{ t = "rep", factionName = "Thorium Brotherhood", faction = 59, standing = 6 },
	} },
	{ title = "The Shadowforge Key", note = "Optional, and it saves every later trip to Lokhtos the Ring of Law fight. Franclorn Forgewright is a ghost in the middle of Blackrock Mountain: only the dead see him, so die in the mountain and walk to his tomb as a spirit. He sends you after Fineous Darkvire in Blackrock Depths, who always drops Ironfel; place it on Franclorn's monument in the Shrine of Thaurissan and the Shadowforge Key falls out. Blackrock Depths is a five-player dungeon: group up.", goals = {
		{ t = "accept", quest = 3801, title = "Dark Iron Legacy", npc = "Franclorn Forgewright", map = 1428, x = 28.96, y = 28.93, era = true, qlvl = 52, optional = true, note = "Franclorn Forgewright, as a ghost" },
		{ t = "turnin", quest = 3801, title = "Dark Iron Legacy", npc = "Franclorn Forgewright", map = 1428, x = 28.96, y = 28.93, era = true, optional = true },
		{ t = "accept", quest = 3802, title = "Dark Iron Legacy", npc = "Franclorn Forgewright", map = 1428, x = 28.96, y = 28.93, era = true, qlvl = 52, optional = true, group = true },
		{ t = "collect", quest = 3802, title = "Dark Iron Legacy", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 10999, itemName = "Ironfel", oi = 1, optional = true, group = true, note = "Ironfel, Fineous Darkvire inside Blackrock Depths" },
		{ t = "turnin", quest = 3802, title = "Dark Iron Legacy", npc = "Monument of Franclorn Forgewright", map = 1427, x = 32.1, y = 94.7, era = true, optional = true, group = true, note = "Monument of Franclorn Forgewright, Shrine of Thaurissan in Blackrock Depths" },
	} },
	{ title = "Lokhtos Darkbargainer to Revered", note = "Honored to Revered is 12,000 reputation, all of it from Lokhtos Darkbargainer in the Grim Guzzler, the tavern deep in Blackrock Depths. The way there: with the Shadowforge Key, open the East Garrison door near the entrance; without it, win the Ring of Law and climb to the East Garrison. Pull the Shadowforge Lock there to lower the bridge to the Manufactory, the only way to the Guzzler. His Favor Amongst the Brotherhood turn-ins never stop counting: 1 Fiery Core, 1 Lava Core or 1 Blood of the Mountain for 200, 2 Core Leather for 150, 10 Dark Iron Ore for 50. To Revered that is 60 cores, 160 Core Leather or 2,400 Dark Iron Ore. The cores and the leather come only from the Molten Core, which is not among the first raids Blizzard has announced for Forever; until it opens, Dark Iron Ore is the way. Miners with 230 skill find Dark Iron Deposits around the Cauldron in Searing Gorge, across the Burning Steppes and inside Blackrock Depths, and a deposit now and then gives a Blood of the Mountain; the ore also sells on the Auction House. Honored opens Flarecore Mantle 18g, Flarecore Robe 6g, Lava Belt 6g, Black Dragonscale Boots 16g, Fiery Chain Girdle 9g, Dark Iron Helm 6g, Dark Iron Reaver 22g, Dark Iron Destroyer 22g and Enchant Weapon - Mighty Spirit 8g.", goals = {
		{ t = "goto", map = 1427, x = 32.1, y = 94.7, era = true, text = "Blackrock Mountain" },
		{ t = "collect", map = 1427, x = 32.1, y = 94.7, era = true, count = 5, item = 17010, itemName = "Fiery Core", optional = true, group = true, note = "Fiery Core: Firewalkers, Flameguards and Firelords in the Molten Core" },
		{ t = "collect", map = 1427, x = 32.1, y = 94.7, era = true, count = 5, item = 17011, itemName = "Lava Core", optional = true, group = true, note = "Lava Core: Lava Elementals, Lava Reavers and Molten Destroyers" },
		{ t = "collect", map = 1427, x = 32.1, y = 94.7, era = true, count = 2, item = 17012, itemName = "Core Leather", optional = true, note = "Core Leather: skin Ancient Core Hounds and Magmadar" },
		{ t = "collect", map = 1427, x = 36.7, y = 78.04, era = true, count = 1, item = 11382, itemName = "Blood of the Mountain", optional = true, note = "Blood of the Mountain: Molten Destroyers, sometimes a Dark Iron Deposit", spots = "36.7,78;39.5,56.4;42.7,36.4;31.3,38.8;22.5,24.4" },
		{ t = "collect", map = 1427, x = 36.7, y = 78.04, era = true, count = 10, item = 11370, itemName = "Dark Iron Ore", optional = true, note = "Dark Iron Ore: Dark Iron Deposits, Mining 230", spots = "36.7,78;39.5,56.4;42.7,36.4;31.3,38.8;22.5,24.4" },
		{ t = "turnin", quest = 6643, title = "Favor Amongst the Brotherhood, Fiery Core", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "Fiery Core: 200" },
		{ t = "turnin", quest = 6644, title = "Favor Amongst the Brotherhood, Lava Core", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "Lava Core: 200" },
		{ t = "turnin", quest = 6646, title = "Favor Amongst the Brotherhood, Blood of the Mountain", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "Blood of the Mountain: 200" },
		{ t = "turnin", quest = 6645, title = "Favor Amongst the Brotherhood, Core Leather", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "2 Core Leather: 150" },
		{ t = "turnin", quest = 6642, title = "Favor Amongst the Brotherhood, Dark Iron Ore", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "10 Dark Iron Ore: 50" },
		{ t = "rep", factionName = "Thorium Brotherhood", faction = 59, standing = 7 },
	} },
	{ title = "A Binding Contract", note = "Carry a Sulfuron Ingot (Golemagg the Incinerator, the Molten Core) to Lokhtos and he offers you a contract: ask about the offer and take it. Handing in the contract with the ingot pays 200 reputation and Plans: Sulfuron Hammer, the hammer Blacksmiths later join with the Eye of Sulfuras into Sulfuras, Hand of Ragnaros.", when = {{ k = "has", n = 1, item = 17203 }, { k = "level", op = ">=", n = 60 }}, goals = {
		{ t = "level", level = 60 },
		{ t = "accept", quest = 7604, title = "A Binding Contract", item = 18628, itemName = "Thorium Brotherhood Contract", qlvl = 60, optional = true, group = true, note = "Thorium Brotherhood Contract, from Lokhtos" },
		{ t = "collect", quest = 7604, title = "A Binding Contract", map = 1427, x = 32.1, y = 94.7, era = true, count = 1, item = 17203, itemName = "Sulfuron Ingot", oi = 1, optional = true, group = true, note = "Sulfuron Ingot, already in your bags" },
		{ t = "turnin", quest = 7604, title = "A Binding Contract", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, optional = true, group = true },
	} },
	{ title = "Lokhtos Darkbargainer to Exalted", note = "Revered to Exalted is 21,000 more: 105 cores or Bloods, 280 Core Leather or 4,200 Dark Iron Ore. The Molten Core materials come from the raid, so a guild or the auction house does most of the work. Revered opens Flarecore Leggings 9g, Chromatic Gauntlets 9g, Corehound Belt 9g, Molten Belt 9g, Dark Iron Leggings 18g, Dark Iron Gauntlets 8g, Fiery Chain Shoulders 20g, Black Amnesty 7g, Blackfury 7g and Enchant Weapon - Mighty Intellect 10g. Exalted opens the epic weapon plans Ebon Hand, Blackguard and Nightfall (12g each) and Dark Iron Boots 8g.", goals = {
		{ t = "turnin", quest = 6643, title = "Favor Amongst the Brotherhood, Fiery Core", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "Fiery Core: 200" },
		{ t = "turnin", quest = 6644, title = "Favor Amongst the Brotherhood, Lava Core", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "Lava Core: 200" },
		{ t = "turnin", quest = 6646, title = "Favor Amongst the Brotherhood, Blood of the Mountain", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "Blood of the Mountain: 200" },
		{ t = "turnin", quest = 6645, title = "Favor Amongst the Brotherhood, Core Leather", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "2 Core Leather: 150" },
		{ t = "turnin", quest = 6642, title = "Favor Amongst the Brotherhood, Dark Iron Ore", npc = "Lokhtos Darkbargainer", map = 1427, x = 32.1, y = 94.7, era = true, qlvl = 60, optional = true, group = true, note = "10 Dark Iron Ore: 50" },
		{ t = "rep", factionName = "Thorium Brotherhood", faction = 59, standing = 8 },
	} },
} end)

Waypost.RegisterSteps("reputation/timbermaw-hold", function() return {
	{ title = "Grazle", note = "Timbermaw Hold starts at Hostile (2,500 of 3,000), so its furbolgs attack you in their tunnels; Grazle, Nafien and Salfa talk to everyone. Grazle waits by the road in the south of Felwood, near the Emerald Sanctuary. Every Deadwood and Winterfall furbolg you kill gives 5 reputation up to the last point of Honored, so the quests below pay twice. The Legacy perk Diplomat adds up to 10% to every gain.", goals = {
		{ t = "accept", quest = 8460, title = "Timbermaw Ally", npc = "Grazle", map = 1448, x = 50.93, y = 85.01, era = true, qlvl = 48 },
	} },
	{ title = "Deadwood Village", note = "The Deadwood furbolgs (level 48-50) hold the village at the south end of Felwood. Keep every Deadwood Headdress Feather: they are worth 10 reputation each later and never stop counting. Overlord Ror (15 reputation) and the rare Ragepaw (25) live here and count until Exalted. Forever pays quests in full at any level; in Classic grey mobs gave about a fifth, about 1 a kill for these furbolgs at 60. Do it while leveling if you can.", goals = {
		{ t = "kill", quest = 8460, title = "Timbermaw Ally", map = 1448, x = 49.73, y = 88.18, era = true, count = 6, target = "Deadwood Warrior", oi = 1, mobLevel = 49, spots = "49.2,88.6;48.7,91;48.3,93.5;46.3,89.2;46.6,92" },
		{ t = "kill", quest = 8460, title = "Timbermaw Ally", map = 1448, x = 48.3, y = 89.46, era = true, count = 6, target = "Deadwood Pathfinder", oi = 2, mobLevel = 50, spots = "48.3,89.5;49.2,91.7;46.3,89.4;47.4,93.4" },
		{ t = "kill", quest = 8460, title = "Timbermaw Ally", map = 1448, x = 48.42, y = 89.84, era = true, count = 6, target = "Deadwood Gardener", oi = 3, mobLevel = 49, spots = "48.3,89.2;48.5,92;46.4,89.6" },
		{ t = "kill", map = 1448, x = 48.23, y = 94.28, era = true, target = "Overlord Ror", optional = true },
		{ t = "kill", map = 1448, x = 47.74, y = 93.06, era = true, target = "Ragepaw", optional = true, note = "Ragepaw, rare" },
	} },
	{ title = "Back to Grazle", goals = {
		{ t = "turnin", quest = 8460, title = "Timbermaw Ally", npc = "Grazle", map = 1448, x = 50.93, y = 85.01, era = true },
		{ t = "accept", quest = 8462, title = "Speak to Nafien", npc = "Grazle", map = 1448, x = 50.93, y = 85.01, era = true, qlvl = 55 },
	} },
	{ title = "Nafien", note = "Nafien stands at the Felwood mouth of the Timbermaw tunnel, at the top of the road in the north of Felwood.", goals = {
		{ t = "turnin", quest = 8462, title = "Speak to Nafien", npc = "Nafien", map = 1448, x = 64.77, y = 8.13, era = true },
		{ t = "accept", quest = 8461, title = "Deadwood of the North", npc = "Nafien", map = 1448, x = 64.77, y = 8.13, era = true, qlvl = 55 },
	} },
	{ title = "Felpaw Village", note = "The northern Deadwood (level 53-55) camp just south of the tunnel. They drop feathers about half the time: the best feather spot. Chieftain Bloodmaw gives 15 until Exalted.", goals = {
		{ t = "kill", quest = 8461, title = "Deadwood of the North", map = 1448, x = 63.68, y = 6.05, era = true, count = 6, target = "Deadwood Den Watcher", oi = 1, mobLevel = 54, spots = "61.1,6.8;62.4,9.6;63.7,6.1;62.5,13.2" },
		{ t = "kill", quest = 8461, title = "Deadwood of the North", map = 1448, x = 62.96, y = 7.33, era = true, count = 6, target = "Deadwood Avenger", oi = 2, mobLevel = 55, spots = "63.1,8.2;61.1,8.4;63.1,10.8;60.1,6.1;63.3,13" },
		{ t = "kill", quest = 8461, title = "Deadwood of the North", map = 1448, x = 62.71, y = 7.14, era = true, count = 6, target = "Deadwood Shaman", oi = 3, mobLevel = 54, spots = "63,6.7;60.3,7.4;62.2,10.8;63,12.5;63.6,9.1" },
		{ t = "kill", map = 1448, x = 62.75, y = 7.74, era = true, target = "Chieftain Bloodmaw", optional = true },
	} },
	{ title = "Back to Nafien", note = "These quests and their kills bring you just past Unfriendly (500 from the start). If Timbermaw Ally paid you less (at level 60 in Classic: 30), kill about 40 more northern Deadwood. From Unfriendly the Timbermaw in the tunnel leave you alone.", goals = {
		{ t = "turnin", quest = 8461, title = "Deadwood of the North", npc = "Nafien", map = 1448, x = 64.77, y = 8.13, era = true },
		{ t = "accept", quest = 8465, title = "Speak to Salfa", npc = "Nafien", map = 1448, x = 64.77, y = 8.13, era = true, qlvl = 55 },
		{ t = "rep", factionName = "Timbermaw Hold", faction = 576, standing = 3 },
	} },
	{ title = "Salfa", note = "Walk through the tunnel to its Winterspring mouth; Salfa stands just outside. Do not attack any Timbermaw: each one costs 25 reputation.", goals = {
		{ t = "turnin", quest = 8465, title = "Speak to Salfa", npc = "Salfa", map = 1452, x = 27.73, y = 34.5, era = true },
		{ t = "accept", quest = 8464, title = "Winterfall Activity", npc = "Salfa", map = 1452, x = 27.73, y = 34.5, era = true, qlvl = 58 },
	} },
	{ title = "Winterfall Village", note = "Winterfall Village lies in the east of Winterspring, just past Everlook. Keep every Winterfall Spirit Beads you loot (10 reputation each later). The Shamans, Den Watchers and Ursas share their spawn points, so kill every furbolg in the village to make the ones you need appear; more Ursas walk the ridge just south-west of the village. Grizzle Snowpaw (rare) and High Chief Winterfall, in the cave at the back, give 25 until Exalted. Alliance: the Wintersaber Trainers' Winterfall Intrusion asks for the same Shamans and Ursas.", goals = {
		{ t = "kill", quest = 8464, title = "Winterfall Activity", map = 1452, x = 67.37, y = 35.22, era = true, count = 8, target = "Winterfall Shaman", oi = 1, mobLevel = 57, spots = "67.5,35.4;68,37.5;69.5,38.3;67.5,39.8" },
		{ t = "kill", quest = 8464, title = "Winterfall Activity", map = 1452, x = 67.51, y = 35.91, era = true, count = 8, target = "Winterfall Den Watcher", oi = 2, mobLevel = 56, spots = "67.6,35.9;68.3,34.7;66.5,34.9;41.6,42.6;30.5,36.3" },
		{ t = "kill", quest = 8464, title = "Winterfall Activity", map = 1452, x = 68.08, y = 36.86, era = true, count = 8, target = "Winterfall Ursa", oi = 3, mobLevel = 58, spots = "68.3,37.6;67.2,39.4;65.8,37.6" },
		{ t = "kill", map = 1452, x = 66.9, y = 35.6, era = true, target = "Grizzle Snowpaw", optional = true, note = "Grizzle Snowpaw, rare" },
		{ t = "kill", map = 1452, x = 69.56, y = 38.31, era = true, target = "High Chief Winterfall", optional = true, group = true, note = "High Chief Winterfall, elite" },
	} },
	{ title = "Back to Salfa", note = "Feathers for Grazle, Feathers for Nafien and Beads for Salfa are open now: 50 reputation for 5 feathers or 5 beads, as often as you like. Do not hand them in yet.", goals = {
		{ t = "turnin", quest = 8464, title = "Winterfall Activity", npc = "Salfa", map = 1452, x = 27.73, y = 34.5, era = true },
	} },
	{ title = "Unfriendly to Neutral", note = "Unfriendly to Neutral is 3,000: about 540 more kills after these quests. Three camps: the northern Deadwood by the Felwood mouth of the tunnel; the Winterfall camps around Frostfire Hot Springs and Timbermaw Post, just south and south-east of Salfa (Pathfinders give 6 a kill, Den Watchers and Totemics 5, the shortest walk to a turn-in); and Winterfall Village in the east. Pick the least crowded. Keep all feathers and beads.", goals = {
		{ t = "level", level = 52 },
		{ t = "collect", count = 5, item = 21377, itemName = "Deadwood Headdress Feather", optional = true, note = "Deadwood Headdress Feathers: keep them" },
		{ t = "collect", count = 5, item = 21383, itemName = "Winterfall Spirit Beads", optional = true, note = "Winterfall Spirit Beads: keep them" },
		{ t = "kill", map = 1452, x = 31.5, y = 36, era = true, target = "Winterfall Pathfinder", mobLevel = 54, optional = true, note = "Winterfall Pathfinders, Frostfire Hot Springs", spots = "31.5,36;33.3,37;34.7,37;39,42.8;40.8,43.1" },
		{ t = "rep", factionName = "Timbermaw Hold", faction = 576, standing = 4 },
	} },
	{ title = "Deadwood Ritual Totem", note = "The northern Deadwood rarely drop a Deadwood Ritual Totem (about 3%). From Neutral, Kernda takes it in the tunnel, on the Felwood side: 150 reputation and two Major Healing and Mana Potions.", when = {{ k = "has", n = 1, item = 20741 }}, goals = {
		{ t = "accept", quest = 8470, title = "Deadwood Ritual Totem", item = 20741, itemName = "Deadwood Ritual Totem", qlvl = 55 },
		{ t = "turnin", quest = 8470, title = "Deadwood Ritual Totem", npc = "Kernda", map = 1448, x = 65.5, y = 3.52, era = true },
	} },
	{ title = "Winterfall Ritual Totem", note = "The Winterfall furbolgs rarely drop a Winterfall Ritual Totem (3-4%). Kernda takes it in the tunnel too: 150 reputation and three Major Healing and Mana Potions.", when = {{ k = "has", n = 1, item = 20742 }}, goals = {
		{ t = "accept", quest = 8471, title = "Winterfall Ritual Totem", item = 20742, itemName = "Winterfall Ritual Totem", qlvl = 56 },
		{ t = "turnin", quest = 8471, title = "Winterfall Ritual Totem", npc = "Kernda", map = 1448, x = 65.5, y = 3.52, era = true },
	} },
	{ title = "Neutral to Friendly", note = "Neutral to Friendly is 3,000: 600 kills. Keep all feathers and beads.", goals = {
		{ t = "collect", count = 5, item = 21377, itemName = "Deadwood Headdress Feather", optional = true },
		{ t = "collect", count = 5, item = 21383, itemName = "Winterfall Spirit Beads", optional = true },
		{ t = "rep", factionName = "Timbermaw Hold", faction = 576, standing = 5 },
	} },
	{ title = "Meilosh", note = "Meilosh stands in the tunnel, near its Felwood mouth. From Friendly he sells: Recipe: Transmute Earth to Water (1 gold 50 silver), Formula: Enchant 2H Weapon - Agility (2 gold 50 silver), Pattern: Warbear Harness (1 gold 60 silver) and Warbear Woolies (2 gold). He also takes 30 Runecloth once for 100 reputation and a choice of shoulders or gauntlets, and Tailors with skill 290 can bring him 2 Mooncloth for 100 more and the Mooncloth Boots pattern.", goals = {
		{ t = "talk", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true },
		{ t = "accept", quest = 6031, title = "Runecloth", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, qlvl = 55, optional = true, note = "Runecloth: 30 Runecloth" },
		{ t = "buy", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, item = 22392, itemName = "Formula: Enchant 2H Weapon - Agility", optional = true, note = "Formula: Enchant 2H Weapon - Agility (Enchanting)" },
		{ t = "buy", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, item = 20253, itemName = "Pattern: Warbear Harness", optional = true, note = "Pattern: Warbear Harness (Leatherworking)" },
		{ t = "buy", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, item = 20254, itemName = "Pattern: Warbear Woolies", optional = true, note = "Pattern: Warbear Woolies (Leatherworking)" },
		{ t = "buy", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, item = 13484, itemName = "Recipe: Transmute Earth to Water", optional = true, note = "Recipe: Transmute Earth to Water (Alchemy)" },
	} },
	{ title = "Runecloth for Meilosh", note = "Runecloth drops from the humanoids of the level 50-60 zones, the Deadwood and Winterfall furbolgs among them.", goals = {
		{ t = "collect", quest = 6031, title = "Runecloth", map = 1448, x = 65.58, y = 2.82, era = true, count = 30, item = 14047, itemName = "Runecloth", oi = 1, mobLevel = 54, spots = "65.6,2.8;60.2,5.8;45.1,14.3;42,19.3;39.1,22.2" },
		{ t = "turnin", quest = 6031, title = "Runecloth", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true },
