	{ title = "Sacred Cloth", note = "Tailors with skill 290: Meilosh takes 2 Mooncloth once for 100 reputation and teaches the Mooncloth Boots.", when = {{ k = "skill", n = 290, name = "Tailoring", skillLine = 197 }}, goals = {
		{ t = "accept", quest = 6032, title = "Sacred Cloth", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, skillName = "Tailoring", skillRank = 280, qlvl = 55, optional = true },
		{ t = "turnin", quest = 6032, title = "Sacred Cloth", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, skillName = "Tailoring", skillRank = 280, optional = true },
	} },
	{ title = "Friendly to Honored", note = "Friendly to Honored is 6,000: 1,200 kills. Keep all feathers and beads. Honored opens at Meilosh: Formula: Enchant Weapon - Agility (3 gold), and for 2 gold 20 silver each Pattern: Heavy Timbermaw Belt and Might of the Timbermaw (Leatherworking) and Wisdom of the Timbermaw (Tailoring).", goals = {
		{ t = "collect", count = 5, item = 21377, itemName = "Deadwood Headdress Feather", optional = true },
		{ t = "collect", count = 5, item = 21383, itemName = "Winterfall Spirit Beads", optional = true },
		{ t = "rep", factionName = "Timbermaw Hold", faction = 576, standing = 6 },
	} },
	{ title = "Honored to Revered", note = "Honored to Revered is 12,000: 2,400 kills, the last ones that count. Kills stop at 11,999 of 12,000 Honored and never tip you into Revered: when they stop, hand in one set of 5 feathers or beads to cross over. Saving every feather and bead pays off now: about 4,800 kills from the start to the end of Honored leave you with about 2,100 feathers and beads, and that is all of Revered to Exalted. Turning them in early would cost you about 2,400 more kills.", goals = {
		{ t = "buy", npc = "Meilosh", map = 1448, x = 65.69, y = 2.81, era = true, item = 19445, itemName = "Formula: Enchant Weapon - Agility", optional = true, note = "Formula: Enchant Weapon - Agility (Enchanting), 3 gold" },
		{ t = "collect", count = 5, item = 21377, itemName = "Deadwood Headdress Feather", optional = true },
		{ t = "collect", count = 5, item = 21383, itemName = "Winterfall Spirit Beads", optional = true },
		{ t = "turnin", quest = 8467, title = "Feathers for Nafien", npc = "Nafien", map = 1448, x = 64.77, y = 8.13, era = true, qlvl = 55, optional = true, note = "Feathers for Nafien: once your kills stop, 5 feathers into Revered" },
		{ t = "turnin", quest = 8469, title = "Beads for Salfa", npc = "Salfa", map = 1452, x = 27.73, y = 34.5, era = true, qlvl = 56, optional = true, note = "Beads for Salfa: or 5 beads" },
		{ t = "rep", factionName = "Timbermaw Hold", faction = 576, standing = 7 },
	} },
	{ title = "Revered to Exalted", note = "Kills stopped at the end of Honored. Revered to Exalted is 21,000: 420 turn-ins, 2,100 feathers and beads. Hand in the feathers to Nafien at the tunnel or Grazle in the south, the beads to Salfa, five at a time. The named furbolgs (Ror, Bloodmaw, Ragepaw, Grizzle Snowpaw, High Chief Winterfall) still count. Revered opens at Meilosh, for 4 gold each: Pattern: Heavy Timbermaw Boots and Timbermaw Brawlers (Leatherworking) and Mantle of the Timbermaw (Tailoring).", goals = {
		{ t = "turnin", quest = 8467, title = "Feathers for Nafien", npc = "Nafien", map = 1448, x = 64.77, y = 8.13, era = true, qlvl = 55, optional = true, note = "Feathers for Nafien: 5 feathers, 50 reputation" },
		{ t = "turnin", quest = 8466, title = "Feathers for Grazle", npc = "Grazle", map = 1448, x = 50.93, y = 85.01, era = true, qlvl = 55, optional = true, note = "Feathers for Grazle: 5 feathers, 50 reputation" },
		{ t = "turnin", quest = 8469, title = "Beads for Salfa", npc = "Salfa", map = 1452, x = 27.73, y = 34.5, era = true, qlvl = 56, optional = true, note = "Beads for Salfa: 5 beads, 50 reputation" },
		{ t = "collect", count = 5, item = 21377, itemName = "Deadwood Headdress Feather", optional = true },
		{ t = "collect", count = 5, item = 21383, itemName = "Winterfall Spirit Beads", optional = true },
		{ t = "rep", factionName = "Timbermaw Hold", faction = 576, standing = 8 },
	} },
	{ title = "The Root of All Evil", note = "At Exalted, Gorn One Eye, in the tunnel by Meilosh, gives The Root of All Evil: plant his Demon Summoning Torch in the mouth of High Chief Winterfall's cave and defeat the demon Xandivious (level 62, elite: bring a group). The reward is Defender of the Timbermaw, a trinket that calls a Timbermaw ally, and 200 reputation.", when = {{ k = "group", q = 8481 }}, goals = {
		{ t = "accept", quest = 8481, title = "The Root of All Evil", npc = "Gorn One Eye", map = 1448, x = 65.18, y = 2.68, era = true, qlvl = 60 },
	} },
	{ title = "Xandivious", note = "Winterfall Village, the cave at the back. Clear the furbolgs around the mouth first, plant the torch, kill Xandivious and loot the Essence from his Demon Bag.", when = {{ k = "onquest", q = {8481} }}, goals = {
		{ t = "collect", quest = 8481, title = "The Root of All Evil", map = 1452, x = 69.8, y = 38.2, era = true, count = 1, item = 21145, itemName = "Essence of Xandivious", oi = 1, group = true },
		{ t = "kill", map = 1452, x = 69.8, y = 38.2, era = true, target = "Xandivious", optional = true, group = true, note = "Xandivious, 25 reputation" },
	} },
	{ title = "Gorn One Eye", when = {{ k = "onquest", q = {8481} }}, goals = {
		{ t = "turnin", quest = 8481, title = "The Root of All Evil", npc = "Gorn One Eye", map = 1448, x = 65.18, y = 2.68, era = true },
	} },
} end)

Waypost.RegisterSteps("reputation/warsong-gulch", function() return {
	{ title = "Sentinel Farsong", note = "Warsong Gulch is a 10 against 10 capture-the-flag battle, from level 10. Queue at any battlemaster in the capitals or from the battleground screen. In Classic every flag your team captures pays everyone 35 reputation (45 on the Warsong Gulch holiday weekend), and a game pays 3 Warsong Gulch Marks of Honor for a win, 1 for a loss. Sentinel Farsong pays 200 reputation for one mark, once per character: the best mark you will ever turn in. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = {"Alliance"} }, when = {{ k = "level", op = ">=", n = 50 }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 7873, title = "Vanquish the Invaders!", npc = "Sentinel Farsong", map = 1440, x = 61.85, y = 83.9, era = true, qlvl = 55 },
		{ t = "collect", quest = 7873, title = "Vanquish the Invaders!", map = 1440, x = 61.9, y = 83.9, era = true, count = 1, item = 20558, itemName = "Warsong Gulch Mark of Honor", oi = 1, note = "one Warsong Gulch Mark of Honor: play a game" },
		{ t = "turnin", quest = 7873, title = "Vanquish the Invaders!", npc = "Sentinel Farsong", map = 1440, x = 61.85, y = 83.9, era = true },
	} },
	{ title = "Alliance Brigadier General", note = "The Alliance Brigadier General pays 100 reputation for 3 Warsong Gulch Marks of Honor the first time, then 50 for every 3 more (Fight for Warsong Gulch). One stands right here at Silverwing Grove beside Sentinel Farsong; others in Stormwind, Ironforge and Darnassus, at Refuge Pointe in the Arathi Highlands and at both gates of Alterac Valley. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Warsong Gulch marks: hand in or spend them before you reach that.", only = { factions = {"Alliance"} }, when = {{ k = "level", op = ">=", n = 50 }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8402, title = "Fight for Warsong Gulch", npc = "Alliance Brigadier General", map = 1440, x = 61.94, y = 83.83, era = true, qlvl = 59 },
		{ t = "collect", quest = 8402, title = "Fight for Warsong Gulch", map = 1440, x = 61.9, y = 83.9, era = true, count = 3, item = 20558, itemName = "Warsong Gulch Mark of Honor", oi = 1, note = "three Warsong Gulch Marks of Honor" },
		{ t = "turnin", quest = 8402, title = "Fight for Warsong Gulch", npc = "Alliance Brigadier General", map = 1440, x = 61.94, y = 83.83, era = true },
	} },
	{ title = "Silverwing Sentinels to Friendly", note = "Neutral to Friendly is 3000 reputation. In Classic a 3-capture win paid 105, and its 3 marks bring 50 more at the Brigadier General: about 155 a win, so some 20 wins. Losses still pay 35 for each flag your team captured. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50, Sentinel Farsong's one-mark quest and the Brigadier General's Fight for Warsong Gulch come in a version for your bracket (from 20 and from 10): 200 once, then 100 and 50 per 3 marks.", only = { factions = {"Alliance"} }, goals = {
		{ t = "talk", npc = "Alliance Brigadier General", map = 1440, x = 61.94, y = 83.83, era = true, optional = true, note = "Alliance Brigadier General: Fight for Warsong Gulch again, 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Silverwing Sentinels", faction = 890, standing = 5 },
	} },
	{ title = "Silverwing Sentinels to Honored", note = "Friendly to Honored is 6000 reputation, about 39 wins at the Classic rate. Friendly opens the first rewards at Illiyana Moonblaze beside Sentinel Farsong: the Rune of Duty and Rune of Perfection trinkets (2g at level 20, 4g at level 40) and food, bandages and draughts that work in the battleground (5s to 20s). She also gives one Sentinel care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages.", only = { factions = {"Alliance"} }, goals = {
		{ t = "talk", npc = "Illiyana Moonblaze", map = 1440, x = 61.49, y = 83.86, era = true, optional = true, note = "Illiyana Moonblaze: Friendly rewards" },
		{ t = "talk", npc = "Alliance Brigadier General", map = 1440, x = 61.94, y = 83.83, era = true, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Silverwing Sentinels", faction = 890, standing = 6 },
	} },
	{ title = "Silverwing Sentinels to Revered", note = "Honored to Revered is 12000 reputation, about 78 wins. Honored opens the Caretaker's Cape (cloak), Sentinel's Medallion (neck), Lorekeeper's Ring and Protector's Band, each sold for levels 18, 28, 38, 48 and 58 (cloak 36s50c to 8g55s, the rest 2g to 7g50s), and the Major Healing and Mana Draughts (10s).", only = { factions = {"Alliance"} }, goals = {
		{ t = "talk", npc = "Illiyana Moonblaze", map = 1440, x = 61.49, y = 83.86, era = true, optional = true, note = "Illiyana Moonblaze: Honored rewards" },
		{ t = "talk", npc = "Alliance Brigadier General", map = 1440, x = 61.94, y = 83.83, era = true, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Silverwing Sentinels", faction = 890, standing = 7 },
	} },
	{ title = "Silverwing Sentinels to Exalted", note = "Revered to Exalted is 21000 reputation, about 136 wins: half of the whole climb. Revered opens the weapons for levels 18 to 58: Sentinel's Blade (dagger), Protector's Sword, Outrunner's Bow and Lorekeeper's Staff (91s to 35g61s). Forever's quartermaster also sells level-25 versions of the four weapons, Resilient helms for level 20 (2g50s) and the Trainee's Sentinel Nightsaber mount (level 25, 10g) with no standing listed.", only = { factions = {"Alliance"} }, goals = {
		{ t = "talk", npc = "Illiyana Moonblaze", map = 1440, x = 61.49, y = 83.86, era = true, optional = true, note = "Illiyana Moonblaze: Revered rewards" },
		{ t = "talk", npc = "Alliance Brigadier General", map = 1440, x = 61.94, y = 83.83, era = true, optional = true, note = "Alliance Brigadier General: 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Silverwing Sentinels", faction = 890, standing = 8 },
	} },
	{ title = "Illiyana Moonblaze", note = "Exalted gives the Legacy Point \"Master of Warsong Gulch\" and opens the epics: Berserker Bracers (plate), Windtalker's Wristguards (mail), Forest Stalker's Bracers (leather) and Dryad's Wrist Bindings (cloth) for levels 40, 50 and 60 (2g47s to 12g11s), and the level 60 Sentinel's legs in plate, lamellar, chain, leather, lizardhide and silk (16g63s to 24g22s). The Silverwing Battle Tabard is 5g.", only = { factions = {"Alliance"} }, goals = {
		{ t = "buy", npc = "Illiyana Moonblaze", map = 1440, x = 61.49, y = 83.86, era = true, item = 19506, itemName = "Silverwing Battle Tabard", note = "Silverwing Battle Tabard, 5g" },
	} },
	{ title = "Captain Shatterskull", note = "Warsong Gulch is a 10 against 10 capture-the-flag battle, from level 10. Queue at any battlemaster in the capitals or from the battleground screen; the Horde gate is here at Mor'shan Base Camp. In Classic every flag your team captures pays everyone 35 reputation (45 on the Warsong Gulch holiday weekend), and a game pays 3 Warsong Gulch Marks of Honor for a win, 1 for a loss. Captain Shatterskull pays 200 reputation for one mark, once per character: the best mark you will ever turn in. Forever's Legacy Diplomat perk adds up to 10% to every number in this guide.", only = { factions = {"Horde"} }, when = {{ k = "level", op = ">=", n = 50 }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 7876, title = "Quell the Silverwing Usurpers", npc = "Captain Shatterskull", map = 1413, x = 46.6, y = 8.41, era = true, qlvl = 55 },
		{ t = "collect", quest = 7876, title = "Quell the Silverwing Usurpers", map = 1413, x = 46.6, y = 8.4, era = true, count = 1, item = 20558, itemName = "Warsong Gulch Mark of Honor", oi = 1, note = "one Warsong Gulch Mark of Honor: play a game" },
		{ t = "turnin", quest = 7876, title = "Quell the Silverwing Usurpers", npc = "Captain Shatterskull", map = 1413, x = 46.6, y = 8.41, era = true },
	} },
	{ title = "Horde Warbringer", note = "The Horde Warbringer pays 100 reputation for 3 Warsong Gulch Marks of Honor the first time, then 50 for every 3 more (Battle of Warsong Gulch). One stands right here at Mor'shan; others in Orgrimmar, Thunder Bluff (and on the plain below it) and the Undercity, at Hammerfall in the Arathi Highlands and at the Alterac Valley gate in the Alterac Mountains. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 Warsong Gulch marks: hand in or spend them before you reach that.", only = { factions = {"Horde"} }, when = {{ k = "level", op = ">=", n = 50 }}, goals = {
		{ t = "level", level = 50 },
		{ t = "accept", quest = 8429, title = "Battle of Warsong Gulch", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, qlvl = 59 },
		{ t = "collect", quest = 8429, title = "Battle of Warsong Gulch", map = 1413, x = 46.6, y = 8.4, era = true, count = 3, item = 20558, itemName = "Warsong Gulch Mark of Honor", oi = 1, note = "three Warsong Gulch Marks of Honor" },
		{ t = "turnin", quest = 8429, title = "Battle of Warsong Gulch", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true },
	} },
	{ title = "Warsong Outriders to Friendly", note = "Neutral to Friendly is 3000 reputation. In Classic a 3-capture win paid 105, and its 3 marks bring 50 more at the Warbringer: about 155 a win, so some 20 wins. Losses still pay 35 for each flag your team captured. Forever has not published its battleground rates, so count the games as a rough guide. Below level 50, Captain Shatterskull's one-mark quest and the Warbringer's Battle of Warsong Gulch come in a version for your bracket (from 20 and from 10): 200 once, then 100 and 50 per 3 marks.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: Battle of Warsong Gulch again, 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Warsong Outriders", faction = 889, standing = 5 },
	} },
	{ title = "Warsong Outriders to Honored", note = "Friendly to Honored is 6000 reputation, about 39 wins at the Classic rate. Friendly opens the first rewards at Kelm Hargunth beside Captain Shatterskull: the Rune of Duty and Rune of Perfection trinkets (2g at level 20, 4g at level 40) and food, bandages and draughts that work in the battleground (5s to 20s). He also gives one Outrider care package at Friendly (pick the one for your level): 10 reputation and a bag of battleground food and bandages.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Kelm Hargunth", map = 1413, x = 46.65, y = 8.38, era = true, optional = true, note = "Kelm Hargunth: Friendly rewards" },
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Warsong Outriders", faction = 889, standing = 6 },
	} },
	{ title = "Warsong Outriders to Revered", note = "Honored to Revered is 12000 reputation, about 78 wins. Honored opens the Battle Healer's Cloak, Scout's Medallion (neck), Advisor's Ring and Legionnaire's Band, each sold for levels 18, 28, 38, 48 and 58 (cloak 36s50c to 9g6s, the rest 2g to 7g50s), and the Major Healing and Mana Draughts (10s).", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Kelm Hargunth", map = 1413, x = 46.65, y = 8.38, era = true, optional = true, note = "Kelm Hargunth: Honored rewards" },
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Warsong Outriders", faction = 889, standing = 7 },
	} },
	{ title = "Warsong Outriders to Exalted", note = "Revered to Exalted is 21000 reputation, about 136 wins: half of the whole climb. Revered opens the weapons for levels 18 to 58: Scout's Blade (dagger), Legionnaire's Sword, Outrider's Bow and Advisor's Gnarled Staff (91s to 35g9s). Forever's quartermaster also sells level-25 versions of the four weapons, Resilient helms for level 20 (2g50s) and the Trainee's Outrider Wolf mount (level 25, 10g) with no standing listed.", only = { factions = {"Horde"} }, goals = {
		{ t = "talk", npc = "Kelm Hargunth", map = 1413, x = 46.65, y = 8.38, era = true, optional = true, note = "Kelm Hargunth: Revered rewards" },
		{ t = "talk", npc = "Horde Warbringer", map = 1413, x = 46.71, y = 8.68, era = true, optional = true, note = "Horde Warbringer: 50 reputation for 3 marks" },
		{ t = "rep", factionName = "Warsong Outriders", faction = 889, standing = 8 },
	} },
	{ title = "Kelm Hargunth", note = "Exalted gives the Legacy Point \"Master of Warsong Gulch\" and opens the epics: Berserker Bracers (plate), Windtalker's Wristguards (mail), Forest Stalker's Bracers (leather) and Dryad's Wrist Bindings (cloth) for levels 40, 50 and 60 (2g47s to 12g11s), and the level 60 Outrider's legs in plate, chain, mail, leather, lizardhide and silk (16g57s to 25g33s). The Warsong Battle Tabard is 5g.", only = { factions = {"Horde"} }, goals = {
		{ t = "buy", npc = "Kelm Hargunth", map = 1413, x = 46.65, y = 8.38, era = true, item = 19505, itemName = "Warsong Battle Tabard", note = "Warsong Battle Tabard, 5g" },
	} },
} end)

Waypost.RegisterSteps("reputation/zandalar-tribe", function() return {
	{ title = "Yojamba Isle", note = "Yojamba Isle is the small island off the north-west coast of Stranglethorn Vale, west of the Zuuldaia Ruins: swim over from the coast. Everyone starts Neutral with the Zandalar Tribe. Vinchaxa takes coins and bijous, Rin'wosho the Trader sells the recipes and trades Honor Tokens, and Jin'rokh, Al'tabim, Maywiki and Falthir hand out the class necklaces and the set pieces. Almost all Zandalar reputation comes from Zul'Gurub, a 20-player raid, and Zul'Gurub is not among the first raids Blizzard has announced for Forever: until it opens there is no Zandalar reputation to earn, and no coins or bijous on the auction house either. Once it is open, the only solo way is buying coins and bijous on the auction house (75 per bijou, 25 per set of three coins). The Legacy perk Diplomat adds up to 10% to every gain; the numbers in this guide are without it.", goals = {
		{ t = "accept", quest = 8240, title = "A Bijou for Zanza", npc = "Vinchaxa", map = 1434, x = 14.5, y = 15.83, era = true, qlvl = 60, note = "Vinchaxa: A Bijou for Zanza" },
	} },
	{ title = "Zul'Gurub to Friendly", note = "Zul'Gurub is the troll city in the north-east of Stranglethorn Vale: a 20-player raid. Trash pays 3 to 5 each until 11,999 of 12,000 Honored, one point short of Revered; the Speakers 15, Ohgan 15, the Edge of Madness boss 25, Gahz'ranka and the five High Priests 100, Bloodlord Mandokir and Jin'do 200 and Hakkar 400, all the way to Exalted. A full clear is about 4,050: one clear reaches Friendly (3,000). Loot every coin, bijou, Primal Hakkari Idol, Channeler's Head and Primal Hakkari set piece. Coins and bijous pay the same at any standing: save them until the trash stops counting, except one bijou for A Bijou for Zanza.", goals = {
		{ t = "collect", map = 1434, x = 49.6, y = 17.5, era = true, item = 19707, itemName = "Red Hakkari Bijou", mobLevel = 60, optional = true, group = true, note = "Red Hakkari Bijou; any of the nine colours does", spots = "50.9,17.5;52.6,17.3" },
		{ t = "rep", factionName = "Zandalar Tribe", faction = 270, standing = 5 },
	} },
	{ title = "A Bijou for Zanza", note = "Destroy one bijou at the Altar of Zanza, the stone altar on the west side of Yojamba Isle (right-click the bijou there), then tell Vinchaxa: 150 reputation and an extra Zandalar Honor Token, once. From then on every bijou you destroy at the altar pays 75 reputation and a token, and every set of three coins Vinchaxa takes pays 25 and a token. They never stop counting.", goals = {
		{ t = "turnin", quest = 8240, title = "A Bijou for Zanza", npc = "Vinchaxa", map = 1434, x = 14.5, y = 15.83, era = true, optional = true, note = "Vinchaxa: 150" },
	} },
	{ title = "Friendly: your class necklace", note = "At Friendly your class's trainer on the isle gives a necklace for free (100 reputation); the same NPC upgrades it at Honored, Revered and Exalted (100 each) with no raid item needed. Friendly also opens Rin'wosho's first recipes (Pattern: Bloodvine Boots, Primal Batskin Bracers, Plans: Bloodsoul Gauntlets, Darksoul Shoulders, Schematic: Bloodvine Lens, Recipe: Greater Dreamless Sleep, 5g each; Formula: Brilliant Mana Oil, 4g) and the Paragons of Power bracers (150 for the Primal Hakkari bracer token of your class).", goals = {
		{ t = "accept", quest = 8041, title = "Strength of Mount Mugamba", npc = "Jin'rokh the Breaker", map = 1434, x = 15.31, y = 14.43, era = true, qlvl = 60, optional = true, only = { classes = {"WARRIOR"} }, note = "Jin'rokh the Breaker: Strength of Mugamba, Friendly" },
		{ t = "turnin", quest = 8041, title = "Strength of Mount Mugamba", npc = "Jin'rokh the Breaker", map = 1434, x = 15.31, y = 14.43, era = true, optional = true, only = { classes = {"WARRIOR"} }, note = "100" },
		{ t = "accept", quest = 8045, title = "The Heathen's Brand", npc = "Jin'rokh the Breaker", map = 1434, x = 15.31, y = 14.43, era = true, qlvl = 60, optional = true, only = { classes = {"PALADIN"} }, note = "Jin'rokh the Breaker: Heathen's Brand, Friendly" },
		{ t = "turnin", quest = 8045, title = "The Heathen's Brand", npc = "Jin'rokh the Breaker", map = 1434, x = 15.31, y = 14.43, era = true, optional = true, only = { classes = {"PALADIN"} }, note = "100" },
		{ t = "accept", quest = 8049, title = "The Eye of Zuldazar", npc = "Al'tabim the All-Seeing", map = 1434, x = 15.34, y = 16.12, era = true, qlvl = 60, optional = true, only = { classes = {"PRIEST"} }, note = "Al'tabim the All-Seeing: The Eye of Zuldazar, Friendly" },
		{ t = "turnin", quest = 8049, title = "The Eye of Zuldazar", npc = "Al'tabim the All-Seeing", map = 1434, x = 15.34, y = 16.12, era = true, optional = true, only = { classes = {"PRIEST"} }, note = "100" },
		{ t = "accept", quest = 8101, title = "The Pebble of Kajaro", npc = "Al'tabim the All-Seeing", map = 1434, x = 15.34, y = 16.12, era = true, qlvl = 60, optional = true, only = { classes = {"MAGE"} }, note = "Al'tabim the All-Seeing: Pebble of Kajaro, Friendly" },
		{ t = "turnin", quest = 8101, title = "The Pebble of Kajaro", npc = "Al'tabim the All-Seeing", map = 1434, x = 15.34, y = 16.12, era = true, optional = true, only = { classes = {"MAGE"} }, note = "100" },
		{ t = "accept", quest = 8106, title = "Kezan's Taint", npc = "Al'tabim the All-Seeing", map = 1434, x = 15.34, y = 16.12, era = true, qlvl = 60, optional = true, only = { classes = {"WARLOCK"} }, note = "Al'tabim the All-Seeing: Kezan's Taint, Friendly" },
		{ t = "turnin", quest = 8106, title = "Kezan's Taint", npc = "Al'tabim the All-Seeing", map = 1434, x = 15.34, y = 16.12, era = true, optional = true, only = { classes = {"WARLOCK"} }, note = "100" },
