	{ title = "Zul'Gurub to Revered", note = "Honored to Revered is 12,000: about three clears. Two one-time quests help: A Collection of Heads (Exzhal on the isle: 200 for five Channeler's Heads from the High Priests, strung on his Sacred Cord) and The Heart of Hakkar (one per kill, for whoever loots it; Molthor on the isle pays 200 and a Zandalarian Hero badge, charm or medallion). Revered opens Bloodvine Vest, Primal Batskin Jerkin, Blood Tiger Breastplate, Bloodsoul Breastplate, Darksoul Breastplate and Mageblood Elixir (5g each), the Paragons of Power chests and mantles (150) and Zanza's Potent Potables.", goals = {
		{ t = "accept", quest = 8201, title = "A Collection of Heads", npc = "Exzhal", map = 1434, x = 15.26, y = 15.5, era = true, qlvl = 60, optional = true, group = true, note = "Exzhal: A Collection of Heads" },
		{ t = "turnin", quest = 8201, title = "A Collection of Heads", npc = "Exzhal", map = 1434, x = 15.26, y = 15.5, era = true, optional = true, group = true, note = "200" },
		{ t = "accept", quest = 8183, title = "The Heart of Hakkar", map = 1434, x = 54, y = 17.6, era = true, item = 19802, itemName = "Heart of Hakkar", qlvl = 60, optional = true, group = true },
		{ t = "turnin", quest = 8183, title = "The Heart of Hakkar", npc = "Molthor", map = 1434, x = 15.04, y = 15.13, era = true, optional = true, group = true, note = "200" },
		{ t = "rep", factionName = "Zandalar Tribe", faction = 270, standing = 7 },
	} },
	{ title = "Revered: necklace, coins and bijous", note = "Trash stopped counting at 11,999 Honored. Revered to Exalted is 21,000: bosses give about 1,350 a clear, and now the saved coins and bijous pay: 75 per bijou (280 bijous alone), 25 per coin set. Coins and bijous are tradeable, so the auction house is the only solo way. Each Paragons piece pays 150, each Zanza enchant 100, each Savage Guard 200. Rin'wosho trades one of Zanza's potables (Spirit, Sheen or Swiftness of Zanza) for an Honor Token.", goals = {
